\section{Static Susceptibilities}
\label{appendixsusceptibility}

The static susceptibility matrix $\hat{\chi}_{{\cal Q} {\cal Q}'}=G_{{\cal Q}{\cal Q}'}^{R}(\omega =0)/L$, where ${\cal Q}$ is a conserved current. 
We start with the electrical current,
\begin{align}
J_{e}&= {ev_{e}K \over 4}\int_{x}\Pi(x).
\end{align}
In general, the retarded Green's function $G_{{\cal Q}{\cal Q}'}^{R}(\omega)$ can be obtained by Wick rotating the corresponding Euclidean Green's function $G_{{\cal Q}{\cal Q}'}^{E}(i\omega_{E}\rightarrow \omega+i\delta)$, where $\omega_{E}$ is the Euclidean frequency. 
 The Euclidean Green's function is (setting $\delta\rightarrow 0$)
\begin{align}
\hat{\chi}_{J_{e}J_{e}} & \equiv {1 \over L} \lim_{\omega_{E} \rightarrow 0} \int_{\tau} e^{i\omega_{E}\tau}\langle J_{e}(\tau) J_{J}^{e}(0) \rangle = ({ev_{e}K \over 4})^{2} \lim_{\omega_{E} \rightarrow 0} {1 \over L} \int_{\tau,x,y} e^{i\omega_{E} \tau}\langle \Pi (x,\tau) \Pi(y,0) \rangle,
\end{align}
where the Euclidean time $\tau\in[0,1/T]$, and $\langle\cdots\rangle$ stands for thermal average. 
We have the famous result in conformal field theory
\begin{align}
\langle \Pi (x,\tau) \Pi(y,0) \rangle={1\over 64\pi K}\left[{(\pi T/v_{e})^{2}\over\sinh^{2}(\pi T(x-y-iv_{e}\tau)/v_{e})}+{(\pi T/v_{e})^{2}\over\sinh^{2}(\pi T(x-y+iv_{e}\tau)/v_{e})}\right].
\end{align}
We generalize the integral by replacing the exponents from $2\rightarrow 2h$, $h\in\mathbb{N}^{+}$. By performing the contour integral, we have the general expression
\begin{align}
{1\over L}\int\limits_{\tau,x,y}e^{i\omega_{E}\tau}{(\pi T/v_{i})^{2h}\over\sinh^{2h}(\pi T(x-y+ipv_{i}\tau)/v_{i})}={2\pi\over\omega_{E}}{(2\pi T/v_{i})^{2h-1}\over(2h-1)!}\prod_{j=1}^{2h-1}({\omega_{E}\over 2\pi T}+h-j),\quad p=\pm.
\end{align}
As a result, we have
\begin{align}
\hat{\chi}_{J_{e}J_{e}}={e^{2}v_{e}K\over 32}.
\end{align}
On the other hand, the thermal current $J_{T}$ and momentum deviation from the Fermi surface $J_{D}$ are given by 
\begin{align}
J_{T}&=-{v_{e}^{2}\over 4} \int_{x} \Pi(\partial_{x}\phi)-v_{p}^{2}\int d^{3}xP(\partial_{x}q),\\
J_{D}& = -{v_{e}^{2}} \int_{x} \Pi(\partial_{x}\phi)-{v_{e}^{2}}\int d^{3}xP(\partial_{x}q).
\end{align}
The static susceptibility,
\begin{align}
\hat{\chi}_{J_{T}J_{T}} & \equiv {1 \over V} \lim_{\omega_{E} \rightarrow 0} \int_{\tau} e^{i\omega_{E} \tau}\langle J_{T}(\tau) J_{T}(0) \rangle\cr
& \approx {v_{e}^{4}\over 16} \times \lim_{\omega_{E} \rightarrow 0} {1 \over L} \int_{\tau,x,y} e^{i\omega_{E} \tau} \langle \Pi(x,\tau)\Pi(y,0)\rangle\langle \partial_{x}\phi(x,\tau)\partial_{y}\phi(y,0)\rangle\cr
& = {\pi^{3} v_{e}T^{2}\over 1356}.
\end{align}
Similarly, we have
\begin{align}
\hat{\chi}_{J_{D} J_{D}} &=\hat{\chi}_{J_{D} J_{T}}\approx {\pi^{3} v_{e}T^{2}\over 339},\\
\hat{\chi}_{J_{e} J_{T}} &= \hat{\chi}_{J_{T} J_{e}} = \hat{\chi}_{J_{e} J_{D}} = \hat{\chi}_{J_{D} J_{e}} = 0.
\end{align}

\section{Evaluation of $F^{i}_{m, {\cal Q}}$}
\label{commute}

In the limit $v_{p}\ll v_{e}$, $F^{U}_{m,{\cal Q}}=i[H^{U}_{m} , {\cal Q}]$, and $F^{\rm dis}_{m,{\cal Q}}={i\over\sqrt{D_{m}}}[H^{\rm dis}_{m} , {\cal Q}]$ are:
\begin{align}\label{correlator}
F_{m, J_{e}}^{U} & = A_{m, J_{e}}^{U} \int_{x} {1 \over a^{m}} \sin \big( \overline{k}_m x + m \phi \big) \big( \partial_{x} q \big),\\
F_{m,{\cal P}}^{U} & \approx A_{m, {\cal P}}^{U}\int_{x} {1 \over a^{m}} \cos \big( \overline{k}_m x + m \phi \big) \big( \partial_{x}^{2} q \big),\\
F_{m, J_{e}}^{{\rm dis}} & = {A_{m, J_{e}}^{{\rm dis}}\over \sqrt{D_{m}}} \left[ \int_{x} {1 \over a^{m}} \xi_{m}(x) e^{i m \phi } \big( \partial_{x} q \big) - h.c.\right], \\
F_{m,{\cal P}}^{{\rm dis}} & \approx {A_{m,{\cal P}}^{{\rm dis}} \over \sqrt{D_{m}}} \left[ \int_{x} {1 \over a^{m}} \xi_{m} e^{i m \phi} (\partial_{x}^{2} q)+ h.c. \right],
\end{align}
where ${\cal P}\in\{J_{T},J_{D}\}$.
The coefficients $A_{m,{\cal Q}}^{i}$ are 
\begin{align}
A_{m,J_{e}}^{U} &= {i\pi ev_{e}K\over 2}, \\
A_{m,J_{D}}^{U} &= 4v_{p}^{2}, \\
A_{m,J_{T}}^{U} &= 2v_{e}^{2}+2v_{p}^{2},\\
A_{m, J_{e}}^{{\rm dis}} &= -{ev_{e}K m\over 4},\\
A_{m, J_{D}}^{{\rm dis}} &= v_{e}^{2}, \\
A_{m, J_{T}}^{{\rm dis}} &= v_{p}^{2}.
\end{align}
The approximation indicated by $``\approx"$ is leading for $v_p \ll v_e$.

\section{Disorder Scattering Memory Matrix Details}
\label{appendixdisordermemory}

The retarded Green's function ${1 \over L} \langle F_{m, J_{e}}^{\rm dis} , F_{m, J_{e}}^{\rm dis} \rangle_{\omega}$ is
\begin{align}
{1 \over L} \langle F_{m, J_{e}}^{\rm dis} , F_{m, J_{e}}^{\rm dis} \rangle_{\omega} & = { A_{m, J_{e}}^{\rm dis} A_{m, J_{e}}^{\rm dis} \over L D_{m}} \int\limits_{x,y,t} e^{i\omega t} g_{e}(x-y,t)g_{p}(x-y,t)\left[ \xi_{m}(x)\xi_{m}^{*}(y) + \xi_{m}^{*}(x)\xi_{m}(y) \right]. 
\end{align}
We perform an integration by parts and drop all boundary terms to obtain ${1\over L}\langle F_{m,{\cal P}}^{\rm dis};F_{m,{\cal P}'}^{\rm dis}\rangle_{\omega}$ for ${\cal P}, {\cal P}'\in\{J_{T},J_{D}\}$:
\begin{align}
{1 \over L} \langle F_{m,{\cal P}}^{\rm dis} , F_{m,{\cal P}'}^{\rm dis} \rangle_{\omega} & = -{ A_{m,{\cal P}}^{\rm dis} A_{m,{\cal P}'}^{\rm dis} \over LD_{m}} \int\limits_{x,y,t} e^{i\omega t} g_{e}(x,t)\big(\partial_{x}^{2}g_{p}(x,t)\big) \left[ \xi_{m}(x)\xi_{m}^{*}(y) + \xi_{m}^{*}(x)\xi_{m}(y) \right]. 
\end{align}

After disorder averaging $\overline{\xi_{m}(x)\xi_{m}^{*}(y)}=D_{m}\delta(x-y)$, we obtain 
\begin{align}
{1 \over L} \langle F_{m, J_{e}}^{\rm dis} , F_{m, J_{e}}^{\rm dis} \rangle_{\omega} &=2A_{m,J_{e}}^{\rm dis} A_{m,J_{e}}^{\rm dis} G_{2}(\omega),\\
{1 \over L} \langle F_{m, {\cal P}}^{\rm dis} , F_{m, {\cal P}'}^{\rm dis} \rangle_{\omega} & = { 2A_{m, {\cal P}}^{\rm dis} A_{m, {\cal P}'}^{\rm dis} } \widetilde{G}_{2}(\omega),
\end{align}
The memory matrix $({\cal \hat{M}}^{\rm dis}_{m})^{{\cal P} {\cal P}'}$ is
\begin{align}
({\cal \hat{M}}^{\rm dis}_{m})^{J_{e}J_{e}}&=2A_{m, J_{e}}^{\rm dis}A_{m, J_{e}}^{\rm dis}{G_{2}(\omega)-G_{2}(\omega=0)\over i\omega},\\
({\cal \hat{M}}^{\rm dis}_{m})^{{\cal P} {\cal P}'}&=2A_{m,{\cal P}}^{\rm dis}A_{m, {\cal P}'}^{\rm dis}{\widetilde{G}_{2}(\omega)-\widetilde{G}_{2}(\omega=0)\over i\omega},
\end{align}
where $G_{2}(\omega)$ and $\widetilde{G}_{2}(\omega)$ are
\begin{align}
G_{2}(\omega)&=\int\limits_{x,t}e^{i\omega t}g_{e}(x,t)g_{p}(x,t)\delta(x),\\
\widetilde{G}_{2}(\omega)&=-\int\limits_{x,t}e^{i\omega t}g_{e}(x,t)\big(\partial_{x}^{2}g_{p}(x,t)\big) \delta(x).
\end{align}
We take the dc limit $\omega\rightarrow 0$:
\begin{align}
\lim_{\omega\rightarrow 0}({\cal \hat{M}}^{\rm dis}_{m})^{J_{e}J_{e}}&=\left.2A_{m,J_{e}}^{\rm dis}A_{m,J_{e}}^{\rm dis}\big(-i\partial_{\omega}G_{2}(\omega)\big)\right|_{\omega=0},\\
\lim_{\omega\rightarrow 0}({\cal \hat{M}}^{\rm dis}_{m})^{{\cal P} {\cal P}'}&=\left.2A_{m, {\cal P}}^{\rm dis}A_{m, {\cal P}'}^{\rm dis}\big(-i\partial_{\omega}\widetilde{G}_{2}(\omega)\big)\right|_{\omega=0}.
\end{align}
To include the Debye cut-off, we apply the Fourier transform trick described in the main text, writing
\begin{align}
G_{2}(\omega)&=\int\limits_{x,t} e^{i\omega t} g_{e}(x,t)g_{p}(x,t)\delta(x)={1\over 8\pi^{3}}\int\limits_{k_{1},k_{2},\omega_{1}} G_{0}^{e}(k_{1},\omega_{1})G_{0}^{p}(k_{2},\omega-\omega_{1})\\
\widetilde{G}_{2}(\omega)&=-\int\limits_{x,t}e^{i\omega t}g_{e}(x,t)\big(\partial_{x}^{2}g_{p}(x,t)\big)\delta(x)={1\over 8\pi^{3}}\int\limits_{k_{1},k_{2},\omega_{1}} k_{2}^{2}G_{0}^{e}(k_{1},\omega_{1})G_{0}^{p}(k_{2},\omega-\omega_{1}).
\end{align}
The dc electrical memory matrices below and above the Debye temperature are found to be
\begin{align}
\lim_{\omega\rightarrow 0}( {\cal \hat{M}}_{m}^{\rm dis} )_{<}^{J_{e}J_{e}}&\approx A_{m, J_{e}}^{\rm dis} A_{m, J_{e}}^{\rm dis} ({2\pi Ta\over v_{e}})^{2\Delta_m+2} {\pi v_{e}^{2}\over v_{p}^{2}T^{2}},\\
\lim_{\omega\rightarrow 0}( {\cal \hat{M}}_{m}^{\rm dis} )_{>}^{J_{e}J_{e}}&\approx A_{m, J_{e}}^{\rm dis} A_{m, J_{e}}^{\rm dis} ({2\pi Ta\over v_{e}})^{2\Delta_m+2} {k_{D}^{2}v_{e}^{3}\omega_{D}\over 64\pi^{5}v_{p}T^{5}} B^{2}({\Delta_m\over 2},1-\Delta_m).
\end{align}
Hence, the dc electrical conductivity $\sigma$ is given by
\begin{align}
\sigma\propto
\begin{cases}
T^{-2\Delta_m},&T\ll\Theta_{D},\cr
T^{3-2\Delta_m},&T\gg\Theta_{D}.
\end{cases}
\end{align}
The dc thermal memory matrices at low and high temperatures are given by
\begin{align}
\lim_{\omega\rightarrow 0}( {\cal \hat{M}}_{m}^{\rm dis} )_{<}^{{\cal P} {\cal P}'} &\approx A_{m, {\cal P}}^{\rm dis} A_{m, {\cal P}'}^{\rm dis} ({2\pi Ta\over v_{e}})^{2\Delta_m+2} {v_{e}^{2}\pi^{3}\over v_{p}^{4}},\\
\lim_{\omega\rightarrow 0}( {\cal \hat{M}}_{m}^{\rm dis} )_{>}^{{\cal P} {\cal P}'} &\approx A_{m, {\cal P}}^{\rm dis} A_{m, {\cal P}'}^{\rm dis} ({2\pi Ta\over v_{e}})^{2\Delta_m+2} {k_{D}^{4}v_{e}^{3}\omega_{D}\over 192\pi^{5}v_{p}T^{5}} B^{2}({\Delta_m \over 2},1-\Delta_m).
\end{align}
The dc thermal conductivity $\kappa$ is
\begin{align}
\kappa\propto
\begin{cases}
T^{1-2\Delta_m},&T\ll\Theta_{D},\cr
T^{6-2\Delta_m},&T\gg\Theta_{D}.
\end{cases}
\end{align}

