Now we can define the concept of Jacobi stability for a second order ODE as follows. This kind of stability refers to the focusing tendency (in a small vicinity of $t_0$) of trajectories of \eqref{kcc-4} with respect to a variation \eqref{kcc-7} that satisfies the condition
\[||x_i(t_0)-\tilde{x}_i(t_0)||=0,\quad ||\dot{x}_i(t_0)-\dot{\tilde{x}}_i(t_0)||\neq0.\]

\begin{definition}\label{kcc-def}
The trajectories of \eqref{kcc-4} are said to be Jacobi stable at $(\boldsymbol{x}(t_0),\dot{\boldsymbol{x}}(t_0))$ if the real parts of the eigenvalues of the deviation curvature tensor $P_j^i|_{t_0}$ are strictly negative, or Jacobi unstable, otherwise.
\end{definition}

We note that Jacobi instability via equation \eqref{kcc-9} means exponential growth of the deviation vector $\xi(t)$, while Jacobi stability means that $\xi(t)$ has an oscillatory variation expressed by a linear combination of trigonometric functions sin and cos. More detailed discussions of the KCC theory, including applications, can be found in \cite{PLA2003,BHS2012,HHLY2015,HPPS2016}.


\section{Main Algorithmic Results}\label{sect-main}

According to the KCC theory described in Section \ref{sect2}, it is necessary to take the following steps to study Jacobi stability of a system of second order ODEs \eqref{eq1-2}.
\vspace{0.1cm}

\noindent{\bf Step 1}. Write a system of second order ODEs in the standard form of the KCC \eqref{eq1-2} (or \eqref{kcc-4}).

%Detect the fixed points of a system of SODEs and 

\vspace{0.1cm}

\noindent{\bf Step 2}. Compute the deviation curvature tensor $P_j^i$ using \eqref{kcc-10} and derive the symbolic expression of the deviation equations by \eqref{kcc-8}.

\vspace{0.1cm}

\noindent{\bf Step 3}. Determine the sign of the real parts of the eigenvalues of $(P_j^i)$ at each fixed point of the system and study the dynamic behavior of the deviation equations near the fixed points.

\vspace{0.1cm}

Usually, given a system of second order ODEs, {\bf Step 1} can be done by solving a linear system of equations with respect to the variables $(d^2x_1/dt^2,\ldots,d^2x_n/dt^2)$. {\bf Step 2} is mainly based on the formulas \eqref{kcc-8} and \eqref{kcc-10}. In {\bf Step 3}, we will provide a computational approach for detecting Jacobi stability of a system via $(P_j^i)$ at a fixed point. We remark that the study on the dynamic behavior of the deviation equations is performed by numerical simulations (combined with our computational approach and the exact expression of the deviation equations derived in {\bf Step 2}). Next, we divide this section into two parts to describe our main results.


\subsection{Algorithms for Step 2}\label{sect3-1}

This subsection is devoted to providing algorithms to compute the deviation curvature tensor $P_j^i$ and exact expression of the deviation equations. In the following we will present algorithms to implement {\bf Step 2}. We use ``Maple-like'' pseudo-code, based on our Maple implementation.


The algorithm {\bf KCC-invariant}, presented below, is based on \eqref{kcc-10} that can be used to derive the deviation curvature tensor $P_j^i$ for a given system of second order ODEs.

\begin{small}
\begin{algorithm}[H]
\caption{{\bf KCC-invariant}$(G)$}
\hspace*{0.02in} {\bf Input:}
a set of equations $G^i$ in a system of second order ODEs \eqref{eq1-2}\\
\hspace*{0.02in} {\bf Output:}
the deviation curvature tensor $(P_j^i)$
\begin{algorithmic}[1]
\State $n:=\mbox{nop}(G)$;

\For{$i$ {\bf from} 1 {\bf to} $n$}
\For{$j$ {\bf from} 1 {\bf to} $n$}
\For{$\ell$ {\bf from} 1 {\bf to} $n$}
\State $N_j^i:={\partial G^i}/{\partial y_j}$;
\State $G_{j,\ell}^i:={\partial N_j^i}/{\partial y_{\ell}}$;

\EndFor
\EndFor
\EndFor


\For{$i$ {\bf from} 1 {\bf to} $n$}
\For{$j$ {\bf from} 1 {\bf to} $n$}

\State $P_j^i:=-2\cdot\partial G^i/\partial x_j$;

\For{$\ell$ {\bf from} 1 {\bf to} $n$}
\State $P_j^i:=P_j^i+y_{\ell}\cdot\frac{\partial N_j^i}{x_{\ell}}+N_{\ell}^i\cdot N_j^{\ell}-2\cdot G^{\ell}\cdot G_{j,\ell}^i$;

\EndFor
\EndFor
\EndFor

\State \Return $(P_j^i)$;
\end{algorithmic}
\end{algorithm}
\end{small}

%In order to study the dynamic behavior of the deviation equations near the fixed points. 

The following theorem gives the symbolic expression of the deviation equations \eqref{kcc-8} near a fixed point $\bar{\boldsymbol{x}}$. It also provides a way to deduce the exact solution of the obtained deviation equations.

\begin{theorem}\label{kcc-deviation}
Let $\boldsymbol{\xi}=(\xi_1,\dots,\xi_n)^\mathrm{T}$ be the deviation vector. Then the deviation equations associated to system \eqref{eq1-2} near a fixed point $\bar{\boldsymbol{x}}$ can be written as 
\begin{equation}\label{KCC-xi-2}
    \ddot{\boldsymbol{\xi}}(t)=
    \begin{pmatrix}
       \boldsymbol{A}_{21} & \boldsymbol{A}_{22} 
    \end{pmatrix}
    \begin{pmatrix}
    \boldsymbol{\xi}(t)\\
    \dot{\boldsymbol{\xi}}(t)
    \end{pmatrix},
\end{equation}
where
\begin{equation*}
\begin{split}
\boldsymbol{A}_{21}&=
    \begin{pmatrix}
     -2\frac{\partial G^1}{\partial x_1}(\mu,\bar{\boldsymbol{x}}) & \dots & -2\frac{\partial G^1}{\partial x_n}(\mu,\bar{\boldsymbol{x}})  \\
     \vdots & \ddots & \vdots   \\
     -2\frac{\partial G^n}{\partial x_1}(\mu,\bar{\boldsymbol{x}}) & \dots & -2\frac{\partial G^n}{\partial x_n}(\mu,\bar{\boldsymbol{x}})  \\
    \end{pmatrix},\\
    \boldsymbol{A}_{22}&=
    \begin{pmatrix}
-2N_1^1(\mu,\bar{\boldsymbol{x}}) & \dots & -2N_n^1(\mu,\bar{\boldsymbol{x}}) \\
     \vdots & \ddots & \vdots   \\
     -2N_1^n(\mu,\bar{\boldsymbol{x}}) & \dots & -2N_n^n(\mu,\bar{\boldsymbol{x}}) \\
    \end{pmatrix}.
\end{split}
\end{equation*}
Moreover, the exact solution of $\boldsymbol{\xi}(t)$ under the initial conditions $\boldsymbol{\xi}(0)=(0,\dots,0)^\mathrm{T}, \dot{\boldsymbol{\xi}}(0)=(\xi_{10},\dots,\xi_{n0})^\mathrm{T}$ can be derived by the formula 
\begin{equation}\label{kcc-xi-3}
    \begin{pmatrix}
        \boldsymbol{\xi}(t)\\
        \dot{\boldsymbol{\xi}}(t)
    \end{pmatrix}=
\left(\sum^\infty_{k=0}\frac{(\boldsymbol{A}t)^k}{k!}\right)
\begin{pmatrix}
        \boldsymbol{\xi}(0)\\
        \dot{\boldsymbol{\xi}}(0)
    \end{pmatrix}=\mathrm{exp}(\boldsymbol{A}t)
    \begin{pmatrix}
        \boldsymbol{\xi}(0)\\
        \dot{\boldsymbol{\xi}}(0)
    \end{pmatrix},
\end{equation}
where \begin{equation*}
    \boldsymbol{A}=
    \begin{pmatrix}
     \boldsymbol{0} & \boldsymbol{E} \\
    \boldsymbol{A}_{21} & \boldsymbol{A}_{22}
    \end{pmatrix}.
\end{equation*}
\end{theorem}

\begin{proof}
Note that the equations of deviation direction \eqref{kcc-8} near the fixed point $\bar{\boldsymbol{x}}$ can be rewritten in the following matrix form
\begin{equation}\label{KCC-xi-4}
    \ddot{\boldsymbol{\xi}}(t)=
    \begin{pmatrix}
       \boldsymbol{A}_{21} & \boldsymbol{A}_{22} 
    \end{pmatrix}
    \begin{pmatrix}
    \boldsymbol{\xi}(t)\\
    \dot{\boldsymbol{\xi}}(t)
    \end{pmatrix},
\end{equation}
where
\begin{equation}\label{KCC-xi-5}
    \boldsymbol{A}_{21}=
    \left.\begin{pmatrix}
     -2\frac{\partial G^1}{\partial x_1} & \dots & -2\frac{\partial G^1}{\partial x_n}  \\
     \vdots & \ddots & \vdots   \\
     -2\frac{\partial G^n}{\partial x_1} & \dots & -2\frac{\partial G^n}{\partial x_n}  \\
    \end{pmatrix}\right|_{\bar{x}},
    \quad
    \boldsymbol{A}_{22}=
    \left.\begin{pmatrix}
     -2N_1^1 & \dots & -2N_n^1 \\
     \vdots & \ddots & \vdots   \\
     -2N_1^n & \dots & -2N_n^n \\
    \end{pmatrix}\right|_{\bar{x}}.\nonumber
\end{equation}
By taking the notation
\begin{equation*}
  \begin{split}
        \dot{\boldsymbol{\xi}}(t) = \boldsymbol{\eta}(t), \quad \ddot{\boldsymbol{\xi}}(t) =  \dot{\boldsymbol{\eta}}(t),  
\end{split}
\end{equation*}
we see that system \eqref{KCC-xi-4} is equivalent to the following system of first order equations
\begin{equation}\label{KCC-xi-6}
    \begin{pmatrix}
    \dot{\boldsymbol{\xi}}(t)\\
    \dot{\boldsymbol{\eta}}(t)
    \end{pmatrix}=\boldsymbol{A}
    \begin{pmatrix}
    \boldsymbol{\xi}(t)\\
    \boldsymbol{\eta}(t)
    \end{pmatrix},
\end{equation}
where
\begin{equation}\label{KCC-xi-7}
    \boldsymbol{A}=
    \begin{pmatrix}
     \boldsymbol{0} & \boldsymbol{E} \\
     \boldsymbol{A}_{21} & \boldsymbol{A}_{22}
    \end{pmatrix}.
\end{equation}
Here $\boldsymbol{0}$ is $n\times n$ zero matrix, and $\boldsymbol{E}$ is $n\times n$ identity matrix. Note that \eqref{KCC-xi-6} is a first order differential system with constant coefficient, so that the solution of \eqref{KCC-xi-4} under initial conditions $\boldsymbol{\xi}(0)=(0,\dots,0)^\mathrm{T},\boldsymbol{\eta}(0)=\dot{\boldsymbol{\xi}}(0)=(\xi_{10},\dots,\xi_{n0})^\mathrm{T}$ can be written as the formula \eqref{kcc-xi-3}.
\end{proof}


The following algorithm {\bf KCC-deviation} is based on Theorem \ref{kcc-deviation}, which provides a straightforward calculation method to derive the exact expression of the deviation equations for a considered system of second order ODEs.

\begin{small}
\begin{algorithm}[H]
\caption{{\bf KCC-deviation}$(G)$}
\hspace*{0.02in} {\bf Input:}
a set of equations $G^i$ in a system of second order ODEs \eqref{eq1-2}\\
\hspace*{0.02in} {\bf Output:}
a list of the deviation equations $\xi_i$ in \eqref{kcc-8}
\begin{algorithmic}[1]
\State $n:=\mbox{nop}(G)$;

\For{$i$ {\bf from} 1 {\bf to} $n$}
\For{$j$ {\bf from} 1 {\bf to} $n$}

\State $N_j^i:={\partial G^i}/{\partial y_j}$;

\EndFor
\EndFor

\State $\boldsymbol{\xi}(t)=(\xi_1(t),\ldots,\xi_n(t))^T$;
\State $\dot{\boldsymbol{\xi}}(t)=\left(\mbox{Diff}(\xi_1,t),\ldots,\mbox{Diff}(\xi_n,t)\right)^T$;
\State $\ddot{\boldsymbol{\xi}}(t):=\left(\mbox{Diff}(\xi_1,t\$2),\ldots,\mbox{Diff}(\xi_n,t\$2)\right)^T$;

\State $\mbox{Jac}:=\mbox{Jacobian}(G, [x_1,\ldots,x_n])$;

\State $\Xi(t):=\ddot{\boldsymbol{\xi}}(t)+2\cdot \mbox{Multiply}\left(\big(N_j^i\big),\dot{\boldsymbol{\xi}}(t)\right)+2\cdot \mbox{Multiply}\left(\mbox{Jac},\boldsymbol{\xi}(t)\right)$;

\State \Return $\Xi(t)$;
\end{algorithmic}
\end{algorithm}
\end{small}


