\section{Examples and Experiments}\label{sect4}
In this section, we explain how to apply the algorithmic tests to study Jacobi stability of systems of second order ODEs and illustrate some of the computational steps by a model of wound strings. In addition, using our algorithmic approach, we also analyze Jacobi stability of an airfoil model with cubic nonlinearity in supersonic flow and a 3-DOF tractor seat-operator model. The experimental results show the applicability and efficiency of our algorithmic approach. All the computations were made in Maple 2023, running under a Windows 11 laptop on Intel(R) Core(TM) Ultra 7 155H  1.40 GHz.

\subsection{Illustrative Example: A Model of Wound Strings}\label{sect5.1}

Lake and Harko proposed a model of wound strings in 2016 \cite{Matthew2016}. It is a system of second order ODEs, expressed as follows
\begin{equation}\label{WS-1}
    \begin{split}
        \ddot{\rho}&+\frac{\rho}{a^2\rho^2+m^2R^2}\left[a^2\left(1-\dot{\rho}^2\right)-\dot{R}^2-C^2\frac{\left(a^2\rho^2+m^2R^2\right)^2}{\rho^4R^2}\right]=0,\\
        \ddot{R}&+\frac{R}{a^2\rho^2+m^2R^2}\left[m^2a^2(1-\dot{\rho}^2)-m^2\dot{R}^2-a^2C^2\frac{(a^2\rho^2+m^2R^2)^2}{\rho^2R^4}\right]=0,
    \end{split}
\end{equation}
where $\rho$ and $R$ are variables,  $a^2\in(0,1]$ is a phenomenological ``wrap factor'', $C$ and $m$ are arbitrary real constants. For brevity, we denote the parameters by $\mu=(a,C,m)$.

To write the model in the standard form of the KCC, we change the notation as
\begin{equation*}
    \rho = x_1, \quad R = x_2, \quad \dot{\rho} = y_1, \quad \dot{R} = y_2.
\end{equation*}
Let $(x,y)=(x_1,x_2,y_1,y_2)$. Then system \eqref{WS-1} becomes
\begin{equation}\label{WS-2}
\begin{split}
\ddot{x}_1+2G^1(\mu,x,y)=0,\quad
\ddot{x}_2+2G^2(\mu,x,y)=0,
\end{split}
\end{equation}
where
\begin{equation}\label{WS-3}
\begin{split}
&G^1=\frac{x_1}{2a^2x_1^2+2m^2x_2^2}\Bigg[a^2\left(1-y_1^2\right)-y_2^2-C^2\frac{\left(a^2x_1^2+m^2x_2^2\right)^2}{x_1^4x_2^2}\Bigg],\\
&G^2=\frac{x_2}{2a^2x_1^2+2m^2x_2^2}\Bigg[
m^2\Big(a^2(1-y_1^2)-y_2^2\Big)-a^2C^2\frac{(a^2x_1^2+m^2x_2^2)^2}{x_1^2x_2^4}\Bigg].
\end{split}
\end{equation}

Applying the algorithm {\bf KCC-invariant} to \eqref{WS-3}, we obtain the following deviation curvature tensor $(P^i_j)$:
\begin{equation}\label{WS-4}
\begin{split}
P^1_1&=-\frac{1}{x_1^4x_2^2\left(a^2x_1^2+m^2x_2^2\right)^2}\Big(2 C^{2} a^{6} x_{1}^{6}+7 C^{2} a^{4} m^{2} x_{1}^{4} x_{2}^{2}\\
&+8 C^{2} a^{2} m^{4} x_{1}^{2} x_{2}^{4}+3 C^{2} m^{6} x_{2}^{6}-3 y_{2} x_{1}^{5} a^{2} y_{1} m^{2} x_{2}^{3}-2 a^{4} x_{1}^{6} x_{2}^{2}\\
&+a^{2} m^{2} x_{1}^{4} x_{2}^{4}+2 a^{2} x_{1}^{6} x_{2}^{2} y_{2}^{2}-m^{2} x_{1}^{4} x_{2}^{4} y_{2}^{2}\Big),\\
P^1_2&=-\frac{1}{x_1x_2^3\left(a^2x_1^2+m^2x_2^2\right)^2}\Big(3 C^{2} a^{6} x_{1}^{4}+6 C^{2} a^{4} m^{2} x_{1}^{2} x_{2}^{2}\\
&+3 C^{2} a^{2} m^{4} x_{2}^{4}+3 a^{2} m^{2} x_{1}^{2} x_{2}^{4} y_{1}^{2}-3 a^{2} m^{2} x_{1}^{2} x_{2}^{4}\\
&-2 a^{2} x_{1}^{3} x_{2}^{3} y_{1} y_{2}+m^{2} x_{1} x_{2}^{5} y_{1} y_{2}\Big),\\
P^2_1&=-\frac{a^2m^2}{x_1^3x_2\left(a^2x_1^2+m^2x_2^2\right)^2}\Big(3 C^{2} a^{4} x_{1}^{4}+6 C^{2} a^{2} m^{2} x_{1}^{2} x_{2}^{2}+3 C^{2} m^{4} x_{2}^{4}\\
&+a^{2} x_{1}^{5} x_{2} y_{1} y_{2}-2 y_{2} m^{2} y_{1} x_{1}^{3} x_{2}^{3}-3 a^{2} x_{1}^{4} x_{2}^{2}+3 y_{2}^{2} x_{1}^{4} x_{2}^{2}\Big),\\
P^2_2&=-\frac{a^2}{x_1^2x_2^4\left(a^2x_1^2+m^2x_2^2\right)^2}\Big(3 C^{2} a^{6} x_{1}^{6}+8 C^{2} a^{4} m^{2} x_{1}^{4} x_{2}^{2}\\
&+7 C^{2} a^{2} m^{4} x_{1}^{2} x_{2}^{4}+2 C^{2} m^{6} x_{2}^{6}-y_{1}^{2} x_{2}^{4} m^{2} a^{2} x_{1}^{4}+2 m^{4} x_{1}^{2} x_{2}^{6} y_{1}^{2}\\
&+a^{2} m^{2} x_{1}^{4} x_{2}^{4}-2 m^{4} x_{1}^{2} x_{2}^{6}-3 m^{2} x_{1}^{3} x_{2}^{5} y_{1} y_{2}
\Big).
\end{split}
\end{equation}


The obtained expressions in \eqref{WS-4} are different from those in \cite[Section 5]{Matthew2016}. After comparing the calculation process, we found that $G^2$ in \cite{Matthew2016} was incorrect ($x^2$ should be $X^2$ there). As a consequence, the symbol $X^2$ was mistakenly written as $X^1$ in $N^2_1$ and $N^2_2$. This ultimately led to errors in the $(P^i_j)$. Thus, some calculations of the deviation curvature tensor in \cite{Matthew2016} need to be reconsidered algorithmically, using the algorithm developed in this
paper.

Now consider system \eqref{WS-2} and let $\bar{x}=(x_1,x_2,y_1=0,y_2=0)$ be a fixed point of it. We have
\begin{equation}
\begin{split}
G^1(\mu,\bar{x})&=-\frac{1}{2 x_{1}^{3} \left(a^{2} x_{1}^{2}+m^{2} x_{2}^{2}\right) x_{2}^{2}}G^{1,1}(\mu,\bar{x}),  \\
G^2(\mu,\bar{x})&=-\frac{a^2}{2 x_{2}^{3} \left(a^{2} x_{1}^{2}+m^{2} x_{2}^{2}\right) x_{1}^{2}}G^{2,1}(\mu,\bar{x}), 
\end{split}
\end{equation}
where
\begin{equation}
\begin{split}
G^{1,1}(\mu,\bar{x})&=C^{2} a^{4} x_{1}^{4}+2 C^{2} a^{2} m^{2} x_{1}^{2} x_{2}^{2}+C^{2} m^{4} x_{2}^{4}-a^{2} x_{1}^{4} x_{2}^{2},\\
G^{2,1}(\mu,\bar{x})&=C^{2} a^{4} x_{1}^{4}+2 C^{2} a^{2} m^{2} x_{1}^{2} x_{2}^{2}+C^{2} m^{4} x_{2}^{4}-m^{2} x_{1}^{2} x_{2}^{4}.\nonumber
\end{split}
\end{equation}
The characteristic polynomial of $(P_j^i)$ at the fixed point is
\begin{equation}\label{kcc-main-JJ}
\begin{split}
p(\lambda)=\lambda^2+a_1(\mu,\bar{x})\lambda+a_2(\mu,\bar{x}),
\end{split}
\end{equation}
where
\begin{equation}
\begin{split}
a_1(\mu,\bar{x})&=\frac{1}{\left(a^{2} x_{1}^{2}+m^{2} x_{2}^{2}\right)^{2} x_{1}^{4} x_{2}^{4}}a_{1,1}(\mu,\bar{x}),\\
a_2(\mu,\bar{x})&=\frac{2a^2}{\left(a^{2} x_{1}^{2}+m^{2} x_{2}^{2}\right)^{2} x_{1}^{6} x_{2}^{6}}a_{2,1}(\mu,\bar{x}),\nonumber
\end{split}
\end{equation}
with
\begin{equation}
\begin{split}
a_{1,1}&(\mu,\bar{x})=3 C^{2} a^{8} x_{1}^{8}+8 C^{2} a^{6} m^{2} x_{1}^{6} x_{2}^{2}+7 C^{2} a^{4} m^{4} x_{1}^{4} x_{2}^{4}\\
&+2 C^{2} a^{2} m^{6} x_{1}^{2} x_{2}^{6}+2 C^{2} a^{6} x_{1}^{6} x_{2}^{2}+7 C^{2} a^{4} m^{2} x_{1}^{4} x_{2}^{4}+8 C^{2} a^{2} m^{4} x_{1}^{2} x_{2}^{6}\\
&+3 C^{2} m^{6} x_{2}^{8}+a^{4} m^{2} x_{1}^{6} x_{2}^{4}-2 a^{2} m^{4} x_{1}^{4} x_{2}^{6}-2 a^{4} x_{1}^{6} x_{2}^{4}+a^{2} m^{2} x_{1}^{4} x_{2}^{6},\\
a_{2,1}&(\mu,\bar{x})=3 C^{4} a^{8} x_{1}^{8}+8 C^{4} a^{6} m^{2} x_{1}^{6} x_{2}^{2}+10 C^{4} a^{4} m^{4} x_{1}^{4} x_{2}^{4}\\
&+8 C^{4} a^{2} m^{6} x_{1}^{2} x_{2}^{6}+3 C^{4} m^{8} x_{2}^{8}-3 C^{2} a^{6} x_{1}^{8} x_{2}^{2}\\
&+5 C^{2} a^{4} m^{2} x_{1}^{6} x_{2}^{4}+5 C^{2} a^{2} m^{4} x_{1}^{4} x_{2}^{6}-3 C^{2} m^{6} x_{1}^{2} x_{2}^{8}-a^{2} m^{2} x_{1}^{6} x_{2}^{6}.\nonumber
\end{split}
\end{equation}

According to Theorem \ref{semi-kcc}, we formulate the following algebraic system $\mathcal{S}$ for the study of Jacobi fixed points of system \eqref{WS-2}:
\begin{equation}
\mathcal{S}:=
\left\{\begin{array}{l}
G^{1,1}(\mu,\bar{x})=G^{2,1}(\mu,\bar{x})
=0,\\ 
x_1\neq0,\,\, x_2\neq0,\,\, a^2>0,\,\, 1-a^2\geq0,\\
a_{1,1}(\mu,\bar{x})>0,\,\, a_{2,1}(\mu,\bar{x})>0.\\
\end{array}\right.\nonumber
\end{equation}
Using the command RealRootClassification in the Maple package RegularChains[SemiAlgebraicSe- tTools] to the above system, we see that system $\mathcal{S}$ cannot have one, two, or three real solutions; system $\mathcal{S}$ always has four real solutions when $m\neq0$, $C\neq0$, and $a^2-1\neq0$. 


Here we restate the result related to the Jacobi stability of the model \eqref{WS-1} as follows.

\begin{theorem}\label{main-kcc1}
The model \eqref{WS-1} cannot have one, two, or three Jacobi stable fixed points, and always has four Jacobi stable fixed points when the condition
\[\mathcal{C}_0=[m\neq0, \quad C\neq0,\quad  a^2-1\neq0]\]
holds.
\end{theorem}

\begin{remark}
Theorem \ref{main-kcc1} is quite different from the conclusion made in \cite[Theorem 1]{Matthew2016}. To verify the correctness of our result, we will perform numerical simulations of dynamic behaviors of the model \eqref{WS-1} near the fixed points. We take the parameter values $(a,C,m)=(\frac{1}{2},1,-1)$. According to Theorem \ref{main-kcc1}, the model \eqref{WS-2} has four Jacobi stable fixed points $(\bar{x}_1,\bar{x}_2)=(\pm 2,\pm 1)$ and $(\bar{x}_1,\bar{x}_2)=(\pm 2,\mp 1)$. However, by \cite[Theorem 1]{Matthew2016}, we see that the fixed points $(-2,-1)$ and $(2,1)$ are Jacobi stable, while the other two fixed points $(-2,1)$ and $(2,-1)$ are Jacobi unstable. In the following we will show that both of the two fixed points $(-2,1)$ and $(2,-1)$ are also Jacobi stable.

\end{remark}


Taking $(a,C,m)=(\frac{1}{2},1,-1)$ and applying algorithm {\bf KCC-deviation} to the $G^i$ in \eqref{WS-2}, we obtain the following deviation equations:
\begin{equation}\label{WS-dev-1}
    \begin{split}
        &\frac{d^2\xi_1}{dt^2}-\frac{2x_1y_1}{x_1^2+4x_2^2}\frac{d\xi_1}{dt}-\frac{8x_1y_2}{x_1^2+4x_2^2}\frac{d\xi_2}{dt}+M^1_1\xi_1+M^1_2\xi_2=0,\\
        &\frac{d^2\xi_2}{dt^2}-\frac{2x_2y_1}{x_1^2+4x_2^2}\frac{d\xi_1}{dt}-\frac{8x_2y_2}{x_1^2+4x_2^2}\frac{d\xi_2}{dt}+M^2_1\xi_1+M^2_2\xi_2=0,
    \end{split}
\end{equation}
where
\begin{equation*}
\begin{split}
M^1_1&=\frac{1}{4 \left(x_{1}^{2}+4 x_{2}^{2}\right)^{2} x_{1}^{4} x_{2}^{2}}\Big(4 x_{1}^{6} x_{2}^{2} y_{1}^{2}+16 x_{1}^{6} x_{2}^{2} y_{2}^{2}-16 x_{1}^{4} x_{2}^{4} y_{1}^{2}\\
&-64 x_{1}^{4} x_{2}^{4} y_{2}^{2}-4 x_{1}^{6} x_{2}^{2}+16 x_{1}^{4} x_{2}^{4}+x_{1}^{6}+20 x_{1}^{4} x_{2}^{2}+112 x_{1}^{2} x_{2}^{4}+192 x_{2}^{6}\Big),\\
M^1_2&=\frac{1}{2 x_{1} \left(x_{1}^{2}+4 x_{2}^{2}\right)^{2} x_{2}^{3}}\Big(16 x_{1}^{2} x_{2}^{4} y_{1}^{2}+64 x_{1}^{2} x_{2}^{4} y_{2}^{2}-16 x_{1}^{2} x_{2}^{4}\\
&+x_{1}^{4}+8 x_{1}^{2} x_{2}^{2}+16 x_{2}^{4}\Big),\\
M^2_1&=\frac{1}{2 x_{2} \left(x_{1}^{2}+4 x_{2}^{2}\right)^{2} x_{1}^{3}}\Big(4 x_{1}^{4} x_{2}^{2} y_{1}^{2}+16 x_{1}^{4} x_{2}^{2} y_{2}^{2}-4 x_{1}^{4} x_{2}^{2}+x_{1}^{4}\\
&+8 x_{1}^{2} x_{2}^{2}+16 x_{2}^{4}\Big),\\
M^2_2&=\frac{1}{16 \left(x_{1}^{2}+4 x_{2}^{2}\right)^{2} x_{1}^{2} x_{2}^{4}}\Big(-16 x_{1}^{4} x_{2}^{4} y_{1}^{2}-64 x_{1}^{4} x_{2}^{4} y_{2}^{2}+64 x_{1}^{2} x_{2}^{6} y_{1}^{2}\\
&+256 x_{1}^{2} x_{2}^{6} y_{2}^{2}+16 x_{1}^{4} x_{2}^{4}-64 x_{1}^{2} x_{2}^{6}+3 x_{1}^{6}+28 x_{1}^{4} x_{2}^{2}+80 x_{1}^{2} x_{2}^{4}+64 x_{2}^{6}\Big).
\end{split}
\end{equation*}

By evaluating system \eqref{WS-dev-1} at the fixed points $(x_1,x_2,y_1,y_2)=(-2,1,0,0)$ and $(x_1,x_2,y_1,y_2)=(2,-1,0,0)$ respectively, we find that the corresponding deviation equations have the same expression:
\begin{equation}\label{WS-dev-2}
\begin{split}
\frac{d^2\xi_1}{dt^2}+\frac{1}{4}\xi_1=0,\quad
\frac{d^2\xi_2}{dt^2}+\frac{1}{4}\xi_2=0.
\end{split}
\end{equation}

A direct computation shows that the general solutions to these equations are given by
\begin{equation}\label{WS-dev-3}
\begin{split}
\xi_1(t)=2\xi_{10}\sin\Big(\frac{t}{2}\Big),\quad
\xi_2(t)=2\xi_{20}\sin\Big(\frac{t}{2}\Big),
\end{split}
\end{equation}
where we have used the initial conditions $\xi_1(0)=\xi_2(0)=0$, $\dot{\xi}_1(0)=\xi_{10}$, $\dot{\xi}_2(0)=\xi_{20}$. It follows from \eqref{kcc-deviation-vector} that
\begin{equation}\label{WS-dev-4}
\begin{split}
||\xi(t)||^2=\frac{1}{\xi_{10}^2+\xi_{20}^2}\cdot\Big[(\xi_1(t))^2+(\xi_2(t))^2\Big]=4\sin^2\left(\frac{t}{2}\right)<t^2,\,\, t\approx0^+.\nonumber
\end{split}
\end{equation}
According to the KCC theory in Section \ref{sect2}, we prove that the fixed points $(-2,1)$ and $(2,-1)$ are also Jacobi stable.

In fact, it is easy to check that 
the expressions of the deviation equations in \eqref{WS-dev-1} are the same at the four fixed points $(\pm 2,\pm 1)$ and $(\pm 2,\mp 1)$. That is to say, these four fixed points have the same stability. This observation further verifies our conclusion. In the following, based on our computational results, we study the focusing/dispersing
behavior of the trajectories near the fixed points of the model \eqref{WS-1}. In order to save space, the dynamic behaviors of the model \eqref{WS-1} near the fixed points are put in Appendix \ref{sec-A}.


\subsection{Other Models and Remarks}\label{sect4.2}


\subsubsection{An Airfoil Model with Cubic Nonlinearity in Supersonic Flow}\label{sect4.2-1}

The aeroelastic model with cubic nonlinear pitching stiffness can be expressed as 
\begin{equation}\label{AM-1}
    \begin{split}
        &m\ddot{h}+S_{\alpha}\ddot{\alpha}+c_h\dot{h}+K_h h =L, \\
        &S_{\alpha}\ddot{h}+ I_{\alpha}\ddot{\alpha}+c_{\alpha}\dot{\alpha}+K_{\alpha}\alpha+eK_{\alpha}\alpha^3 = M,
    \end{split}
\end{equation}
where $m$ is the mass of the wing, $S_{\alpha}=mx_{\alpha}b$ is the wing mass static moment about the elastic axis, $I_{\alpha}=m(r_{\alpha}b)^2$ is the inertial moment of the wing about the elastic axis, $c_{h}$ and $c_{\alpha}$ are the linear plunging and pitching damping coefficients, $K_h$ and $K_{\alpha}$ are the plunging and pitching stiffness coefficients, $e$ is
the non-dimensional nonlinear stiffness coefficient, $b$ is the wing's semi-chord length, $h$ is the plunging displacement, $\alpha$ is the pitching angle, the superposed dots denote derivative with respect to time $t$, $L$ and $M$ are the aerodynamic force and moment. We refer to \cite{Librescu2003,Zheng2008} for the setting details of this example.


Introducing the following dimensionless variable
\begin{equation}
\begin{split}
\eta&=\frac{h}{b},\quad \tau=\frac{U_{\infty}}{b}t,\quad 
\omega_h=\sqrt{\frac{K_h}{m}},\quad \omega_{\alpha}=\sqrt{\frac{K_{\alpha}}{I_{\alpha}}},\\
\bar{\omega}&=\frac{\omega_h}{\omega_{\alpha}},\quad 
\mu=\frac{m}{4\rho_{\infty}b^2},\quad V=\frac{U_{\infty}}{b\omega_{\alpha}}\nonumber
\end{split}
\end{equation}
the dimensionless equations of motion for the airfoil can be written as (see \cite{Zheng2008} for the setting details)
\begin{equation}\label{AM-2}
\begin{split}
\ddot{\eta}+x_{\alpha} \ddot{\alpha}&+ 2\zeta_h \frac{\bar{\omega}}{V}\dot{\eta}+\left(\frac{\bar{\omega}}{V}\right)^2\eta=-\frac{1}{\mu M_{\infty}}\Bigg[\alpha+\dot{\eta}+(1-a)\dot{\alpha}\\&\qquad\quad+\frac{1}{12}M_{\infty}^2(1+k)\alpha^3\Bigg], \\
\frac{x_{\alpha}}{r_{\alpha}^2}\ddot{\eta}+\ddot{\alpha}& +2\zeta_{\alpha}\frac{1}{V}\dot{\alpha}+\frac{1}{V^2}\alpha+\frac{e}{V^2}\alpha^3=\\
        &\frac{1}{\mu M_{\infty}r_{\alpha}^2}\Bigg[(1-a)\alpha+(1-a)\dot{\eta}+\left(\frac{4}{3}-2a+a^2\right)\dot{\alpha}\\
        &+\frac{1}{12}M_{\infty}^2(1-a)(1+k)\alpha^3\Bigg],
    \end{split}
\end{equation}
where $M_{\infty}$ is the flight Mach number, $k$ is the isentropic gas coefficient. For easy reference and comparison, we take some of the parameter values for the airfoil constants suggested in \cite{Zheng2008}
\begin{equation}
\begin{split}
\mu&=50,\quad \bar{\omega}=1, \quad x_{\alpha}=\frac{1}{4},\quad a=r_{\alpha}^2=\frac{1}{2},\\
\zeta_h&=\zeta_{\alpha}=\frac{1}{10},\quad e=20,\quad k=\frac{7}{5}.\nonumber
\end{split}
\end{equation}
Let $\eta=x_1$, $\alpha=x_2$, $\dot{\eta}=y_1$, $\dot{\alpha}=y_2$, set $(x,y)=(x_1,x_2,y_1,y_2)$ and $\bar{\mu}=(M_{\infty},V)$. Then system \eqref{AM-2} can be further transformed into the following KCC standard form:
\begin{equation}\label{AM-3}
\begin{split}
\ddot{x}_1+2G^1(\bar{\mu},x,y)=0,\quad
\ddot{x}_2+2G^2(\bar{\mu},x,y)=0,
\end{split}
\end{equation}
where
\begin{equation}
\begin{split}
G^1&(\bar{\mu},x,y)=\frac{1}{2100 V^{2}M_{\infty}}\Big(6 V^{2} M_{\infty}^{2} x_{2}^{3}-6000 M_{\infty} x_{2}^{3}+30 V^{2} x_{2}+30 V^{2} y_{1}\\
&+19 V^{2} y_{2}+240 V M_{\infty} y_{1}-60 V M_{\infty} y_{2}+1200 M_{\infty} x_{1}-300 M_{\infty} x_{2}\Big),\\
G^2&(\bar{\mu},x,y)=-\frac{1}{5250 V^{2}M_{\infty}}\Big(18 V^{2} M_{\infty}^{2} x_{2}^{3}-60000 M_{\infty} x_{2}^{3}+90 V^{2} x_{2}+90 V^{2} y_{1}\\
&+85 V^{2} y_{2}+300 V M_{\infty} y_{1}-600 V M_{\infty} y_{2}+1500 M_{\infty} x_{1}-3000 M_{\infty} x_{2}\Big).\nonumber
\end{split}
\end{equation}

Our computational results of the model \eqref{AM-3} are summarized as the following theorem.
\begin{theorem}\label{KCC-math-airfoil}
The following statements hold for the aeroelastic airfoil model \eqref{AM-3}.

\begin{itemize}
    \item[(a)] System \eqref{AM-3} has exactly one Jacobi stable fixed point if and only if one of the following three conditions holds
\begin{equation}
\begin{split}  
\mathcal{C}_1=&[0<R_1,\,\, 0<R_2,\,\,0<R_4,\,\, 0<R_5,\,\, 0<R_6] \wedge \mathcal{C}^*,\\
\mathcal{C}_2=&[0<R_1,\,\, 0<R_2,\,\,0<R_3,\,\, R_4<0] \wedge \mathcal{C}^*,\\
\mathcal{C}_3=&[0<R_1,\,\, 0<R_2,\,\,0<R_3,\,\,0<R_4,\,\,R_5<0,\,\,0<R_6]\wedge \mathcal{C}^*,\nonumber
\end{split}
\end{equation}
where
\begin{equation}
\begin{split}
&R_1=-9450 V^{2} M_{\infty}-43 V^{2}+135 V M_{\infty}+621900 M_{\infty}^{2},\\
&R_2=1800 V^{4} M_{\infty}+1500 V^{3} M_{\infty}^{2}-15660000 V^{2} M_{\infty}^{3}+4 V^{4}+20 V^{3} M_{\infty}\\
&-123675 V^{2} M_{\infty}^{2}+297000 V M_{\infty}^{3}+769590000 M_{\infty}^{4},\\
&R_3=-V^{2}+50 M_{\infty},\\
&R_4=V^{2} M_{\infty}-5000,\\
&R_5=-18900 V^{4} M_{\infty}^{2}+43 V^{4} M_{\infty}-135 V^{3} M_{\infty}^{2}+795600 V^{2} M_{\infty}^{3}\\
&+47250000 V^{2} M_{\infty}-215000 V^{2}+675000 V M_{\infty}-1615500000 M_{\infty}^{2},\\
&R_6=3600 V^{6} M_{\infty}^{2}+3000 V^{5} M_{\infty}^{3}-31320000 V^{4} M_{\infty}^{4}-4 V^{6} M_{\infty}-20 V^{5} M_{\infty}^{2}\\
&-146325 V^{4} M_{\infty}^{3}-522000 V^{3} M_{\infty}^{4}+1579410000 V^{2} M_{\infty}^{5}-4500000 V^{4} M_{\infty}\\
&-532500000 V^{3} M_{\infty}^{2}+155250000000 V^{2} M_{\infty}^{3}+20000 V^{4}+100000 V^{3} M_{\infty}\\
&+56625000 V^{2} M_{\infty}^{2}+28485000000 V M_{\infty}^{3}-7829550000000 M_{\infty}^{4},\\
&\mathcal{C}^*=[(M_{\infty}-10)\cdot R_1\cdot R_2\cdot R_3\cdot R_4\cdot R_5\cdot R_6\neq0].
\nonumber
\end{split}
\end{equation}

    \item[(b)] System \eqref{AM-3} has exactly two Jacobi stable fixed points if and only if one of the following two conditions holds
\begin{equation}
\begin{split}  
\mathcal{C}_4=&[R_1<0,\,\, R_3<0,\,\,R_4<0,\,\, 0<R_5,\,\, 0<R_6] \wedge \mathcal{C}^*,\\
\mathcal{C}_5=&[0<R_1,\,\, R_2<0,\,\,R_3<0,\,\,R_4<0,\,\, 0<R_5,\,\, 0<R_6] \wedge \mathcal{C}^*.\nonumber
\end{split}
\end{equation}


\end{itemize}

\end{theorem}


In Figure \ref{fig:kcc-equilibria}, we provide partitions of the parameter sets $\mathcal{C}_1$ and $\mathcal{C}_5$ for distinct numbers of Jacobi stable fixed points. The focusing/dispersing
behaviors of the trajectories near the fixed points of the model \eqref{AM-3} are given in Appendix \ref{sec-B}.


