Applying Algorithm 2 to system \eqref{3D-1}, we obtain the deviation equations:
\begin{equation}\label{3D-dev-1}
    \begin{split}
        \frac{d^2 \xi_1}{dt^2}&=-\frac{K_1+K_2}{M_1}\xi_1+\frac{K_2}{M_1}\xi_2-\frac{C_1+C_2}{M_1}\frac{d\xi_1}{dt}+\frac{C_2}{M_1}\frac{d\xi_2}{dt},\\
        \frac{d^2 \xi_2}{dt^2}&=\frac{K_2}{M_2}\xi_1-\frac{K_2+K_3}{M_2}\xi_2+\frac{K_3}{M_2}\xi_3+\frac{C_2}{M_2}\frac{d\xi_1}{dt}-\frac{C_2+C_3}{M_2}\frac{d\xi_2}{dt}+\frac{C_3}{M_2}\frac{d\xi_3}{dt},\\
        \frac{d^2 \xi_3}{dt^2}&=-\frac{K_3}{M_3}\xi_2+\frac{K_3}{M_3}\xi_3-\frac{C_3}{M_3}\frac{d\xi_1}{dt}+\frac{C_3}{M_3}\frac{d\xi_2}{dt}.
    \end{split}
\end{equation}


