\subsection{Comparison of Learned Policies and Analytical Solution}
%
\begin{figure}[!t]
    \centering
    \includegraphics[width=1.0\linewidth]{Figures/safe_ranges_minmax.pdf}
    \caption{Promising perching range for each agent.  Horizontal bars show the minimum and maximum percentage change relative to nominal value in tether length ($\Delta\ell_{\text{tether}}$) and perching weight mass ($\Delta m_{\text{pw}}$), with promising perching result. The success rate within the displayed range is at least 80\%.}

    \label{fig:safe_range}
