\section{Introduction} \label{S:Intro}

\subsection{Classical Hecke \texorpdfstring{$L$}{L}-series}
We investigate special values of Hecke $L$-series attached to Carlitz cyclotomic fields. The motivating problem comes from $L$-functions of Jacobi sum Hecke characters~\cites{And86Taniyama, Lichtenbaum82, Schappacher}, where one defines a Hecke character $J_{K,\ba}$ on an abelian number field $K/\QQ$ depending on a parameter~$\ba$ in the free abelian group on $\QQ/\ZZ$.

Lichtenbaum~\cite{Lichtenbaum82}*{Thm.~3.1} proved that critical values $L(J_{K,\ba},n)$ are $\Qbar$-multiples of prescribed powers of $\pi$ and powers of special $\Gamma$-values $\Gamma(a/N)$, where $a/N \in \QQ$ depend on~$\ba$. He conjectured that these multiples were in fact in $\QQ$ up to a square root of the discriminant of $K$ or its maximal real subfield. A few years later Anderson~\cite{And86Taniyama}*{Thm.~2} proved Lichtenbaum's $\Gamma$-hypothesis using his theory of ulterior motives. For detailed accounts of $L$-functions of Jacobi sum Hecke characters, the reader is directed to~\cites{And86Taniyama, Lichtenbaum82, Schappacher}.

For example, if $\ba = 2[1/3] - [2/3]$ and $K = \QQ(\sqrt{-3})$, then the character $J_{K,\ba}$ is related to the elliptic curve $y^2 +y= x^3$ with complex multiplication by $O_K$. One finds
\[
L(J_{K,\ba},1) = \frac{\Gamma(1/3)^2}{9 \Gamma(2/3)}.
\]

\subsection{Anderson Hecke characters}
Turning to the setting of function fields, we let $A = \FF_q[\theta]$ be the polynomial ring in a variable~$\theta$ over the finite field $\FF_q$, and let $A_+$ denote its monic elements. We take $k = \FF_q(\theta)$ for the fraction field of $A$, $k_{\infty} = \laurent{\FF_q}{1/\theta}$ for the completion of $k$ at its infinite place, and $\C$ for the completion of an algebraic closure of~$k_{\infty}$. We let $\ok$ denote the algebraic closure of $k$ in $\C$. For $f \in A_+$ with $\deg f \geqslant 1$, we let $K = k(\zeta)$ denote the $f$-th Carlitz cyclotomic field (see \S\ref{SS:cyclodefs}) and $B \subseteq K$ the integral closure of~$A$ in~$K$. We let $b \mapsto \rho_b$ be the isomorphism $(A/fA)^{\times} \iso \Gal(K/k)$ such that $\rho_b(\zeta) = C_b(\zeta)$, where $C$ is the Carlitz module.

\begin{subsubsec}{Coleman functions}
Inspired by work of Coleman~\cite{Coleman88}, Anderson~\cite{And92} introduced soliton functions, which are functions on the product $X \times X$, where $X/\FF_q$ is a smooth projective curve for the function field $K$. Later, researchers replaced solitons in applications with more direct specializations called Coleman functions $g_{\ba} \in \ok(\bX)$ ($\bX = \ok \times_{\FF_q} X$) in~\cites{ABP04, SinhaPhD, Sinha97a, Sinha97b}. These functions possess explicit divisors
\[
\divf(g_{\ba}) = W_{\ba}^{(1)} - W_{\ba} + \Xi_{\ba} - I_{\ba}
\]
(see \S\ref{SS:Coleman}), which we use to define both Anderson's Hecke characters and Sinha's $t$-modules. Coleman functions play a similar role to shtuka functions for Drinfeld-Hayes modules as in~\cite{Thakur93}, and they underpin many results (e.g., see \cites{BP02, CPY10, ChangTW25, Thakur99, Wei22}).
\end{subsubsec}

\begin{subsubsec}{Hecke characters}
Using Jacobi sum Hecke characters as a model, Anderson~\cite{And92} defined a class of Hecke characters, later expanded by Sinha~\cite{Sinha97a},
\begin{equation}
\chi_{\ba} : \cI_{K,\ff} \to K^{\times}
\end{equation}
where $\ba$ is an element of the free abelian group $\cA_f$ on $f^{-1}A/A$, $\ff \subseteq B$ is the radical of~$fB$, and $\cI_{K,\ff}$ is the group of fractional ideals of $B$ prime to $\ff$. For $\fp$ a maximal ideal of $B$ relatively prime to~$f$, Anderson defines $\chi_{\ba}(\fp)$ by
\[
\chi_{\ba}(\fp) = \prod_{i=0}^{\ell - 1} g_{\ba}^{(i)}(\xi) \quad  \in K^{\times},
\]
where $\ell = [\FF_{\fp}:\FF_q]$ and $\xi \in \bX(K)$ is the generic point corresponding to the inclusion $K \hookrightarrow \C$. See \S\ref{SS:AndHecke}. Anderson proved that $\chi_{\ba}$ is an algebraic Hecke character for $K$ of conductor dividing~$\ff$ and designated infinity type $\Theta_{\ba} \in \ZZ[\Gal(K/k)]$ (see Theorem~\ref{T:AndHecke}). It aligns with work of Goss~\cite{Goss92a} and Hayes~\cite{Hayes93} on Hecke characters in function fields.
\end{subsubsec}

\begin{subsubsec}{Goss $L$-series}
In Theorem~\ref{T:GossLMainintro} and Corollary~\ref{C:HeckeLMainintro} below we prove special $L$-value formulas for Goss $L$-series attached to $\chi_{\ba}$,
\[
L(\chi_{\ba},s) = \prod_{\fp \nmid \ff} \biggl( 1 - \frac{\chi_{\ba}(\fp)}{\cN(\fp)^s} \biggr)^{-1}, \quad s \in \ZZ,
\]
which is a product over primes of $B$ not dividing $\ff$ and which takes values in $k_{\infty}(\zeta) \subseteq \C$ (see \S\ref{SSS:HeckeL}, \S\ref{E:AndHeckeLdef}). Previously, Sinha~\cite{Sinha97a} had proved a function field version of Deligne's conjecture on special $\Gamma$-values that showed that, when $\Gamma(\ba) \in \oK$, the Galois action on $\Gamma(\ba)$ transforms via $\chi_{\ba}$, namely that $\rho_{\fp}(\Gamma(\ba)) = \chi_{\ba}(\fp) \Gamma(\ba)$ for a Frobenius element $\rho_{\fp} \in \Gal(K^{\sep}/K)$. To our knowledge there has been little work on special values of $L(\chi_{\ba},s)$ to date.
\end{subsubsec}

\begin{subsubsec}{$\Pi$-factorial and special $\Pi$-values} \label{SSS:GammaPi}
In \cite{Thakur91}, Thakur defined the geometric factorial function $\Pi : \C \setminus(-A_+) \rightarrow \C$ via
\begin{equation} \label{E:Pi(x)def}
\Pi(x) \assign \prod_{a \in A_+} \biggl( 1 + \frac{x}{a} \biggr)^{-1}.
\end{equation}
It is related to the geometric $\Gamma$-function by $\Pi(x) = x\Gamma(x)$, and as such it is an analogue of the classical factorial. Thakur~\cite{Thakur91} proved several classes of functional equations for $\Gamma(x)$, which established it as an analogue of the classical $\Gamma$-function.

If $x \in k \setminus (-A_+)$, then we refer to $\Pi(x)$ as a \emph{special $\Pi$-value}. We note that special $\Pi$-values fall in~$k_{\infty}$, which will play an important role in calculating Taelman regulators (see Proposition~\ref{P:RegCalc}). Sinha~\cite{Sinha97b} demonstrated that certain special $\Pi$-values occur as periods of $t$-modules $E_{\ba}$ (see below, and  see Theorem~\ref{T:periodsintro}). Algebraic relations over $\ok$ on special $\Pi$-values have been studied extensively \cites{ABP04,BP02,CPY10,Sinha97b,Wei22}, by applying transcendence techniques in~\cites{ABP04, Yu97}, and in the present paper we show they arise naturally in values of $L$-functions (see Theorem~\ref{T:GossLMainintro} and Corollary~\ref{C:HeckeLMainintro}).
\end{subsubsec}

\subsection{Sinha modules}
Just as $L$-functions of Jacobi sum Hecke characters can be interpreted as factors in $L$-functions of abelian varieties, or more generally of motives (see \cites{And86Taniyama, Lichtenbaum82, Schappacher}), we begin our study of $L(\chi_{\ba},s)$ by analyzing more closely a family of Anderson $t$-modules with complex multiplication that were originally defined by Sinha~\cites{SinhaPhD, Sinha97b}. For an effective parameter $\ba \in \cA_f$ (all coefficients are non-negative) and $\deg \ba > 0$, Sinha used Anderson's theory of $t$-motives~\cite{And86} to define an Anderson $t$-module
\begin{equation}
E_{\ba} : \bA \to \Mat_d(\ok[\tau]),
\end{equation}
where $\bA = \FF_q[t]$ and $\tau$ is the $q$-th power Frobenius endomorphism. See \S\ref{SS:tmoddualtmot} for more information on $t$-modules.

The $t$-module $E_{\ba}$ possesses complex multiplication by $\bB \cong B$ with CM-type $\Xi_{\ba}$, as defined by Brownawell, Chang, Wei, and the second author in~\cites{BP02,BCPW22} (see Remark~\ref{R:EaCM}). It is coabelian ($\bA$-finite), has rank $r = [K:k] = \#(A/fA)^{\times}$, and has dimension $d = \deg(\ba)\cdot r/(q-1)$ (see Lemma~\ref{L:Haprops}). Sinha's constructions yield a $t$-module defined over~$\ok$, but he did not produce a field of definition. In order to analyze Goss $L$-functions for~$E_{\ba}$ our first main result is to clarify this situation (stated later as Theorem~\ref{T:EaKdef}).

\begin{theoremintro} \label{T:EaKdefintro}
Let $\ba \in \cA_f$ be effective with $\deg \ba > 0$. Then $E_{\ba}$ has a model defined over~$K$.
\end{theoremintro}

\begin{subsubsec}{The $t$-comotive for $E_{\ba}$}
The arguments to prove this theorem focus first on the construction of the $t$-comotive (``dual $t$-motive,'' see Remark~\ref{R:comotive})
\[
H_{\ba}(\ok) = H^0 \bigl(\bU,\cO_{\bX}(-W_{\ba}^{(1)}) \bigr), \quad
\bU = \Spec \ok \otimes_{\FF_q} \bB,
\]
from which we define $E_{\ba}$. See \S\ref{SS:Sinhadefs} for precise definitions. We recall that the operation of $\sigma = \tau^{-1}$ on $H_{\ba}(\ok)$ is provided through multiplication by the Coleman function $g_{\ba}$, which then plays the role of shtuka functions for Drinfeld-Hayes modules as in Thakur~\cite{Thakur93}.  These $t$-comotives were originally defined by Anderson, Brownawell, and the second author~\cite{ABP04}, and they are parallel to the $t$-motives defined by Sinha~\cite{Sinha97b}.

As constructed, $H_{\ba}(\ok)$ is a left $\ok[t,\sigma]$-module (see~\S\ref{SS:tmoddualtmot}), and it is an ideal of the coordinate ring $\ok[\bU]$ of the affine part $\bU$ of $\bX$. A first step toward Theorem~\ref{T:EaKdefintro} is showing~$g_{\ba}$ is defined over $B[f^{-1}]$ in Proposition~\ref{P:coldef}. But then a key difficulty in proving Theorem~\ref{T:EaKdefintro} is determining that $H_{\ba}(\ok)$ has a $\ok[\sigma]$-basis consisting of functions defined over $K$, which we prove in Proposition~\ref{P:HaKdef}. The methods revolve around dissecting the arguments in~\citelist{\cite{ABP04}*{\S 6.4} \cite{BCPW22}*{Thm.~4.2.2} \cite{Sinha97b}*{Thm.~3.2.5}} to devise an algorithm for producing $\ok[\sigma]$-bases of $H_{\ba}(\ok)$ explicitly in \S\ref{SS:Fodef}, leading to explicit computation of $E_{\ba}$ (see~\S\ref{S:examples}).
\end{subsubsec}

\begin{subsubsec}{Good reduction}
We address reduction modulo primes of $B$ and primes of good reduction for $E_{\ba}$ in~\S\ref{SS:reduction}. To define good reduction we adapt the point of view of Gardeyn~\cite{Gardeyn02}, requiring that the rank of a $t$-comotive and its reduction be the same. In Corollary~\ref{C:EaSigma} we confirm that~$E_{\ba}$ has a model with good reduction outside of a finite set of primes $\Sigma_{\ba}$ of $B$ containing the primes dividing~$f$. These conditions are sufficient to prove Theorem~\ref{T:GossLMainintro} and Corollary~\ref{C:HeckeLMainintro} below, but we prove in the appendix that for every prime $\fp$ of $B$ not dividing~$f$, there is a model for $E_{\ba}$ for which it has good reduction at $\fp$ (see Corollary~\ref{C:Eagoodprimes}).
\end{subsubsec}

\begin{corollaryintro} \label{C:Eagoodprimesintro}
Let $\ba \in \cA_f$ be effective with $\deg \ba > 0$, and let $\fp$ be a maximal ideal of $B$ relatively prime to $f$. Then $E_{\ba}$ has good reduction at~$\fp$.
\end{corollaryintro}

Another component in our special $L$-value formulas is the determination of the period lattice of $E_{\ba}$. These periods had already been computed by Sinha~\cite{Sinha97b}*{\S 5}, but as his $t$-modules were constructed using $t$-motives instead of $t$-comotives, they are not technically the same. However, in the setting of $t$-comotives, one can apply Anderson's exponentiation theorem (Theorem~\ref{T:Anderson}, see also \citelist{\cite{HartlJuschka20}*{\S 2.5} \cite{NamoijamP24}*{\S 3.4}}), which permits us to bypass some of the complications of~\cite{Sinha97b} stemming from rigid analysis and homological algebra.

\begin{subsubsec}{Rigid analytic trivializations of $H_{\ba}$}
A major input into Anderson's exponentiation theorem is a rigid analytic trivialization of the $t$-comotive (see \S\ref{SSS:AndExp}). Adapting arguments from~\cite{ABP04}*{\S 6.4}, we show in Proposition~\ref{P:PhiaPsiadiag} that a rigid analytic trivialization for~$H_{\ba}$ can be expressed in terms of the infinite product
\[
\cG_{\ba} = \prod_{N=1}^{\infty} g_{\ba}^{(N)},
\]
which is a product of Frobenius twists of $g_{\ba}$ taken in an extension of the Tate algebra $\TT_{\theta}$ (see Proposition~\ref{P:cGaf}, and also~\cite{Sinha97b}*{\S 5.1}, where similar products were investigated).
\end{subsubsec}

\begin{subsubsec}{Interpolation formulas}
For $\ba = \sum_a m_a [a/f] \in \cA_f$ we take $\Pi(\ba) = \prod_a \Pi(a/f)^{m_a}$. Anderson~\cite{And92}*{\S 5.3} (see also~\citelist{\cite{ABP04}*{\S 6.3} \cite{Sinha97b}*{\S 5.3}}) proved interpolation formulas for Coleman functions yielding for $b \in (A/fA)^{\times}$,
\[
\Pi(b \star\ba) = \cG_{\ba}(\xi_b)^{-1},
\]
where $\xi_b \in \bX(K)$ are generic points arising from the embeddings $K \hookrightarrow \C$ and $b \star \ba$ represents the star action. See \S\ref{SS:Coleman} for more information. Sinha~\cite{Sinha97b}*{\S 5.2.6, \S 5.3.9} showed that certain coordinates of periods of $E_{\ba}$ are expressible in terms of special $\Pi$-values. We extend Sinha's results to arbitrary coordinates using hyperderivatives on $\ok(\bX)$ (stated as Theorem~\ref{T:periods}). We say $\ba \in \cA_f$ is \emph{basic} if it is of the form $\ba = [a/f]$, and note that Sinha's evaluations in~\cite{Sinha97b}*{\S 5.3} revolve around these basic cases where $(a,f)=1$.
\end{subsubsec}

\begin{theoremintro} \label{T:periodsintro}
Let $\ba \in \cA_f$ be effective with $\deg \ba > 0$. Let $E_{\ba}$ be constructed with respect to a normalized $\ok[\sigma]$-basis on $H_{\ba}(\ok)$. The period lattice $\Lambda_{\ba}$ of $E_{\ba}$ has an $\bA$-basis $\pi_1, \dots, \pi_r$ so that for index sets $\cP_{\ba}$, $\cS_{\ba}$ defined in \S\ref{SSS:normalized}, the following hold.
\begin{alphenumerate}
\item For $1 \leqslant i \leqslant r$, with $\ell_a = \mult_{\xi_b}(\Xi_{\ba}) - 1$,
\[
\pi_i = \begin{pmatrix}
\vdots \\ \pd_t^{\ell_b - j} \bigl( z^{i-1} \cG_{\ba}^{-1} \bigr)\big|_{\xi_b} \\ \vdots
\end{pmatrix}_{(b,j) \in \cS_{\ba}}.
\]
The coordinate corresponding to $(b,\ell_b) \in \cS_{\ba}$ is $\rho_b(\zeta)^{i-1} \Pi (b \star \ba)$ \textup{(cf.~\cite{Sinha97b}*{\S 5.3})}.
\item When $\ba = [a/f]$ is basic, for $1 \leqslant i \leqslant r$,
\[
\pi_i = \begin{pmatrix}
\vdots \\ \rho_b(\zeta)^{i-1} \Pi\bigl( [ba/f] \bigr) \\ \vdots
\end{pmatrix}_{b \in \cP_{\ba}}.
\]
\end{alphenumerate}
\end{theoremintro}

\subsection{Special \texorpdfstring{$L$}{L}-values}
Our main results relate Goss $L$-functions for $E_{\ba}$ with $L$-functions for $\chi_{\ba}$, and then we prove special value formulas for them in terms of special $\Pi$-values.

\begin{subsubsec}{Goss $L$-functions for $E_{\ba}$}
For $\ba \in \cA_f$ effective with $\deg \ba > 0$, we pick a model $E_{\ba} : \bA \to \Mat_d(B[\tau])$ together with a finite set of primes $\Sigma_{\ba}$ of $B$, including all primes dividing $f$, outside of which $E_{\ba}$ has good reduction (see \S\ref{SSS:EaBmodel}). The Goss $L$-function is
\[
L( E_{\ba}^{\vee}/K,\Sigma_{\ba},s) = \prod_{\fp \notin \Sigma_{\ba}} Q_{\ba,\fp}^{\vee} \bigl( \cN(\fp)^{s} \bigr)^{-1}, \quad s \in \ZZ,
\]
where $Q_{\ba,\fp}^{\vee}(X)$ is the reciprocal polynomial of the characteristic polynomial of the Frobenius at $\fp$ acting on the dual of the Tate module $T_{\lambda}(E_{\ba})$ (see \S\ref{SSS:GossLtmod}).
\end{subsubsec}

\begin{subsubsec}{Identities with Hecke $L$-series}
Letting $\psi_{\ba} = \chi_{-\ba}$, we prove in Proposition~\ref{P:Lidentities},
\[
L(E_{\ba}^{\vee}/K,\Sigma_{\ba},s) = \prod_{b \in (A/fA)^{\times}} L(\psi_{\ba}^{\rho_b}, \Sigma_{\ba},s) = L(\psi_{\ba},\Sigma_{\ba},s)^r.
\]
We obtain the first side of this identity by computing the characteristic polynomials of Frobenius of $E_{\ba}$ using techniques of~\cite{HuangP22} and relating them to $\psi_{\ba}$ (cf.~\cite{DebryPhD}*{\S 3.3.5}). The second part utilizes Galois symmetry (see Lemma~\ref{L:chiaGalsymm}).
\end{subsubsec}

\begin{subsubsec}{$L$-value identities}
The main tools for evaluating Goss $L$-functions are rooted in the work of Taelman~\cites{Taelman09, Taelman10, Taelman12}. For the $t$-modules $E_{\ba}$ we apply $L$-value formulas of Fang~\cite{Fang15}, which as in Taelman's identities equate $L(E_{\ba}^{\vee}/K,\Sigma_{\ba},0)$ with the product of a regulator term $\Reg(E_{\ba}/B) \in k_{\infty}^{\times}$ and a class module term $\rh(E_{\ba}/B) \in A_+$ (see \S\ref{SS:Taelman}). We appeal also to constructions of Angl\`es, Ngo Dac, Pellarin, and Tavares Ribeiro~\cites{ANT17b, ANT20, ANT22, APT18, AT17}. Although the model for $E_{\ba}$ used to construct $L(E_{\ba}^{\vee}/K,\Sigma_{\ba},s)$ may have bad reduction at some primes not dividing~$f$, Corollary~\ref{C:Eagoodprimesintro} permits defining $L(E^{\vee}/K,s)$ that avoids only Euler factors for $\fp \mid f$ (see Remark~\ref{R:LnoSigmas}). The following theorem and corollary (stated as Theorem~\ref{T:GossLMain} and Corollary~\ref{C:HeckeLMain}) assume that $(a,f)=1$, but the full results for $(a,f)\neq 1$ are in \S\ref{SS:specialLvalues}.
\end{subsubsec}

\begin{theoremintro} \label{T:GossLMainintro}
Let $\ba = [a/f] \in \cA_f$ be basic with $(a,f)=1$, and fix $E_{\ba}: \bA \to \Mat_d(B[\tau])$ as in \S\ref{SSS:EaBmodel}. There is $C_{\rR} \in \ok^{\times}$ with $\sgn(C_{\rR})=1$ and
\[
C_{\rR}^{r} \in \begin{cases}
k^{\times} &\text{if $r$ is even,} \\ 
K^{\times}\ \text{and}\ C_{\rR}^{2r} \in k^{\times} &\text{if $r$ is odd;}
\end{cases}
\]
$C_{\rH} \in \ok^{\times}$ with $\sgn(C_{\rH}) = 1$ so that $\rh(E_{\ba}/B) = C_{\rH}^r$; and $C_{\rE} \in K^{\times}$ with $C_{\rE}^{r} \in k^{\times}$ and $\sgn(C_{\rE}) = 1$, so that
\[
L(E_{\ba}^{\vee}/K,0) = C_{\rR}^r \cdot C_{\rH}^r \cdot C_{\rE}^r  \cdot \prod_{\substack{b \in A_+ \\ \deg b < \deg f \\ (b,f)=1}} \Pi(b/f)^r.
\]
\end{theoremintro}

The constants $C_{\rR}$, $C_{\rH}$, and $C_{\rE}$, arise from calculations for the regulator, class module, and extra Euler factors respectively, and typically depend on the model for $E_{\ba}$ (see \S\ref{SS:specialLvalues}).

\begin{corollaryintro} \label{C:HeckeLMainintro}
Under the same conditions as Theorem~\ref{T:GossLMainintro},
\[
L(\psi_{\ba},0) = C_{\rR} \cdot C_{\rH} \cdot C_{\rE} \cdot \prod_{\substack{b \in A_+ \\ \deg b < \deg f \\ (b,f)=1}} \Pi(b/f).
\]
\end{corollaryintro}

\begin{remark}
These special value formulas rely on $\ba$ being basic in a fundamental way. By Theorem~\ref{T:periodsintro}, the coordinates of periods of $E_{\ba}$ are $B$-multiples of elements of $k_{\infty}$, and as such the period lattice comprises a portion of Taelman's regulator lattice when computing $\Reg(E_{\ba}/B)$. When $\ba$ is basic, the rank of $\Lambda_{\ba}$ is the same as the rank of the regulator lattice, and thus up to a multiple from $A_+$ the regulator can be determined from the period lattice (see Remark~\ref{R:basic} and Proposition~\ref{P:RegCalc}).
When $\ba$ is not basic, $\Lambda_{\ba}$ forms a submodule of strictly smaller rank than the regulator lattice, and there are additional contributions to $\Reg(E_{\ba}/B)$ coming from as yet to be determined logarithms.
\end{remark}

\subsection{Outline}
After preliminary discussions in \S\ref{S:Prelim}, we review information on Carlitz cyclotomic fields, Coleman functions, and Anderson Hecke characters in~\S\ref{S:cyclo}. We investigate refined properties of Sinha modules $E_{\ba}$ in~\S\ref{S:Sinha}, especially rigid analytic properties of their $t$-comotives in~\S\ref{SS:analyticSinha} and fields of definition in~\S\ref{SS:Fodef}. In~\S\ref{S:GossHeckeL} we prove our main results on Goss and Hecke $L$-series for $E_{\ba}$ and $\psi_{\ba}$, and we provide examples in \S\ref{S:examples}. Finally in \S\ref{App:GoodRed} we characterize primes of good reduction for $E_{\ba}$.

