\section{Primes of good reduction} \label{App:GoodRed}

We prove here that the primes $\fp$ of $B$ not dividing $f$ are primes of good reduction for $E_{\ba}$, as mentioned in \S\ref{SS:reduction}. The key arguments rely on analyses of the relationships between Sinha $t$-comotives over $K$ and over $\FF_{\fp}$.

\subsection{Good reduction of \texorpdfstring{$H_{\ba}$}{Ha} and \texorpdfstring{$E_{\ba}$}{Ea}} \label{SS:appdualtmot}
We review some generalities for reductions of function spaces modulo $\fp$. For a divisor $D \in \Div_K(\bX)$ such that $\cL(D) \subseteq \ok[t,z]$, we let
\[
\cL(D,B_{\fp}) \assign \cL(D) \cap B_{\fp}[t,z].
\]
Because $D$ is defined over $K$, as in \S\ref{SS:AndHecke} it can be interpreted as a sum $\cD$ of horizontal divisors on the curve $\cX = B_{\fp} \times_{\FF_q} X$ over $\Spec B_{\fp}$. As such we can identify $\cL(D,B_{\fp}) = H^0(\cX/B_{\fp},\cO_{\cX/B_{\fp}}(\cD))$, and moreover,
\[
K \otimes_{B_{\fp}} \cL(D,B_{\fp}) = \cL(D) \cap K[t,z] = H^0(X/K,\cO_{X/K}(D)) \rassign \cL(D,K).
\]
The Riemann-Roch theorem~\cite{Rosen}*{Thm.~5.4} implies that $\cL(D)$ has a $\ok$-basis consisting of elements in $K[t,z]$, so in particular
\[
\cL(D) = \ok \otimes_{K} \cL(D,K) = \ok \otimes_{B_{\fp}} \cL(D,B_{\fp}).
\]
Now let
\[
\cL(\oD,\FF_{\fp}) \assign H^0(X,\cO_X(\oD)) \cap \FF_{\fp}[t,z] = H^0(X/\FF_{\fp},\cO_{X/\FF_{\fp}}(\oD)),
\]
and consider the reduction map
\begin{equation} \label{E:pidef}
\pi : \cL(D,B_{\fp}) \to \cL(\oD,\FF_{\fp}).
\end{equation}
Clearly, $\ker \pi = \cL(D,B_{\fp}) \cap \fp B_{\fp}[t,z] = \fp \cL(D,B_{\fp})$. If we let $P = \im \pi$, then $P$ is a finite dimensional $\FF_{\fp}$-vector space, and
\begin{equation} \label{E:LDBp}
P \cong \cL(D,B_{\fp})/\fp\cL(D,B_{\fp}).
\end{equation}
By Nakayama's lemma \cite{LangAlg}*{\S X.4}, if we pick $\alpha_1, \dots, \alpha_n \in \cL(D,B_{\fp})$ such that $\oalpha_1, \dots, \oalpha_n$ is an $\FF_{\fp}$-basis of~$P$, then $\alpha_1, \dots, \alpha_n$ are a $B_{\fp}$-basis of $\cL(D,B_{\fp})$. Hence they also form a $K$-basis of $\cL(D,K)$, and therefore,
\begin{equation} \label{E:reddim}
\dim_{K} \cL(D,K) \leqslant \dim_{\FF_{\fp}} \cL(\oD,\FF_{\fp}).
\end{equation}
Now since $\bX$ is simply the extension of scalars to~$\ok$ of the smooth projective irreducible curve $X/\FF_q$, both $\bX$ and $X$ have the same genus, say~$\gamma$. In the case that $\deg D = \deg \oD > 2\gamma -2$, the Riemann-Roch theorem assures us that~\eqref{E:reddim} is an equality.

We apply these considerations to the situation of \S\ref{SS:Fodef}.
As in~\eqref{E:Midef}, for $i \in \ZZ$ we let $M_i = \cL(-W_{\ba}^{(1)} + i I_{\ba})$ and $\oM_i = \cL( -\oW_{\ba}^{(1)} + i I_{\ba})$. We write
\[
M_i(B_{\fp}) = M_i \cap B_{\fp}[t,z] = \cL(-W_{\ba}^{(1)} + i I_{\ba},B_{\fp}), \quad M_i(K) = M_i \cap K[t,z],
\]
and
\[
\oM_i(\FF_{\fp}) = \oM_i \cap \FF_{\fp}[t,z] = \cL(-\oW_{\ba}^{(1)} + i I_{\ba},\FF_{\fp}).
\]
We have reduction maps for each $i \in \ZZ$,
\begin{equation} \label{E:piidef}
\pi_i : M_i(B_{\fp}) \to \oM_i(\FF_{\fp}).
\end{equation}
For $N \geqslant 0$ taken from Lemma~\ref{L:Miprops}(g) and its proof, we obtain that for $i \geqslant N-1$,
\[
\dim_K M_i(K) = \dim_{\FF_{\fp}} \oM_i(\FF_{\fp}) \quad \Rightarrow \quad
\pi_i(M_i(B_{\fp})) = \oM_i(\FF_{\fp}).
\]
In particular,
\[
\pi_{N-1}(M_{N-1}(B_{\fp})) =\oM_{N-1}(\FF_{\fp}), \quad
\pi_N(M_N(B_{\fp})) = \oM_{N}(\FF_{\fp}).
\]
The maps $\{ \pi_i \}$ form maps of directed systems and induce
\[
\pi : \bigcup_{i=0}^{\infty} M_i(B_{\fp}) \to \bigcup_{i=0}^{\infty} \oM_i(\FF_{\fp}), \quad \bigl(= H_{\ba,\fp}(\FF_{\fp}) \bigr).
\]
We now prove a straightforward lemma on extending bases on two-dimensional arrays of vector spaces. Throughout we let `$\sqcup$' denote a disjoint union.

\begin{lemma} \label{L:triangle-v2}
Let $N \geqslant0$, and let $\{ V_{i,j} \mid 0 \leqslant i \leqslant j \leqslant N \}$ be (finite dimensional) vector spaces over a field~$F$. Suppose we have injective $F$-linear maps
\begin{align*}
\rho_{i,j} : V_{i,j-1} &\hookrightarrow V_{i,j}, \quad &&(0 \leqslant i < j \leqslant N), \\
\delta_{i,j} : V_{i-1,j} &\hookrightarrow V_{i,j}, \quad &&(0 < i \leqslant j \leqslant N),
\end{align*}
such that for $0 < i < j \leqslant N$,
\[
\delta_{i,j} \circ \rho_{i-1,j} = \rho_{i,j} \circ \delta_{i,j-1} : V_{i-1,j-1} \to V_{i,j},
\]
and the induced map
\[
V_{i-1,j-1} \iso V_{i,j-1} \times_{V_{i,j}} V_{i-1,j}
\]
is an isomorphism. Then for $0 \leqslant i \leqslant j \leqslant N$, we can pick (finite) subsets $D_{i,j}$, $R_{i,j}$, $Z_{i,j} \subseteq V_{i,j}$ such that the following hold.
\begin{alphenumerate}
\item $Z_{i,j}$ is a basis of $V_{i,j}$ for $0 \leqslant i \leqslant j \leqslant N$.
\item $Z_{i,j} = \delta_{i,j}(Z_{i-1,j}) \sqcup D_{i,j}$ for $0 < i \leqslant j \leqslant N$.
\item $Z_{i,j} = \rho_{i,j}(Z_{i,j-1}) \sqcup R_{i,j}$ for $0 \leqslant i < j \leqslant N$.
\item For $0 < i < j \leqslant N$, 
\[
Z_{i,j} = (\delta_{i,j} \circ \rho_{i-1,j})(Z_{i-1,j-1}) \sqcup \rho_{i,j}(D_{i,j-1}) \sqcup \delta_{i,j}(R_{i-1,j}) \sqcup (D_{i,j} \cap R_{i,j}).
\]
\end{alphenumerate}
\end{lemma}

\begin{proof}
The diagram to keep in mind is the following,
\begin{equation} \label{E:triangle-v2}
\begin{tikzcd}[row sep=scriptsize, column sep=scriptsize]
V_{0,0} \arrow[r, hook, "\rho_{0,1}"]
&V_{0,1} \arrow[r, hook, "\rho_{0,2}"] \arrow[d, hook, "\delta_{1,1}"]
&V_{0,2} \arrow[r, hook] \arrow[d, hook, "\delta_{1,2}"]
&\cdots \arrow[r,hook]
&V_{0,N} \arrow[d, hook, "\delta_{1,N}"]
\\
& V_{1,1} \arrow[r, hook, "\rho_{1,2}"]
& V_{1,2} \arrow[r, hook] \arrow[d, hook, "\delta_{2,2}"]
& \cdots \arrow[r, hook]
& V_{1,N} \arrow[d, hook, "\delta_{2,N}"]
\\
& & V_{2,2} \arrow[r, hook]
& \cdots \arrow[r, hook]
& V_{2,N} \arrow[d, hook]
\\
& & & \ddots & \vdots \arrow[d, hook]
\\
& & & & V_{N,N}.
\end{tikzcd}
\end{equation}
For $0 \leqslant i \leqslant j \leqslant N$, we define $D_{i,j}$, $R_{i,j}$, and $Z_{i,j}$ recursively. We let $Z_{0,0} = D_{0,0} = R_{0,0}$ be any basis of $V_{0,0}$. For $0 < j \leqslant N$, if $Z_{0,j-1}$ has been defined, we choose $R_{0,j}$ so that $Z_{0,j} \assign \rho_{0,j}(Z_{0,j-1}) \sqcup R_{0,j}$ is a basis for $V_{0,j}$. For convenience we set $D_{0,j} \assign R_{0,j}$. The sets $R_{0,j}$, $Z_{0,j}$ for $0 \leqslant j \leqslant N$ then satisfy parts (a) and~(c) as desired.
For $0 < i \leqslant N$, suppose that $Z_{i-1,i}$ has been defined. We pick $D_{i,i} \subseteq V_{i,i}$ so that $Z_{i,i} \assign \delta_{i,i}(Z_{i-1,i}) \sqcup D_{i,i}$ is a basis of $V_{i,i}$. For convenience we set $R_{i,i} \assign D_{i,i}$.

For $0 < i < j \leqslant N$ suppose that $Z_{i-1,j-1}$, $Z_{i,j-1}$, $Z_{i-1,j}$, $D_{i,j-1}$, and $R_{i-1,j}$ have been defined. As such, by hypothesis
\[
Z_{i,j-1} = \delta_{i,j-1}(Z_{i-1,j-1}) \sqcup D_{i,j-1}, \quad Z_{i-1,j} = \rho_{i-1,j}(Z_{i-1,j-1}) \sqcup R_{i-1,j}.
\]
Consider the augmented square from~\eqref{E:triangle-v2},
\begin{center}
\begin{tikzcd}
V_{i-1,j-1} \arrow[r, hook, "\rho_{i-1,j}"] \arrow[d, hook, "\delta{i,j-1}"]
& V_{i-1,j} \arrow[d, hook]  \arrow[dr, bend left=20, "\delta_{i,j}"]& \\
V_{i,j-1} \arrow[r,hook] \arrow[rr, bend right=20, "\rho_{i,j}"']
& \rho_{i,j}(V_{i,j-1}) + \delta_{i,j}(V_{i-1,j}) \arrow[r, hook] & V_{i,j}.
\end{tikzcd}
\end{center}
Because $V_{i-1,j-1} \cong V_{i,j-1} \times_{V_{i,j}} V_{i-1,j}$, we conclude that
\[
\rho_{i,j}(V_{i,j-1}) \cap \delta_{i,j}(V_{i-1,j}) = (\delta_{i,j} \circ \rho_{i-1,j})(V_{i-1,j-1}).
\]
Thus $(\delta_{i,j} \circ \rho_{i-1,j})(Z_{i-1,j-1}) \sqcup \rho_{i,j}(D_{i,j-1}) \sqcup \delta_{i,j}(R_{i-1,j})$ is a basis of $\rho_{i,j}(V_{i,j-1}) + \delta_{i,j}(V_{i-1,j})$, and so we can pick $Y \subseteq V_{i,j}$ so that
\[
Z_{i,j} \assign (\delta_{i,j} \circ \rho_{i-1,j})(Z_{i-1,j-1}) \sqcup \rho_{i,j}(D_{i,j-1}) \sqcup \delta_{i,j}(R_{i-1,j}) \sqcup Y
\]
is a basis for $V_{i,j}$. We then set
\[
D_{i,j} \assign \rho_{i,j}(D_{i,j-1}) \sqcup Y, \quad
R_{i,j} \assign \delta_{i,j}(R_{i-1,j}) \sqcup Y.
\]
In particular, $D_{i,j} = \rho_{i,j}(D_{i,j-1}) \sqcup (D_{i,j} \cap R_{i,j})$ and $R_{i,j} = \delta_{i,j}(R_{i-1,j}) \sqcup (D_{i,j} \cap R_{i,j})$.
Properties (b)--(d) then follow.
\end{proof}

\begin{proposition} \label{P:Hagoodred}
Let $\ba \in \cA_f$ be effective with $\deg \ba > 0$, and let $\fp$ be a maximal ideal of~$B$ relatively prime to $f$. Then $H_{\ba}(\ok)$ has a $\ok[\sigma]$-basis $\{ h_1, \dots, h_d \} \subseteq B_{\fp}[t,z]$ such that $\{ \oh_1, \dots, \oh_d \} \subseteq \FF_{\fp}[t,z]$ is an $\FF_{\fp}[\sigma]$-basis of $H_{\ba,\fp}(\FF_{\fp})$.
\end{proposition}

\begin{proof}
We construct our $\ok[\sigma]$-basis of $H_{\ba}(\ok)$ through Proposition~\ref{P:HaKdef}, namely using the recursion in \S\ref{SSS:UVTSdefs} and Remark~\ref{R:algorithm}.
We first define a sequence $\{ \oP_i \}_{i \in \ZZ}$ of $\FF_{\fp}$-subspaces of $H_{\ba,\fp}(\FF_{\fp})$. For $i < 0$, we set $\oP_i = \{ 0 \}$, and as in \eqref{E:piidef}, for $i \geqslant 0$ we take
\begin{equation}
\oP_i \assign \pi(M_i(B_{\fp})) = \pi_i(M_i(B_{\fp})).
\end{equation}
We consider the following diagram of finite dimensional $\FF_{\fp}$-vector spaces, where for $0 \leqslant i \leqslant j \leqslant N$, the $i$-th row is filtration of $\oM_{i}(\FF_{\fp})$ and the $j$-th column is a filtration of $\oP_j$,
\begin{equation} \label{E:triangleMP}
\begin{tikzcd}[row sep=scriptsize, column sep=small]
\oP_0 \arrow[r, hook]
&\oM_0(\FF_{\fp}) \cap \oP_1 \arrow[r, hook] \arrow[d, hook]
&\oM_0(\FF_{\fp}) \cap \oP_2 \arrow[r, hook] \arrow[d, hook]
&\cdots \arrow[r,hook]
&\oM_0(\FF_{\fp}) \cap \oP_N = \oM_0(\FF_{\fp}) \arrow[d, hook]
\\
& \oP_1 \arrow[r, hook]
& \oM_1(\FF_{\fp}) \cap \oP_2 \arrow[r, hook] \arrow[d, hook]
& \cdots \arrow[r, hook]
& \oM_1(\FF_{\fp}) \cap \oP_N = \oM_1(\FF_{\fp}) \arrow[d, hook]
\\
& & \oP_2 \arrow[r, hook]
& \cdots \arrow[r, hook]
& \oM_2(\FF_{\fp}) \cap \oP_N = \oM_2(\FF_{\fp}) \arrow[d, hook]
\\
& & & \ddots & \vdots \arrow[d, hook]
\\
& & & & \oM_N(\FF_{\fp}) \cap \oP_N = \oP_N.
\end{tikzcd}
\end{equation}
We are in the situation of Lemma~\ref{L:triangle-v2} with $V_{i,j} = \oM_i(\FF_\fp) \cap \oP_j$. The maps $\delta_{i,j}$, $\rho_{i,j}$, in Lemma~\ref{L:triangle-v2} are inclusions and can be suppressed. Thus, for $0 \leqslant i \leqslant j \leqslant N$, we select
\[
\oD_{i,j},\ \oR_{i,j},\ \oZ_{i,j} \subseteq \oM_i(\FF_{\fp}) \cap \oP_j,
\]
such that $\oZ_{i,j}$ is an $\FF_{\fp}$-basis of $\oM_i(\FF_{\fp}) \cap \oP_j$ and $\oD_{i,j}$, $\oR_{i,j}$ satisfy the conclusions in Lemma \ref{L:triangle-v2}. Accordingly, $\oZ_{0,0} = \oR_{0,0}$, and after repeated applications of Lemma~\ref{L:triangle-v2}(b)--(c),
\[
\oZ_{i,j} = \biggl( \bigsqcup_{0 < \ell \leqslant j} \oR_{0,\ell} \biggr) \sqcup \biggl( \bigsqcup_{0 < k \leqslant i} \oD_{k,j} \biggr), \quad (0 \leqslant i \leqslant j \leqslant N).
\]
In particular for $0 \leqslant i \leqslant N$,
\begin{gather*}
\oP_i = \biggl( \bigoplus_{0 \leqslant \ell \leqslant i} \Span_{\FF_{\fp}} (\oR_{0,\ell}) \biggr) \oplus \biggl( \bigoplus_{0 < k \leqslant i} \Span_{\FF_{\fp}} (\oD_{k,i}) \biggr), \\
\oM_i(\FF_{\fp})  = \biggl( \bigoplus_{0 \leqslant \ell \leqslant N} \Span_{\FF_{\fp}} (\oR_{0,\ell}) \biggr) \oplus \biggl( \bigoplus_{0 < k \leqslant i} \Span_{\FF_{\fp}} (\oD_{k,N}) \biggr) = \oP_i \oplus \biggl( \bigoplus_{i < \ell \leqslant N} \Span_{\FF_{\fp}} (\oR_{i,\ell}) \biggr). \notag
\end{gather*}
Now as $\{ \oM_i(\FF_{\fp}) \}$ satisfies the criteria of \S\ref{Cr:Mi}, we can construct an $\FF_{\fp}[\sigma]$-basis of $H_{\ba,\fp}(\FF_{\fp})$ using Proposition~\ref{P:HaKdef}, namely the construction in~\S\ref{SSS:UVTSdefs} together with Lemma \ref{L:Silinind}. Following along with~\S\ref{SSS:UVTSdefs}, we construct $\FF_{\fp}$-bases $\{ \oS_i \}$ and $\{ \oT_i \}$. We can take
\[
\oT_0 \assign \oR_{0,0} \sqcup \dots \sqcup \oR_{0,N},
\]
and we set $\oT_{0,j} \assign \oR_{0,j}$ for $0 \leqslant j \leqslant N$.
By the construction in~\S\ref{SSS:UVTSdefs}, for $i > 0$, $\oT_i$ is selected by choosing an $\FF_{\fp}$-basis of $\oM_i(\FF_{\fp})/(\oM_{i-1}(\FF_{\fp}) + \sigma \oM_{i-1}(\FF_{\fp}))$.
We have inclusions
\begin{multline*}
\frac{\oP_i + (\oM_{i-1}(\FF_{\fp}) + \sigma \oM_{i-1}(\FF_{\fp}))}{\oM_{i-1}(\FF_{\fp}) + \sigma \oM_{i-1}(\FF_{\fp})} \subseteq \frac{(\oM_i(\FF_{\fp}) \cap \oP_{i+1}) + (\oM_{i-1}(\FF_{\fp}) + \sigma \oM_{i-1}(\FF_{\fp}))}{\oM_{i-1}(\FF_{\fp}) + \sigma \oM_{i-1}(\FF_{\fp})} \\
{}\subseteq \dots \subseteq
\frac{(\oM_i(\FF_{\fp}) \cap \oP_{N}) + (\oM_{i-1}(\FF_{\fp}) + \sigma \oM_{i-1}(\FF_{\fp}))}{\oM_{i-1}(\FF_{\fp}) + \sigma \oM_{i-1}(\FF_{\fp})} = \frac{\oM_i(\FF_{\fp})}{\oM_{i-1}(\FF_{\fp}) + \sigma \oM_{i-1}(\FF_{\fp})}.
\end{multline*}
From this we see that we can select $\oT_i$ to be a union of subsets of bases of
\[
\oP_i \subseteq (\oM_i(\FF_{\fp}) \cap \oP_{i+1}) \subseteq \cdots \subseteq (\oM_i(\FF_{\fp}) \cap \oP_{N-1}) \subseteq \oM_i(\FF_{\fp}).
\]
However, since $\oM_{i-1}(\FF_{\fp}) + \sigma \oM_{i-1}(\FF_{\fp}) \supseteq \oM_{i-1}(\FF_{\fp})$, these subsets do not come from the rows $< i$ in~\eqref{E:triangleMP}. Therefore, for $i \leqslant j \leqslant N$, using Lemma~\ref{L:triangle-v2}(d), we can go back and choose $\oD_{i,j}$, $\oR_{i,j}$, with
\begin{equation} \label{E:oTijdef}
\oT_{i,j} \subseteq \oD_{i,j} \cap \oR_{i,j} \quad \textup{so that} \quad
\oT_i \assign \oT_{i,i} \sqcup \cdots \sqcup \oT_{i,N}
\end{equation}
induces an $\FF_{\fp}$-basis of $\oM_i(\FF_{\fp})/(\oM_{i-1}(\FF_{\fp}) + \sigma \oM_{i-1}(\FF_{\fp}))$ as desired.  By \S\ref{SSS:UVTSdefs} and Remark~\ref{R:algorithm}, $\oS_{0} = \oT_0 = \oT_{0,0} \sqcup \cdots \sqcup \oT_{0,N}$, and for $1 \leqslant i \leqslant N$,
\[
\oS_i = \bigsqcup_{0 \leqslant k \leqslant i} \oT_k =  \bigsqcup_{\substack{0 \leqslant k \leqslant i \\ k \leqslant \ell \leqslant N}} \oT_{k,\ell} \quad \Rightarrow \quad \oS_N = \bigsqcup_{0 \leqslant k \leqslant \ell \leqslant N} \oT_{k,\ell}.
\]
In particular $\oS_N$ is an $\FF_{\fp}[\sigma]$-basis of $H_{\ba,\fp}(\FF_{\fp})$.

Now we consider $M_i(B_{\fp})$ for $0 \leqslant i \leqslant N$, and the $B_{\fp}$-submodules, for $0 \leqslant i \leqslant j \leqslant N$,
\begin{equation}
\cM_{i,j} \assign \pi_j^{-1} \bigl( \oM_{i}(\FF_{\fp}) \bigr) = \pi_j^{-1} \bigl( \oM_i(\FF_{\fp}) \cap \oP_j \bigr) \subseteq M_j(B_{\fp}).
\end{equation}
We can fashion a similar diagram to~\eqref{E:triangleMP} by placing $\cM_{i,j}$ in each entry, and we note from the definition of $\oP_i$ that
\[
\cM_{i,i} = \pi_i^{-1} \bigl( \oM_{i}(\FF_{\fp}) \cap \oP_i \bigr) = M_i(B_{\fp}), \quad 0 \leqslant i \leqslant N.
\]
Furthermore, for $0 \leqslant i \leqslant j \leqslant N$,
\[
\pi_j (\cM_{i,j}) = \oM_i(\FF_{\fp}) \cap \oP_j,
\]
as $\pi_j$ surjects onto $\oP_j$ by construction. For $0 \leqslant j \leqslant N$, by the discussion in~\eqref{E:LDBp}, Nakayama's lemma implies that $M_j(B_{\fp})$ is a free $B_{\fp}$-module of finite rank, and
\[
\rank_{B_{\fp}} M_j(B_{\fp}) = \dim_{\FF_{\fp}} \oP_j, \quad (0 \leqslant j \leqslant N).
\]
More generally, for $0 \leqslant i \leqslant j \leqslant N$, we have the exact sequence of $B_{\fp}$-modules,
\begin{equation} \label{E:Mijseq}
0 \to \cM_{i,j} \cap \fp M_j(\FF_{\fp}) \to \cM_{i,j} \xrightarrow{\pi_j} \oM_{i}(\FF_{\fp}) \cap \oP_j \to 0,
\end{equation}
and
\begin{equation} \label{E:2ndiso}
\frac{\cM_{i,j}}{\cM_{i,j} \cap \fp M_j(B_{\fp})} \cong
\frac{\cM_{i,j} + \fp M_j(B_{\fp})}{\fp M_j(B_{\fp})} \subseteq
\frac{M_j(B_{\fp})}{\fp M_j(B_{\fp})}.
\end{equation}
Thus,
\[
\dim_{\FF_{\fp}} \biggl( \frac{\cM_{i,j} + \fp M_j(B_{\fp})}{\fp M_j(B_{\fp})} \biggr) = \dim_{\FF_{\fp}} \bigl( \oM_i(\FF_{\fp}) \cap \oP_j \bigr)
\leqslant \rank_{B_{\fp}} M_j(B_{\fp}).
\]
For $0 \leqslant i \leqslant j \leqslant N$, we set
\[
\cV_{i,j} \assign \frac{\cM_{i,j} + \fp M_j(B_{\fp})}{\fp M_j(B_{\fp})} = \frac{\pi_j^{-1}(\oM_i(\FF_{\fp})) + \fp M_j(B_{\fp})}{\fp M_j(B_{\fp})},
\]
and we note
\[
\cV_{i,i} = \frac{M_i(B_{\fp}) + \fp M_i(B_{\fp})}{\fp M_i(B_{\fp})} = \frac{M_i(B_{\fp})}{\fp M_i(B_{\fp})}, \quad (0 \leqslant i \leqslant N).
\]
We define $\FF_{\fp}$-linear maps
\[
\rho_{i,j} : \cV_{i,j-1} \to \cV_{i,j},\ (0 \leqslant i < j \leqslant N), \quad
\delta_{i,j} : \cV_{i-1,j} \to \cV_{i,j}, \ (0 < i \leqslant j \leqslant N),
\]
by the natural maps
\begin{align*}
\rho_{i,j} &: \frac{\pi_{j-1}^{-1}(\oM_i(\FF_{\fp})) + \fp M_{j-1}(B_{\fp})}{\fp M_{j-1}(B_{\fp})} \to \frac{\pi_j^{-1}(\oM_i(\FF_{\fp})) + \fp M_j(B_{\fp})}{\fp M_j(B_{\fp})}, \\
\delta_{i,j} &: \frac{\pi_{j}^{-1}(\oM_{i-1}(\FF_{\fp})) + \fp M_{j}(B_{\fp})}{\fp M_{j}(B_{\fp})} \to \frac{\pi_j^{-1}(\oM_i(\FF_{\fp})) + \fp M_j(B_{\fp})}{\fp M_j(B_{\fp})}.
\end{align*}
It is clear that $\delta_{i,j}$ is injective for $0 < i \leqslant j \leqslant N$. Furthermore, for $0 \leqslant i < j \leqslant N$,
\[
\bigl( \pi_{j-1}^{-1} \bigl( \oM_i(\FF_{\fp}) \bigr) + \fp M_{j-1}(B_{\fp}) \bigr) \cap \fp M_j(B_{\fp}) \subseteq M_{j-1}(B_{\fp}) \cap \fp M_j(B_{\fp}) = \fp M_{j-1} (B_{\fp}),
\]
so $\rho_{i,j}$ is injective. Now for $0 < i < j \leqslant N$, we have $\delta_{i,j} \circ \rho_{i-1,j} = \rho_{i,j} \circ \delta_{i,j-1} : \cV_{i-1,j-1} \to \cV_{i,j}$, and we consider the induced map, $\phi : \cV_{i-1,j-1} \to \cV_{i,j-1} \times_{\cV_{i,j}} \cV_{i-1,j}$. Moreover, we have
\begin{multline*}
\phi : \frac{\pi_{j-1}^{-1}(\oM_{i-1}(\FF_{\fp})) + \fp M_{j-1}(B_{\fp})}{\fp M_{j-1}(B_{\fp})} \\
\to
\frac{\pi_{j-1}^{-1}(\oM_{i}(\FF_{\fp})) + \fp M_{j-1}(B_{\fp})}{\fp M_{j-1}(B_{\fp})} \times_{\cV_{i,j}}
\frac{\pi_{j}^{-1}(\oM_{i-1}(\FF_{\fp})) + \fp M_{j}(B_{\fp})}{\fp M_{j}(B_{\fp})}, 
\end{multline*}
where the right-hand term consists of pairs $(\alpha,\beta)$ for which $\rho_{i,j}(\alpha) = \delta_{i,j}(\beta)$, and for $x \in \pi_{j-1}^{-1}(\oM_{i-1}(\FF_{\fp}))$,
\[
\phi \bigl( x + \fp M_{j-1}(B_{\fp}) \bigr) =
\bigl( x + \fp M_{j-1}(B_{\fp}), x + \fp M_j(B_{\fp}) \bigr).
\]
We see easily that $\phi$ is injective. To see that $\phi$ is surjective, suppose that $y \in \pi_{j-1}^{-1}(\oM_{i}(\FF_{\fp}))$ and $z \in \pi_{j}^{-1}(\oM_{i-1}(\FF_{\fp}))$ satisfy $\rho_{i,j} ( y + \fp M_{j-1}(B_{\fp})) = \delta_{i,j} ( z + \fp M_{j}(B_{\fp}))$.
That is,
\[
y + \fp M_j(B_{\fp}) = z + \fp M_j(B_{\fp}).
\]
But then $\pi_j(z) = \pi_j(y) = \pi_{j-1}(y)$. Since $\pi_j(z) \in \oM_{i-1}(\FF_{\fp})$ and $\pi_{j-1}(y) \in \oM_i(\FF_{\fp})$, we see that $\pi_{j-1}(y) \in \oM_{i-1}(\FF_{\fp})$, and so $y \in \pi_{j-1}^{-1}(\oM_{i-1}(\FF_{\fp}))$. Furthermore,
\[
\phi \bigl( y + \fp M_{j-1}(B_{\fp}) \bigr) = \bigl( y + \fp M_{j-1}(B_{\fp}), y + \fp M_j(B_{\fp}) \bigr) = \bigl( y + \fp M_{j-1}(B_{\fp}), z + \fp M_j(B_{\fp}) \bigr),
\]
and thus $\phi$ is surjective.

Therefore, the $\FF_{\fp}$-vector spaces $\{ \cV_{i,j} \mid 0 \leqslant i \leqslant j \leqslant N \}$ together with corresponding maps $\delta_{i,j}$, $\rho_{i,j}$, satisfy the hypotheses of Lemma~\ref{L:triangle-v2}. Furthermore, the isomorphisms
\[
\cV_{i,j} \iso \oM_i(\FF_{\fp}) \cap \oP_{j},
\]
induced by \eqref{E:Mijseq}--\eqref{E:2ndiso}, are compatible so that
\begin{equation} \label{E:alignment}
\bigl\{ \cV_{i,j} \mid 0 \leqslant i \leqslant j \leqslant N \bigr\} \quad \stackrel{\sim}{\longleftrightarrow} \quad \bigl\{ \oM_{i} \cap \oP_j \mid 0 \leqslant i \leqslant j \leqslant N \bigr \}
\end{equation}
are isomorphic systems satisfying the hypotheses of Lemma~\ref{L:triangle-v2}. In this way, the $\FF_{\fp}$-bases $\oZ_{i,j}$ obtained from Lemma~\ref{L:triangle-v2} for $\{ \oM_i(\FF_{\fp}) \cap \oP_j \}$ can be transferred to $\{ \cV_{i,j} \}$ with the same properties (and vice versa). Furthermore, for $0 \leqslant i \leqslant N$, the inclusions $\cV_{0,i} \subseteq \cV_{1,i} \subseteq \cdots \subseteq \cV_{i,i}$ are
\[
\frac{\pi_i^{-1}(\oM_0(\FF_{\fp})) + \fp M_i(B_{\fp})}{\fp M_i(B_{\fp})} \subseteq \frac{\pi_i^{-1}(\oM_1(\FF_{\fp})) + \fp M_i(B_{\fp})}{\fp M_i(B_{\fp})} \subseteq \cdots \subseteq  \frac{M_i(B_{\fp})}{\fp M_i(B_{\fp})}.
\]
Applying Nakayama's lemma we find subsets $D_{k,i} \subseteq \pi_i^{-1}(\oM_{k}(\FF_{\fp}))$ for $0 \leqslant k \leqslant i$ so that
\begin{equation} \label{E:ZiMidef}
Z_{i} \assign D_{0,i} \sqcup \cdots \sqcup D_{i,i}
\end{equation}
is a $B_{\fp}$-basis of $M_i(B_{\fp})$ with $\pi(Z_i) = \oZ_{i,i}$. Since $\pi_i(\pi_i^{-1}(\oM_k(\FF_{\fp}))) = \oM_k(\FF_{\fp}) \cap \oP_i$, these can be arranged so that
\[
\pi_i(D_{k,i}) = \oD_{k,i}, \quad (0 \leqslant k \leqslant i \leqslant N).
\]

Before the final analysis, we need to investigate compatibility with the bases $\oT_i$ coming from $\oM_i(\FF_{\fp}) / (\oM_{i-1}(\FF_{\fp}) + \sigma \oM_{i-1}(\FF_{\fp}))$. To that end, we recall from Lemma~\ref{L:Miprops}(c) and Remark~\ref{R:Kdef} that, for $i > 0$, $M_{i-1} + \sigma M_{i-1}$ is defined over $K$, and moreover,
\[
M_{i-1} + \sigma M_{i-1} = \cL(-W_{\ba}^{(1)} + (i-1)I_{\ba}) + \cL(-W_{\ba}^{(1)} - \Xi_{\ba} + i I_{\ba}).
\]
We set
\begin{align*}
(M_{i-1} + \sigma M_{i-1})(B_{\fp}) &\assign (M_{i-1} + \sigma M_{i-1}) \cap B_{\fp}[t,z], \\
(M_{i-1} + \sigma M_{i-1})(K) &\assign (M_{i-1} + \sigma M_{i-1}) \cap K[t,z],
\end{align*}
and note that since $M_{i-1} + \sigma M_{i-1}$ is defined over $K$,
\[
(M_{i-1} + \sigma M_{i-1})(K) = K \otimes_{B_{\fp}} (M_{i-1} + \sigma M_{i-1})(B_{\fp}).
\]
We claim that the $B_{\fp}$-modules
\[
\frac{M_i(B_{\fp})}{M_{i-1}(B_{\fp})}, \quad
\frac{M_i(B_{\fp})}{(M_{i-1} + \sigma M_{i-1})(B_{\fp})},
\]
are torsion free. Let us consider the second module. Suppose that $h \in M_i(B_{\fp})$ and $u \in B_{\fp}$ with $uh \in (M_{i-1} + \sigma M_{i-1})(B_{\fp})$. Then $h \in (M_{i-1} + \sigma M_{i-1})(K)$, and so
\begin{multline*}
h \in (M_{i-1} + \sigma M_{i-1})(K) \cap M_i(B_{\fp}) \\
= (M_{i-1} + \sigma M_{i-1})(K) \cap M_i(K) \cap B_{\fp}[t,z] = (M_{i-1} + \sigma M_{i-1})(B_{\fp}).
\end{multline*}
The argument for the first module is similar. In particular, as $M_{i-1}(B_{\fp}) \subseteq (M_{i-1} + \sigma M_{i-1})(B_{\fp}) \subseteq M_i(B_{\fp})$ are all free $B_{\fp}$-modules of finite rank, we find that a $B_{\fp}$-basis for $M_{i-1}(B_{\fp})$ can be extended to bases of both $(M_{i-1} + \sigma M_{i-1})(B_{\fp})$ and $M_i(B_{\fp})$.

We can construct the sets $\{ S_i \}$, $\{ T_i \}$, in \S\ref{SSS:UVTSdefs} by using $B_{\fp}$-bases of $M_i(B_{\fp})/(M_{i-1} + \sigma M_{i-1})(B_{\fp})$. Moreover, we have a filtration,
\[
\frac{\pi_i^{-1}(\oM_k(\FF_{\fp})) + (M_{i-1} + \sigma M_{i-1})(B_{\fp})}{(M_{i-1} + \sigma M_{i-1})(B_{\fp})} \subseteq \frac{M_i(B_{\fp})}{(M_{i-1} + \sigma M_{i-1})(B_{\fp})}, \quad (0 \leqslant k \leqslant i),
\]
of free $B_{\fp}$-modules of finite rank. For $0 \leqslant k \leqslant i$, since $\pi_i(\pi_i^{-1}(\oM_k(\FF_{\fp}))) = \oM_k(\FF_{\fp}) \cap \oP_i$, it follows from Nakayama's lemma that
\begin{multline*}
\rank_{B_{\fp}} \biggl( \frac{\pi_i^{-1}(\oM_k(\FF_{\fp})) + (M_{i-1} + \sigma M_{i-1})(B_{\fp})}{(M_{i-1} + \sigma M_{i-1})(B_{\fp})} \biggr) \\
\geqslant \dim_{\FF_{\fp}} \biggl( \frac{(\oM_k(\FF_{\fp}) \cap \oP_{i}) + (\oM_{i-1}(\FF_{\fp}) + \sigma \oM_{i-1}(\FF_{\fp}))}{\oM_{i-1}(\FF_{\fp}) + \sigma \oM_{i-1}(\FF_{\fp})} \biggr).
\end{multline*}
Therefore, after perhaps rearranging our $B_{\fp}$-basis $Z_{i}$ of $M_i(B_{\fp})$ from~\eqref{E:ZiMidef}, we can pick a subset $T_{k,i} \subseteq Z_{i}$ which induces a $B_{\fp}$-basis of $(\pi_i^{-1}(\oM_k(\FF_{\fp})) + (M_{i-1} + \sigma M_{i-1})(B_{\fp})) / (M_{i-1}$ $+ \sigma M_{i-1})(B_{\fp}))$, such that
\begin{equation} \label{E:Tki}
\pi_i(T_{k,i}) \supseteq \oT_{k,i}.
\end{equation}
Moreover, we can take $T_i = T_{0,i} \sqcup \dots \sqcup T_{i,i}$ to be our choice of subset of $M_i$ that induces a $\ok$-basis of $M_{i}/(M_{i-1} + \sigma M_{i-1})$ as in~\S\ref{SSS:UVTSdefs}.

As noted, $\oS_N$ is an $\FF_{\fp}[\sigma]$-basis of $H_{\ba,\fp}(\FF_{\fp})$. Proposition~\ref{P:HaKdef} and Remark~\ref{R:algorithm} imply
\[
S_N \assign \bigsqcup_{0 \leqslant i \leqslant N} T_i = \bigsqcup_{\substack{0 \leqslant i \leqslant N \\ 0 \leqslant k \leqslant i}} T_{k,i} = \bigsqcup_{0 \leqslant k \leqslant i  \leqslant N} T_{k,i}
\]
is a $\ok[\sigma]$-basis of $H_{\ba}(\ok)$. But then by~\eqref{E:Haprankdim},
\[
d = |S_N| = \sum_{i=0}^{N} \sum_{k=0}^i |T_{k,i}| \geqslant \sum_{i=0}^{N} \sum_{k=0}^i |\oT_{k,i}| = |\oS_N| = d.
\]
Therefore, this inequality is an equality, and the containments in~\eqref{E:Tki} are also equalities. Furthermore, $S_N$ satisfies $\pi(S_N) = \oS_N$, and we are done.
\end{proof}

The following corollary is then a consequence of Propositions~\ref{P:Eagoodred} and~\ref{P:Hagoodred}.

\begin{corollary} \label{C:Eagoodprimes}
Let $\ba \in \cA_f$ be effective with $\deg \ba > 0$, and let $\fp$ be a maximal ideal of $B$ relatively prime to $f$. Then $E_{\ba}$ has good reduction at~$\fp$.
\end{corollary}

