		\section{Proof of Threshold Saturation for single-sided SC-PCCs} \label{appx:proof}
		For the single-sided SC-PCC ensembles with $\lambda_0=\hdots=\lambda_m=\frac{1}{m+1}$, i.e. $\lambda = \frac{m}{m+1}$ and coupled subsequences are of equal lengths, the DE equations for information bits in \eqref{DE:HSC_PCC} become
		\begin{subequations}\label{DE:HSC_PCC1}
			\begin{align}
				& \bar{\mathsf{p}}_{1,\U,t}\vhead{\ell}=F_1\Bigg( \frac{\varepsilon}{m+1}\sum^m_{j=0}  \mathsf{p}_{1,\L,t+j}\vhead{\ell-1}  , \ev\Bigg), \\
				& \bar{\mathsf{p}}_{1,\L,t}\vhead{\ell}=F_1\Bigg(\frac{\varepsilon}{m+1}\sum^m_{j=0}  \mathsf{p}_{1,\U,t-j}\vhead{\ell-1} ,\ev\Bigg).
			\end{align}
		\end{subequations}
		Note that unlike the conventional SC-PCCs \cite{Moloudi-scTurbo}, the coupling structures in the upper and lower RSC encoders are asymmetric. Let $x_t\vhead{\ell} \triangleq \frac{1}{m+1}\sum^m_{j=0}  \mathsf{p}_{1,\U,t-j}\vhead{\ell}$. We can rewrite the DE equations \eqref{DE:HSC_PCC1} into
		\begin{subequations}
			\begin{align}
				x_t\vhead{\ell}=&\frac{1}{m+1}\sum^m_{j=0}F_1\Bigg(\frac{\varepsilon}{m+1}\sum^m_{k=0}F_1\Big(\varepsilon x_{t-j+k}\vhead{\ell-2} ,\ev\Big),\ev\Bigg) \\
				=&\frac{1}{m+1}\sum^m_{j=0}f\Bigg(\frac{1}{m+1}\sum^m_{k=0}g\Big(x_{t-j+k}\vhead{\ell-2} \Big); \varepsilon\Bigg),\label{eq:trs_pcc1}
			\end{align}
		\end{subequations}
		where \eqref{eq:trs_pcc1} follows by letting $f(x;\varepsilon) =g(x)= F_1(\varepsilon x,\ev)$. It is easy to verify that $f(x;\varepsilon)$ and $g(x)$ form a scalar admissible system \cite[Def. 1]{Yedla-threshold_satruation}. By \cite[Th. 1]{Yedla-threshold_satruation}, for any $\varepsilon < \varepsilon_{\text{MAP}}$, the only fixed point of the recursion in \eqref{eq:trs_pcc1} is $\boldsymbol{x}\vhead{\infty} = \big[ x_t\vhead{\infty}, \hdots ,x_T\vhead{\infty} \big] = \boldsymbol{0}$ as $T \rightarrow \infty$, $m \rightarrow \infty$, and $T \gg m$.

		Table \ref{tb:scpcc} compares the BP decoding thresholds $\ebp$ of single-sided SC-PCC$(m=1)$ with the MAP decoding thresholds $\emap$ of the uncoupled ensemble. One can see that the BP decoding threshold of single-sided SC-PCC$(m=1,\lambda_1=0.5)$, i.e. the HSC-PCC$(m=1)$, approaches the MAP decoding thresholds for all considered rates. 

