 then  
 \begin{align*}  & \|  f\|^2_{\mathcal D^{\sigma }_{\alpha, k}}  =  \alpha   |f(\frac{1}{2})|^2 + (1-\sigma)^2 \pi \sum_{n=0}^\infty  \frac{1}{n+1} | a_n|^2     
  \\
  &  +  \frac{\sigma^2 }{\alpha^2 }  \sum_{n,m=0}^\infty  (n+1)(m+1) a_{n+1} \bar a_{m+1}             \lim_{
