&  +  (1-\sigma) \sigma \frac{1}{\alpha}   \sum_{n,m=0}^\infty  (m+1) \left(\bar a_{m+1} a_n \frac{z^n {(\bar z)}^{m+ 1-\alpha }}{ e _{k-1}( {(\bar z)}^{\alpha})} +  a_{m+1} \bar a_n \frac{z^{m+ 1-\alpha } {(\bar z)}^n}{e_{k-1} ({z}^{\alpha}) } \right). 
