\begin{proof}
Follows from direct computations and  note  that $k=1$ implies  $e_{k-1} (w) =1$, and  if $k=\infty$ then $e_{k-1} (w) =\textrm{exp}(w) =e^w$ for all $w\in \mathbb C$.
\end{proof}

\begin{prop}\label{CReprodProp} Reproducing property. 
Suppose  $\sigma\in (0,1)$ and $f\in \textrm{Hol}(\mathbb D)$ such that $\dfrac{ {d}^{\sigma}}{ d z _{\alpha, k} } f $ belongs to the complex  Bergman space associated to $\mathbb D$. Then
\begin{align*}
& f (z)   
 = -  \frac{ \sigma }{1-\sigma  }\frac{  f   '(z) }{ \alpha  z^{ \alpha-1}  e_{k-1} ( z^{\alpha})     } +  \frac{ 1 }{1-\sigma  }  \int_{\mathbb D} B(z,\zeta)  \frac{ {d}^{\sigma}}{ d z _{\alpha, k} } f(\zeta) d_{\zeta}\mu 
 \end{align*} 
  and 
  \begin{align*}
 &  f(z) =  \textrm{exp}[\dfrac{\sigma-1}{\sigma}  ( \  e_k ((\frac{1}{2})^{\alpha}) - e_k (z^{\alpha}) \  ) ] f(\frac{1}{2}) +  \int_{\mathbb D} \mathcal K_{\frac{1}{2}}(z,\zeta)   \frac{ {d}^{\sigma}}{ d z _{\alpha, k} } f(\zeta) d_{\zeta}\mu, 
\end{align*}
where
$$ \mathcal K_{\frac{1}{2}}(z,\zeta) =  \textrm{exp}[\dfrac{1-\sigma}{\sigma}  e_k (z^{\alpha}) ]  \int_{\gamma_{\frac{1}{2}, z}}  \frac{1}{\sigma}  \textrm{exp}[\dfrac{\sigma-1}{\sigma}  e_k (w^{\alpha}) ]\left(\frac{d}{dw}    e_k (w^{\alpha}) \right)     B(w,\zeta) dw , $$ 
 $B(\cdot, \cdot)$ is the Bergman kernel associated to $\mathbb D$ and $\gamma_{\frac{1}{2}, z}$ is a rectifiable path contained in $\mathbb D \setminus (-1,0]$ from 
  $\frac{1}{2}$ to  $z$.
\end{prop}

\begin{proof} The reproducing property of the Bergman kernel  gives us directly the  first  identity since 
\begin{align*}
& (1-\sigma )f (z) +    \sigma \frac{  f   '(z) }{ \alpha  z^{ \alpha-1}  e_{k-1} ( z^{\alpha})     }  
 =  \int_{\mathbb D} B(z,\zeta)  \frac{ {d}^{\sigma}}{ d z _{\alpha, k} } f(\zeta) d_{\zeta}\mu .
 \end{align*}
 On the other hand, using Proposition \ref{pro1} we see that  
 \begin{align*}
& \frac{d}{dz} \left(\textrm{exp}[\dfrac{\sigma-1}{\sigma}  e_k (z^{\alpha}) ] f(z) \right) \\
=&  \int_{\mathbb D} \frac{1}{\sigma}  \textrm{exp}[\dfrac{\sigma-1}{\sigma}  e_k (z^{\alpha}) ]\left(\frac{d}{dz}    e_k (z^{\alpha}) \right)     B(z,\zeta)  \frac{ {d}^{\sigma}}{ d z _{\alpha, k} } f(\zeta) d_{\zeta}\mu. 
\end{align*} 
Therefore, 
\begin{align*} 
& \textrm{exp}[\dfrac{\sigma-1}{\sigma}  e_k (z^{\alpha}) ] f(z) =  \textrm{exp}[\dfrac{\sigma-1}{\sigma}  e_k ((\frac{1}{2})^{\alpha}) ] f(\frac{1}{2}) \\ 
 &+  \int_{\mathbb D} \left(  \int_{\gamma_{\frac{1}{2}, z}}  \frac{1}{\sigma}  \textrm{exp}[\dfrac{\sigma-1}{\sigma}  e_k (w^{\alpha}) ]\left(\frac{d}{dw}    e_k (w^{\alpha}) \right)     B(w,\zeta) dw\right) \frac{ {d}^{\sigma}}{ d z _{\alpha, k} } f(\zeta) d_{\zeta}\mu. 
\end{align*}
\end{proof}

\begin{rem}\label{RemDirchlet-Bergman}
If we chose $\sigma=\alpha^2$ then we obtain the family of function spaces 
  $(\mathcal D^{\alpha^2}_{\alpha, k} )_{\alpha \in (0,1]}$ and its respective fractal fractional derivative is given by
  \begin{align*}  \frac{ {d}^{\alpha^2 }}{ d z _{\alpha, k} }f (z)  = (1-\alpha^2)f (z) +   \alpha z^{\alpha -1 }\frac{ f   '(z) }{   e ( z^{\alpha})_{k -1}    },
 \quad \forall   f\in C^1(\mathbb D ,\mathbb C ),  
\end{align*}
for all $z\in \mathbb D$.  Note the  fact  $\alpha =0$  is allowed  
\begin{align*}  \frac{ {d}^{0 }}{ d z _{0, k} }f (z)  =  f (z), \quad \forall  f\in C^1(\mathbb D ,\mathbb C )    \end{align*} 
for all $z\in \mathbb D$,  although we probably do not have many of the results demonstrated above. In addition for $\alpha =1$ we see that  
\begin{align*}  \frac{ {d}^{1 }}{ d z _{1, k} }f (z)  =   \frac{ f   '(z) }{   e ( z )_{k -1}    },
 \quad \forall   f\in C^1(\mathbb D ,\mathbb C ),  
\end{align*}
for all $z\in \mathbb D$. 

Therefore, in case  $k=1$  we see that  the family of function spaces    $(\mathcal D^{\alpha^2 }_{\alpha, 1} )_{\alpha \in [0,1]}$ contains the Bergman space, $\mathcal D^{0 }_{0, 1} $, and the Dirichlet space, $\mathcal D^{1}_{1, 1}$, both associated to $\mathbb D\setminus(-1,0]$.
\end{rem}

\section{Quaternionic slice regular fractal-fractional Dirichlet type spaces}\label{Sec5}
\begin{defn} 
Given $\alpha \in (0,1]$, a quaternionic fractal measures is  given in terms of the quaternionic exponential truncated as follows: 
$q\mapsto e_k(q^{\alpha})$ for $k\in \mathbb N\cup\{0\}$ such that mapping $e_{k-1}(q^{\alpha}) \neq 0$ for all $q\in  \mathbb E := \mathbb B\setminus (-1,0]$, where $(-1,0]$ consists of $q$ such that  ${\bf q}$ is the vector zero and $ -1 < q_0 \leq 0 $.  

Consider the mappings $\chi_0, \chi_1\in C((0, 1) \times \mathbb E, \mathbb R)$ such that 
$$\lim_{\sigma\to 0^+} \chi_1(\sigma,q) = 1, \lim_{\sigma\to 0^+} \chi_0(\sigma,q) = 0, \lim_{\sigma\to 1^-} \chi_1(\sigma,q) = 0, \lim_{\sigma\to 1^-} \chi_0(\sigma,q) = 1,$$
for all $q\in   \mathbb E$. 
Given $\beta \in (0,1] $ and  ${\bf i}\in \mathbb S^2$ then the  quaternionic  generalized fractal-fractional  ${\bf i}$-derivative of $f\in \mathcal{SR}(\mathbb E)$, the zero set of $f\mid_{\mathbb E_{\bf i}}$ is the empty set, is given   as follows: 
\begin{align*}
& \frac{ {d}^{\sigma,\beta}}{ d q _{\alpha, k  , {\bf i} } } f\mid_{\mathbb E_{\bf i}} (z)\\
: = & \chi_1(\sigma, z)  f\mid_{\mathbb E_{\bf i}} (z) + \chi_0(\sigma, z) \lim_{\zeta\to z} \left(e _k( z^{\alpha}) - e _k( \zeta^{\alpha}) \right)^{-1} \left(f\mid_{\mathbb E_{\bf i}} ^{\beta} (z) - f\mid_{\mathbb E_{\bf i}} ^{\beta} (\zeta) \right),   
\end{align*}
for all $z\in\mathbb E_{\bf i}$.   
\end{defn} 

\begin{prop}
The quaternionic generalized fractal-fractional ${\bf i}$-derivative of $f\in \mathcal{SR}(\mathbb E)$ such that $f ^{\beta}\in  \mathcal{SR}(\mathbb E)$ and the zero set of $f\mid_{\mathbb E_{\bf i}}$ is the empty set  is given by  
\begin{align*}
& \frac{ {d}^{\sigma,\beta}}{ d q _{\alpha, k , {\bf i} } } f\mid_{\mathbb E_{\bf i}} (z)\\
= & \chi_1(\sigma, z) f\mid_{\mathbb E_{\bf i}} (z) + \chi_0(\sigma,z)(\alpha z^{\alpha-1} \ast e _k( z^{\alpha})')^{-\ast} \ast (f\mid_{\mathbb E_{\bf i}} ^{\beta})' (z), \quad \forall z\in\mathbb E_{\bf i},
\end{align*}
where $(f ^{\beta})'$ and $e _k( q^{\alpha})'$ are Cullen derivatives of the slice regular functions $f^{\beta}$ and $e _k( q^{\alpha})$, respectively. 
\end{prop}

\begin{proof}
\begin{align*}
& \frac{{d}^{\sigma,\beta}}{dq_{\alpha, k}}_{\bf i}f\mid_{\mathbb E_{\bf i}} (z) = \chi_1(\sigma, z)  f\mid_{\mathbb E_{\bf i}} (z)  \\
& + \chi_0(\sigma, z)  \lim_{\zeta\to z} \left(e _k( z^{\alpha}) - e _k( \zeta^{\alpha}) \right)^{-1} (z-\zeta)^{-1}(z-\zeta) \left(f\mid_{\mathbb E_{\bf i}} ^{\beta}  (z) -  f\mid_{\mathbb E_{\bf i}} ^{\beta}  (\zeta) \right)  \\
= & \chi_1(\sigma, z)   f\mid_{\mathbb E_{\bf i}} (z)   +   \chi_0(\sigma,z)   ( e _k( z^{\alpha})' ) ^{-\ast}   \ast  (f\mid_{\mathbb E_{\bf i}} ^{\beta})' (z), \quad \forall z\in\mathbb E_{\bf i} \\
= & \chi_1(\sigma, z)   f\mid_{\mathbb E_{\bf i}} (z) + \chi_0(\sigma,z) (\alpha z^{\alpha-1} \ast e _k( z^{\alpha})')^{-\ast} \ast (f\mid_{\mathbb E_{\bf i}}^{\beta})' (z), \quad \forall z\in\mathbb E_{\bf i}.
\end{align*}
Finally, note that  the mapping  $ q\mapsto (\alpha q^{\alpha-1} \ast e _k( q^{\alpha})' ) ^{-\ast} $ for all $q\in \mathbb E$ is an   intrinsic slice regular function 
\end{proof}

\begin{rem}
According to the previous proposition and if the zero set of $f$ is the empty, then 
\begin{align*}  
\frac{{d}^{\sigma,\beta}}{dq_{\alpha, k, {\bf i}}} f(q) = & \chi_1(\sigma, q) f(q) + \chi_0(\sigma,q)  
  (\alpha q^{\alpha-1} \ast e _k( q^{\alpha})') ^{-\ast} \ast (f ^{\beta})' (q), 
\end{align*}  
for all $q\in \mathbb E$. 
\end{rem}

\begin{defn}
Let ${\bf i}\in \mathbb S^2$ then by $\mathfrak D^{\sigma,\beta}_{\alpha, k,{\bf i}}$ we denote the function set formed by   
$f\in \mathcal {SR}(\mathbb E)$ such that the zero set of $f\mid_{\mathbb E_{\bf i}}$ is the empty set and 
\begin{align*}  
\int_{\mathbb E_{\bf i}} \|\frac{{d}^{\sigma,\beta}}{dq_{\alpha, k, {\bf i}}} f \mid_{ \mathbb E_{\bf i}}(z)\|^2 d_z\mu_{\bf i} < \infty. 
\end{align*}

The function set $\mathfrak D^{\sigma,\beta}_{\alpha, k,{\bf i}}$ is  called ${\bf i}-\beta$ generalized fractal-fractional Dirichlet  type set of slice regular functions induced by $\frac{ {d}^{\sigma,\beta}}{ d q _{\alpha, k, {\bf i}}}$ and associated to $\mathbb E$. 
\end{defn}
\begin{rem}
There are several cases to consider on $\mathfrak D^{\sigma,\beta}_{\alpha, k,{\bf i}}$, however, we will restrict our attention to the case $\beta=1$ because $\dfrac{{d}^{\sigma,1}}{dq_{\alpha, k}}$ is a quaterinonic left-linear operator, $\mathfrak D^{\sigma, 1}_{\alpha, k,{\bf i}}$ is a quaternionic right-linear space and the condition on the zero sets of these function are not necessary.
So from now on, we shall write $\dfrac{ {d}^{\sigma}}{dq_{\alpha, k, {\bf i}}} = \dfrac{ {d}^{\sigma, 1}}{dq_{\alpha, k, {\bf i}}}$   and the function set $\mathfrak D^{\sigma }_{\alpha, k,{\bf i}}= \mathfrak  D^{\sigma,1}_{\alpha, k,{\bf i}}$ becomes at quaternionic right-module, which will be called ${\bf i}$-generalized  fractal-fractional Dirichlet type-space of slice regular functions associated to $\mathbb E$. 
\end{rem} 

\begin{defn} 
The quaternionic right-module $\mathfrak  D^{\sigma }_{\alpha, k,{\bf i}}$ is equipped with 
\begin{align*}  
\langle f,g \rangle_{\mathfrak D^{\sigma }_{\alpha, k,{\bf i}}}:= &  \alpha \overline{f( \frac{1}{2})} g(\frac{1}{2}) + \int_{\mathbb E_{\bf i}\setminus [0,1)}  \overline{ \left( \frac{ {d}^{\sigma}}{ d q _{\alpha, k, {\bf i}}} f\mid_{\mathbb E_{\bf i}}(z) \right)}   
\left(\frac{ {d}^{\sigma}}{dz_{\alpha, k, {\bf i}}} \mid_{\mathbb E_{\bf i}} (z) \right) d_z\mu,
\end{align*}
and 
\begin{align*} 
\|f\|_{\mathfrak  D^{\sigma }_{\alpha, k, {\bf i} } }^2  := & \alpha \|f(\frac{1}{2})\|^2 + \int_{\mathbb E_{\bf i}}\| \frac{ {d}^{\sigma}}{d z _{\alpha, k, {\bf i}} } f\mid_{\mathbb E_{\bf i}}(z) \|^2 d_z\mu,
\end{align*}
for all $f,g\in \mathfrak D^{\sigma }_{\alpha, k, {\bf i}}$. 
\end{defn}

Similarly to Section \ref{Sec2} assume that $\chi_0(\sigma,q) = \sigma$ and $\chi_1(\sigma,q) = 1-\sigma$ for all $q\in \mathbb E$ with $\sigma\in (0,1)$. Then

\begin{prop}\label{SRpro1} If $f\in \mathcal{SR}(\mathbb E)$ then 
\begin{align*}
\left(\textrm{exp}[\dfrac{\sigma-1}{\sigma}  e_k (q^{\alpha})] \ast f(q) \right)'  
= & \frac{1}{\sigma} \textrm{exp}[\dfrac{\sigma-1}{\sigma} e_k (q^{\alpha})] \ast( e_k (q^{\alpha})')^{-\ast} \ast \frac{ {d}^{\sigma}}{ d q _{\alpha, k, {\bf i}}} f(q), 
\end{align*}
 for all $q\in \mathbb E$.
\end{prop}
\begin{proof} Note that the mapping $q\mapsto \textrm{exp}[\dfrac{\sigma-1}{\sigma} e_k (q^{\alpha})]$ is an intrinsic slice regular function and the proof follows from direct computations.
\end{proof}

\begin{rem}\label{rem3}
Given  $f \in \mathfrak  D^{\sigma }_{\alpha, k,{\bf i}}$ by Lemma \ref{LemS} there exist $f_1,f_2 \in \mathcal {SR}(\mathbb E)$ such that  $f\mid_{\mathbb E_{\bf i}}(z) = f_1(z) + f_2 (z) {\bf j} $, where ${\bf j}\in\mathbb S^2$ and  
\begin{align}\label{DirichletEsp}
\dfrac{ {d}^{\sigma}}{ d q _{\alpha, k, {\bf i}} } f\mid_{\mathbb E_{\bf i}} (z)  = &  \dfrac{ {d}^{\sigma }}{ d z _{\alpha, k} } f_1(z) +  \dfrac{ {d}^{\sigma }}{ d z _{\alpha, k} } f_2(z)  {\bf j}  , \quad \forall z\in \mathbb E_{\bf i} , \nonumber \\
 \|f\|_{\mathfrak  D^{\sigma }_{\alpha, k, {\bf i} } }^2  = & \|f_1\|_{\mathcal D^{\sigma }_{\alpha, k}}^2    +  \|f_2\|_{\mathcal D^{\sigma }_{\alpha, k}}^2, 
\end{align}
i.e.,  $f_1,f_2 \in \mathcal D^{\sigma }_{\alpha, k}$ in the complex plane $\mathbb C({\bf i})$. In addition, using Theorem \ref{TeoR}   we conclude that  
  $f \in \mathfrak  D^{\sigma }_{\alpha, k,{\bf i} } $  iff   $f_1,f_2 \in \mathcal D^{\sigma }_{\alpha, k}$ in the complex plane $\mathbb C({\bf i})$ and 
  $f = P_{ {\bf  i} }(f_1+ f_2{\bf j}) $ on $\mathbb E$.
\end{rem}

\begin{prop} 
The quaternionic right-module $(\mathfrak D^{\sigma}_{\alpha, k, {\bf i}}, \|\cdot \|_{\mathfrak D^{\sigma}_{\alpha, k, { \bf i}}})$ is a normed quaternionic right-module . 
\end{prop}
\begin{proof} 
Let $f\in \mathfrak  D^{\sigma }_{\alpha, k,{\bf i}}$ such that $\|f\|_{\mathfrak  D^{\sigma }_{\alpha, k, {\bf i}}} = 0$. By the previous remark there exist $f_1,f_2 \in \mathcal D^{\sigma }_{\alpha, k}$ in the complex plane $\mathbb C({\bf i})$ such that 
$f = P_{ {\bf  i} }(f_1+ f_2{\bf j}) $ on $\mathbb E$ and 
$$\|f\|_{\mathfrak  D^{\sigma }_{\alpha, k, {\bf i}}}^2 = \|f_1\|_{\mathcal D^{\sigma }_{\alpha, k}}^2 + \|f_2\|_{\mathcal D^{\sigma }_{\alpha, k}}^2.$$
Therefore,  $\|f_1\|_{\mathcal D^{\sigma }_{\alpha, k}} = \|f_2\|_{\mathcal D^{\sigma }_{\alpha, k}}=0$ and from Proposition \ref{pro2} we see that $f_1\equiv f_2\equiv  0$. Then $f\equiv 0$.   

From direct computations we obtain  that  
\begin{align*}
\|f \|_{\mathfrak  D^{\sigma }_{\alpha, k, {\bf i}} }  \geq  & 0 , \\ 
\|  f a  \|_{\mathfrak  D^{\sigma }_{\alpha, k, {\bf i}  } } = &  \|f \|_{\mathfrak  D^{\sigma }_{\alpha, k,{\bf i}} } |a| \\
\|f+g \|_{\mathfrak  D^{\sigma }_{\alpha, k, {\bf i}} }  \leq & \|f \|_{\mathfrak  D^{\sigma }_{\alpha, k, {\bf i} } }   + \|g \|_{\mathfrak  D^{\sigma }_{\alpha, k, {\bf i}} }  ,  
\end{align*}
for all $f,g \in  \mathfrak  D^{\sigma }_{\alpha, k, {\bf i}}$ and $a\in \mathbb H$.
\end{proof}

\begin{prop}   
$(\mathfrak  D^{\sigma }_{\alpha, k, {\bf i}} , \|\cdot \|_{\mathfrak D^{\sigma}_{\alpha, k, {\bf i}}})$ is  a  quaternionic Banach right-module.  
\end{prop}

\begin{proof}
If $(f_n)_{\mathbb N}$ is a Cauchy sequence of elements of  $ \mathfrak  D^{\sigma }_{\alpha, k, {\bf i}}$ then from  Remark \ref{rem3} there exists 
  $f_{1,n}, f_{2,n}   \in \mathcal D^{\sigma }_{\alpha, k}$ in the complex plane $\mathbb C({\bf i})$ for all $n\in \mathbb N$ such that 
  $f_n = P_{ {\bf  i}}(f_{1,n}+ f_{2,n}{\bf j}) $ on $\mathbb E$, where ${\bf j} \in \mathbb S^2$ such that ${\bf j}\perp {\bf i}$ and the identity   
\begin{align*} 
 \|f_n - f_m \|_{\mathfrak  D^{\sigma }_{\alpha, k, {\bf i} } }^2  = & \|f_{1,n} - f_{1,m}\|_{\mathcal D^{\sigma }_{\alpha, k}}^2 
    +  \|f_{2,n} - f_{2,m}\|_{\mathcal D^{\sigma }_{\alpha, k}}^2, 
\end{align*}
for all $n,m\in \mathbb N$ shows that  $(f_{1,n})_{n\in \mathbb N}$,  $ (f_{2,n})_{n\in \mathbb N}$   are Cauchy sequences in
 $ \mathfrak  D^{\sigma }_{\alpha, k } $. Using  Proposition 
\ref{pro3}  and Remark \ref{rem3} there exist $ f_ 1  ,  \ f_{2}\in  \mathfrak  D^{\sigma }_{\alpha, k } $ such that    
$(f_n)_{n\in \mathbb N}$ converges   to $f = P_{ {\bf  i} }(f_1+ f_2{\bf j}) \in  \mathfrak  D^{\sigma }_{\alpha, k, {\bf i}}$.
\end{proof}

\begin{rem}
It is clearly that $\langle \cdot ,\cdot  \rangle_{\mathfrak  D^{\sigma }_{\alpha, k, {\bf i}}}$ is a quaternionic  inner product in  $\mathfrak  D^{\sigma }_{\alpha, k, {\bf i}}$. Therefore 
$$\left( \mathfrak  D^{\sigma }_{\alpha, k, {\bf i}}, \langle \cdot ,\cdot \rangle_{\mathfrak D^{\sigma }_{\alpha, k, {\bf i}}}\right)$$ is a quaternionic Hilbert right-module.
\end{rem}

\begin{prop}
Let $f \in \mathcal {SR}(\mathbb B) \cap \mathfrak  D^{\sigma }_{\alpha, k, {\bf i}}$ and assume there exists a sequence of quaternions $(a_n)_{n\geq 0}$ such that  
$$f(q)= \sum_{n=0}^\infty q^n a_n ,\quad \forall q\in \mathbb B,$$
then 
\begin{align*}  
& \|f\|_{\mathfrak  D^{\sigma }_{\alpha, k, {\bf i} } }^2 = \alpha   |f (\frac{1}{2})|^2 + (1-\sigma)^2 \pi \sum_{n=0}^\infty  
\frac{1}{n+1} | a_{ n}|^2   \\
  &  +  \frac{\sigma^2 }{2\alpha^2 }  \sum_{n,m=0}^\infty  (n+1)(m+1)\left(a_{n+1} \bar a_{m+1}                                    
		-  {\bf i }a_{n+1} \bar a_{m+1} {\bf i}\right)  \alpha_{m,n}
    \\ 
&  + \frac{  (1-\sigma) \sigma }{2\alpha} \sum_{n,m=0}^\infty 2 (m+1)  Re \left[  
 \left(a_{m+1} \bar a_n -  {\bf i }a_{m+1} \bar a_n {\bf i} \right) \beta_{n,m} \right],   
\end{align*}
where  
 \begin{align*}
 \alpha_{m,n}=  &    \lim_{
 {   \begin{array}{c} 
  \rho \to 1^-   \\ 
  \theta_1\to -\pi^+\\
  \theta_2 \to  \pi^- \end{array}}}    
\int_{0}^\rho \int_{\theta_1}^{\theta_2}  
\frac{r ^{n+m+3 -2\alpha } e^{i \theta (n-m)}} {| e_{k-1} (r^{\alpha} e^{ i \alpha \theta}) |^2} dr d\theta  \\
\beta_{m,n} = & 
 \lim_{
 {\begin{array}{c} 
  \rho \to 1^-   \\ 
  \theta_1\to -\pi^+ \\
  \theta_2 \to  \pi^- \end{array}}}    
\int_{0}^\rho \int_{\theta_1}^{\theta_2} \frac{ r^{n+m+ 2-\alpha }  e^{i\theta ( m +1 -n - \alpha)}}{e_{k-1}(r^{\alpha} e^{i \theta \alpha})} dr d\theta
\end{align*}
\end{prop}

\begin{proof}
Given ${\bf j}\in \mathbb S^2$ and ${\bf j}\perp {\bf i}$ there exist $a_{k,n}\in \mathbb C({\bf i})$ for all $n\geq 0$ and $k=1,2$ such that $a_n = a_{1,n}+ a_{2,n}{\bf j}$. Then $f_k(z) = \sum_{n=0}^{\infty} z^n a_{k,n}$ for all $z\in \mathbb E_{\bf i}$ and $k=1,2$ such that $f\mid_{\mathbb E_{\bf i}} = f_1 + f_2{\bf j}$ on $\mathbb E_{\bf i}$. 

In addition, $f_{1}, f_{2} \in \mathcal D^{\sigma }_{\alpha, k}$  and
\begin{align*}
 \|f\|_{\mathfrak  D^{\sigma }_{\alpha, k, {\bf i} } }^2  = & \|f_1\|_{\mathcal D^{\sigma }_{\alpha, k}}^2    +  \|f_2\|_{\mathcal D^{\sigma }_{\alpha, k}}^2 . 
 \end{align*}   
To finish the proof we use Proposition \ref{pro6} and the identities:
  $$  {\bf i }a_n {\bf i}= - a_{1,n}+ a_{2,n} {\bf j} ,  \quad
 \dfrac{1}{2}\left(  a_n -  {\bf i }a_n {\bf i}\right)  =   a_{1,n}    , \quad  \dfrac{1}{2}\left(  a_n +   {\bf i }a_n {\bf i}\right)  =   a_{2,n} \quad \forall  n\geq  0,$$
to obtain that 
 \begin{align*}
 & a_{1, n } \bar a_{1, m } + a_{2, n } \bar a_{2, m } \\
 = & 
 \dfrac{1}{2}\left(  a_n -  {\bf i }a_n {\bf i}\right)  \dfrac{1}{2}\left( \bar a_m -  {\bf i } \bar  a_m {\bf i}\right)  + 
 \dfrac{1}{2}\left(  a_n +  {\bf i }a_n {\bf i}\right)  \dfrac{1}{2}\left( \bar a_m + {\bf i } \bar a_m {\bf i}\right)  \\
 = &  
 \dfrac{1}{4}\left[a_n \bar a_m -  {\bf i }a_n {\bf i} \bar a_m - a_n {\bf i } \bar a_m {\bf i} - {\bf i }a_n \bar a_m {\bf i}    + 
    a_n \bar a_m +  {\bf i }a_n {\bf i} \bar a_m  +  a_n  {\bf i } \bar a_m {\bf i}  - {\bf i }a_n \bar a_m {\bf i}   \right]  \\
    = &  \dfrac{1}{2}\left(a_n \bar a_m  -  {\bf i }a_n \bar a_m {\bf i}     \right)  , \quad \forall \  n,m\geq 0.
\end{align*} 
\end{proof}

\begin{cor}
Let $f \in \mathcal {SR}(\mathbb B)$ and a sequence of quaternions $(a_n)_{n\geq 0}$ such that  
 $$f(q)= \sum_{n=0}^\infty q^n a_n ,\quad \forall q\in \mathbb B.$$
Then for any $f\in  \mathfrak  D^{\sigma }_{\alpha, 1, {\bf i}}$ we have  
 \begin{align*}  & \|  f \|^2_{\mathfrak  D^{\sigma }_{\alpha, 1, {\bf i}}} =  \alpha |f(\frac{1}{2})|^2 + 
 (1-\sigma)^2 \pi \sum_{n=0}^\infty  \frac{1}{n+1} | a_{n}|^2     
 + \frac{\sigma^2 }{\alpha^2} \sum_{n=0}^\infty  \frac{(n+1)^2}{2n +4-2\alpha} |a_{ n+1}| ^2  \\
 & + \frac{(1-\sigma) \sigma }{ \alpha} \sum_{n,m=0}^\infty 
 \frac{(m+1) \Im  \left[ ( e^{i2\pi (m-n+1 -\alpha)}-1 ) \left(a_{m+1} \bar a_n - {\bf i }a_{m+1} \bar a_n {\bf i} \right) \right]}{ (n+m+3-\alpha) (m-n+1-\alpha )}.    
\end{align*}
On the other hand, if $f\in  \mathfrak  D^{\sigma }_{\alpha, \infty, {\bf i}}$.  Then  
\begin{align*}  
& \|  f\|^2_{\mathfrak  D^{\sigma }_{\alpha, \infty, {\bf i}}} = \alpha |f(\frac{1}{2})|^2 + (1-\sigma)^2 \pi \sum_{n=0}^\infty  \frac{1}{n+1} | a_n|^2  \\
  &  +  \frac{\sigma^2}{2 \alpha^2} \sum_{n,m=0}^\infty (n+1)(m+1) \left(a_{n+1} \bar a_{m+1} - {\bf i }a_{n+1} \bar a_{m+1} {\bf i}     \right) \alpha_{n,m} \\ 
&  +
 \frac{  (1-\sigma) \sigma }{\alpha}   \sum_{n,m=0}^\infty   (m+1) \Re  \left[ \left(    a_{m+1} \bar a_n -  {\bf i }a_{m+1} \bar a_n {\bf i} \right) \beta_{n,m} \right],    
\end{align*}
where 
\begin{align*}
\alpha_{n,m}= & \int_{0}^1 \int_{-\pi}^{  \pi}  
 \frac{r^{n+m+3 -2\alpha } e^{i \theta (n-m)}} {\textrm{exp} ( 2r^{\alpha} \cos  (\alpha \theta))} dr d\theta \\
\beta_{n,m} =  &  \int_{0}^1 \int_{-\pi}^{\pi} \frac{ r^{n+m+ 2-\alpha }  e^{ i\theta ( m +1 -n - \alpha)} }{\textrm{exp} (r^{\alpha} e^{ i \theta \alpha})} dr d\theta
\end{align*} 
\end{cor}
\begin{proof}
The first fact follows from the identity $\|f\|^2_{\mathfrak  D^{\sigma }_{\alpha, 1, {\bf i}}} = \|f_1\|^2_{\mathcal D^{\sigma }_{\alpha, 1}} + \|f_2\|^2_{\mathcal D^{\sigma }_{\alpha, 1}}$, Corollary \ref{corK1Infty} and similar computations to the previous theorem such as 
\begin{align*}  
& \|  f \|^2_{\mathfrak  D^{\sigma }_{\alpha, 1, {\bf i}}}  =  \alpha   |f(\frac{1}{2})|^2 +  (1-\sigma)^2 \pi \sum_{n=0}^\infty  \frac{1}{n+1} | a_{n}|^2 +  \frac{\sigma^2 }{\alpha^2 }  \sum_{n=0}^\infty  \frac{(n+1)^2}{ 2n +4-2\alpha} |a_{ n+1}| ^2  \\
&  + \frac{  (1-\sigma) \sigma }{\alpha}   \sum_{n,m=0}^\infty \frac{ 2 (m+1)  \Im  \left[ (e^{i2\pi (m-n+1 -\alpha)} -1) \left( a_{1, m+1} \bar a_{1,n}  +  a_{2, m+1} \bar a_{2,n} \right) \right]}{(n+m+3-\alpha)(m-n+1-\alpha)}.    
\end{align*} 
Beside, the second fact is a consequence of  
$\|  f\|^2_{\mathfrak  D^{\sigma }_{\alpha, \infty, {\bf i}} }  = \|  f_1\|^2_{\mathcal D^{\sigma }_{\alpha, \infty }}  + \|  f_2\|^2_{\mathcal D^{\sigma }_{\alpha, \infty }}  $,  Corollary \ref{corK1Infty} and similar computations. 
\end{proof}

\begin{prop} 
Let $f  \in \mathcal {SR}(\mathbb B) \cap \mathfrak  D^{\sigma }_{\alpha, k, {\bf i}}$ and   ${\bf j} \in \mathbb S^2$. Then 
\begin{align*}   
\|f\|_{\mathfrak  D^{\sigma }_{\alpha, k, {\bf j} } }^2  \leq 8 \|f\|_{\mathfrak  D^{\sigma }_{\alpha, k, {\bf i} } }^2.  
\end{align*}
\end{prop}

\begin{proof}
Representation Formula Theorem allows us to see that 
 \begin{align*}  \frac{ {d}^{\sigma }}{ d q _{\alpha, k, {\bf j} } } f\mid_{\mathbb E_{\bf j}} (w)    =& \frac{1}{2}(1-{\bf j} {\bf i})  \frac{ {d}^{\sigma }}{ d q _{\alpha, k, {\bf i} } }f \mid_{\mathbb E_{\bf i}} (z) 
 +  \frac{1}{2}(1+{\bf j} {\bf i})  \frac{ {d}^{\sigma }}{ d q _{\alpha, k, {\bf i} } } f\mid_{\mathbb E_{\bf i}} (\bar z),
 \end{align*}
 for all $w= x+y{\bf j} \in \mathbb B_{\bf j}$, where $z= x+y{\bf i} \in \mathbb B_{\bf i} $.  Therefore, 
 \begin{align*}  \| \frac{ {d}^{\sigma }}{ d q _{\alpha, k, {\bf j} }  } f 
\mid_{\mathbb E_{\bf j}} (w)  \|^2   \leq &\left(  \|  \frac{ {d}^{\sigma }}{ d q _{\alpha, k, {\bf i} } } f
\mid_{\mathbb E_{\bf i}} (z)\| +  
  \| \frac{ {d}^{\sigma }}{ d q _{\alpha, k, {\bf i} } } f 
\mid_{\mathbb E_{\bf i}}(\bar z)\|  \right)^2 \\
 \leq &4 \left(  \|  \frac{ {d}^{\sigma }}{ d q _{\alpha, k, {\bf i} } } f
\mid_{\mathbb E_{\bf i}} (z)\|^2 +  
  \| \frac{ {d}^{\sigma }}{ d q _{\alpha, k, {\bf i} }} f 
\mid_{\mathbb E_{\bf i}} (\bar z)\|^2  \right), \\
   \int_{\mathbb E_{\bf j}}  \| \frac{ {d}^{\sigma }}{ d q _{\alpha, k, {\bf j} } } f 
\mid_{\mathbb E_{\bf j}} (w)  \|^2  d_w\mu   \leq   &4 \left( \int_{\mathbb E_{\bf i}} 
     \|  \frac{ {d}^{\sigma }}{ d q _{\alpha, k, {\bf i} } } 
\mid_{\mathbb E_{\bf i}}f (z)\|^2 d_z\mu  +  
 \int_{\mathbb E_{\bf i}}  \| \frac{ {d}^{\sigma }}{ d q _{\alpha, k, {\bf i}}} f
\mid_{\mathbb E_{\bf i}} (\bar z)\|^2 d_{\bar z}\mu  \right) \\
  \leq   &8   \int_{\mathbb E_{\bf i}}   \|  \frac{ {d}^{\sigma }}{ d q _{\alpha, k, {\bf i}}} 
\mid_{\mathbb E_{\bf i}}f (z)\|^2 d_z\mu .
\end{align*} 
\end{proof}

\begin{rem} The previous proposition shows that $ \mathcal {SR}(\mathbb B) \cap \mathfrak  D^{\sigma }_{\alpha, k, {\bf i}}$ and 
$\mathcal {SR}(\mathbb B) \cap \mathfrak  D^{\sigma}_{\alpha, k, {\bf j}}$ are the same function sets for any ${\bf i }, {\bf j} \in \mathbb S^2$ but  these are differents as quaternionic  Hilbert right-modules  which  is an usual phenomenon in the theory of slice regular functions
\end{rem}

\begin{cor} Reproducing property.  Given $\sigma\in (0,1)$. Suppose $f\in \mathcal{SR}(\mathbb B)$ such that $\dfrac{ {d}^{\sigma}}{ d q _{\alpha, k,{\bf i}} } f $ belongs to the ${\bf i}-$slice regular Bergman space associated to $\mathbb B_{\bf i}$ for some ${\bf i}\in \mathbb S^2$. Then
\begin{align*}
& f (q)   
 = -  \frac{\sigma }{1-\sigma }  \alpha  q^{ \alpha-1}  \ast (e_{k-1} ( q^{\alpha})    )^{-\ast} \ast   f   '(q)  +  \frac{ 1 }{1-\sigma  }  \int_{\mathbb B_{\bf i}} \mathcal B_{\bf i }(q,\zeta)  \frac{ {d}^{\sigma}}{ d q _{\alpha, k, {\bf i }} } f\mid _{\mathbb B_{\bf i }}(\zeta) d_{\zeta}\mu_{\bf i} ,\\ 
 &  f(q) =  \textrm{exp}[\dfrac{\sigma-1}{\sigma}  ( \  e_k ((\frac{1}{2})^{\alpha}) - e_k (q^{\alpha}) \  ) ] f(\frac{1}{2}) +  \int_{\mathbb B_{\bf i }} \mathcal K_{\frac{1}{2}}(q,\zeta)   \frac{ {d}^{\sigma}}{ d q_{\alpha, k, {\bf i }} } f\mid _{\mathbb B_{\bf i }}(\zeta) d_{\zeta}\mu_{\bf i }, 
\end{align*}
where
$$ \mathcal K_{\frac{1}{2}}(q,\zeta) =  \textrm{exp}[\dfrac{1-\sigma}{\sigma}  e_k (q^{\alpha}) ]  \ast \int_{\gamma_{\frac{1}{2}, q}}  \frac{1}{\sigma}  \textrm{exp}[\dfrac{\sigma-1}{\sigma}  e_k (w^{\alpha}) ]\left(\frac{d}{dw}    e_k (w^{\alpha}) \right)    \mathcal  B_{{\bf i}}(w,\zeta) d_w\mu_{\bf i},$$ 
Here, $\mathcal B_{\bf i }(\cdot, \cdot)$ is the slice regular Bergman kernel associated to $\mathbb B_{\bf i}$ and $\gamma_{\frac{1}{2}, q}$is a rectifiable path contained in $\mathbb B_{I_q} \setminus (-1,0]$ from $\frac{1}{2}$ to $q$.   
\end{cor}

\begin{proof} Use the  reproducing property of the slice regular Bergman kernel,  see \cite{CGSBERgman, CGLSS},   and  Proposition \ref{SRpro1}.
\end{proof}

\begin{rem} Similarly to the complex case commented in Remark \ref{RemDirchlet-Bergman} choosing $\sigma=\alpha^2$ then the family of slice regular function spaces $(\mathfrak D^{\alpha^2,1}_{\alpha, k, {\bf i }})_{\alpha \in (0,1]}$ it is possible consider $\alpha =0$.  In addition, for $k=1$ we have that the well-known ${\bf i}$-slice regular function spaces of Dirichlet and Bergman are given $\mathfrak D^{0,1}_{0, 1, {\bf i}} $ and $\mathfrak  D^{1,1}_{1, 1, {\bf i }} $, respectively, i.e.,  these  slice regular function spaces are elements of the family $(\mathfrak  D^{\alpha^2,1}_{\alpha, 1, {\bf i}})_{\alpha \in [0,1]}$.
\end{rem}

\begin{rem}
There are many questions that can be resolved in future papers on the  quaternionic Hilbert right-module $\mathcal {SR}(\mathbb B) \cap \mathfrak  D^{\sigma }_{\alpha, k, {\bf i}}$ that arise from the generalization of the slice regular function  space  of Dirichlet and Bergman and the properties of these two  quaternionic right-modules.
\end{rem}

