	We also provide examples of non-log-concave target distributions for which our results can be applied to establish mixing time bounds for both variants of the Gibbs sampler, filling a gap not addressed by any other existing literature.



	\section{Preliminaries} \label{sec:prelim}

	\subsection{The Gibbs sampler} \label{subsec:gs}


	We consider a probability distribution $\pi (\mathd x)$ supported on $\R^d$, equipped with its standard Borel $\sigma$-algebra. Let $P(x,\mathd y)$ be the Markov transition kernel of a discrete-time Markov chain on $\R^d$ with stationary (or invariant) distribution $\pi$. Here, the Markov chain is interpreted as the MCMC method for generating approximate samples from $\pi$. The kernel $P$ is said to be reversible with respect to $\pi$ if
	$$
	\pi ( \mathd x) P(x,\mathd y) = \pi(\mathd y) P(y, \mathd x) \qquad \forall x,y \in \R^d.
	$$
	Reversibility with respect to $\pi$ implies stationarity of $\pi$, however the reverse implication is in general false. 
	Among MCMC methods, we focus on the Gibbs sampler. This method has two commonly used variants: the random-scan Gibbs sampler and the systematic-scan Gibbs sampler, which we now introduce.
	Let  $x = \left(x_1, \dots, x_d\right) \in \R^d$. For $1 \leq k \leq l \leq d$, we write
	$$
	x_{k:l} = (x_{k}, x_{k+1}, \dots, x_{l-1}, x_{l}) \in \R^{l-k+1}
	$$
	and
	$$x_{-k} = (x_1, \dots, x_{k-1},  x_{k+1}, \dots, x_d) \in \R^{d-1}.$$ 
	Given another point $y = \left(y_1, \dots, y_d\right) \in \R^d$, we also write
	\begin{equation}\label{notationindex}
		(x_{-k}, y_k) = (x_1, \dots, x_{k-1}, y_k, x_{k+1}, \dots, x_d).
	\end{equation}
	We additionally use the notation $\left[ d \right] = \left\{1,\dots, d\right\}$. Let $X \sim \pi$. Denote the conditional distribution of $X_k$ given $X_{-k} = x_{-k}$ as $\pi( \cdot \mid x_{-k})$. For all $k \in [d]$, define the Markov kernel
	$$
	P_k (x, \mathd y) = \pi ( \mathd y_k \mid x_{-k}) \delta_{x_{-k}} (\mathd y_{-k}),
	$$ where $\delta_{x_{-k}}$ denotes the $(d-1)$-dimensional Dirac delta distribution: for all measurable $S \subseteq \R^{d-1}$, 
	$$
	\delta_{x_{-k}} (S) = 
	\begin{cases}
		1  &\text{if } x_{-k} \in S, \\
		0  &\text{if } x_{-k} \notin S.
	\end{cases}
	$$
	%	 The kernel $P_k$ acts on functions $f \in L^2 ( \pi)$ via
	%	 \begin{align*}
		%	 	P_k f (x) &= \int f(x_{-k}, y_k) \pi ( \mathd y_k \mid x_{-k}) \\
		%	 	&= \E \left[ f(X) \mid X_{-k} = x_{-k}\right].
		%	 \end{align*}
	Using the kernels $P_k$, we now define the Markov kernels corresponding to the random-scan and systematic-scan Gibbs samplers. For two Markov kernels $P$ and $Q$, we denote their composition as $PQ(x,\mathd y) = \int P(u, \mathd y) Q(x, \mathd u)$.

	\begin{defn}
		The Markov kernel associated with the random-scan Gibbs sampler is defined as the mixture of the Markov kernels $P_k$:
		$$
		P_{\mathrm{RS}} = \frac{1}{d} \sum_{k=1}^d P_k.
		$$
		The Markov kernel associated with the systematic-scan Gibbs sampler is defined as the composition of the Markov kernels $P_k$:
		$$
		P_{\mathrm{SS}} = P_d P_{d-1} \dots P_2 P_1.
		$$
	\end{defn}

	In words, the random-scan Gibbs sampler selects a single coordinate uniformly at random and resamples it from its conditional distribution, while leaving the other coordinates unchanged. 
	In contrast, the  systematic-scan Gibbs sampler sequentially updates each coordinate in a predetermined order, from 1 to $d$, resampling each from its respective conditional distribution. 

	It is worth noting that the Markov kernel associated with the random-scan Gibbs sampler is $\pi$-reversible, whereas the Markov kernel associated with the systematic-scan Gibbs sampler is generally not.  
	To address this, one approach is to use the multiplicative reversibilization of the systematic-scan Gibbs sampler. The kernel for this version is defined as
	$$
	P_\mathrm{SS}^* P_{\mathrm{SS}} = P_1 P_{2} \dots P_{d-1} P_d P_{d-1} \dots P_2 P_1,
	$$
	where $P^*$ represents the adjoint operator of a Markov kernel $P$. In this version, the coordinates are updated first in increasing order, from $1$ to $d$, and then in decreasing order, from $d$ to $1$.


	\subsection{Assumptions on the target distribution} \label{subsec:assumptions}

	%We now outline the key assumptions imposed on the target distribution $\pi$.

	In the following, let $\abs{\cdot}$ denote the standard Euclidean norm on $\R^d$.
	Unless stated otherwise, all expectations and variances are taken with respect to the target distribution $\pi$.
	We say that a function \mbox{$f: \R^d \to \R$} is locally Lipschitz if its restriction to any open ball in $\R^d$ is Lipschitz continuous.
	With these conventions in mind, we now consider two functional inequalities for $\pi$, namely the Poincar\'e and the log-Sobolev inequality. 

	\begin{defn}%[\citealp{milman2009role}] 
		\label{PI}
		Let $q \geq 1$. The distribution $\pi$ is said to satisfy a $L^q$-Poincar\'e inequality (\po{q}) with constant $\cpo{q} > 0$ if for any locally Lipschitz function $f: \R^d \to \R$,
		\begin{equation} \label{PIid}
			\E\left[\abs{f - \E [ f ]}^q \right]\leq \frac{1}{\cpo{q}} \cdot \E \left[ \abs{ \nabla f }^q\right].
		\end{equation}
		%Ideally, we would like the constant \cpo{q} to be as large as possible so that the above inequality holds.
		We take \cpo{q} to be the largest constant for which this inequality holds.
	\end{defn}

	\begin{defn}%[\citealp{bobkov2005entropy}] 
		\label{LSI}
		Let $q \geq 1$. The distribution $\pi$ is said to satisfy a $L^q$-\hbox{log-Sobolev} inequality (\ls{q}) with constant $\cls{q} > 0$ if for any locally Lipschitz function \mbox{$f: \R^d\to\R$},
		\begin{equation} \label{LSIid}
			\E\left[\abs{f }^q \cdot \log\abs{f }^q \right] - \E\left[\abs{f }^q \right] \cdot \log \E\left[ \abs{f}^q \right] \leq \frac{1}{\cls{q}} \cdot \E \left[ \abs{\nabla f}^q\right].
		\end{equation}
		As before, %we would like \cls{q} to be as large as possible.
		we take \cls{q} to be the largest constant for which this inequality holds.
	\end{defn}

	These functional inequalities extend the classical assumption of (strong) log-concavity for $\pi$. Specifically, \cite{bobkov1999isoperimetric} proved that \po{1} is satisfied by all log-concave distributions, and \citet{bakry2006diffusions} showed that \ls{2} holds for all strongly log-concave distributions. As shown in \citet[Proposition 6.2]{bobkov2005entropy}, \ls{q} is also preserved by bounded perturbation \`a la \citet{holley1987logarithmic}. More generally, \citet{ledoux2006concentration} proved that \po{2} and \ls{2} respectively imply sub-exponential and sub-Gaussian tail bounds for the distribution $\pi$. Log-Sobolev inequalites have also been proven for mixture distributions \citep{chen2021dimension}.

	%The $L^1$-Poincar\'e constant \cpo{1} is sometimes known as the Cheeger constant.
	%Furthermore, it can be shown that these functional inequalities form a hierarchy: if $\pi$ satisfies \po{q}, then $\pi$ satisfies \po{r} for any $1 \leq q \leq r$ \citep[Proposition 2.5]{milman2009role}. We believe that an equivalent result also holds for the log-Sobolev inequalities.
	%\textbf{[Include our (I think new) proof?]}
	%Moreover, if $\pi$ satisfies \ls{q} with constant $\cls{q}$, then \citet[Theorem 2.1]{bobkov2005entropy} showed that $\pi$ satisfies \po{q} with constant $\cpo{q} \geq 4\cls{q}/ \log 2$.
	%$$\cpo{q} \geq \frac{4 \cls{q}}{\log2}$$ \citep[Theorem 2.1]{bobkov2005entropy}.

	Furthermore, if $\pi$ satisfies \ls{q} with constant $\cls{q}$, then \citet[Theorem 2.1]{bobkov2005entropy} showed that $\pi$ satisfies \po{q} with constant $\cpo{q} \geq 4\cls{q}/ \log 2$. In addition, it can be shown that these functional inequalities form a hierarchy: if $\pi$ satisfies \po{q}, then $\pi$ satisfies \po{r} for any $1 \leq q \leq r$ \citep[Proposition 2.5]{milman2009role}. An analogous result  holds for log-Sobolev inequalities, as formalized in the following proposition.

	\begin{prop} \label{LSIhierarchy}
		Let $1 \leq q \leq r$. Suppose that the distribution $\pi$ satisfies \ls{q} with constant \cls{q}. Then, $\pi$ also satisfies \ls{r} with constant
		$$
		\frac{5}{128} \left(\frac{4}{105}\right)^{r/q}
		\left(\frac{q}{r}\right)^r \cls{q}^{r/q} \leq \cls{r}.
		$$
	\end{prop}

	To the best of our knowledge, Proposition~\ref{LSIhierarchy} does not appear explicitly in the literature. For completeness, we include a proof in Appendix~\ref{sec:appendixproofs}, which may also be of independent interest.

	We now introduce one final regularity assumption on the conditional distributions of $\pi$. 
	To formalize this, recall that the total variation (TV) distance between two probability distributions $\mu$ and $\nu$ supported on $\R^d$ is given by
	$$
	\norm{\mu- \nu}_\tv = \sup \left\{ \abs{\mu (S) - \nu (S)} : S \subseteq \R^d \text{ measurable} \right\}.
	$$

	\begin{defn} \label{def:tvcontinuous}
		Let $M > 0$ and $\beta \in (0,1]$. The conditional distributions of $\pi$ are said to be $(M, \beta)$-TV continuous if
		$$
		\norm{\pi( \cdot \mid x_{-k}) - \pi( \cdot \mid y_{-k})}_\tv \leq M \abs{x_{-k} - y_{-k}}^\beta \qquad \forall k \in [d], ~\forall x, y \in \R^d.
		$$
	\end{defn}

	%This property has been established within the Bayesian framework \citep{dolera2020uniform, dolera2023lipschitz}. 

	This type of continuity has been shown to hold for posterior distributions in Bayesian models, under assumptions such as Lipschitz continuity of the likelihood and sufficient integrability of the prior \citep{dolera2020uniform, dolera2023lipschitz}.
	Moreover, in Subsection \ref{subsection:potentials}, we will show how to verify that the conditional distributions of $\pi$ are TV-continuous under standard conditions on the potential function $U = - \log \pi$.


	\section{Convergence analysis of Markov chains} \label{sec:markovconv}

	\subsection{Mixing times of Markov chains}

	We begin by recalling key definitions and concepts related to the mixing of Markov chains. 
	Let $\mu$ denote the initial distribution of the Markov chain associated to a kernel $P$. After $k$ steps, the distribution of the chain is given by $\mu P^k$, where
	$$
	\mu P^k (\mathd x) = \int P^k(y,\mathd x) \mu (\mathd y).
	$$
	%Often, we suppose that our initial distribution to be ``not too far away'' from the stationary distribution, i.e., that our Markov chain has a warm start.
	It is often assumed that the initial distribution is ``not too far'' from the stationary distribution, a condition referred to as a warm start.

	\begin{defn}
		Let $\Omega >0 $. A $\pi$-invariant Markov chain with initial distribution $\mu$ is said to have a $\Omega$-warm start if
		$$
		\sup \left\{ \frac{\mu(S)}{\pi (S)} : S \subseteq \R^d \text{ measurable} \right\} \leq \Omega.
		$$
	\end{defn}

	%	Note that the constant $\Omega$ can easily grow exponentially with the dimension $d$, even in fairly innocent examples \citep{dwivedi2019log}.

	Note that the constant $\Omega$ can grow exponentially with the dimension $d$ even in fairly innocent examples.
	For instance, this occurs when the initial distribution is a Gaussian centered at the mode of a strongly log-concave target \citep{dwivedi2019log}.
	Nevertheless, when $\pi$ is strongly log-concave, \citet{altschuler2024faster} showed that a distribution with a $\Oc (1)$-warm start can be efficiently obtained using the underdamped Langevin dynamics in $\Oc (\sqrt{d})$~iterations.
	We now define the mixing time of a Markov chain as the minimum number of iterations required for the chain to be ``close'' to its stationary distribution in total variation distance.

	\begin{defn}
		Let $\zeta > 0$. The $\zeta$-mixing time of a $\pi$-invariant Markov chain with transition kernel $P$ is defined as
		$$
		\tau (\zeta, P) = \inf\left\{ k \geq 0 : \norm{\mu P^k - \pi}_{\tv} \leq \zeta\right\}.
		$$
	\end{defn}

	A common approach to bound the mixing time is to study a quantity known as the conductance of the Markov chain, which is defined as follows.

	\begin{defn}
		%[\citealp{chen2020fast}]\\
		Consider a $\pi$-invariant Markov chain with transition kernel $P$.
		The conductance of $P$ is defined as
		$$
		\Phi (P) = \inf \left\{\frac{\int_S P(x,S^c) \pi (\mathd x) }{\pi (S)} : S \subseteq \R^d \text{ measurable}, \text{ } \pi (S) \leq \frac{1}{2} \right\}.
		$$
	\end{defn}

	The connection between the mixing time of a Markov chain and its conductance was established by \citet{lovasz1993random}, who extended the earlier work of \citet{jerrum1988conductance} to general state spaces. Importantly, this result does not require the transition kernel $P$ to be reversible.

	\begin{thm}[\citealp{lovasz1993random}, Corollary 1.5] \label{lovsimThm}
		%Let $P$ be the transition kernel of a $\pi$-invariant Markov chain initialized at a $\Omega$-warm start. Then for all $k \geq 0$,
		Consider a $\pi$-invariant Markov chain with transition kernel $P$ initialized at a $\Omega$-warm start. Then, for all $k \geq 0$,
		$$
		\norm{\mu P^k - \pi}_{\tv} \leq \sqrt{\Omega} \cdot \exp \left(- \frac{k}{2} \cdot \Phi(P)^2 \right).
		$$
	\end{thm}


	\begin{cor} \label{lovsimCor}
		Consider a $\pi$-invariant Markov chain with transition kernel $P$ initialized at a $\Omega$-warm start. Then, its $\zeta$-mixing time can be bounded by
		$$
		\tau (\zeta, P) \leq \frac{2}{\Phi(P)^2} \cdot \log \left( \frac{\sqrt{\Omega}}{\zeta}\right).
		$$
	\end{cor}


	The problem of upper bounding the mixing time is thus reduced to proving a lower bound on the conductance. 


	\subsection{The spectral gap}

	%Another key quantity for assessing the convergence of Markov chains is the spectral gap, which we define here. 
	Let
	$$
	L^2_\pi = \left\{ f : \R^d \to \R : \int f(x)^2 \pi (\mathd x) < \infty\right\}
	$$
	denote the Hilbert space of square $\pi$-integrable functions. For all $f, g \in L^2_\pi$, the scalar product associated to this space is
	$$
	\langle f, g \rangle = \int f(x) g(x) \pi (\mathd x),
	$$
	with corresponding $L^2_\pi$-norm $\norm{f}_2 = \sqrt{\langle f, f \rangle}$. Note that a Markov kernel $P$ can be seen as an operator that acts on functions $f \in L^2_\pi$ via
	$$
	Pf(x) = \int f(y) P(x, \mathd y).
	$$
	Let also $I$ denote the identity operator: $I f = f$.

	\begin{defn}
		Consider a $\pi$-invariant Markov chain with transition kernel $P$. Suppose that $P$ is $\pi$-reversible. The spectral gap of $P$ is defined as 
		$$
		\lambda_2 (P) = \inf \left\{ \frac{\langle f, (I - P) f \rangle}{\norm{f}_2}: f \in L^2_\pi, \text{ } \E [f] = 0 \right\}.
		$$
	\end{defn}

	When $P$ is reversible, the spectral gap provides a bound on the $L^2_\pi$-convergence rate of the Markov chain: for any $f \in L^2_\pi$ with $\E \left[f\right] = 0$, we have 
	$$
	\norm{Pf}_2 \leq \left(1 - \lambda_2\right) \norm{f}_2.
	$$
	See \cite[Exercise 12.4]{levin2017markov} for a proof.
	%The spectral gap of a reversible Markov kernel $P$ is related to its conductance by Cheeger's inequalities \citep{cheeger1970lower}.
	The spectral gap of a reversible Markov kernel $P$ is related to its conductance via the following bounds, also known as Cheeger's inequalities \citep{cheeger1970lower}.

	\begin{thm}[\citealp{lawler1988bounds}, Theorem 2.1] \label{cheegerinequalties}
		Let $\Phi (P)$ and $\lambda_2 (P)$ denote respectively the conductance and spectral gap of a reversible Markov kernel $P$. Then,
		$$
		\frac{1}{2}\cdot \Phi^2 (P) \leq \lambda_2 (P) \leq \Phi (P).
		$$
	\end{thm}	


	A lower bound on the conductance thus translates to a lower bound on the spectral gap.
	Theorem~\ref{cheegerinequalties} applies specifically to the reversible setting and covers the random-scan Gibbs sampler as well as reversibilized forms of the systematic-scan Gibbs sampler, such as the variant with kernel $P_{\mathrm{SS}}^* P_{\mathrm{SS}}$ discussed in Subsection \ref{subsec:gs}.
	In this paper, however, we do not directly assume reversibility and instead focus on mixing time bounds as in Corollary~\ref{lovsimCor}.
	For non-reversible chains, various notions of spectral gaps have been proposed; see, for instance, \citet{kontoyiannis2012geometric} for definitions based on suitably weighted Banach spaces, and \citet{chatterjee2023spectral} for finite state spaces.
	Other approaches \citep{fill1991eigenvalue, paulin2015concentration, choi2020metropolis} use reversibilized Markov kernels  to derive similar bounds on the convergence rate.
	However, the sharpness of such bounds in the non-reversible setting remains unclear, and a detailed investigation lies beyond the scope of this work.


	%It is worth noting that \citet{chatterjee2023spectral} introduced a version of the spectral gap that applies to non-reversible chains. This serves as a useful tool for analyzing the $L^2_\pi$-convergence of empirical averages in finite state spaces.


	\subsection{Bounding the conductance} \label{subsection:boundingconductance}

	In order to bound the conductance of a $\pi$-invariant Markov kernel $P$, two main components are required: a three-set isoperimetric inequality for the distribution $\pi$, and a close coupling condition for the kernel $P$. In what follows, we write $\id: \R \to \R$ for the identity function and use $\sqcup$ to denote the union of disjoint sets.

	\begin{defn} \label{3sidef}
		Let $\Upsilon: (0, \infty) \to (0, \infty)$ and $\Psi: (0,1/2) \to (0,\infty)$ be two %increasing 
		non-decreasing
		functions. 
		Additionaly, assume that $\Psi/\id$ is 
		%decreasing
		non-increasing.
		%, where $\id: \R \to \R$ denotes the identity function
		The distribution $\pi$ is said to satisfy a three-set isoperimetric inequality with functions $\Upsilon, \Psi$, if for all measurable partitions $S_1 \sqcup S_2 \sqcup S_3 = \R^d$,
		$$
		\pi ( S_3) \geq \Upsilon(\mathcal{D} ( S_1, S_2 )) \cdot \Psi(\min \{ \pi ( S_1), \pi ( S_2) \}),
		$$
		where $\mathcal{D} ( S_1, S_2) = \inf \{ \abs{x-y} : x \in S_1, y \in S_2 \}$ denotes the distance between  $S_1$ and $S_2$.
	\end{defn}

	When $\pi$ is log-concave (or a bounded perturbation thereof), a three-set inequality can be derived by controlling a quantity known as the isoperimetric profile of $\pi$
	\citetext{\citealp[Theorem 1.2]{milman2009role2}; \citealp[Section 3]{andrieu2024explicit}}. 
	Bounds on the isoperimetric profile have also been established when $\pi$ satisfies \po{1}  and \ls{1} 
	%; see \citet[Theorem 1]{rothaus1985analytic} and \citet[Theorem 1.2]{bobkov1997some}. 
	\citep{rothaus1985analytic, bobkov1997some}.
	In all these cases, $\Upsilon$ is taken to be a multiple of  the identity function.
	However, this approach generally breaks down for non-log-concave $\pi$, as shown in \citet[Subsection 1.2]{milman2009role}.
	%	For convenience, we state the three-set isoperimetric inequality corresponding to \po{1}, which follows from  \citet[Theorem 1.2]{bobkov1997some} and \citet[Lemma 14]{andrieu2024explicit}.

	%	\begin{prop}
		%		Suppose that the distribution $\pi$ satisfies \po{1} with constant \cpo{1}. Then $\pi$ satisfies a three-set isoperimetric inequality with functions
		%		$$
		%		\Upsilon (t) = \cpo{1}t, \qquad \Psi (t) =t.
		%		$$
		%	\end{prop}
	%To address these limitations, we take a more direct approach to derive a novel three-set isoperimetric inequality for distributions satisfying \po{q} or \ls{q} with $q>1$. In this setting, $\Upsilon$ is no longer restricted to the identity function.

	\begin{defn}
		Let $\delta, \varepsilon > 0$. A Markov kernel $P$ is said to satisfy a $(\delta, \varepsilon)$-close coupling condition if
		$$
		\abs{x-y} \leq \delta \implies \norm{P (x, \cdot) - P (y, \cdot)}_\tv \leq 1 - \varepsilon \qquad \forall x,y \in \R^d.
		$$
	\end{defn}
	%In what follows, let $\id: \R \to \R$ denote the identity function.

	The close coupling condition ensures that when $x$ and $y$ are ``close'' in Euclidean distance, the probability distributions $P(x, \cdot)$ and $P(y, \cdot)$ are ``close'' in total variation distance. 
	%Conventionally, $\delta$ is chosen to scales inversely with the dimension $d$ to ensure that $\varepsilon$ remains of constant order. 
	%In what follows, let $\id: \R \to \R$ denote the identity function.
	Assuming that $\pi$ satisfies a three-set isoperimetric inequality and $P$ satisfies a close coupling condition, we are able to establish a lower bound on the conductance of the Markov chain. 
	%The following result, whose proof can be found in Appendix \ref{sec:appendixproofs}, builds on several previous works; for further details, see the survey by \citet{vempala2005geometric}. 



	\begin{prop} \label{conductanceTHM}
		Consider a $\pi$-invariant Markov kernel $P$. Suppose that $\pi$ satisfies a three-set isoperimetric inequality with functions $\Upsilon, \Psi$, and $P$ satisfies a $(\delta, \varepsilon)$-close coupling condition. Then, for any measurable $S \subseteq \R^d$ with $\pi(S) \leq 1/2$,
		$$
		\int_S P(x,S^c) \pi (\mathd x) \geq \frac{\varepsilon}{4} \cdot \min \left\{  \pi (S ), \Upsilon(\delta) \cdot \Psi\left( \frac{\pi (S )}{2} \right) \right\}.
		$$
	\end{prop}

	\begin{cor} \label{conductanceProfileLowerBound}
		Under the conditions of Proposition \ref{conductanceTHM}, the conductance of the Markov kernel $P$ can be bounded by
		$$
		\Phi (P)\geq \frac{\varepsilon \cdot \Psi (1/4)}{2}  \cdot  \min \left\{\frac{1}{2 \cdot \Psi (1/4)}, \Upsilon (\delta)\right\}.
		$$
	\end{cor}

	The proof of Proposition \ref{conductanceTHM} can be found in Appendix \ref{sec:appendixproofs} and builds on several previous works; see \citet[Lemma 15]
	{andrieu2024explicit} and the survey by \citet{vempala2005geometric} for further details. 
	Notably, Proposition \ref{conductanceTHM} and Corollary \ref{conductanceProfileLowerBound} do not require the Markov kernel $P$ to be reversible. 
	Conventionally, $\delta$ is chosen to scale inversely with the dimension $d$ to ensure that $\varepsilon$ remains of constant order.
	Under this regime, Corollary~\ref{conductanceProfileLowerBound} yields
	%Furthermore, in Corollary \ref{conductanceProfileLowerBound}, if $\varepsilon$ is constant and $\delta$ decreases with the dimension $d$, then
	$$
	\Phi(P)\gtrsim \min \{1, \Upsilon (\delta)\} = \Upsilon (\delta)
	$$
	for sufficiently large $d$. 
	%However, in practice, and in the cases we consider, this threshold is reached even for small values of $d$ (e.g., $d=4$).


	%Given a target distribution that satisfies a Poincar\'e or log-Sobolev inequality, the next step is to establish a close coupling condition for the $\pi$-invariant kernel $P$. This is addressed in the next section, where $P$ is taken to be the Markov kernel corresponding to the Gibbs sampler.

	\section{Main results} \label{sec:mainresults}

	\subsection{Three-set isoperimetric inequalities via functional inequalities} \label{sec:3sifi}




	%As noted earlier, when the distribution $\pi$ is not log-concave, three-set isoperimetric inequalities can only be derived under the conditions \po{1} or \ls{1}. However, when extending to $L^q$-Poincar\'e or $L^q$-log-Sobolev inequalities with $q > 1$, traditional methods relying on the isoperimetric profile of $\pi$ cease to be effective.
	We now establish three-set isoperimetric inequalities for distributions $\pi$ satisfying an \hbox{$L^q$-Poincar\'e} or $L^q$-log-Sobolev inequality for any $q \geq 1$.
	As noted in Subsection \ref{subsection:boundingconductance}, traditional methods based on the isoperimetric profile cease to be effective when $\pi$ is not log-concave.
	To overcome these challenges, we take a more direct approach to derive  three-set isoperimetric inequalities for distributions satisfying \po{q} or \ls{q} with $q\geq1$. In this setting, $\Upsilon$ is no longer restricted to be proportional to the identity function. In what follows, denote the indicator function of a measurable set $S \subseteq \R^d$ as $\mathbbm{1}_S$.  Additionally, define the $L^q_\pi$-norm of a function $f$ as
	$$
	\norm{f}_q = \left( \int \abs{f(x)}^q \pi(\mathd x)\right)^{1/q}.
	$$

	\begin{prop} \label{3siPI}
		Let $q \geq 1$. If the distribution $\pi$ satisfies \po{q} with constant $\cpo{q}$, then $\pi$ satisfies a three-set isoperimetric inequality with functions
		\begin{gather*}
			\Upsilon(t) = \frac{\cpo{q} t^q}{2^{2q} \left(1 + 2^q  \cpo{q} t^q\right)}, \qquad
			\Psi(t) = t.
		\end{gather*}
	\end{prop}

	\begin{proof}
		Let $S_1 \sqcup S_2 \sqcup S_3 = \R^d$ be a partition of space with $\mathcal{D}(S_1, S_2) > 0$. Inspired by \citet[Proposition 1.7]{ledoux2001concentration}, define the function
		$$
		f(x) = \max \left\{ 0, 1 - \frac{\mathcal{D}(x, S_1)}{\mathcal{D}(S_1, S_2)} \right\}.
		$$
		Observe that the map $x \mapsto \mathcal{D} (x, S_1)$ is Lipschitz continuous with constant 1.
		Indeed, for any $\xi >0$, let $s_\xi \in S_1$ be such that $\abs{y-s_\xi} \leq \mathcal{D} (y, S_1) + \xi$. Then,
		\begin{align*}
			\mathcal{D} (x, S_1) &\leq \abs{x - s_\xi} \\
			&\leq \abs{x-y} + \abs{y-s_\xi} \\
			&\leq \abs{x-y} + \mathcal{D} (y, S_1) + \xi,
		\end{align*}
		so that $\mathcal{D} (x, S_1) - \mathcal{D} (y, S_1) \leq \abs{x-y} + \xi$.
		Swapping the roles of $x$ and $y$ and letting $\xi \to 0$, we obtain  $\abs{\mathcal{D} (x, S_1) - \mathcal{D} (y, S_1)} \leq \abs{x-y}$.
		It follows that the function $f$ is equal to 1 on $S_1$, vanishes on $S_2$, and is Lipschitz continuous on a subset of $S_3$, with the modulus of its gradient equal to $\mathcal{D} (S_1, S_2)^{-1}$; elsewhere on $S_3$, $f$ vanishes. In particular, $f(x) \in [0,1]$ for $x \in S_3$. Applying \eqref{PIid} to $f$, we obtain
		\begin{equation} \label{3siPI:direct}
			\norm{f - \mathbb{E}[f]}_q^q = \mathbb{E} \left[ \abs{f - \mathbb{E}[f]}^q \right] \leq \frac{1}{\cpo{q}} \cdot \mathbb{E} \left[ \abs{\nabla f}^q \right] \leq \frac{\pi(S_3)}{\cpo{q} \cdot \mathcal{D}(S_1, S_2)^q}.
		\end{equation}
		We now compare $\mathbb{E}[\abs{f - \mathbb{E}[f]}^q]$ to the corresponding quantity for the indicator function~$\mathbbm{1}_{S_1}$, namely $\mathbb{E}\left[\abs{\mathbbm{1}_{S_1} - \mathbb{E}[\mathbbm{1}_{S_1}]}^q\right]$. 
		By the triangle inequality and Jensen's inequality, we get
		\begin{align*}
			\mathbb{E}\left[\abs{\mathbbm{1}_{S_1} - \mathbb{E}[\mathbbm{1}_{S_1}]}^q\right]^{1/q} &=\norm{\mathbbm{1}_{S_1} - \mathbb{E}[\mathbbm{1}_{S_1}]}_q \\
			&\leq \norm{f - \mathbbm{1}_{S_1}}_q + \norm{f - \mathbb{E}[f]}_q + \abs{\mathbb{E}[f] - \mathbb{E}[\mathbbm{1}_{S_1}]} \\
			&\leq 2 \norm{f - \mathbbm{1}_{S_1}}_q + \norm{f - \mathbb{E}[f]}_q.
		\end{align*}
		Using the inequality $\left(a + b\right)^q \leq 2^q \left(a^q + b^q\right)$ for $a, b \geq 0$, it follows that
		\begin{equation} \label{3siPI:1} 
			\mathbb{E}\left[\abs{\mathbbm{1}_{S_1} - \mathbb{E}[\mathbbm{1}_{S_1}]}^q\right] \leq 2^q \left( 2^q \norm{f - \mathbbm{1}_{S_1}}_q^q + \norm{f - \mathbb{E}[f]}_q^q \right).
		\end{equation}
		Since $f - \mathbbm{1}_{S_1}$ vanishes on $S_1 \sqcup S_2$ and takes values in $[0, 1]$ on $S_3$, we have
		\begin{equation} \label{3siPI:2} 
			\norm{f - \mathbbm{1}_{S_1}}_q^q = \mathbb{E} \left[ \abs{f - \mathbbm{1}_{S_1}}^q \right] \leq \pi(S_3).
		\end{equation}
		Inserting \eqref{3siPI:direct} and \eqref{3siPI:2} into \eqref{3siPI:1}, we get
		$$
		\mathbb{E}\left[\abs{\mathbbm{1}_{S_1} - \mathbb{E}[\mathbbm{1}_{S_1}]}^q\right] \leq 2^q \left( 2^q + \frac{1}{\cpo{q} \cdot \mathcal{D}(S_1, S_2)^q} \right) \pi(S_3).
		$$
		We now derive a lower bound for $\mathbb{E}[\abs{\mathbbm{1}_{S_1} - \mathbb{E}[\mathbbm{1}_{S_1}]}^q]$:
		\begin{align*}
			\mathbb{E}\left[\abs{\mathbbm{1}_{S_1} - \mathbb{E}[\mathbbm{1}_{S_1}]}^q\right] &= \left(1 - \pi(S_1)\right)^q \pi(S_1) + \pi(S_1)^q \left(1 - \pi(S_1)\right) \\
			&= \left(1 - \pi(S_1)\right) \pi(S_1) \left[\left(1 - \pi(S_1)\right)^{q-1} + \pi(S_1)^{q-1}\right] \\
			&\geq \frac{1}{2^{q-1}} \left(1 - \pi(S_1)\right) \pi(S_1) \\
			&\geq \frac{1}{2^q} \cdot \min\left\{\pi(S_1), 1 - \pi(S_1)\right\} \\
			&\geq \frac{1}{2^q} \cdot \min\left\{\pi(S_1), \pi(S_2)\right\},
		\end{align*}
		where we have used the inequality $1/2 \cdot \min\{x, 1-x\} \leq x(1-x)$ for $x \in [0, 1]$.
		Combining these bounds, we obtain
		$$
		\min\left\{\pi(S_1), \pi(S_2)\right\} \leq 2^{2q} \left( 2^q + \frac{1}{\cpo{q} \cdot \mathcal{D}(S_1, S_2)^q} \right) \pi(S_3),
		$$
		or equivalently,
		$$ 
		\pi(S_3) \geq \frac{\mathcal{D}(S_1, S_2)^q}{2^{2q} \left( \cpo{q}^{-1} + 2^q \cdot \mathcal{D}(S_1, S_2)^q \right)} \cdot \min\left\{\pi(S_1), \pi(S_2)\right\}.
		$$
		The $L^q$-Poincar\'e inequality thus implies a three-set isoperimetric inequality
		$$
		\pi (S_3) \geq \Upsilon (\mathcal{D}(S_1, S_2)) \cdot \min\{\pi(S_1), \pi(S_2)\},
		$$
		where
		$$
		\Upsilon(t) = \frac{\cpo{q} t^q}{2^{2q}\left(1 + 2^q \cpo{q} t^q\right)}.
		$$

	\end{proof}

	To derive a three-set isoperimetric inequality corresponding to the $L^q$-log-Sobolev inequality, it is useful to analyze the properties of the function $x \mapsto x \cdot \log (1/x)$. The proof of the following lemma is provided in Appendix \ref{sec:appendixproofs}. 

	\begin{lem} \label{3siLSIlem}
		For $x \in [0,1]$, consider the function  
		$
		\rho(x) = x \cdot \log (1/x)
		$.
		Then:
		\begin{itemize}
			\item The function $\rho(x)$ is positive and achieves its maximum at $x = e^{-1}$.
			\item For all $x,h \in [0,1]$ such that $x + h \leq 1$,
			$
			\rho(x+h) \geq \rho(x) - h
			$.
		\end{itemize}
	\end{lem}



	\begin{prop} \label{3siLSI}
		Let $q \geq 1$. If the distribution $\pi$ satisfies \ls{q}  with constant \cls{q}, then $\pi$ satisfies a three-set isoperimetric inequality with functions
		\begin{gather*}
			\Upsilon(t) = \frac{\cls{q} t^q}{1 + \left(1 + e^{-1}\right) \cls{q} t^q}, \qquad	\Psi(t) = \frac{t}{2} \cdot \log \left( \frac{2}{t}\right).
		\end{gather*}
	\end{prop}

	\begin{proof}
		Let $S_1 \sqcup S_2 \sqcup S_3 = \R^d$ be a partition of space with $\mathcal{D}(S_1, S_2) > 0$. Similarly to Proposition \ref{3siPI}, define the function
		$$
		f(x) = \max \left\{ 0, 1 - \frac{\mathcal{D}(x, S_1)}{\mathcal{D}(S_1, S_2)} \right\}.
		$$
		As seen before, the map $x \mapsto \mathcal{D}(x, S_1)$ is Lipschitz continuous with constant 1. It follows that the function $f$ is equal to 1 on $S_1$, vanishes on $S_2$, and is Lipschitz continuous on a subset of $S_3$, with the modulus of its gradient equal to $\mathcal{D} (S_1, S_2)^{-1}$; elsewhere on $S_3$, $f$~vanishes. In particular, $f(x) \in [0,1]$ for $x \in S_3$. Applying \eqref{LSIid} to $f$, we obtain
		\begin{equation} \label{3siLSI:direct}
			\E\left[\abs{f }^q \cdot \log\abs{f }^q \right] - \E\left[\abs{f }^q \right] \cdot \log \E\left[ \abs{f}^q \right] \leq \frac{1}{\cls{q}} \cdot \mathbb{E} \left[ \abs{\nabla f(x)}^q \right] \leq \frac{\pi (S_3)}{\cls{q} \cdot \mathcal{D} (S_1, S_2)^q}.
		\end{equation}
		For $x \in [0,1]$, consider the function  
		$
		\rho(x) = x \cdot \log (1/x)
		$.
		Using the convention that $0 \cdot \log (0) = 1 \cdot \log (1) = 0$, we can rewrite
		$$
		\E\left[\abs{f }^q \cdot \log\abs{f }^q \right] = {\int_{S_3}} \abs{f(x)}^q \cdot \log \left(\abs{f(x)}^q\right) \pi(\mathd x) = - {\int_{S_3}} \rho \left(\abs{f (x)}^q\right) \pi (\mathd x)
		$$
		and
		\begin{align*}
			\E\left[\abs{f }^q \right] \cdot \log \E\left[ \abs{f}^q \right] &= \left( \pi (S_1) + \int_{S_3} \abs{f(x)}^q \pi(\mathd x) \right) \cdot \log \left( \pi (S_1) + \int_{S_3} \abs{f(x)}^q \pi(\mathd x) \right) \\
			&= - \rho \left( \pi (S_1) + \int_{S_3} \abs{f(x)}^q \pi(\mathd x) \right) .
		\end{align*}
		By the first part of Lemma \ref{3siLSIlem},
		\begin{equation} \label{3siLSI:1}
			\E\left[\abs{f }^q \cdot \log\abs{f }^q \right] \geq - e^{-1} \cdot \pi(S_3).
		\end{equation}
		Noting that $\E[\abs{f}^q]\leq 1$, the second part of Lemma \ref{3siLSIlem} gives
		\begin{align*}
			\rho\left( \pi (S_1) + \int_{S_3} \abs{f(x)}^q \pi(\mathd x) \right) 		& \geq \pi	(S_1) \cdot \log \left( \frac{1}{\pi (S_1)} \right) - \int_{S_3} \abs{f(x)}^q \pi(\mathd x) \\
			&\geq  \pi	(S_1)\cdot \log \left( \frac{1}{\pi (S_1)} \right) - \pi(S_3),
		\end{align*}
		and thus
		\begin{equation} \label{3siLSI:2}
			-\E\left[\abs{f }^q \right] \cdot \log \E\left[ \abs{f}^q \right] \geq \pi	(S_1)\cdot \log \left( \frac{1}{\pi (S_1)} \right) - \pi(S_3).
		\end{equation}
		Inserting \eqref{3siLSI:1} and \eqref{3siLSI:2} into \eqref{3siLSI:direct}, we obtain
		$$
		\frac{\pi (S_3)}{\cls{q} \cdot \mathcal{D} (S_1, S_2)^q} \geq \pi(S_1)\cdot \log \left( \frac{1}{\pi (S_1)} \right) - (1 + e^{-1}) \pi(S_3),
		$$
		or equivalently,
		$$
		\pi (S_3) 
		\geq \frac{\mathcal{D} (S_1, S_2)^q}{\cls{q}^{-1} + (1 +e^{- 1})\cdot  \mathcal{D}(S_1, S_2)^q} \cdot \pi (S_1) \cdot \log \left( \frac{1}{\pi (S_1)} \right).
		$$
		By swapping $S_1$ with $S_2$ in the definition of the function $f$, an identical argument yields
		$$
		\pi (S_3) 
		\geq \frac{\mathcal{D} (S_1, S_2)^q}{\cls{q}^{-1} + (1 +e^{- 1}) \cdot  \mathcal{D}(S_1, S_2)^q}\cdot  \pi (S_2)  \cdot \log \left( \frac{1}{\pi (S_2)} \right).
		$$
		Combing these results, we have 
		\begin{align*}
			\pi (S_3) 
			&\geq \frac{\mathcal{D} (S_1, S_2)^q}{\cls{q}^{-1} + (1 +e^{- 1})\cdot  \mathcal{D}(S_1, S_2)^q}\cdot \max \left\{ \pi (S_1)\cdot \log \left( \frac{1}{\pi (S_1)} \right),~ \pi (S_2) \cdot\log \left( \frac{1}{\pi (S_2)} \right) \right\} \\
			&\geq \frac{\mathcal{D} (S_1, S_2)^q}{\cls{q}^{-1} + (1 +e^{- 1})\cdot  \mathcal{D}(S_1, S_2)^q} \cdot \min\left\{\pi(S_1), \pi(S_2)\right\}\cdot \log \left( \frac{1}{\min\left\{\pi(S_1), \pi(S_2)\right\} } \right) \\
			&\geq \frac{\mathcal{D} (S_1, S_2)^q}{\cls{q}^{-1} + (1 +e^{- 1})\cdot  \mathcal{D}(S_1, S_2)^q} \cdot \frac{\min\left\{\pi(S_1), \pi(S_2)\right\}}{2}\cdot \log \left( \frac{2}{\min\left\{\pi(S_1), \pi(S_2)\right\} } \right)
		\end{align*}
		The advantage of this last expression is that the function $x \mapsto x/2 \cdot \log (2/x)$ is increasing everywhere on $(0,1/2)$, contrary to the function $x \mapsto x \cdot \log (1/x)$. The $L^q$-log-Sobolev inequality thus implies a three-set isoperimetric inequality
		$$
		\pi (S_3) \geq \Upsilon (\mathcal{D}(S_1, S_2)) \cdot \Psi (\min\{\pi(S_1), \pi(S_2)\}),
		$$
		where
		$$
		\Upsilon(t) = \frac{\cls{q} t^q}{1 + (1 +e^{- 1}) \cls{q} t^q}, \qquad \Psi(t) = \frac{t}{2} \cdot \log \left( \frac{2}{t}\right).
		$$
	\end{proof}

	%The logarithmic term in $\Psi$ from Proposition \ref{3siLSI} can be exploited to improve the mixing time's dependence on the warm start parameter \citep{chen2020fast}. However, we do not pursue this direction here. 
	Notably, the $L^q$-Poincar\'e and $L^q$-log-Sobolev inequalities both lead to three-set isoperimetric inequalities with $\Upsilon(t) \sim \cpo{q}t^q$ as $t\to 0$. Here the sign $\sim$ means that the two quantities are asymptotic, meaning their ratio converges to a constant as $t\to 0$.
	This regime is particularly relevant in high-dimensional settings, where $t$ typically scales inversely with the dimension, as per the discussion following Corollary \ref{conductanceProfileLowerBound}.
	In contrast, when $\pi$ is log-concave, we have $\Upsilon(t)\sim t$ as $t\to 0$ \citep[Subsection 3.2]{andrieu2024explicit}.
	%In particular, when $q=1$, this recovers the results of \citet{bobkov1997some} and \citet{rothaus1985analytic} up to constant factors.

	\subsection{Close coupling conditions for the Gibbs kernels}\label{sec:ccss}

	Here, we establish close coupling conditions for the systematic-scan and random-scan Gibbs kernels, assuming  that the conditional distributions of the target distribution $\pi$ are \hbox{TV continuous} (as per Definition \ref{def:tvcontinuous}). 
	%The following results rely on  sequential coupling arguments similar to those of \citet{marton2004measure}; see also \citet{roberts2013note} for a formal construction of these couplings.
	The following results rely on sequential coupling arguments; see \citet{roberts2013note} for a formal construction of such couplings, and \citet{marton2004measure, wang2014convergence} for related coupling techniques in Wasserstein distance.
	We begin with the systematic-scan Gibbs sampler.


	%Combined with the three-set isoperimetric inequalities from the previous subsection, these conditions provide a means of bounding the conductance of each Gibbs sampler for a broad class of target distributions. 



	\begin{prop} \label{ssgibbsccc}
		Suppose that the conditional distributions of $\pi$ are $(M,\beta)$-TV continuous.
		Then,
		$$
		\norm{P_{\mathrm{SS}} (x, \cdot) - P_{\mathrm{SS}} (y, \cdot)}_\tv \leq 1 - \left( 1 - M \abs{x-y}^\beta\right)^d \qquad \forall x,y \in \R^d.
		$$
		Hence, $P_{\mathrm{SS}}$ satisfies a $(\delta, \varepsilon)$-close coupling condition with
		$$
		\delta  = \left(Md\right)^{-1/\beta}, \qquad \varepsilon = e^{-1}.
		$$
	\end{prop}


	\begin{proof}
		The coupling inequality for the total variation distance can be expressed as
		$$
		\norm{P_{\mathrm{SS}} (x, \cdot) - P_{\mathrm{SS}} (y, \cdot)}_\tv = \inf \left\{ \Pb (U \neq V ) : U \sim P_{\mathrm{SS}} (x, \cdot),  V \sim  P_{\mathrm{SS}} (y, \cdot) \right\}.
		$$
		%To construct a candidate coupling, we define $U^{(k)}$ and $V^{(k)}$, for $k = 0,\dots, d$, as the intermediate states of two coupled Markov chains starting from $x$ and $y$, respectively. These represent the configurations after the first $k$ coordinates have been updated in a sequential scan. We now describe a sequential coupling of $P_{\mathrm{SS}} (x, \cdot)$ and $P_{\mathrm{SS}} (y, \cdot)$ as follows:
		To construct a candidate coupling of \( P_{\mathrm{SS}}(x, \cdot) \) and \( P_{\mathrm{SS}}(y, \cdot) \), we introduce intermediate states \( U^{(k)} \) and \( V^{(k)} \), for \( k = 0, \dots, d \), which represent the configurations after updating the first \( k \) coordinates of two chains initialized at \( x \) and \( y \), respectively. The coupling proceeds as follows:

		\begin{itemize}
			\item Initialize $U^{\left(0\right)} = x$ and $V^{\left(0\right)} = y$.
			\item For $k=1, \dots, d$, draw a maximal coupling
			$$
			W \sim \pi \left( \cdot \mid U^{\left(k-1\right)}_{-k}\right), \qquad W' \sim \pi \left( \cdot \mid V^{\left(k-1\right)}_{-k}\right),
			$$
			such that
			\begin{equation} \label{sscoupling}
				\Pb \left(W \neq W'\mid U^{\left(k-1\right)}_{-k}, V^{\left(k-1\right)}_{-k} \right) = \norm{ \pi \left( \cdot \mid U^{\left(k-1\right)}_{-k}\right) -  \pi \left( \cdot \mid V^{\left(k-1\right)}_{-k}\right)}_\tv.
			\end{equation}
			See \citet[Theorem 5.2]{lindvall2002lectures} for an explicit construction of a maximal coupling. Note that both sides of \eqref{sscoupling} are random quantities depending on $U^{\left(k-1\right)}$, $V^{\left(k-1\right)}$.
			\item Update the variables by setting
			$$
			U^{(k)} = \left(U^{(k-1)}_{-k}, W\right), \qquad V^{(k)} = \left(V^{(k-1)}_{-k}, W'\right).
			$$
			In words, only the $k$'th coordinate is updated when transitioning from $U^{(k-1)}$ to $U^{(k)}$ (and from $V^{(k-1)}$ to $V^{(k)}$). The notation used here for indexing $U^{(k)}$ and $V^{(k)}$ follows the convention introduced in \eqref{notationindex}.
			\item Finally, set $U = U^{\left(d\right)}$, $V = V^{\left(d\right)}$.
		\end{itemize}
		By construction, we have $U \sim P_{\mathrm{SS}}(x, \cdot)$ and $V \sim P_{\mathrm{SS}} (y, \cdot)$. Moreover, observe that for all $k \in [d]$, we have
		$
		U^{\left(k\right)} = \left( U_{1:k}, x_{k+1:d} \right)$ and  $V^{\left(k\right)} = \left( V_{1:k}, y_{k+1:d} \right)
		$.
		Using this, \eqref{sscoupling} can be rewritten as
		\begin{equation} \label{sscoupling2}
			\Pb (U_k \neq V_k \mid  U_{1:k-1}, V_{1:k-1} ) = \norm{ \pi \left( \cdot \mid U_{1:k-1}, x_{k+1:d}\right) - \pi \left( \cdot \mid V_{1:k-1}, y_{k+1:d}\right)}_\tv.
		\end{equation}
		Conditional on the event $\left\{ U_{1:k-1} = V_{1:k-1}\right\}$, we have
		$$
		\abs{\left( U_{1:k-1}, x_{k+1:d}\right) - \left( V_{1:k-1}, y_{k+1:d}\right)} = \abs{x_{k+1:d} - y_{k+1:d}}.
		$$
		Thus,  by \eqref{sscoupling2} and the assumption that the conditional distributions of \(\pi\) are \((M, \beta)\)-TV continuous, it follows that
		\begin{align*}
			\Pb &(U_k \neq V_k \mid U_{1:k-1} = V_{1:k-1}) \\
			&=\E_{U_{1:k-1}, V_{1:k-1}} \left[ \norm{ \pi \left( \cdot \mid U_{1:k-1}, x_{k+1:d}\right) - \pi \left( \cdot \mid V_{1:k-1}, y_{k+1:d}\right)}_\tv \mid  U_{1:k-1} = V_{1:k-1} \right] \\
			&\leq M\abs{x_{k+1:d} - y_{k+1:d}}^\beta,
		\end{align*}
		where the expectation is taken over the joint distribution of $U_{1:k-1}, V_{1:k-1}$.
		We can now bound the total variation distance between $P_{\mathrm{SS}} (x, \cdot)$ and $P_{\mathrm{SS}} (y, \cdot)$ as follows:
		\begin{align*}
			\norm{P_{\mathrm{SS}} (x, \cdot) - P_{\mathrm{SS}} (y, \cdot) }_\tv 
			&\leq \Pb (U \neq V) \\ 
			&= 1 - \Pb (U = V) \\
			&= 1 - \Pb \left( \bigcap_{k=1}^d \left\{ U_k = V_k \right\} \right) \\
			%&= 1 - \Pb \left(U_1 = V_1\right) \cdot \Pb \left(U_2 = V_2 \kid U_1 = V_1\right) \\
			%&\phantok{= } \cdot \ldots \cdot \Pb \left(U_{d-1} = V_{d-1} \kid U_{1:d-2} = V_{1:d-2}\right) \cdot \Pb \left(U_{d} = V_{d} \kid U_{1:d-1} = V_{1:d-1}\right) \\
			&= 1 - \prod_{k=1}^d \Pb (U_k = V_k \mid U_{1:k-1} = V_{1:k-1}) \\
			&= 1 - \prod_{k=1}^d \left[1-\Pb (U_k \neq V_k \mid U_{1:k-1} = V_{1:k-1})\right] \\
			%&= 1 - \prod_{k=1}^d \left(1- \frac{\int  p_{k-1} \left(z,z\right) \norm{ \pi \left( \cdot \mid z, x_{k+1:d}\right) - \pi \left( \cdot \mid z, y_{k+1:d}\right)}_\tv \mathd z }{\int p_{k-1} \left(z,z\right) \mathd z} \right) \\
			&\leq 1 - \prod_{k=1}^d \left(1-  M \abs{x_{k+1:d} - y_{k+1:d}}^\beta\right) \\
			&\leq 1 - \left(1 -  M \abs{x - y}^\beta\right)^d.
		\end{align*}
	\end{proof}

	%\subsection{The close coupling condition for the random-scan Gibbs kernel} \label{sec:ccrs}

	We now turn our attention towards obtaining a close coupling for the random-scan Gibbs sampler. However, one issue immediately becomes apparent: when $x,y \in \R^d$  do not share a coordinate (i.e., when $x-y$ has a non-zero component in each coordinate direction), the supports of $P_{\mathrm{RS}}(x, \cdot)$ and $P_{\mathrm{RS}} (y, \cdot)$ are disjoint. In this case,
	$$
	\norm{P_{\mathrm{RS}} (x, \cdot) - P_{\mathrm{RS}} (y, \cdot)}_\tv = 1.
	$$	
	To circumvent this issue, we adopt a similar approach to \citet{narayanan2022mixing} by establishing a close-coupling condition for the iterated kernel  $P_{\mathrm{RS}}^N$. Notably, when $N \geq d$, $P_{\mathrm{RS}}^N (x, \cdot)$ is globally supported  for all $x \in \R^d$. It turns out that $N \sim d \cdot \log d$ as $d \to \infty$ is indeed the correct scaling in order to get a non-degenerate close coupling condition for the iterated random-scan Gibbs kernel, as formalized in the next lemma. Let $\lceil \cdot \rceil$ denote the ceiling function. The proof can be found in Appendix \ref{sec:appendixproofs}.

	\begin{lem} \label{couponlem}
		Let
		$
		I_1, \dots, I_{N} \sim \mathrm{Unif} [d]
		$ be independent and identically distributed.
		Denote by $\Xi$ the set of unique values attained by $I_1, \dots, I_{N}$. If $N =  \lceil 4 d \cdot \log d\rceil$, then
		$$
		\Pb ( \Xi = [d]) \geq \frac{1}{2}.
		$$
	\end{lem}



	Lemma \ref{couponlem} is closely related to the classic coupon collector problem in probability \citep{erdos1961classical}. Using the same notation, observe that when $N=d$, we have
	$$
	\Pb  ( \Xi =  [d]) = \frac{d!}{d^d} \sim \frac{\sqrt{d}}{e^d}
	$$
	as $d \to \infty$, by Stirling's formula. The probability of observing all $d$ unique values in exactly $d$ draws thus decreases exponentially with the dimension $d$.

	\begin{prop} \label{rsgibbsccc}
		Suppose that the conditional distributions of $\pi$ are $(M,\beta)$-TV continuous. Let $N_d =  \lceil 4 d \cdot \log d \rceil$. Then,
		$$
		\norm{P_{\mathrm{RS}}^{N_d} (x, \cdot) - P_{\mathrm{RS}}^{N_d} (y, \cdot)}_\tv \leq 1 - \frac{1}{2}  ( 1 - M \abs{x-y}^\beta)^{N_d} \qquad \forall x,y \in \R^d.
		$$
		Hence, $P_{\mathrm{RS}}^{N_d}$ satisfies a $(\delta, \varepsilon)$-close coupling condition with
		$$
		\delta  = \left(MN_d\right)^{-1/\beta}, \qquad \varepsilon = \left(2e\right)^{-1}.
		$$
		In particular, $\delta \geq (5Md\cdot \log d)^{-1/\beta}$.
	\end{prop}

	\begin{proof}
		Similarly to Theorem \ref{ssgibbsccc}, we construct a sequential coupling of $P_{\mathrm{RS}}^{N_d} (x, \cdot)$ and $P_{\mathrm{RS}}^{N_d} (y, \cdot)$ as follows:
		\begin{itemize}
			\item Draw
			$
			I_1, \dots, I_{N_d} \sim \mathrm{Unif} [d]
			$
			independent and identically distributed.
			\item Initialize $U^{\left(0\right)} = x$ and $V^{\left(0\right)} = y$.
			\item For $k = 1, \dots, d$, draw a maximal coupling
			$$
			W_k \sim \pi \left( \cdot \mid U^{\left(k-1\right)}_{-{I_k}}\right), \qquad W_k' \sim \pi \left( \cdot \mid V^{\left(k-1\right)}_{-{I_k}}\right),
			$$
			such that
			\begin{equation} \label{rscoupling}
				\Pb \left(W_k \neq W_k'\mid U^{\left(k-1\right)}_{-{I_k}}, V^{\left(k-1\right)}_{-{I_k}} \right) = \norm{ \pi \left( \cdot \mid U^{\left(k-1\right)}_{-{I_k}}\right) -  \pi \left( \cdot \mid V^{\left(k-1\right)}_{-{I_k}}\right)}_\tv.
			\end{equation}
			Note that both sides of \eqref{rscoupling} are random quantities depending on $U^{\left(k-1\right)}$, $V^{\left(k-1\right)}, I_k$.
			\item Update the variables by setting
			$$
			U^{(k)} = \left(U^{(k-1)}_{-I_k}, W\right), \qquad V^{(k)} = \left(V^{(k-1)}_{-I_k}, W'\right).
			$$
			In words, only the $I_k$'th coordinate is updated when transitioning from $U^{(k-1)}$ to $U^{(k)}$ (and from $V^{(k-1)}$ to $V^{(k)}$). The notation used here for indexing $U^{(k)}$ and $V^{(k)}$ follows the convention introduced in \eqref{notationindex}.
			\item Finally, set $U = U^{(N_d)}$, $V = V^{\left(N_d\right)}$.
		\end{itemize}
		By construction, $U \sim P_{\mathrm{RS}}^{N_d} (x, \cdot)$ and $V \sim P_{\mathrm{RS}}^{N_d} (y, \cdot)$. 
		As before, denote by $\Xi$ the set of unique values attained by $I_1, \dots, I_{N_d}$. When $x$ and $y$ differ in at least two coordinates, the event $\left\{U = V\right\}$ has a non-zero probability of occurring only if $\Xi = [d]$, i.e., when all coordinates have been updated at least once by $P_{\mathrm{RS}}^{N_d}$. More generally, for all  $x,y \in \R^d$, we have
		\begin{align*}
			\Pb ( U = V ) \geq  \Pb ( \{U = V\} \cap \{\Xi = \left[ d \right]\} )  
			= \Pb (\Xi = [d]) \cdot  \Pb (U = V \mid \Xi = \left[ d \right]).
		\end{align*}
		By Lemma \ref{couponlem}, $\Pb ( \Xi = \left[ d \right]) \geq 1/2$ when $N_d = \left \lceil 4 d \cdot \log d \right \rceil$. Hence, for this value of $N_d$, we get 
		\begin{align}
			\norm{P_{\mathrm{RS}}^{N_d} (x, \cdot) - P_{\mathrm{RS}}^{N_d} (y, \cdot)}_\tv &\leq \Pb (U \neq V) \nonumber \\
			&= 1 - \Pb (U = V) \nonumber \\
			&\leq 1 - \Pb (\Xi = [d]) \cdot \Pb (U = V \mid \Xi = [d]) \nonumber\\
			&\leq 1 - \frac{1}{2}\cdot  \Pb (U = V \mid \Xi = [d]). \label{rscoupling2}
		\end{align}
		By matching each step of the sequential coupling described above, the conditional probability in \eqref{rscoupling2} can be lower bounded by
		\begin{align}
			\Pb (U = V \mid \Xi = [d]) 	&\geq  \Pb \left( \bigcap_{k=1}^{N_d} \left\{ W_k = W_k'\right\} ~\middle| ~ \Xi = \left[ d \right]\right)  \nonumber \\
			&= \prod_{k=1}^{N_d}  \Pb \left(W_k = W_k' ~\middle| ~ \bigcap_{l=1}^{k-1} \left\{ W_l = W_l'\right\} \cap \left\{\Xi = \left[ d \right]\right\}\right)  \nonumber \\
			&= \prod_{k=1}^{N_d} \left[ 1- \Pb \left(W_k \neq W_k' ~\middle| ~ \bigcap_{l=1}^{k-1} \left\{ W_l = W_l'\right\} \cap \left\{\Xi = \left[ d \right]\right\}\right)\right] \label{rscoupling3}.
		\end{align}
		Consider a fixed a sequence of indices $I_1, \dots, I_{N_d}$ and $k \in \left[ N_d\right]$. Observe that up to the $k$'th step of our sequential coupling, the coordinates of $U^{\left(k\right)}$ that differ from those of $U^{\left(0\right)} = x$ are necessarily equal to some $W_l$ with $l \leq k$. Identically, the coordinates of $V^{\left(k\right)}$ that differ from those of $V^{\left(0\right)} = y$ are necessarily equal to some $W_l'$ with $l \leq k$. Therefore, conditional on the event 
		$
		\bigcap_{l=1}^{k-1} \left\{ W_l = W_l'\right\},
		$
		we have
		$$
		\left \lvert U^{\left(k-1\right)} - V^{\left(k-1\right)} \right \rvert \leq \left \lvert x -y \right \rvert.
		$$
		As $\left(W_k, W_k'\right)$ is a maximal coupling, it follows that 
		\begin{align}
			\Pb &\left( W_k \neq W_k' ~\middle| ~ \bigcap_{l=1}^{k-1}  \left\{ W_l = W_l'\right\} \cap \left\{\Xi = \left[ d \right]\right\}\right) \nonumber \\ 
			&= \E_{U^{\left(k-1\right)}, V^{\left(k-1\right)}, I_k} \left[\norm{ \pi \left( \cdot \mid U^{\left(k-1\right)}_{-{I_k}}\right) -  \pi \left( \cdot \mid V^{\left(k-1\right)}_{-{I_k}}\right)}_\tv ~\middle| ~  \bigcap_{l=1}^{k-1} \left\{ W_l = W_l'\right\} \cap \left\{\Xi = \left[ d \right] \right\} \right] \nonumber \\
			&\leq \E_{U^{\left(k-1\right)}, V^{\left(k-1\right)}, I_k} \left[ M\left \lvert U^{\left(k-1\right)}_{-I_k} - V^{\left(k-1\right)}_{-I_k} \right \rvert^\beta  ~\middle| ~  \bigcap_{l=1}^{k-1} \left\{ W_l = W_l'\right\} \cap \left\{\Xi = \left[ d \right] \right\} \right] \nonumber \\
			&\leq \E_{U^{\left(k-1\right)}, V^{\left(k-1\right)}, I_k} \left[ M \left \lvert U^{\left(k-1\right)} - V^{\left(k-1\right)} \right \rvert^\beta  ~\middle| ~ \bigcap_{l=1}^{k-1} \left\{ W_l = W_l'\right\} \cap \left\{\Xi = \left[ d \right] \right\} \right] \nonumber \\
			&\leq M\left \lvert x - y \right \rvert^\beta, \label{rscoupling4}
		\end{align}
		where the subscript in the expectation indicates that it is taken with respect to the joint distribution of $U^{(k-1)}, V^{(k-1)}, I_k$.
		Combining \eqref{rscoupling2}, \eqref{rscoupling3}, \eqref{rscoupling4}, we finally obtain
		$$
		\norm{P_{\mathrm{RS}}^{N_d} (x, \cdot) - P_{\mathrm{RS}}^{N_d} (y, \cdot)}_\tv \leq 1 - \frac{1}{2}  \left( 1 - M \left \lvert x-y\right \rvert^\beta\right)^{N_d}.
		$$
	\end{proof}

	When a geometric drift condition holds for a certain Lyapunov function, these close coupling conditions are reminiscent of local Doeblin conditions \citep[Assumption 3.4]{hairer2010convergence} restricted to particular level sets of the Lyapunov function; see also \citep[Assumption 2]{hairer2011yet} for an alternative representation in terms of minorization conditions. In this case, one can establish geometric rates of convergence for the Markov process 
	(\citealp[Theorem 3.6]{hairer2010convergence}; \citealp[Theorem 1.2]{hairer2011yet}). Nevertheless, a naive application of Propositions \ref{ssgibbsccc} and \ref{rsgibbsccc} leads to spectral gap bounds that scale exponentially with the dimension.
	It is unclear whether this approach can be improved in the present setting.

	\subsection{Mixing time bounds for the Gibbs sampler} \label{sec:mixbounds}

	By combining the three-set isoperimetric inequalities from Subsection \ref{sec:3sifi} with the close coupling conditions from Subsection \ref{sec:ccss}, we can bound the conductance of the systematic-scan and random-scan Gibbs kernels. These results apply to target distributions that satisfy a $L^q$-Poincar\'e or $L^q$-log-Sobolev inequality, and whose conditional distributions are TV continuous. Throughout this subsection, we use $\lesssim$ to denote inequalities that hold up to a universal constant factor.

	\begin{thm} \label{thm:condss}
		Consider a target distribution $\pi$ that satisfies \po{q} with constant $\cpo{q}$. Suppose that the conditional distributions of $\pi$ are $(M,\beta)$-TV continuous. Then, the conductance of the systematic-scan Gibbs kernel is bounded by
		$$
		\Phi (P_\mathrm{SS}) \gtrsim \min \left\{1, \frac{\cpo{q}}{\left(Md\right)^{q/\beta}} \right\}.
		$$
		If the chain is initialized at a $\Omega$-warm start, then the $\zeta$-mixing time is bounded by
		$$
		\tau (\zeta, P_{\mathrm{SS}}) \lesssim \max \left\{1, \frac{\left(Md\right)^{2q/\beta}}{\cpo{q}^2}\right\} \cdot \log \left( \frac{\sqrt{\Omega}}{\zeta}\right).
		$$
	\end{thm}

	\begin{proof}
		The bound on the conductance follows from combining Corollary \ref{conductanceProfileLowerBound}, Proposition \ref{3siPI}, and Proposition \ref{ssgibbsccc}. The bound on the mixing time is obtained via Corollary \ref{lovsimCor}.
	\end{proof}

	\begin{thm} \label{thm:condrsit}
		Consider a target distribution $\pi$ that satisfies \po{q} with constant $\cpo{q}$. Suppose that the conditional distributions of $\pi$ are $(M,\beta)$-TV continuous. Let $N_d = \left \lceil 4 d \cdot \log d \right \rceil$. Then, the conductance of the iterated random-scan Gibbs kernel is bounded by
		$$
		\Phi \left(P^{N_d}_{\mathrm{RS}} \right) \gtrsim \min \left\{ 1, \frac{\cpo{q}}{\left(MN_d\right)^{q/\beta}} \right\} .
		$$
		The spectral gap satisfies
		$$
		\lambda_2 \left(P^{N_d}_{\mathrm{RS}} \right) \gtrsim \min \left\{ 1, \frac{\cpo{q}^2}{\left(MN_d\right)^{2q/\beta}} \right\} .
		$$
		If the chain is initialized at a $\Omega$-warm start, then the $\zeta$-mixing time is bounded by
		$$
		\tau \left(\zeta, P^{N_d}_{\mathrm{RS}}\right) \lesssim \max \left\{1, \frac{\left(MN_d\right)^{2q/\beta}}{\cpo{q}^2} \right\}  \cdot \log \left( \frac{\sqrt{\Omega}}{\zeta}\right).
		$$
	\end{thm}

	\begin{proof}
		The conductance bound follows from Corollary \ref{conductanceProfileLowerBound}, Proposition \ref{3siPI}, and Proposition \ref{rsgibbsccc}. The spectral gap is then bounded using Theorem \ref{cheegerinequalties}, while the mixing time bound is obtained via Corollary \ref{lovsimCor}.
	\end{proof}

	%Nevertheless, we believe that the lower bound on the spectral gap in Theorem~\ref{cheegerinequalties} is not tight for the Gibbs sampler. This belief is supported by the case of the random walk on the $d$-dimensional hypercube, where \citet[Chapter~5]{trevisan2013lecture} showed that the conductance and spectral gap are of the same order. The Gibbs sampler shares a similar local structure: each update modifies only a single coordinate, analogous to the single-bit flips in the hypercube walk.

	We now focus on bounding the conductance and spectral gap of the random-scan Gibbs kernel $P_{\mathrm{RS}}$. As noted by \citet[Lemma 5.3]{narayanan2022mixing}, for any reversible Markov kernel $P$ and for all $N \geq 1$, we have
	\begin{equation*} \label{condbounditerated}
		\Phi (P) \geq \frac{1}{N} \cdot \Phi \left(P^N\right).
	\end{equation*}
	Let $  \sigma (P)$ denote the second largest eigenvalue of $P$, so that $\lambda_2 (P) = 1 -   \sigma (P)$. Notably, $  \sigma \left(P^N\right) =   \sigma (P)^N$, which implies that
	\begin{align}
		\lambda_2 (P) &= 1 -   \sigma (P) \nonumber \\ 
		&= 1 -   \sigma \left(P^N\right)^{1/N} \nonumber  \\ 
		&= 1 - \left(1 - \lambda_2 \left(P^N\right)\right)^{1/N}\nonumber  \\
		&\geq 1 - \left( 1- \frac{1}{N} \cdot \lambda_2 \left(P^N\right) \right) \nonumber  \\
		&= \frac{1}{N} \cdot \lambda_2 \left(P^N\right) \nonumber,
	\end{align}
	where we have used the inequality $1-t \leq \left(1 - t/N\right)^N$ for $0 \leq t \leq 1$. Regarding mixing times, observe that $\tau (\zeta, P) \leq N \cdot \tau \left(\zeta, P^N\right)$.

	\begin{cor} \label{cor:condrs}
		Under the conditions of Theorem \ref{thm:condrsit}, the conductance of the random-scan Gibbs kernel is bounded by
		$$
		\Phi (P_{\mathrm{RS}} ) \gtrsim \frac{1}{d\cdot \log d} \cdot \min \left\{ 1, \frac{\cpo{q}}{M^{q/\beta} (d\cdot \log d)^{q/\beta}} \right\}
		.
		$$
		The spectral gap satisfies
		$$
		\lambda_2 (P_{\mathrm{RS}} ) \gtrsim \frac{1}{d\cdot \log d} \cdot \min \left\{ 1, \frac{\cpo{q}^2}{M^{2q/\beta} (d\cdot \log d)^{2q/\beta}} \right\}
		.
		$$
		The $\zeta$-mixing time is bounded by
		$$
		\tau (\zeta, P_{\mathrm{RS}}) \lesssim d\cdot \log d \cdot \max \left\{ 1, \frac{M^{2q/\beta} (d\cdot \log d)^{2q/\beta}}{\cpo{q}^2} \right\}
		\cdot \log \left( \frac{\sqrt{\Omega}}{\zeta}\right).
		$$
	\end{cor}

	%The logarithmic term in $\Psi$ from Proposition \ref{3siLSI} can be exploited to improve the mixing time's dependence on the warm start parameter \citep{chen2020fast}. However, we do not pursue this direction here. 

	These results demonstrate that the systematic-scan and random-scan Gibbs samplers exhibit polynomial mixing time dependence on the dimension $d$ for a large class of target distributions.
	Note that a single step of the systematic-scan kernel $P_\mathrm{SS}$ updates all $d$ coordinates, whereas the random-scan kernel $P_\mathrm{RS}$ only updates one.
	Even after accounting for this difference, a residual $\log d$ factor remains in the mixing time bounds for random-scan.
	This additional $\log d$ factor
	%in the random-scan Gibbs sampler’s bounds%
	highlights a modest penalty compared to systematic scan for well-behaved target distributions. This aligns with prior heuristic observations about the efficiency of these sampling schemes \citep{diaconis2013some} and arises naturally from spectral bounds on mixing times \citep{gaitonde2024comparison}.

	By Proposition \ref{3siLSI}, all results in this subsection extend to distributions satisfying \ls{q} instead of \po{q}, with the conductance bounds remaining equivalent up to constant factors.
	Consequently, the bounds on the mixing time in total variation distance remain unchanged when replacing a Poincar\'e inequality with a log-Sobolev inequality of the same order.
	However, improvements may be possible when using a different norm to define the mixing time. 
	For instance, in $\chi^2$-divergence, \citet[Theorem 1]{chen2020fast} demonstrated that the logarithmic factor in $\Psi$ from Proposition \ref{3siLSI} can be exploited to improve the mixing time's dependence on the warm start parameter (see Corollary \ref{lovsimCor}), reducing it from $\log$ to $\log \log$.

	%For instance, in $\chi^2$-divergence, \citet[Lemma 3]{chen2020fast} showed that the logarithmic factor in $\Psi$ from Proposition~\ref{3siLSI} allows improving the mixing time dependence on the warm start parameter from $\log$ to $\log \log$.


	%However, in $\chi^2$-divergence, \citet{chen2020fast} demonstrated that the logarithmic factor in $\Psi$ from Proposition \ref{3siLSI} can be exploited to improve the mixing time's dependence on the warm start parameter.
	%	We do not explore this direction here.



	\section{Extensions and applications} \label{sec:extensionapp}

	\subsection{Implications for Lipschitz and smooth potentials} \label{subsection:potentials}

	We now examine the regularity assumption on the conditional distributions of the target $\pi$ introduced in Definition \ref{def:tvcontinuous}.
	The density of $\pi$ with respect to the Lebesgue measure can be written as	
	$$
	\pi (\mathd x) \propto e^{-U\left(x\right)} \mathd x,
	$$
	where the function $U:\R^d \to \R$ is known as the potential.
	Many previous works assume that the potential function is either Lipschitz continuous \citep{lehec2023langevin} or smooth \citep[see, e.g.,][]{ascolani2024entropy}. 
	We show that TV continuity of the conditional distributions of $\pi$ (Definition \ref{def:tvcontinuous}) is a strictly weaker condition than these regularity assumptions on $U$.

	\begin{defn} \label{logContDef}
		Let $L > 0$. The potential $U$ is said to be $L$-Lipschitz continuous if
		$$
		\abs{U(x) - U(y)} \leq L \abs{x - y} \qquad \forall x,y \in \R^d.
		$$
		%When $\alpha = 1$, $U$ is said to be $L$-Lipschitz continuous.
		Equivalently, the distribution $\pi$ is said to be $L$-log-Lipschitz continuous.
	\end{defn}

	\begin{defn} \label{logSmoothDef}
		Let $L > 0$. The potential $U$ is said to be $L$-smooth if $U$ is continuously differentiable with
		$$
		\abs{\nabla U(x) - \nabla U(y)} \leq L \abs{x - y} \qquad \forall x,y \in \R^d.
		$$
		%When $\alpha = 1$, $U$ is said to be $L$-smooth.
		Equivalently, the distribution $\pi$ is said to be $L$-log-smooth.
	\end{defn}

	To establish our result, we first demonstrate that log-Lipschitz continuity and log-smoothness extend to the marginal distributions of $\pi$. The proof of the following lemma is located in Appendix \ref{sec:appendixproofs}.

	%To achieve this, we begin by showing that log-Lipschitz continuity and log-smoothness are inherited by the marginal distributions of $\pi$.

	\begin{lem} \label{marginalsloglipsmooth}
		The following properties hold:
		\begin{itemize}
			\item If the distribution $\pi$ is $L$-log-Lipschitz continuous, then all marginal distributions of $\pi$ are also $L$-log-Lipschitz continuous.
			\item If the distribution $\pi$ is $L$-log-smooth, then all marginal distributions of $\pi$ are also $L$-log-smooth.
		\end{itemize}
	\end{lem}



	Lemma \ref{marginalsloglipsmooth} complements \citet[Theorems 3.3 and 3.8]{saumard2014log}, who proved that (strong) log-concavity is also inherited by the marginal distributions of $\pi$.

	\begin{lem} \label{tvconditionalsloglip}
		Suppose that the distribution $\pi$ is $L$-log-Lipschitz continuous. Then, the conditional distributions of $\pi$ are $(\sqrt{L}, 1/2)$-TV continuous.
	\end{lem}

	\begin{proof}
		For simplicity,  we redefine the variables as $ x_{-k} = s$, $y_{-k} = t$. The joint distribution can be rewritten as
		$
		\pi (\theta, s) \propto e^{-U(\theta, s)}.
		$
		From this, the conditional distribution is expressed as
		$$
		\pi (\theta | s ) = \frac{\pi (\theta, s)}{\pi(s)} = \frac{e^{-U(\theta, s)}}{\int e^{-U(\psi, s) } \mathd \psi} = \frac{e^{-U(\theta, s)}}{e^{-V(s)}},
		$$
		where $$V(s) = - \log \left(\int e^{-U(\psi, s) } \mathd \psi\right).$$ By Lemma \ref{marginalsloglipsmooth}, the function $V$ is $L$-Lipschitz continuous.
		We now compute the KL-divergence between $\pi (\cdot \mid s)$ and $\pi (\cdot \mid t)$:
		\begin{align*}
			\mathrm{KL} (\pi (\cdot \mid s),\pi (\cdot \mid t) ) &= \int  \log \left(\frac{\pi (  \theta \mid s )}{\pi (  \theta \mid t )}\right) \pi ( \mathd \theta \mid s ) \\
			&= \int \log\pi (  \theta \mid s )\pi ( \mathd \theta \mid s ) - \int \log \pi (  \theta \mid t ) \pi ( \mathd \theta \mid s ) \\
			&= - \int U(\theta, s) \pi ( \mathd \theta \mid s )  + V(s) +  \int U(\theta, t) \pi ( \mathd \theta \mid s )  - V(t) \\
			&\leq \int  \abs{U(\theta, s) - U(\theta, t) }   \pi ( \mathd \theta \mid s ) +  \abs{V(s) - V(t)} \\
			&\leq 2L \abs{s-t}.
		\end{align*}
		We conclude by applying Pinsker's inequality:
		\begin{align*}
			\norm{ \pi (\cdot \mid s) -  \pi (\cdot \mid t) }_\tv &\leq \sqrt{\frac{1}{2} \cdot \mathrm{KL} (\pi (\cdot \mid s),\pi (\cdot \mid t) )} \\
			&\leq \sqrt{L \abs{s-t}}.
		\end{align*}

	\end{proof}

	\begin{lem} \label{tvconditionalslogsmooth}
		Suppose that the distribution $\pi$ is $L$-log-smooth. Then, the conditional distributions of $\pi$ are $(\sqrt{L}, 1)$-TV continuous.
	\end{lem}
	\begin{proof}
		We proceed similarly to Lemma \ref{tvconditionalsloglip}. Using the same notation, recall that
		\begin{align*}
			\mathrm{KL} (\pi (\cdot \mid s),\pi (\cdot \mid t) ) 
			= \int ( U(\theta, t) - U(\theta, s) )   \pi ( \mathd \theta \mid s ) +  V(s) - V(t) .
		\end{align*}
		%where $$V(s) = - \log \left(\int e^{-U(\psi, s) } \mathd \psi\right).$$ By Lemma \ref{marginalsloglipsmooth}, the function $V$ is $L$-smooth. 
		Observe that
		$
		\nabla V(s) = 
		%\frac{\int \nabla_s U(\psi, s)e^{-U(\psi, s)} \mathd \psi}{\int e^{-U(\psi, s)} \mathd \psi} = 
		\int \nabla_s U(\theta, s) \pi(\mathd \theta \mid s).
		$
		It follows that
		\begin{align*}
			\mathrm{KL} (\pi (\cdot \mid s),\pi (\cdot \mid t) ) 
			&= \int ( U(\theta, t) - U(\theta, s) )   \pi ( \mathd \theta \mid s ) +  V(s) - V(t) \\
			&\leq \int \left( \nabla_s U(\theta, s)^T (t-s) + \frac{L}{2} \abs{s-t}^{2}\right)  \pi ( \mathd \theta \mid s ) \\
			&\quad  + \nabla V(t)^T (s-t) +  \frac{L}{2} \abs{s-t}^{2} \\
			&\leq \int ( \nabla_s U (\theta, s) - \nabla_t U (\theta, t))^T (t-s) \pi ( \mathd \theta \mid s ) +  L \abs{s-t}^{2} \\
			&\leq 2L \abs{s-t}^{2}.
		\end{align*}
		We conclude by applying Pinsker's inequality:
		\begin{align*}
			\norm{ \pi (\cdot \mid s) -  \pi (\cdot \mid t) }_\tv &\leq \sqrt{\frac{1}{2} \cdot \mathrm{KL} (\pi (\cdot \mid s),\pi (\cdot \mid t) )} \\
			&\leq \sqrt{L} \abs{s-t}.
		\end{align*}
	\end{proof}

	The class of log-smooth and (strongly) log-concave target distributions is widely studied in the analysis of MCMC mixing times; see \citet{ascolani2024entropy, wadia2024mixing} for results regarding the Gibbs sampler. For comparison, we now establish conductance bounds for the systematic-scan and random-scan Gibbs kernels when the target distribution is log-smooth and satisfies \po{1}. These results follow directly from Theorem \ref{thm:condss} and Corollary \ref{cor:condrs}, combined with Lemma \ref{tvconditionalslogsmooth}.

	\begin{cor} \label{cor:condsslog}
		Consider a $L$-log-smooth target distribution $\pi$ that satisfies \po{1}. Then, the conductance of the systematic-scan Gibbs kernel is bounded by
		$$
		\Phi (P_\mathrm{SS}) \gtrsim \min \left\{ 1, \frac{\cpo{1}}{\sqrt{L}d} \right\}
		.
		$$
		If the chain is initialized at a $\Omega$-warm start, then the $\zeta$-mixing time is bounded by
		$$
		\tau (\zeta, P_{\mathrm{SS}}) \lesssim \max \left\{ 1, \frac{L d^2}{\cpo{1}^2} \right\}  \cdot \log \left( \frac{\sqrt{\Omega}}{\zeta}\right).
		$$

	\end{cor}

	However, the mixing time bound in Corollary \ref{thm:condss} appears to be loose when $\pi$ is a Gaussian distribution, as suggested by comparisons with \citet{roberts1997updating}. 
	%These authors showed that the convergence rate (defined in a slightly different sense) of the systematic-scan Gibbs sampler does not depend on the dimension $d$.

	\begin{cor} \label{cor:condrslog}
		Consider a $L$-log-smooth target distribution $\pi$ that satisfies \po{1}. Then, the conductance of the random-scan Gibbs kernel is bounded by
		$$
		\Phi (P_{\mathrm{RS}} ) \gtrsim \frac{1}{d\cdot \log d} \cdot \min \left\{ 1, \frac{\cpo{1}}{\sqrt{L}d \cdot \log d} \right\}
		.
		$$
		The spectral gap satisfies
		$$
		\lambda_2 (P_{\mathrm{RS}} ) \gtrsim \frac{1}{d\cdot \log d} \cdot \min \left\{ 1, \frac{\cpo{1}^2}{L(d \cdot \log d)^2} \right\}
		.
		$$
		If the chain is initialized at a $\Omega$-warm start, then the $\zeta$-mixing time is bounded by
		$$
		\tau (\zeta, P_{\mathrm{RS}}) \lesssim d\cdot \log d \cdot \max \left\{ 1, \frac{L (d \cdot \log d)^2}{\cpo{1}^2} \right\}
		\cdot \log \left( \frac{\sqrt{\Omega}}{\zeta}\right).
		$$
	\end{cor}

	Unfortunately, the spectral gap bound in Corollary \ref{cor:condrs} is suboptimal when $\pi$ is strongly log-concave and $L$-log-smooth. In such cases, \citet[Corollary 3.6]{ascolani2024entropy} established that 
	\begin{equation} \label{sgaprsgibbstight} 
		\lambda_2(P_{\mathrm{RS}}) \gtrsim \frac{\cpo{1}^2}{Ld}. 
	\end{equation} 
	Moreover, \citet[Theorem 1]{amit1996convergence} demonstrated that the bound in \eqref{sgaprsgibbstight} is tight when $\pi$ is a Gaussian distribution. 
	The sharp bounds obtained in \citet{ascolani2024entropy} are based on contraction arguments in KL-divergence and critically depend on the assumption of strong log-concavity.
	In particular, it is unclear whether these bounds even extend to bounded perturbations as in \citet{holley1987logarithmic}.
	In contrast, our approach does not exploit such strong structural assumptions, which limits its capacity to achieve comparably sharp bounds. 
	However, this generality allows it to apply to a broader class of target distributions, including those that are not strongly log-concave.

	Furthermore, we believe that the lower bound on the spectral gap in Theorem \ref{cheegerinequalties} is not tight for the Gibbs sampler. 
	This belief is supported by the case of the random walk on the $d$-dimensional hypercube, where \citet[Chapter 5]{trevisan2013lecture} showed that the conductance and spectral gap are of the same order, making the first bound from Theorem \ref{cheegerinequalties} loose in this setting.
	The Gibbs sampler shares a similar local structure to the $d$-dimensional hypercube: each update resamples a single coordinate from its exact conditional, in analogy to the single-bit flips in the hypercube walk.


	%It is worth noting, however, that the analysis in \citet{ascolani2024entropy} fails to provide bounds on the spectral gap of $P_{\mathrm{RS}}$ as soon as $\pi$ is not strongly log-concave, contrary to our approach.
	%However, unlike \citet{ascolani2024entropy}, our approach extends to target distributions that are not strongly log-concave, providing more general bounds for the Gibbs sampler's performance.


	\subsection{Non-log-concave examples}

	Here, we present examples of $d$-dimensional target distributions where our methods yield explicit mixing time bounds for the Gibbs sampler, in contrast to those of \citet{ascolani2024entropy, wadia2024mixing}.

	\paragraph{Continuous Gaussian mixture.}

	For all $t \in \R^d$, let $\varphi_t (\mathd x) \propto \exp(-|x-t|^2 / 2) \mathd x$ denote a Gaussian distribution with mean $t$ and covariance matrix $I_d$. Define the mixing distribution $$\nu (\mathd t) \propto e^{- \abs{\abs{t}^2 -4}} \mathd t.$$ The resulting Gaussian mixture
	$$
	\pi_1 (\mathd x) = \int \varphi_t (\mathd x) \nu (\mathd t)
	$$
	is log-smooth and satisfies \ls{2} \citep[Subsection 4.2]{chen2021dimension}. However, since $\nu$ is multimodal, $\pi_1$ is not log-concave.

	\paragraph{Discrete Laplace mixture.}

	Let $m_1, m_2 \in \R^d$ with $m_1 = -m_2 = (1, 1, \dots, 1)$. Consider the two-component mixture of Laplace distributions
	$$
	\pi_2 (\mathd x) \propto \left(\frac{1}{2} \cdot e^{-\abs{x-m_1}} + \frac{1}{2} \cdot e^{-\abs{x-m_2}}\right)\mathd x.
	$$ This distribution is log-Lipschitz continuous, and satisfies \po{2} as shown by \citet{chafai2010fine,schlichting2019poincare}. However, $\pi_2$ is not log-concave.

	\paragraph{Perturbed Laplace distribution.} 

	Consider the distribution
	$$
	\pi_3 (\mathd x) \propto e^{- \abs{x} + 2 \cos \abs{x}} \mathd x.
	$$
	This distribution is log-Lipschitz continuous and satisfies \po{1} \citep{bobkov1997some}. However, the added perturbation prevents $\pi_3$ from being log-concave.

