	\begin{proof}[Proof of Proposition \ref{LSIhierarchy}]
		%Suppose that the distribution $\pi$ satisfies \ls{q} with constant \cls{q}.
		Define the function $N_q (x) = \abs{x}^q \cdot \log ( 1 + \abs{x}^q)$ for all $x\in \R^d$. Given a function $f : \R^d \to \R$, we denote its Orlicz norm associated to $N_q$ by
		$$
		\norm{f}_{N_q} = \inf \left\{ \lambda > 0 : \int N_q \left(\frac{f(x)}{\lambda}\right) \pi (\mathd x) \leq 1\right\}.
		$$
		Let $\norm{f}_q$ also denote the $L^q_\pi$-norm of $f$, as defined in Subsection \ref{sec:3sifi}. We now  introduce two functional inequalities in the Orlicz space. Let  $\mathtt{c}_q > 0$ and $\tilde{\mathtt{c}}_q > 0$ denote the largest constants such that, for all locally Lipschitz functions $f : \R^d \to \R$,
		\begin{align}
			\mathtt{c}_q \norm{f - \E [f]}_{N_q}^q &\leq \E \left[ \abs{\nabla f  }^q\right], \label{lsiorliczmean} \\
			\tilde{\mathtt{c}}_q \norm{f - m [f]}_{N_q}^q &\leq \E \left[ \abs{\nabla f  }^q\right], \label{lsiorliczmedian}
		\end{align}
		where $m [f]$ denotes a median of $f$. \citet[Proposition 3.1]{bobkov2005entropy} showed that \ls{q} is equivalent to the functional inequality \eqref{lsiorliczmean}, with constants satisfying \hbox{$\mathtt{c}_q/16\leq \cls{q} \leq 7 \mathtt{c}_q$}.
		Moreover, by \citet[Lemma 2.1]{milman2009role}, we have $\tilde{\mathtt{c}}_q/2 \leq \mathtt{c}_q \leq 3 \tilde{\mathtt{c}}_q$.
		The functional inequality \eqref{lsiorliczmedian} is therefore equivalent to \ls{q}, with constants satisfying
		\begin{equation} \label{lsilsimedianconstants}
			\frac{\tilde{\mathtt{c}}_q}{32} \leq \cls{q} \leq 21\tilde{\mathtt{c}}_q.
		\end{equation}
		Now, take any locally Lipschitz function $f$ with $m[f] = 0$ and define $g = \mathrm{sgn}(f)\cdot \abs{f}^{r/q}$, where $\mathrm{sgn} (\cdot)$ denotes the sign function. In particular, we  have $m[g] = 0$ as well. Applying \eqref{lsiorliczmedian} to $g$ yields
		\begin{equation} \label{lsiG}
			{	\tilde{\mathtt{c}}_q}^{1/q}  \norm{g}_{N_q} \leq \norm{\abs{\nabla g }}_q.
		\end{equation}
		Since the solution to the equation $1/u + 1/r = 1/q$ is $u = qr/(r-q)$, an application of H\"older's inequality gives
		\begin{align*}
			\norm{\abs{\nabla g }}_q &\leq \frac{r}{q}  \norm{\abs{f}^{r/q-1} \cdot \abs{\nabla f}}_q \\
			&= \frac{r}{q} \norm{\abs{f}^{r/q-1}}_{qr/(r-q)} \cdot \norm{\abs{\nabla f}}_r \\
			&= \frac{r}{q} \norm{f}_r^{r/q -1} \cdot \norm{\abs{\nabla f}}_r \\
			&\leq \frac{r}{q} \left(\frac{5}{4}\right)^{1/q - 1/r}   \norm{f}_{N_r}^{r/q-1} \cdot \norm{\abs{\nabla f}}_r.
		\end{align*}
		To justify the transition from the second to the third line, observe that
		$$
		\left(\frac{r}{q} -1\right) \frac{qr}{r-q} = \frac{r^2-qr}{r-q} = r
		$$
		and
		$$
		\frac{r-q}{qr} = \frac{1}{r} \left(\frac{r}{q} - 1\right).
		$$
		The last inequality follows from \citet[Lemma 3.2]{bobkov2005entropy}.
		Furthermore, for all $\lambda > 0$, we have
		\begin{align*}
			N_q \left(\frac{g}{\lambda}\right) &=  \frac{\abs{f}^r}{\lambda^q} \cdot \log \left(1 + \frac{\abs{f}^r}{\lambda^q}\right) \\
			&= \abs{\frac{f}{\lambda^{q/r}}}^r \cdot \log \left(1 + \abs{ \frac{f}{\lambda^{q/r}}}^r\right) \\
			&= N_r \left(\frac{f}{\lambda^{q/r}}\right).
		\end{align*}
		It follows that
		\begin{align*}
			\norm{g}_{N_q} &= \inf \left\{ \lambda > 0 : \int N_q \left( \frac{ g(x)}{\lambda} \right) \pi(\mathd x) \leq 1\right\} \\
			&= \inf \left\{ \lambda > 0 : \int N_r \left( \frac{f(x)}{\lambda^{q/r}}  \right) \pi(\mathd x) \leq 1\right\} \\
			&= \inf \left\{ \lambda^{q/r} > 0 : \int N_r \left( \frac{f(x)}{\lambda^{q/r}} \right) \pi(\mathd x) \leq 1\right\}^{r/q} \\
			&= \inf \left\{ \lambda' > 0 : \int N_r \left( \frac{f(x)}{\lambda'} \right) \pi(\mathd x) \leq 1\right\}^{r/q} \\
			&= \norm{f}_{N_r}^{r/q}.
		\end{align*}
		Inserting these identities into \eqref{lsiG} gives
		$$
		{	\tilde{\mathtt{c}}_q}^{1/q} \norm{f}_{N_r}^{r/q} \leq \left(\frac{5}{4}\right)^{1/q - 1/r}  \frac{r}{q}    \norm{f}_{N_r}^{r/q-1} \cdot \norm{\abs{\nabla f}}_r.
		$$
		Rearranging terms and raising both sides to the power $r$, we obtain
		$$
		\left(\frac{4}{5}\right)^{r/q-1} \left(\frac{q}{r}\right)^r  {	\tilde{\mathtt{c}}_q}^{r/q} \norm{f}_{N_r}^r \leq  \E \left[ \abs{\nabla f  }^r\right].
		$$
		Hence,
		\begin{equation*}
			\left(\frac{4}{5}\right)^{r/q-1} \left(\frac{q}{r}\right)^r  {	\tilde{\mathtt{c}}_q}^{r/q} \leq \tilde{\mathtt{c}}_r.
		\end{equation*}
		Finally, applying \eqref{lsilsimedianconstants} twice yields
		$$
		%\frac{1}{32\cdot 21^{r/q}} \left(\frac{4}{5}\right)^{r/q-1}
		\frac{5}{128} \left(\frac{4}{105}\right)^{r/q}
		\left(\frac{q}{r}\right)^r \cls{q}^{r/q} \leq \cls{r}.
		$$
	\end{proof}

	\begin{proof}[Proof of Proposition \ref{conductanceTHM}]
		Let $S$ $\subseteq \R^d$ with $\pi ( S) \leq 1/2$. Note that in this case, \mbox{$\pi ( S^c  ) \geq \pi( S )$}. Define the sets
		\begin{align*}
			S_1 &= \left\{ x \in S  : P (x, S^c) \leq \frac{\varepsilon}{2}\right\}, \\
			S_2 &= \left\{ x \in S^c  : P (x, S) \leq \frac{\varepsilon}{2}\right\}, \\
			S_3 &= \left( S_1 \sqcup S_2 \right)^c.
		\end{align*}
		Here, $S_1$ and $S_2$ can be viewed as ``bad'' sets: in $S_1$ (respectively $S_2$), the probability to escape $S $ (respectively $S^c$) is small. Note that $S_1 \sqcup S_2 \sqcup S_3 = \R^d$, forming a partition of space. We now separate two different cases.

		In the first case, suppose that $\pi ( S_1 ) \leq \pi ( S)/2$ or $\pi ( S_2 ) \leq \pi ( S^c)/2$, i.e., at least one of the ``bad'' sets is small. If $\pi ( S_1 ) \leq \pi ( S)/2$, then
		\begin{align*}
			\int_S  P   (x, S^c ) \pi(\mathd x ) &\geq \int_{  S  \setminus S_1}  P   ( x, S^c ) \pi   (\mathd x ) \\
			& \geq \frac{\varepsilon}{2}\cdot \pi   (   S   \setminus S_1  ) \\
			& = \frac{\varepsilon}{2}   \left[ \pi   (S  ) - \pi   ( S_1  )  \right] \\
			& \geq \frac{\varepsilon}{4}\cdot \pi   (S  ).
		\end{align*}
		If $\pi   ( S_2  ) \leq \pi   ( S^c   )/2$, we proceed analogously: 
		\begin{align*}
			\int_S P   (x, S^c ) \pi   (\mathd x )  &= \int_{S^c}  P   (x, S )  \pi   (\mathd x ) \\
			&\geq \int_{  S^c   \setminus S_2} P   ( x, S^c )  \pi   (\mathd x )  \\
			& \geq \frac{\varepsilon}{2}\cdot \pi   (   S^c   \setminus S_2  ) \\
			& = \frac{\varepsilon}{2}   \left[ \pi   (S^c  )- \pi   ( S_2  )  \right] \\
			& \geq \frac{\varepsilon}{4} \cdot\pi   ( S^c    ) \\
			& \geq \frac{\varepsilon}{4}\cdot \pi   ( S   ).
		\end{align*}
		Importantly, reversibility is not required to establish the first equality, as noted by \citet[Lemma 2]{dwivedi2019log}.

		In the second case, suppose that $\pi   ( S_1  ) > \pi   ( S  )/2$ and $\pi   ( S_2  ) > \pi   ( S^c  )/2$, i.e., both of the ``bad'' sets are large. Take $x \in S_1$, $y \in S_2$. We have
		$$
		\norm{P (x, \cdot ) - P (y, \cdot)}_\tv \geq P   ( x, S  ) - P   ( y, S  ) = 1 - P   ( x, S^c  ) - P   ( y, S  ) \geq 1 - \varepsilon.
		$$
		By the contrapositive of the $  ( \delta, \varepsilon  )$-close coupling condition, this implies $\abs{x-y} >\delta$, and consequently, $\mathcal{D}  ( S_1, S_2 ) \geq\delta$. This leads to
		\begin{align*}
			\int_S P  ( x, S^c ) \pi   (\mathd x )  &= \frac{1}{2}   \left[ \int_S  P  ( x, S^c ) \pi   (\mathd x )  + 	\int_{S^c} P  ( x, S ) \pi   (\mathd x )    \right] \\
			&\geq \frac{1}{2}   \left[ \int_{  S    \setminus S_1} P  ( x, S^c ) \pi   (\mathd x )  + \int_{  S^c    \setminus S_2} P  ( x, S ) \pi   (\mathd x )    \right]\\
			&\geq \frac{\varepsilon}{4}   \left[ \pi   (   S    \setminus S_1  ) + \pi   (   S^c    \setminus S_2  ) \right] \\
			&= \frac{\varepsilon}{4} \cdot \pi   ( S_3 ) \\
			&\geq \frac{\varepsilon}{4} \cdot \Upsilon  \left(\mathcal{D}  (S_1, S_2 ) \right) \cdot \Psi   \left(\min   \left\{ \pi   ( S_1 ), \pi   ( S_2 )  \right\} \right) \\
			&\geq \frac{\varepsilon}{4} \cdot \Upsilon  (\delta ) \cdot \Psi  \left( \frac{\pi (S  )}{2}  \right).
		\end{align*}
		The statement follows by taking minimums of both cases.
	\end{proof}

	\begin{proof}[Proof of Lemma \ref{3siLSIlem}]
		The derivative of $\rho$ is given by $\rho' (x) = \log (1/x) - 1$, 
		which is positive for $x < e^{-1}$ and negative for $x \geq e^{-1}$. This establishes the first part of the lemma. Furthermore, for $e^{-1} \leq x \leq 1$, observe that $\rho'(x) \in [-1, 0]$, implying that $\rho$ is Lipschitz continuous on this interval with constant 1.

		To prove the second part, we consider the following cases.
		First, if $x + h < e^{-1}$, then both $x$ and $x + h$ lie in the region where $\rho$ is increasing. Therefore, $\rho(x + h) \geq \rho(x) \geq \rho(x) - h$, as required.
		Next, consider the case where $x + h \geq e^{-1}$.
		If $x \geq e^{-1}$, since $\rho$ is decreasing and Lipschitz continuous on this region, we have as desired
		$$
		\rho(x) - \rho(x + h) =  \abs{\rho(x) - \rho(x + h)} \leq h.
		$$
		If $x < e^{-1}$,  we split the integral representation of $\rho(x + h) - \rho(x)$ as follows:
		\begin{align*}
			\rho(x + h) &= \rho(x) + \int_{x}^{e^{-1}} \rho'(s) \mathd s + \int_{e^{-1}}^{x + h} \rho'(s) \mathd s \\
			&\geq \rho(x) + \int_{e^{-1}}^{x + h} \rho'(s) \mathd s \\
			&\geq \rho(x) - \left( x + h - e^{-1} \right) \\
			&\geq \rho(x) - h.
		\end{align*}
		This establishes the second part of the lemma.
	\end{proof}

	\begin{proof}[Proof of Lemma \ref{couponlem}]
		Let $T$ be the random variable representing the number of i.i.d. draws from the distribution $\mathrm{Unif}[d]$ required to observe all $d$ unique values. Following \citet[Subsection 2.4.1]{mitzenmacher2017probability}, we have
		$$
		\E [T] = d \sum_{j=1}^d \frac{1}{j}.
		$$
		Approximating the above sum with the logarithm, we have
		$$
		d \cdot \log d \leq \E [T] \leq d \cdot \log d + d.
		$$
		An application of Markov's inequality finally yields
		\begin{align*}
			\Pb ( \Xi = [d]) &= \Pb  ( T \leq N) \\&\geq \Pb  ( T \leq 4 d \cdot \log d) \\
			&\geq \Pb  (T \leq 2  (d \cdot \log d + d)) \\
			&= 1 - \Pb  (T > 2  (d \cdot \log d + d)) \\
			&\geq 1 - \frac{\E  [T]}{2  (d \cdot \log d + d)} \\
			&\geq \frac{1}{2}.
		\end{align*}
	\end{proof}

	\begin{proof}[Proof of Lemma \ref{marginalsloglipsmooth}]
		Consider a partition of the space such that $\pi = \pi \left(\theta, s \right)$ with $\theta \in \R^{d_1}$, $s \in \R^{d_2}$, where $d_1 + d_2 = d$. Write
		$
		\pi \left(\theta, s\right) \propto  e^{-U\left(\theta, s\right)}$. The marginal distribution of $\pi$ with respect to $s$ can be expressed as $\pi \left(s\right) \propto e^{-V\left(s\right)}$, where
		$$
		V (s) = - \log \left( \int e^{- U(\theta, s)} \mathd \theta\right).
		$$
		Additionally, the conditional distribution of $\pi$ is
		$$
		\pi (\mathd\theta \mid s) = \frac{e^{-U(\theta,s)} \mathd \theta}{\int e^{-U(\eta,s)} \mathd \eta}.
		$$
		If $U$ is Lipschitz continuous, then the gradient $\nabla U$ exists almost everywhere and satisfies $\abs{U(\theta, s)} \leq L$. The gradient of $V$ can be written as 
		$$
		\nabla V (s) = \int \nabla_s U(\theta, s) \pi (\mathd \theta \mid s),
		$$
		where $\nabla_s U(\theta, s)$ represents the gradient of $U(\theta, s)$ with respect to the coordinates of $s$. Therefore, 
		$$
		\abs{\nabla V (s)} = \int \abs{\nabla_s U(\theta, s)} \pi (\mathd \theta \mid s) \leq L
		$$
		almost everywhere, which shows that $V$ is also $L$-Lipschitz continuous. 

		Now suppose that $U$ is $L$-smooth, meaning that the Hessian $\nabla^2 U$ exists almost everywhere and satisfies $\nabla^2 U(\theta, s) \preceq LI_d$, where $I_d$ denotes the $d$-dimensional identity matrix. Writing $w^2 = ww^T$ for a vector $w \in \R^{d_2}$, the Hessian of $V$ is
		$$
		\nabla^2 V(s) = \int \nabla^2 U(\theta, s) \pi (\mathd\theta \mid s) + \left(\int \nabla_s U(\theta, s) \pi (\mathd\theta \mid s)\right)^2 - \int \left(\nabla_s U(\theta, s)\right)^2 \pi (\mathd\theta \mid s).
		$$
		By the Cauchy-Schwarz inequality,
		$$
		\left(\int \nabla_s U(\theta, s) \pi (\mathd\theta \mid s)\right)^2 - \int \left(\nabla_s U(\theta, s)\right)^2 \pi (\mathd\theta \mid s) \preceq 0.
		$$
		Thus,
		$$
		\nabla^2 V(s) \preceq \int \nabla^2 U(\theta, s) \pi (\mathd\theta \mid s) \preceq LI_{d_2},
		$$
		implying that $V$ is also $L$-smooth.		
	\end{proof}


