Our objective is to deploy a general methodology for the computation of different quantities in the space of random Poisson measures. This methodology is based on two essential tools, namely Mecke's formula and the pseudo-chaotic expansion \cite{Caroline_Anthony_chaotic}, which requires the introduction of some operators on this space.  
%When working in the space of random Poisson measures, two essential tools for analyzing functionals in this space are Mecke's formula and pseudo-Chaotic decomposition \cite{Caroline_Anthony_chaotic}. Using this formulas involves the use of some operators on the functional in question. 
In the following section, we define elements of Malliavin's calculus in order to exploit Mecke's formula through the pseudo-chaotic expansion.


\section{Elements of Malliavin's calculus}

\subsection{Spaces and the add point operator}
We introduce some elements of Malliavin's calculus on Poisson processes. We set 
$$ L^0(\Omega):=\left\{ F:\Omega \to \real, \; \mathcal{F}^{\bN}-\textrm{ measurable}\right\},$$
$$ L^2(\Omega):=\left\{ F \in L^0(\Omega), \; \E[|F|^2] <+\infty\right\}.$$
Fix $n \in \N^*$. We set $\br^{\otimes n}$ the extension of $\br$ on $(\bX^n,\mathfrak{X}^{\otimes n})$.
Let
$$L^0(\bX^n) := \left\{f:\bX^n \to \real, \; \mathfrak X^{\otimes n}-\textrm{measurable } \right\}$$
and for $p\in\{1,2\}$,
\begin{equation}
	\label{definition:L2j}
	L^p(\bX^n) := \left\{f \in L^0(\bX^n),   \; \int_{\bX^n} |f(\bx_1,\cdots,\bx_n)|^p \br^{\otimes n}(d\bx_1 \cdots d\bx_n) <+\infty\right\}.
\end{equation}
Besides,
\begin{equation}
	\label{definition:L2js}
	L^p_s(\bX^n) := \left\{f \in L^p(\bX^n) \textrm{ and } f \textrm{ is symmetric} \right\}
\end{equation}
is the space of square-integrable symmetric mappings where we recall that $f:\bX^n \to \real$ is said to be symmetric if for any element $\sigma$ in $\mathcal S_n$ (the set of all  permutations of $\{1,\cdots,n\}$), 
$$ f(\bx_1,\ldots, \bx_n) = f(\bx_{\sigma(1)},\ldots, \bx_{\sigma(n)}), \quad \forall (\bx_1,\ldots,\bx_n) \in \bX^n.  $$


\noindent
The main ingredient we will make use of are the add-points operators on the Poisson space $\Omega$.  For any finite set $J$, we set $|J|$ its cardinal. 
\begin{definition}$[$Add-points operators$]$\label{definitin:shifts}
	Given $n\in \mathbb N^*$, and $J:=\{\bx_1,\ldots,\bx_n\} \subset \bX$ a subset of $\bX$ with $|J|=n$,
	we set the measurable mapping :
	\begin{eqnarray*}
		\varepsilon_{J}^{+,n} : \Omega & \longrightarrow & \Omega  \\
		\bO & \longmapsto   & \bO + \sum_{\bx \in J} \delta_{\bx} \ind{\bO(\{\bx\})=0}.
	\end{eqnarray*}
	Note that by definition 
	$$  \bO + \sum_{\bx \in J} \delta_{\bx} \ind{\bO(\{\bx\})=0} = \bO + \sum_{m=1}^{n} \delta_{\bx_j} \ind{\bO(\{\bx_j\})=0} $$
	that is we add the atoms $\bx_j$ to the path $\bO$ unless they already were part of it (which is the meaning of the term $\ind{\bO(\{\bx_j\})=0}$). Note that since $\br$ is assumed to be atomless, given a set $J$ as above, $\P[\bN(J)=0]=1$ hence in what follows we will simply write $\bO + \sum_{j=1}^{n} \delta_{\bx_j}$ for $\varepsilon_{\bold{x}}^{+,n} (\bO)$.  
\end{definition}

\subsection{The Malliavin derivative}

\noindent In the context of Malliavin's calculation, a tool that is often mentioned is the associated derivative.

\begin{definition}
	\label{definition:Dn}
	For $F$ in $L^2(\Omega)$, $n\in \mathbb N^*$, $(\bx_1,\ldots,\bx_n) \in \bX^n$, we set 
	\begin{equation}
		\label{eq:Dn}
		\bold{D}_{(\bx_1,\ldots,\bx_n)}^{n} F:= \sum_{J \subset \{\bx_1,\ldots,\bx_n\}} (-1)^{n-|J|} F\circ \varepsilon_{J}^{+,|J|},
	\end{equation}
	where we recall that $\emptyset \subset \bX$.
	For instance when $n=1$, we write  $\bold{D}_{\bx} F := \bold{D}_{\bx}^1 F = F(\cdot + \delta_{\bx}) - F(\cdot)$ which is the difference operator (also called add-one cost operator\footnote{see \cite[p.~5]{Last2016}}). Relation (\ref{definition:Dn}) rewrites as 
	$$ \bold{D}^n_{(\bx_1,\ldots,\bx_n)} F (\bO)= \sum_{J\subset \{1,\ldots,n\}} (-1)^{n-|J|} F\left(\omega + \sum_{j \in J} \delta_{\bx_j}\right), \quad \textrm{ for a.e. } \bO \in \Omega.$$
	Note that with this definition, for any $\bO$ in $\Omega$, the mapping 
	$$ (\bx_1,\ldots,\bx_n) \mapsto \bold{D}_{(\bx_1,\ldots,\bx_n)}^n F (\bO) $$
	belongs to $L^0_s(\bX^n)$ defined as (\ref{definition:L2js}).
\end{definition}

\begin{remark}
	\label{rk:Dderm}
	If $F$ is deterministic, then by definition $\bD^n F=0$ for any $n\geq 1$.
\end{remark}

The chaotic-chaotic expansion developed in \cite{Caroline_Anthony_chaotic} involves deterministic operators  $ \T^n$  which correspond to  iterated  Malliavin derivatives  under the specific event $\{\bN(\bX)=0\}$.
%However, as illustrated in \cite{Caroline_Anthony_chaotic}, the derivative involved in the pseudo-chaotic decomposition is the previous Malliavin derivative under the event $\{\bN(\bX)=0\}$.

\begin{definition}
	\label{definition:patwisederivative}
	For $F\in L^0(\Omega)$, we define the deterministic operators: 
	$$ \T^0 F:= F(\emptyset),$$ 
	$$
	\left.\begin{array}{lll}
		\T^n:& L^0(\Omega) & \to L^0_s(\bX^n) \\
		&F &\mapsto \T^n F 
	\end{array}\right.
	$$
	where for any $(\bx_1,\cdots,\bx_n) \in \bX^n$, $\T^n_{(\bx_1,\cdots,\bx_n) }$ is defined by 
	$$ \T^n_{(\bx_1,\cdots,\bx_n)} F := \sum_{J\subset \{\bx_1,\cdots,\bx_n\}} (-1)^{n-|J|} F(\varpi_{J}),$$
	with $\varpi_{J} := \sum_{y_i\in J} \delta_{\by_i} \in \Omega$ for $J=\{\by_1,\ldots,\by_k\}$.
\end{definition}


\noindent
In particular, even though $F$ is a random variable, $\T^n_{(\bx_1,\cdots,\bx_n)} F$ is in $\mathbb R$ as each
term $F(\varpi_{J})$ is the evaluation of $F$ at the outcome $\varpi_{J}$. Moreover, this operator belongs to $L^1_s(\bX^n)$.

\begin{convention}[Ordered points]\label{convention:orderpoint}
	Since the operator  $\T^n_{(\bx_1,\cdots,\bx_n)} F$ is symmetric, we will assume that the points $(\bx_1,\ldots,\bx_n) \in \bX^n$ are always taken ordered with respect to the time component $t$.
\end{convention}
\subsection{Factorial measures and iterated integrals} 

\begin{prop}(Factorial measures; See \textit{e.g.} \cite[Prop 1]{Last2016}).
	\label{prop:factormeas}
	There exists a unique sequence of counting random measures $(\bN^{(n)})_{n\in \mathbb N^*}$ where for any $n$, $\bN^{(n)}$ is a counting random measure on $(\bX^n, \mathfrak X^{\otimes n})$ with
	\begin{align*}
		&\bN^{(1)}:=\bN  \quad \mbox{ and \quad  for } \quad  A \in \mathfrak X^{\otimes (n+1)},\\
		&\bN^{(n+1)}(A) \\ 
		&:= \int_{\bX^n} \left[ \int_\bX \ind{(\bx_1,\ldots,\bx_{n+1})\in A} \bN(d\bx_{n+1}) - \sum_{j=1}^n \ind{(\bx_1,\ldots,\bx_{n},\bx_j)\in A} \right] \bN^{(n)}(d\bx_1,\ldots,d\bx_n); 
	\end{align*}
\end{prop}
\noindent With this definition at hand we introduce the notion of iterated integrals. In particular for $A \in \mathfrak X$, 
$$ \bN^{(n)}(A^{\otimes n}) = \bN(A) (\bN(A)-1) \times \cdots \times (\bN(A)-n+1).$$
Note that by definition $\bN^{(n)}(A) \ind{\bN(A) < n}=0$. We now turn to the definition of iterated integrals with respect to the counting measure $\bN^{(n)}(d\bx_1,\ldots,d\bx_n)$.


\begin{definition}
	\label{definition:interated}
	Let $n \in \mathbb N^*$ and $f_n \in L^1_s(\bX^n)$.
		$ \boldsymbol{\mathcal{I}}_n(f_n)$ the $n^{th}$ iterated integral of $f_n$ with respect to  the Poisson measure $\bN$ is defined as 
		$$ \boldsymbol{\mathcal{I}}_n(f_n):= \int_{\bX^{n}}  f_n(\bx_1,\ldots,\bx_n) \; \bN^{(n)}(d\bx_1,\ldots,d\bx_n),$$
		where each of the integrals above is well-defined pathwise for $\P$-a.e. for each \textit{$\bO \in \Omega$, as a   Stieltjes integral }.

\end{definition}


\subsection{The Mecke formula}
We end this section by recalling a particular case of Mecke's formula (see \textit{e.g.} \cite[Relation (11)]{Last2016}).

\begin{lemma}[A particular case of Mecke's formula]
	\label{lemma:Mecke}
		Let $F \in L^0(\Omega)$, $n\in \mathbb N$ and $h\in L^0(\bX^n)$ 
	such that
$$\int_{\bX^n} |h(\bx_1,\ldots,\bx_n)| \E\left[|F\circ \varepsilon_{\bx_1,\ldots,\bx_n}^{+,n}|\right]  \br^{\otimes n}(d\bx_1,\ldots,d\bx_n)<+\infty.$$

Then 
	\begin{equation}\label{eq:Mecke_1}
	\E\left[F \int_{\bX^n} h d\bN^{(n)}\right] = \int_{\bX^n} h(\bx_1,\ldots,\bx_n) \E\left[F\circ \varepsilon_{\bx_1,\ldots,\bx_n}^{+,n}\right] \br^{\otimes n}(d\bx_1,\ldots,d\bx_n).
	\end{equation}
By taking $F=1$ we get
	\begin{align}\label{eq:Mecke_2}
		\E\left[\bpI_n(f_n)\right] &= \int_{\bX^n}f_n(\bx_1,\dots,\bx_n)\br^{\otimes n}(d\bx_1,\ldots,d\bx_n) \nonumber\\
		&=\sum_{k_1=1}^d \dots \sum_{k_n=1}^d \int_{([0,T]\times \R_+ \times \R_+)^n}f_n(\bx_1,\dots,\bx_n)\prod_{i=1}^n\bnu^{k_i}(dy_i)d\theta_i dt_i.
	\end{align}
\end{lemma}



\section{Pseudo-chaotic expansion for counting processes}
The second ingredient in our analysis relies on the pseudo-chaotic expansion. This section presents some essential results around this expansion, with a focus on the process $\boldsymbol{Z}$.

\subsection{Around the pseudo-chaotic expansion of $\boldsymbol{Z}$}

%b{Old : Lemma \ref{lemma:magic_lemma} together with the general peudo-chaotic expansion given in \cite{Caroline_Anthony_chaotic} provide the following representation for a $(\bZ,\bM,\bP)-$MSPD.}
%\b{Proposition : }

{The following theorem provides the  peudo-chaotic expansion for a $(\bZ,\bM,\bP)-$MSPD,  following   results from \cite{Caroline_Anthony_chaotic}.}

\begin{theorem}
	\label{th:pseudochaoticcounting}
	Let $\boldsymbol{Z}$ a $(\bZ,\bM,\bP)-$MSPD, we recall that this process is given by the SDE(\ref{eq:MSPD}):
	$$
	\left\lbrace
	\begin{array}{l}
		\myZ{T} := \int_{\bX_T}\bZeta^{i,k}(T-t,y) \ind{\theta \leq \bLamb_t^k} \bN(dk,dt,d\theta,dy) \\ \hspace{12cm} T\geq 0 \\
		\bLamb_T^i:= \bM^i(T) + \int_{\bX_T}\bP^{i,k}(T-t,y) \ind{\theta \leq \bLamb_t^k} \bN(dk,dt,d\theta,dy). \\
	\end{array}
	\right. 
	$$
	Then $\boldsymbol{Z}^{i}_T$ admits the pseudo-chaotic representation 
	\begin{equation}\label{eq:pseudo_chao}
		\myZ{T} = \lim_{M\to \infty}\sum_{n=1}^{+\infty}\frac{1}{n!}\bpI_n\left(\T^n_{(\bx_1,\cdots,\bx_n)}\myZ{T}\ind{([0,T]\times[0,M])^n}\right)
	\end{equation}

	with for all $(\bx_1,\ldots,\bx_n) \in \bX^n$,
	\begin{equation}
		\label{eq:ckcounting}
		\hspace*{-0.5cm}\T^n_{(\bx_1,\ldots,\bx_n)}\myZ{T} = \bZeta^{i,k_n}(T-t_n,y_n)\T^{n-1}_{(\bx_1,\dots,\bx_{n-1})}\ind{\theta_{n}\leq \bLamb^{k_n}_{t_n}}.
	\end{equation}
\end{theorem}

\begin{proof}
Equation (\ref{eq:pseudo_chao}) follows from \cite{Caroline_Anthony_chaotic} which gives the pseudo-chaotic expansion of any random linear
functional of $\bN$ restricted to a bounded domain (say $[0, T] \times [0, M]$, for $T, M > 0$) of $\R_+^2$; with a
focus on random variables of the form $H_t$ where $H$ is a counting process with bounded
intensity (we refer the reader to \cite{Caroline_Anthony_chaotic} for a complete exposition). Even though the intensity of
$\myZ{T}$ is unbounded, it is proved in \cite{Caroline_Anthony_chaotic} that marginals of Hawkes processes admit
a pseudo-chaotic expansion. Then to prove (\ref{eq:ckcounting}), recalling that $\bx = (k,t,\theta,y)$,
\begin{align*}
	\T^n_{(\bx_{1},\cdots,\bx_{n})} \myZ{T} &= \sum_{J\subset \{\bx_1,\cdots,\bx_n\}} (-1)^{n-|J|} \left(\int_{\bX_T}\bZeta^{i,k}(T-t,y) \ind{\theta \leq \bLamb_t^k} \bN(dk,dt,d\theta,dy)\right) (\varpi_{J})\\
	&= \sum_{J\subset \{\bx_1,\cdots,\bx_n\}} (-1)^{n-|J|}\sum_{\bx_m\in J} \bZeta^{i,k_m}(T-t_m,y_m)\ind{\theta_m \leq \bLamb_{t_m}^{k_m} (\varpi_{J})} \\
	&= \sum_{J\subset \{\bx_1,\cdots,\bx_n\}} \sum_{\bx_m\in J}(-1)^{n-|J|} \bZeta^{i,k_m}(T-t_m,y_m)\ind{\theta_m \leq \bLamb_{t_m}^{k_m} (\varpi_{J})}\\
	&= \sum_{m=1}^n \sum_{J\subset \{\bx_1,\cdots,\bx_n\};\bx_m\in J} (-1)^{n-|J|}\bZeta^{i,k_m}(T-t_m,y_m)\ind{\theta_m \leq \bLamb_{t_m}^{k_m} (\varpi_{J} + \delta_{\bx_m}))} \\
	&= \sum_{m=1}^n  \bZeta^{i,k_m}(T-t_m,y_m)  \sum_{J\subset \{\bx_1,\cdots,\bx_{i-1},\bx_{i+1},\cdots,\bx_n\}} (-1)^{n-1-|J|} \ind{\theta_m \leq \bLamb_{t_m}^{k_m} (\varpi_{J} + \delta_{\bx_m}))} \\
\end{align*}
Then, for $m \in \{1,\cdots,n\}$ we have that
\begin{align*}
	&\sum_{J\subset \{\bx_1,\cdots,\bx_{m-1},\bx_{m+1},\cdots,\bx_n\}} (-1)^{n-1-|J|} \ind{\theta \leq \bLamb_{t_m}^{k_m} (\varpi_{J} + \delta_{\bx_m})}\\
	&= \sum_{J^-\subset \{\bx_1,\cdots,\bx_{m-1}\}}\sum_{J^+\subset \{\bx_{m+1},\cdots,\bx_n\}}(-1)^{n-1-|J^-|-|J^+|}\ind{\theta_m \leq \bLamb_{t_m}^{k_m} (\varpi_{J^- \cup J^+} + \delta_{\bx_i})}\\
	&=\sum_{J^-\subset \{\bx_1,\cdots,\bx_{m-1}\}}\ind{\theta_m \leq \bLamb_{t_m}^{k_m} (\varpi_{J^-})} (-1)^{n-1-|J^-|}\sum_{J^+\subset \{\bx_{m+1},\cdots,\bx_n\}}(-1)^{|J^+|}
\end{align*}
where the last equality follows from the predictability of $\bLamb$.
Moreover, if $\bx_m \neq \bx_n$ then,
$$
\sum_{J^+\subset \{\bx_{m+1},\cdots,\bx_n\}}(-1)^{|J^+|} = 0.
$$
And if $\bx_m = \bx_n$ then $J^+ = \emptyset$ which implies, 
$$\sum_{J^+\subset \{\bx_{m+1},\cdots,\bx_n\}}(-1)^{|J^+|} = 1.$$
Thus, 
\begin{align*}
	\T^n_{(\bx_1,\cdots,\bx_n)}\myZ{T}&= \bZeta^{i,k_n}(T-t_n,y_n)\sum_{U\subset \{\bx_1,\cdots,\bx_{n-1}\}}(-1)^{n-1-|U|}\ind{\theta_n \leq \bLamb_{t_n}^{k_n} (\varpi_{U})}\\
	&=\bZeta^{i,k_n}(T-t_n,y_n)\T^{n-1}_{(\bx_1,\cdots,\bx_{n-1})}\ind{\theta_n \leq \bLamb_{t_n}^{k_n}}.
\end{align*}


\end{proof}

\begin{remark}\label{remark:Tnlambda}
As $\bM^i(T)$ is deterministic, $\T^{n} \bM^i(T)=0$ hence from  \eqref{eq:ckcounting} we deduce that
$$\T^n_{(\bx_1,\ldots,\bx_n)} \bLamb_T^i = \bP^{i,k_n}(T-t_n,y_n)\T^{n-1}_{(\bx_1,\dots,\bx_{n-1})}\ind{\theta_{n}\leq \bLamb^{k_n}_{t_n}}.$$
\end{remark}

\begin{remark}\label{remark:pre_compatibility}
	Consider a set  $J= (\bx_1,\cdots,\bx_n)$ of ordered points  in $\bX_T$ (see Convention \ref{convention:orderpoint}). Then  $\myZ{T}$  evaluated on $J$ satisfies,  for any $\omega\in\Omega$
\begin{eqnarray*}
	\myZ{T}\left( \sum_{\bx_m\in J} \delta_{\bx_m} \right) &=& \sum_{\bx_m\in J}\bZeta^{i,k_m}(T-t_m,y_m)\ind{\theta_{m} \leq \bLamb_{t_m}^{k_m}( \sum_{\bx_j\in J}  \delta_{\bx_j })}\\
	&\leq& \sum_{m\in J}\bZeta^{i,k_m}(T-t_m,y_m)\leq \myZ{T}\left( \omega + \sum_{\bx_m\in J} \delta_{\bx_m} \right). 
\end{eqnarray*}
Since for all $(i,k)\in \{1,\dots,d\}^2$, $\bZ^{i,k}$ is positive,	 $	\myZ{T}( \sum_{j\in J} \delta_{\bx_j})$  reaches its maximum   when every point in $J$ is accepted by the 
	thinning criteria $\ind{\theta_{m} \leq {\bLamb_{t_m}^{k_m}(\sum_{j\in J} \delta_{\bx_j})}}$. In fact, if we assume that every point in $J$ verifies the thinning criteria we have for all $\bx_m \in J$,
\begin{equation}\label{eq:Caro}
	\theta_{m}\leq \bM^{k_m}
	+  \sum_{j=1}^{m-1}\bP^{k_m,k_j}(t_m-t_j,y_j) = {\bLamb_{t_m}^{k_m}(\sum_{j\in J} \delta_{\bx_j})}\leq \bLamb_{t_m}^{k_m}(\omega + \sum_{j\in J} \delta_{\bx_j}),
	\end{equation}
	where the  sum stops at $j=m - 1$ because of  the predictability of $\lambda_T^i$ (see Definition \ref{def:self-excitation}).
\end{remark}
This brings us to introduce the following lemma which establishes a compatibility condition on a set of points $\bx_j$ such that $\T^n_{(\bx_1, \dots, \bx_n)}{\myZ{t}}\neq0$.
\begin{lemma}[Compatibility condition]Let  $\boldsymbol{Z}$ a $(\bZ,\bM,\bP)-$MSPD. Fix $T \geq 0$, let $n \in \N^*$, $(\bx_1 \dots, \bx_n)\in (\bX_T)^n$ following Convention \ref{convention:orderpoint}.
	It holds that, 

	$$
	\T^n_{(\bx_1, \dots, \bx_n)}{\myZ{T}}=\T^n_{(\bx_1, \dots, \bx_n)}{\myZ{T}}\ind{\theta_1 \leq \bM^{k_1}(t_1)} \prod_{m=2}^{n}\ind{\theta_m \leq \bM^{k_m}(t_m)
		+  \sum_{j=1}^{m-1}\bP^{k_m,k_j}(t_m-t_j,y_j)}.
	$$
$(\bx_1 \dots, \bx_n)$ is said to satisfy the compatibility condition if
\begin{equation}\label{eq:compatibility}
	\ind{\theta_1 \leq \bM^{k_1}} \prod_{m=2}^{n}\ind{\theta_m \leq \bM^{k_m}
		+  \sum_{j=1}^{m-1}\bP^{k_m,k_j}(t_m-t_j,y_j)} = 1.
\end{equation}
\end{lemma}
\begin{proof}
	By applying (\ref{eq:ckcounting}) from Theorem \ref{th:pseudochaoticcounting} to $\boldsymbol{Z}$ and by definition of the operator $\T$ we have that,
	$$
	\T^n_{(\bx_1, \dots, \bx_n)}{\myZ{T}}= \bZeta^{i,k_n}(T-t_n,y_n) \sum_{J\subset\{1,\dots,n-1\}}(-1)^{n-1-|J|} 
	\ind{\theta_{n} \leq \lambda_{t_n}^{k_n}(\sum_{p \in J}\delta_{\bx_p})}.
	$$
	Hence, inequality \eqref{eq:Caro} (with $m=n$) implies
	$$
	\T^n_{(\bx_1, \dots, \bx_n)}{\myZ{T}}\ind{\theta_n > \mu^{k_n} + \sum_{m = 1}^{n-1}\bP^{k_n,k_m}(t_n - t_m,y_m)}=0.
	$$
	\\
	Let $ \ell\in\{2,\dots,n\}$,
	\begin{align*}
		&\T^n_{(\bx_1, \dots, \bx_n)}{\myZ{T}}\ind{\theta_\ell > \bM^{k_\ell}(t_\ell) + \sum_{m = 1}^{\ell-1}\bP^{k_\ell,k_m}(t_k - t_m,y_m)}\\
		&= \bZeta^{i,k_n}(T-t_n,y_{n}) \ind{\theta_\ell > \bM^{k_\ell}(t_\ell) + \sum_{m = 1}^{\ell-1}\bP^{k_\ell,k_m}(t_k - t_m,y_m)} \sum_{J\subset\{1,\dots,n-1\}}(-1)^{n-1-|J|} 
		\ind{\theta_{n} \leq \bLamb_{t_n}^{k_n}(\sum_{p \in J}\delta_{\bx_p})}\\
		&=\bZeta^{i,k_n}(T-t_n,y_{n}) \ind{\theta_\ell > \bM^{k_\ell}(t_\ell) + \sum_{m = 1}^{\ell-1}\bP^{k_\ell,k_m}(t_k - t_m,y_m)} \\
		&\left(\sum_{J\subset\{1,\dots,n-1\}; \ell \in J}(-1)^{n-1-|J|} 
		\ind{\theta_{n} \leq \bLamb_{t_n}^{k_n}(\sum_{p \in J}\delta_{\bx_p})} + \sum_{J\subset\{1,\dots,n-1\}; \ell \notin J}(-1)^{n-1-|J|} 
		\ind{\theta_{n} \leq \bLamb_{t_n}^{k_n}(\sum_{p \in J}\delta_{\bx_p})}\right)\\
		&=\bZeta^{i,k_n}(T-t_n,y_{n}) \ind{\theta_\ell > \bM^{k_\ell}(t_\ell)  +\sum_{m = 1}^{\ell-1}\bP^{k_\ell,k_m}(t_k - t_m,y_m)} \\
		&(\sum_{J\subset\{1,\dots,\ell-1,\ell+1,\dots,n-1\}} \hspace*{-1cm} (-1)^{n-2-|J|} 
		\ind{\theta_{n} \leq \bLamb_{t_n}^{k_n}(\delta_{x_\ell}+\sum_{p \in J}\delta_{\bx_p})} 
		 + \sum_{J\subset\{1,\dots,\ell-1,\ell+1,\dots,n-1\}}   \hspace*{-1cm} (-1)^{n-1-|J|} 
		\ind{\theta_{n} \leq \bLamb_{t_n}^{k_n}(\sum_{p \in J}\delta_{\bx_p})}).
	\end{align*}
	Since on the domain
	$\{\theta_\ell > \bM^{k_\ell}(t_\ell) + \sum_{m = 1}^{\ell}\bP^{k_\ell,k_m}(t_\ell - t_m,y_m)\}$
	we have that,
	$$\ \bLamb_{t_n}^{k_n}(\delta_\ell + \sum_{p \in J}\delta_{\bx_p})=\bLamb_{t_n}^{k_n}(\sum_{p \in J}\delta_{\bx_p}), $$
	therefore for any  $ \ell\in\{2,\dots,n\}$
	$$
	\T^n_{(\bx_1, \dots, \bx_n)}{\myZ{T}}\ind{\theta_\ell > \bM^{k_\ell}(t_\ell) + \sum_{m = 1}^{\ell-1}\bP^{k_\ell,k_m}(t_\ell - t_m,y_m)}
	= 0 .
	$$
For $\ell=1$
	$$
	\T^n_{(\bx_1, \dots, \bx_n)}{\myZ{T}}= \ind{\theta_{1} \leq \bLamb_{t_1}^{k_1}(\delta_{\bx_1})}=\ind{\theta_{1} \leq \bM^{k_1}(t_1)}
	$$
	which concludes the proof.
\end{proof}


\subsection{Shifted processes}
Combining  Mecke's formula  (\ref{eq:Mecke_1}) %(\ref{eq:Mecke_2}) 
and the pseudo-chaotic expansion (Theorem \ref{th:pseudochaoticcounting})  involves processes of the form $F\circ \varepsilon_{\bx_1,\ldots,\bx_n}^{+,n}$ that we call shifted processes. An in-depth study of these processes for $F= \myZ{}$, is of interest, as they can be interpreted as stressed scenarios.

\begin{remark}[A consequence of the compatibility condition]
We would like to enhance an important consequence of the compatibility condition when shifting the intensity of an MSPD.
Let $\boldsymbol{Z}$ a $(\bZ,\bM,\bP)-$MSPD. Let $n \in \N^*$, $(\bx_1 \dots, \bx_n)\in (\bX_T)^n$ satisfying the compatibility condition (\ref{eq:compatibility}), then for any $\omega \in \Omega$,  the shifted processes are given by
	\begin{align*}
		\myZ{T}\circ \varepsilon_{(\bx_1 \dots, \bx_n)}^{+,n}(\omega)&=\left( \int_{\bX_T}\bZeta^{i,k}(T-t,y) \ind{\theta \leq \bLamb_t^k} \bN(dk,dt,d\theta,dy)\right)(\omega + \sum_{j=1}^{n}\delta_{\bx_j})\\
		&=\left(\int_{\bX_T}\bZeta^{i,k}(T-t,y)  \ind{\theta \leq \bLamb_t^k(\omega + \sum_{j=1}^{n}\delta_{\bx_j})} \bN(dk,dt,d\theta,dy)\right)(\omega)\\
		&+\sum_{j=1}^{n}\bZeta^{i,k_j}(T-t_j,y_j) \ind{\theta_j \leq \bLamb_{t_j}^{k_j}(\omega + \sum_{j=1}^{n}\delta_{\bx_j})}.
	\end{align*}
Since $(\bx_1 \dots, \bx_n)\in (\bX_T)^n$ satisfy the compatibility condition,  Remark \ref{remark:pre_compatibility} implies 
\begin{align*}
	\myZ{T}\circ \varepsilon_{(\bx_1 \dots, \bx_n)}^{+,n}&=\sum_{j=1}^{n}\bZeta^{i,k_j}(T-t_j,y_j)+\int_{\bX_T}\bZeta^{i,k}(T-t,y)\ind{\theta \leq \bLamb_t^k\circ \varepsilon_{(\bx_1 \dots, \bx_n)}^{+,n}} \bN(dk,dt,d\theta,dy).
\end{align*}
Moreover, from Remark \ref{remark:lambda_MSPD}, $\bLamb - \bM$ can be seen as an MSPD which gives us, 
	\begin{align*}
		\bLamb_T^i\circ \varepsilon_{(\bx_1 \dots, \bx_n)}^{+,n}
		&= \bM^i(T)+ \sum_{j=1}^{n}\bP^{i,k_j}(T-t_j,y_j)  + \int_{\bX_T}\bP^{i,k}(T-t,y)  \ind{\theta \leq \bLamb_t^k\circ \varepsilon_{(\bx_1 \dots, \bx_n)}^{+,n}} \bN(dk,dt,d\theta,dy).
	\end{align*}
\end{remark}
From the results above, we can remark that a shifted process $\myZ{T}\circ \varepsilon_{(\bx_1 \dots, \bx_n)}^{+,n}$ can  be seen as  a MSPD-process whose baseline intensity is impacted by  $(\bx_1 \dots, \bx_n)$. This leads to the following definition.


\begin{definition}[Compensated shift of an MSPD]\label{def:compensated shift}
	Let $\boldsymbol{Z}$ a $(\bZ,\bM,\bP)-$MSPD and let $n \in \N^*$, $(\bx_1 \dots, \bx_n)\in (\bX_T)^n$ satisfy the compatibility condition (\ref{eq:compatibility}). Then its compensated shift $\boldsymbol{Z}\odot\varepsilon_{(\bx_1 \dots, \bx_n)}^{+,n}$ given by
	\begin{equation}
			\myZ{T}\odot\varepsilon_{(\bx_1 \dots, \bx_n)}^{+,n} := \myZ{T}\circ \varepsilon_{(\bx_1 \dots, \bx_n)}^{+,n} -  \sum_{j=1}^{n}\bZeta^{i,k_j}(T-t_j,y_j),
	\end{equation}
	is a $(\bP,\bM_{(\bx_1,\dots,\bx_n)},\bP)-$MSPD where $\bM_{(\bx_1,\dots,\bx_n)}$ is such that, 
	$$
	\bM^i_{(\bx_1,\dots,\bx_n)}(T) = \bM^i(T)+ \sum_{j=1}^{n}\bP^{i,k_j}(T-t_j,y_j).
	$$ 
	In other terms we have that the compensated shift of a $(\bZeta,\bM,\bP)-$MSPD noted $\boldsymbol{Z}_{T}\odot\varepsilon_{(\bx_1 \dots, \bx_n)}^{+,n}$, is a $(\bZeta,\bM_{(\bx_1,\dots,\bx_n)},\bP)-$MSPD.
\end{definition}

 Remark \ref{remark:lambda_MSPD} highlighted  that $\bLamb_T -\bM(T)$  is  a $(\bP,\bM,\bP)-$MSPD. This stays true in the case of the compensated shift, in fact we have
$$
\bLamb_T^i\odot\varepsilon_{(\bx_1 \dots, \bx_n)}^{+,n}:=\bLamb_T^i\circ \varepsilon_{(\bx_1 \dots, \bx_n)}^{+,n}-\bM^i(T)- \sum_{j=1}^{n}\bP^{i,k_j}(T-t_j,y_j)
$$
which is a $(\bP,\bM_{(\bx_1,\dots,\bx_n)},\bP)-$MSPD.

\section{Expectation and correlations}
This section illustrates how the previous results enable us to develop a new methodology for calculating quantities related to this MSPD process $\boldsymbol{Z}$  (in particular risk valuation). To start with, we develop the computations for the expectation and the correlations  of $\boldsymbol{Z}$. For the expectation, a well-known method consists of exploiting the fact that the expectation of the intensity satisfies a Volterra equation.
However, this method is not available for the calculation of higher-order moments. Therefore, for the computation of the covariance, we will combine the pseudo-chaotic expansion with Mecke's formula to obtain expressions involving the expectation of shifted processes that can be obtained as solution of a Volterra type equation.

\subsection{Expectation of the process $\boldsymbol{Z}$ and its shifted version}
We start with the following result that extends \cite[Theorem 2]{Bacryetal2013} and \cite[Theorem 2.4]{hillairet2023explicit}.
\begin{prop}\label{prop:expectation}
	Let $\boldsymbol{Z}$ a $(\bZ,\bM,\bP)-$MSPD. Let $p \in \N^*$, $(\bx_1 \dots, \bx_p)\in (\bX_T)^p$ satisfying the compatibility condition (\ref{eq:compatibility}). Then we have
	\begin{itemize}
		\item[(i)] Expectation of $\boldsymbol{Z}_T$ : $$\E[\boldsymbol{Z}_T] = \int_{0}^{T}\bZetaE(T-v) \left(\bM(v) + \int_{0}^{v}  \bPs(v-w)\bM(w) dw\right) dv . $$
		\item[(ii)] Expectation of $\boldsymbol{Z}_T$ shifted by $(\bx_1 \dots, \bx_p)$ :
		 \begin{align*}
		\E[\boldsymbol{Z}_T\circ \varepsilon_{(\bx_1,\dots,\bx_p)}^{+,p}]&=\E[\boldsymbol{Z}_T] +  \sum_{j=1}^{p}\bZeta^{.,k_j}(T-t_j,y_j) \\ &+\sum_{j=1}^{p}\int_{t_j}^{T}\bZetaE(T-v) \left(\bP^{.,k_j}(v-t_j,y_j) + \int_{t_j}^{v}  \bPs(v-w) \bP^{.,k_j}(w-t_j,y_j)dw\right) dv.
		 \end{align*}
	\end{itemize}
\end{prop}

\begin{proof}
	For (i), by taking the expectation of the process $\myZ{T}$ we have that, 
	$$
	\E[\myZ{T}] = \sum_{k=1}^d\int_{\bX_T} \bZetaE^{i,k}(T-t) \E[\bLamb_t^k] dt.
	$$
	Hence in order to compute $\E[\myZ{T}]$ we first need $\E[\bLamb_t^k]$, for $k=1,\cdots,d$.
	It satisfies the linear Volterra ODE 
%	$$	\E[\bLamb_T^i] = \bM^i(T) + \sum_{k=1}^d\int_{0}^T \bPE^{i,k}(T-t) \E[\bLamb_t^k] dt, $$
	which reads in a matrix form as 
	$$
	\E[\bLamb_T] = \bM(T) + \int_{0}^T \bPE(T-t) \E[\bLamb_t] dt,
	$$
	whose solution is given by, 
	$$
	\E[\bLamb_T] = \bM(T)+ \int_{0}^{T} \bPs(T-w)\bM(w) dw.
	$$
	Thus,
	\begin{align*}
		\E[\boldsymbol{Z}_{T}] &= \int_{0}^T \bZetaE(T-t) \E[\bLamb_t] dt\\
		&=\int_{0}^T \bZetaE(T-t)\left(\bM(t) + \int_{0}^{t} \bPs(t-w)\bM(w)dw \right)dt.
	\end{align*}
	For (ii), we use Definition \ref{def:compensated shift} to deduce
	\begin{align*}
		\hspace{-2cm}\E[\boldsymbol{Z}_T\odot \varepsilon_{(\bx_1,\dots,\bx_p)}^{+,p}] &=\int_{0}^T \bZetaE(T-t)\left(\bM(t)+ \sum_{j=1}^{p}\bP^{.,k_j}(t-t_j,y_j)\right)dt \\
		& + \int_{0}^T \bZetaE(T-t)\left(\int_{0}^{t} \bPs(t-w)\bM(w)dw  + \int_{0}^{t} \bPs(t-w)\sum_{j=1}^{p}\bP^{.,k_j}(w-t_j,y_j)dw\right)dt\\
		&=\E[\boldsymbol{Z}_T]\\
		&+\int_{0}^T \bZetaE(T-t)\left( \sum_{j=1}^{p}\bP^{.,k_j}(t-t_j,y_j)  + \int_{0}^{t} \bPs(t-w)\sum_{j=1}^{p}\bP^{.,k_j}(w-t_j,y_j)dw\right)dt.
	\end{align*}

\end{proof}
\noindent In (ii) of Proposition \ref{prop:expectation}, the expectation $\E[\myZ{T}\odot \varepsilon_{(\bx_1,\dots,\bx_p)}^{+,p}]$ of a $(\bZ,\bM_{(\bx_1,\dots,\bx_p)},\bP)-$MSPD is expressed as the sum of the expectations of a $(\bZ,\bM,\bP)-$MSPD and a $(\bZ,\bM_{(\bx_1,\dots,\bx_p)} - \bM,\bP)-$MSPD. This indicates that the expectation of the processes exhibits some linearity  property with respect to the baseline intensity. This observation is made formal in the following remark.
%The next remark is based on the proof of the previous proposition. By keeping in mind the expression of the expectation of a $(\bZ,\bM,\bP)-$MSPD and that $\myZ{T}\odot \varepsilon_{(\bx_1,\dots,\bx_p)}^{+,p}$ is a $(\bZ,\bM_{(\bx_1,\dots,\bx_p)},\bP)-$MSPD, one can remark that $\E[\myZ{T}\odot \varepsilon_{(\bx_1,\dots,\bx_p)}^{+,p}]$ can be expressed by the sum of the expectations of a $(\bZ,\bM,\bP)-$MSPD and a $(\bZ,\bM_{(\bx_1,\dots,\bx_p)} - \bM,\bP)-$MSPD. In that sens, the expectation of the processes exhibits some linearity with respect to the baseline intensity.
\begin{remark}[Expectation's linearity with respect to the baseline intensity] \mbox{ }\\
		Let $\boldsymbol{Z}$ a $(\bZ,\bM,\bP)-$MSPD. Let $p \in \N^*$, and consider a family of \textit{d-}dimensional vectors $\left(\boldsymbol{\Lambda}_j\right)_{1\leq j\leq p}$ such that $\forall j \in[\![1,p]\!],\forall i \in[\![1,d]\!] \;\boldsymbol{\Lambda}_j^i:\R_+\to\R_+ $. Consider the baseline intensity given by
	$$\tilde\bM(t) = \bM(t)+ \sum_{j=1}^{p}\bold{\Lambda}_j(t),$$
	and the associated processes such that $\boldsymbol{\tilde Z}$ is a $(\bZ,\tilde \bM,\bP)-$MSPD and 
	$\boldsymbol{ \tilde \Z}$ is a $(\bZ,\sum_{j=1}^{p}\bold{\Lambda}_j(T),\bP)-$MSPD.
	We have that
	\begin{align*}
		\E[\boldsymbol{\tilde Z}_T]&=\int_{0}^{T}\bZetaE(T-v) \left(\tilde\bM(v) + \int_{0}^{v}  \bPs(v-w)\tilde\bM(w) dw\right) dv =\E[\boldsymbol{Z}_T] + \E[\boldsymbol{\tilde \Z}_T]. 
	\end{align*}
\end{remark}
\begin{remark}
Proposition \ref{prop:expectation} provides as a by product a generalization of the Wald identity which in dimension 1 reduces to  \vspace{-4mm}
$$ \E[L_T] = \E[N_T] \E[Y_1]; \quad  \text{ for } L_T:=\sum_{j=1}^{N_T} Y_j    \vspace*{-3mm}$$
where  $N$ a counting process independent from the iid random variables $(Y_j)_{j\geq 1}$. In our setting, for $1\leq i\leq d$, we prove that 
\vspace{-2mm}
 $$\E[\boldsymbol{L}^i_T] = \E[Y^i]\E[\boldsymbol{H}^i_T]   \quad  \text{ for }
  L^i_T:=\sum_{j=1}^{H_T^i} Y^i_j  \vspace*{-3mm}$$ 
 where $(Y^i_j)_{j\geq 1}$ are iid random variables with probability density $\bnu^i$, 
 but in which $\E[\boldsymbol{H}^i_T]$ is impacted by the distributions of the claims sizes $(Y^1, \cdots, Y^d)$.
\end{remark}
For computing the expectation of the intensity, we apply Proposition \ref{prop:expectation} to $(\bLamb - \bM)$ which  can be considered as a $(\bP,\bM,\bP)-$MSPD 
%$\bLamb\circ \varepsilon_{(\bx_1,\dots,\bx_n)}^{+,n}$.
(see Remark \ref{remark:lambda_MSPD}).
Since the \textit{d-}kernel $\bZeta$ coincides with the self-excitation \textit{d-}kernel $\bP$, the expression for the expectation simplifies using (\ref{eq:magic_convol}).
\begin{corollary}[Intensity expectation]
	%Consider Definition \ref{def:MSPD}, then 
	The expectation of the intensity $\bLamb^i_T$ (see (\ref{eq:MSPD}))  is given by
	$$
	\E[\bLamb_T] = \bM(T)+ \int_{0}^{T} \bPs(T-w)\bM(w) dw
	$$
	and, for $p \in \N^*$, $(\bx_1 \dots, \bx_p)\in (\bX_T)^p$,  its shifted version is given by
	\begin{align*}
		\E[\bLamb^i_T\circ \varepsilon_{(\bx_1,\dots,\bx_p)}^{+,p}]&=\E[\bLamb_T^i] + \sum_{j=1}^{p}\left(\bP^{i,k_j}(T-t_j,y_j)+ \int_{t_j}^{T} \bPs^{i,.}(T-w)\bP^{.,k_j}(w-t_j,y_j)dw\right).
	\end{align*}
\end{corollary}

