\subsection{A general correlation formula}
As presented at the beginning of this section, our methodology allows one to compute more general functionals of the process $\boldsymbol{Z}$ which would not be possible by using existing methodologies (as the one presented in \cite{Bacryetal2013} with Volterra equations or in \cite{jaisson2014limit_appendix} with the moment measures). In particular one would like to compute the expectation of building blocks having the form of a product $\boldsymbol{Z}\boldsymbol{\Gamma}$ where $\boldsymbol{Z}$ is an $(\bZeta,\bM,\bP)-$MSPD and $\boldsymbol{\Gamma}:= \left(\boldsymbol{\Gamma}^\ell\right)_{1\leq \ell \leq d} \in L^2(\Omega)$ and whose expectation of the shifted version can be written as  
$$\E\left[ \boldsymbol{\Gamma}^\ell\circ\varepsilon_{(\bx_1,\dots,\bx_p)}^{+,p}\right] =\E\left[\boldsymbol{\Gamma}^\ell\right] +  \sum_{j=1}^p \boldsymbol{\rho}_\ell(k_j,t_j,y_j),$$
%However an assumption on $\boldsymbol{\Gamma}$ will involve a $\mathcal M_{d,1}^+$-valued map $\boldsymbol{\rho}$ such that each component $\boldsymbol{\rho}^{\ell}(k,t,y): \{1,\dots,d\}\times\R_+^2\to\R_+$.
with  $\boldsymbol{\rho}:= \left(\boldsymbol{\rho}_\ell\right)_{1\leq \ell \leq d}\in \mathcal M_{d,1}^+$, $\boldsymbol{\rho}_\ell:\{1,\dots,d\}\times\R_+^2 \to \R_+$ and such that 
\begin{equation}
\label{eq:integrkernelstill}
\int_{\R_+}\bZeta^{i,k}(T-t,y)\boldsymbol{\rho}_\ell(k,t,y)\bnu^{k}(dy)<+\infty, \; \forall (i,k,t).
\end{equation}
We define  for $T >0$,  $(\bZeta \boldsymbol{\rho}_\ell)^T: \R_+ \times\R_+\to\mathcal M_{d,d}^+$ and $\overline{(\bZeta \boldsymbol{\rho}_\ell)^T}: \R^+ \to \mathcal M_{d,d}^+ $  as
$$
(\bZeta \boldsymbol{\rho}_\ell)^T(t,y):= \left(\bZeta^{i,k}(T-t,y)\boldsymbol{\rho}_\ell(k,t,y)\right)_{1\leq i,k \leq d},
$$
$$
\overline{(\bZeta \boldsymbol{\rho}_\ell)^T}(t) := \left(\int_{\R_+}\bZeta^{i,k}(T-t,y)\boldsymbol{\rho}_\ell(k,t,y)\bnu^{k}(dy)\right)_{1\leq i,k \leq d}.
$$
Moreover, since $(\bZeta \boldsymbol{\rho}_\ell)^T$ is a \textit{d-}kernel (due to the integrability Condition (\ref{eq:integrkernelstill})) and  $\boldsymbol{Z}^{(\boldsymbol{\bZeta\rho}_\ell)^T}$ is a $((\bZeta\boldsymbol{\rho}_\ell)^T,\bM,\bP)-$MSPD, its expectation is given by Proposition \ref{prop:expectation} as
\begin{align*}
	\E[\boldsymbol{Z}^{(\boldsymbol{\bZeta\rho}_\ell)^T}_T]= \int_{0}^{T}\overline{(\bZeta\boldsymbol{\rho}_\ell)^T}(u)\left(\int_{0}^{u}\bPs(u-v)\bM(v)dv + \bM(u) \right)du.
\end{align*}
\textbf{Convention:}
To lighten the notations, we write $\bZeta \boldsymbol{\rho}_\ell:=(\bZeta \boldsymbol{\rho}_\ell)^T$ when there is no ambiguity in the context.\\
In the result below, $T>0$ is a fixed horizon.


\begin{theorem}\label{prop:expGamma}\label{th:gamma}
	Let $\boldsymbol{Z}$ a $(\bZeta,\bM,\bP)-$MSPD and $(\bx_1,\dots,\bx_p)\in (\bX_T)^p$ satisfying the compatibility condition (\ref{eq:compatibility}). Let $\boldsymbol{\Gamma} \in \mathcal M_{d,1}^+$ such that for $1\leq \ell \leq d$, $\boldsymbol{\Gamma}^\ell\in L^2(\Omega)$ and
	\begin{equation}\label{relationgamma}
		\E\left[ \boldsymbol{\Gamma}^\ell\circ\varepsilon_{(\bx_1,\dots,\bx_p)}^{+,p}\right] =\E\left[\boldsymbol{\Gamma}^\ell\right] +  \sum_{j=1}^p \boldsymbol{\rho}_\ell(k_j,t_j,y_j),
	\end{equation}
	where $\boldsymbol{\rho}_\ell:\{1,\dots,d\}\times\R_+^2 \to \R_+$ is a deterministic function (specific to $\boldsymbol{\Gamma}^\ell$) satisfying (\ref{eq:integrkernelstill}).\\
	Then for $1\leq i,\ell \leq d$ we have
	$$\E\left[\myZ{T}\boldsymbol{\Gamma}^\ell\right] =\E\left[\myZ{T}\right] \E\left[\boldsymbol{\Gamma}^\ell\right] + \E\left[(\boldsymbol{Z}^{\boldsymbol{\bZeta\rho}_\ell}_T)^i\right] + \int_{0}^T\bZetaE^{i,.}(T-v)\left(\int_{0}^{v}\bPs(v-w)\E\left[\boldsymbol{Z}^{\boldsymbol{\bP\rho_\ell}\hspace{0.05cm}}_w\right]dw + \E\left[\boldsymbol{Z}^{\boldsymbol{\bP\rho_\ell}\hspace{0.05cm}}_v\right] \right)dv,$$
	where $\boldsymbol{Z^{\bZeta \rho_\ell}}$ is a $(\bZeta \boldsymbol{\rho}_\ell,\bM,\bP)-$MSPD and $\boldsymbol{Z^{\bP\rho_\ell}}$ is a $(\bP\boldsymbol{\rho}_\ell,\bM,\bP)-$MSPD.
\end{theorem}
\noindent The demonstration  of Theorem \ref{prop:expGamma} relies on the following lemma, whose proof is postponed in the appendix.
\begin{lemma}\label{lemma:magic}
	Let $\boldsymbol{Z}$ a $(\bZeta,\bM,\bP)-$MSPD, and $\boldsymbol{\rho}_\ell:\{1,\dots,d\}\times\R_+^2 \to \R_+$ such that $\int_{\R_+}\boldsymbol{\rho}_\ell(k,t,y)\nu^k(dy)<+\infty$, then  for $1\leq i \leq d$
	\begin{align*}
		&\sum_{n=1}^{+\infty} \frac{1}{n!} \int_{\bX_T^n}\left(\T^n_{(\bx_1,\dots,\bx_n)} \myZ{T}\right)\;\sum_{j=1}^n\boldsymbol{\rho}_\ell{(k_j,t_j,y_j)}\; \br^{\otimes n}(d\bx_1,\ldots,d\bx_n) \\
		&=\E\left[(\boldsymbol{Z}^{\boldsymbol{\bZeta\rho}_\ell}_T)^i\right] +\int_{0}^T\bZetaE^{i,.}(T-v)\int_{0}^{v}\left(\bPs(v-w)\E[\boldsymbol{Z}^{\boldsymbol{\bP\rho_\ell}}_{w}] + \E[\boldsymbol{Z}^{\boldsymbol{\bP\rho_\ell}}_{v}] \right)dwdv. 
	\end{align*}
	Moreover if $\sum \boldsymbol{\rho}_\ell \equiv 1$, then
	\begin{align*}
		&\sum_{n=1}^{+\infty} \frac{1}{n!} \int_{\bX_T^n} \T^n_{(\bx_1,\dots,\bx_n)} \myZ{T} \; \br^{\otimes n}(d\bx_1,\ldots,d\bx_n) = \E\left[\boldsymbol{Z}^i_T\right].
	\end{align*} 
\end{lemma}
\begin{proof}[Proof of Theorem \ref{prop:expGamma}]
	Using successively the pseudo-chaotic expansion for $\myZ{T}$, the Mecke formula and  Lemma \ref{lemma:magic} we have 
	\begin{align*}
		&\E[\myZ{T}\boldsymbol{\Gamma}^\ell]=  \lim_{M\to \infty}\sum_{n=1}^{+\infty}\frac{1}{n!}\E[\boldsymbol{\mathcal{I}}_n(\T^n \myZ{T}\ind{([0,T]\times[0,M])^n})\boldsymbol{\Gamma}^\ell]\\
		&= \lim_{M\to \infty}\sum_{n=1}^{+\infty}\frac{1}{n!} \int_{(\bX_T^M)^n} \T^n_{(\bx_1,\dots,\bx_n)} \myZ{T}\E\left[ \boldsymbol{\Gamma}^\ell\circ\varepsilon_{(\bx_1,\dots,\bx_n)}^{+,n}\right] \br^{\otimes n}(d\bx_1,\ldots,d\bx_n) \\
		&=\E[\myZ{T}]\E[\boldsymbol{\Gamma}^\ell] +\sum_{n=1}^{+\infty} \frac{1}{n!} \int_{\bX_T^n}\T^n_{(\bx_1,\dots,\bx_n)} \myZ{T}\sum_{j=1}^n\boldsymbol{\rho}_\ell{(t_j,y_j,k_j)}\br^{\otimes n}(d\bx_1,\ldots,d\bx_n)\\
		&= \E[\myZ{T}]\E[\boldsymbol{\Gamma}^\ell] + \E\left[(\boldsymbol{Z}^{\boldsymbol{\bZeta\rho}_\ell}_T)^i\right] +\int_{0}^T\bZetaE^{i,.}(T-v)\left(\int_{0}^{v}\bPs(v-w)\E\left[\boldsymbol{Z}^{\boldsymbol{\bP\rho_\ell}}_{w}\right]dw + \E\left[\boldsymbol{Z}^{\boldsymbol{\bP\rho_\ell}}_{v}\right] \right)dv
	\end{align*}
	where  $X^{M}_T:=\{1,\dots,d\}\times[0,T]\times[0,M]\times\R_+$.
\end{proof}
\noindent Theorem \ref{prop:expGamma} is now applied to compute the covariance of two MSPDs having different kernels.
\subsection{Correlations of MSPDs}
By combining Proposition \ref{prop:expectation} and  Theorem \ref{prop:expGamma}, we deduce the following proposition.
\begin{theorem}[Correlations of two MSPDs]\label{prop:correlationZ}
	Let $\boldsymbol{Z}$ a $(\bZeta,\bM,\bP)-$MSPD and $\boldsymbol{\tilde Z}$ a $(\tilde\bZeta,\tilde\bM,\tilde\bP)-$MSPD, then for $0 \leq T \leq S$, their covariance (for $1\leq i, \ell \leq d$) is 
	\begin{equation}\label{eq:covMSPD}
		Cov\left(\boldsymbol{Z}^i_T, \boldsymbol{\tilde Z}^\ell_S\right) = \E\left[(\boldsymbol{Z}_T^{\boldsymbol{\bZeta\tilde\rho_\ell}})^i\right] + \int_{0}^T\bZetaE^{i,.}(T-v)\left(\int_{0}^{v}\bPs(v-w)\E[\boldsymbol{Z}^{\boldsymbol{\bP\tilde\rho_\ell}}_{w}]dw + \E[\boldsymbol{Z}^{\boldsymbol{\bP\tilde\rho_\ell}}_{v}] \right)dv,
	\end{equation}
	where  $\bZeta \boldsymbol{\tilde\rho_\ell} := (\bZeta \boldsymbol{\tilde\rho_\ell})^T$ and $\boldsymbol{Z^{\bZeta\tilde\rho_\ell}}$ is a $(\bZeta \boldsymbol{\tilde\rho_\ell},\bM,\bP)-$MSPD $; \\{\bP\boldsymbol{\tilde\rho_\ell}}:={(\bP\boldsymbol{\tilde\rho_\ell})^T}$
	and $\boldsymbol{Z^{\bP\boldsymbol{\tilde\rho_\ell}}}$ a $(\bP \boldsymbol{\tilde\rho_\ell},\bM,\bP)-$MSPD with
	$$
	\boldsymbol{\tilde\rho}_\ell{(k,t,y)}:=\tilde\bZeta^{\ell,k}(S-t,y)
	+ \int_{t}^{S}\overline{\tilde\bZeta}^{\ell,.}(S-v) \left(\tilde\bP^{.,k}(v-t,y) + \int_{t}^{v}\TbPs(v-w) \tilde\bP^{.,k}(w-t,y)dw \right)dv.
	$$
\end{theorem}

\begin{proof}
	Let $p \in \N^*$, $(\bx_1 \dots, \bx_p)\in (\bX_T)^p$ satisfying the compatibility condition (\ref{eq:compatibility}), then from Proposition \ref{prop:expectation} we have that
	\begin{align*}
		\E[\boldsymbol{\tilde Z}_S^\ell\circ \varepsilon_{(\bx_1,\dots,\bx_p)}^{+,p}]&=\E[\boldsymbol{\tilde Z}_S^\ell] +  \sum_{j=1}^{p} \tilde\bZeta^{\ell,k_j}(S-t_j,y_j)\\
		&+\sum_{j=1}^{p} \int_{t_j}^{S}\overline{\tilde\bZeta}^{\ell,.}(S-v) \left(\tilde\bP^{.,k_j}(v-t_j,y_j) + \int_{t_j}^{v}\TbPs(v-w) \tilde\bP^{.,k_j}(w-t_j,y_j)dw \right)dv\\
		&=\E[\boldsymbol{\tilde Z}_S^\ell]  + \sum_{j=1}^{p}\boldsymbol{\tilde\rho}_\ell {(k_j,t_j,y_j)}.
	\end{align*}
	Thus applying Theorem \ref{prop:expGamma} with $\boldsymbol{\Gamma}^\ell:=\boldsymbol{\tilde Z}^\ell$ gives
	\begin{align*}
		Cov\left(\boldsymbol{Z}^i_T,\boldsymbol{\tilde Z}^\ell_S\right) = \E\left[(\boldsymbol{Z}_T^{\boldsymbol{\bZeta\tilde\rho_\ell}})^i\right] + \int_{0}^T\bZetaE^{i,.}(T-v)\left(\int_{0}^{v}\bPs(v-w)\E[\boldsymbol{Z}^{\boldsymbol{\bP\tilde\rho_\ell}}_{w}]dw + \E[\boldsymbol{Z}^{\boldsymbol{\bP\tilde\rho_\ell}}_{v}] \right)dv,
	\end{align*}
	where $\boldsymbol{Z^{\bZeta\tilde\rho_\ell}}$ is a $(\bZeta \boldsymbol{\tilde\rho_\ell},\bM,\bP)-$MSPD and $\boldsymbol{Z^{\bP\boldsymbol{\tilde\rho_\ell}}}$ a $(\bP \boldsymbol{\tilde\rho_\ell},\bM,\bP)-$MSPD.
\end{proof}
\noindent Remark that the  second term  in  the right hand side  of (\ref{eq:covMSPD}) can also be written  as the expectation of a $(\bZeta,\E[\boldsymbol{Z}^{\boldsymbol{\bP\tilde\rho_\ell}}],\bP)-$MSPD. More generally, 
this procedure, used here to compute the covariance, can be easily iterated to compute moments of further orders, to the price of cumbersome expressions.


\subsection{Case of a counting process with separable kernel}
In the case of counting process with separable \textit{d-}kernel $\bP(t,y) = \boldsymbol{\Phi}(t) \star\boldsymbol{B}(y)$, the expression of the covariance of the process at two different dates can be simplified, thanks to an extra convolution in the final expression.  For $1\leq i, \ell \leq d$, we introduce 
the transposed  \textit{d-}dimensional vector $\boldsymbol{\mathfrak{C}}$
\begin{equation}\label{eq:correlseparable}
(\boldsymbol{\mathfrak{C}}^k)_{1\leq k \leq d}:=\left(\frac{\int_{\R_+}\boldsymbol{B}^{i,k}(y) \boldsymbol{B}^{\ell,k}(y)\bnu^{k}(dy)}{\int_{\R_+}\boldsymbol{B}^{i,k}(y)\bnu^{k}(dy)\int_{\R_+}\boldsymbol{B}^{\ell,k}(y)\bnu^{k}(dy)}\right)_{1\leq k \leq d}
\hspace*{-5mm}=\left(\frac{\mathbb E( \boldsymbol{B}^{i,k}(Y^k) \boldsymbol{B}^{\ell,k}(Y^k) ) }{\mathbb E(\boldsymbol{B}^{i,k}(Y^k)) \mathbb E (\boldsymbol{B}^{\ell,k}(Y^k) )}\right)_{1\leq k \leq d}.
\end{equation}
Remark  that $\boldsymbol{\mathfrak{C}}^{k} = 1$
	means that $Cov(\boldsymbol{B}^{i,k}(Y^k),\boldsymbol{B}^{\ell,k}(Y^k))=0$.




\begin{prop}\label{prop:cov_sep}
	Let $\boldsymbol{H}$ a $(\boldsymbol{\bI_d},\bM,\bP)-$MSPD counting process and $\bP$ a separable \textit{d-}kernel such that $\bP(t,y) = \boldsymbol{\Phi}(t) \star\boldsymbol{B}(y)$, then for $0 \leq T \leq S$  and  $1\leq i, \ell \leq d$ we have 
	\begin{align*}
		&Cov\left(\boldsymbol{H}^i_T,\boldsymbol{H}^\ell_S\right)\\
		&=\int_{0}^T\int_{u}^{T}\bPs^{i,.}(t-u)dt\star\left( \boldsymbol{\bI_d}^{\ell,.}+ \boldsymbol{\mathfrak{C}}\star\int_{u}^{S}\bPs^{\ell,.}(v-u)dv\right)\left(\int_{0}^{u}\bPs(u-v)\bM(v)dv + \bM(u) \right)du\\
		&+ \int_{0}^{T}\boldsymbol{\bI_d}^{i,.}\star\left(\boldsymbol{\bI_d}^{\ell,.}+ \int_{u}^{S}\bPs^{\ell,.}(v-u)dv\right)\left(\int_{0}^{u}\bPs(u-v)\bM(v)dv + \bM(u) \right)du,
	\end{align*}
	where the transposed  \textit{d-}dimensional vector $\boldsymbol{\mathfrak{C}}$ is given in \eqref{eq:correlseparable}. \\
	 Moreover, if $\boldsymbol{\mathfrak{C}}^{k} = 1$ for all $1\leq k \leq d$
