		\begin{align*}
			&Cov\left(\boldsymbol{H}^i_T,\boldsymbol{H}^\ell_S\right)=\\
			&\hspace{-1.5cm}\int_{0}^T\left(\boldsymbol{\bI_d}^{i,.} + \int_{u}^{T}\bPs^{i,.}(y-u)dy\right)\star\left( \boldsymbol{\bI_d}^{\ell,.}+ \int_{u}^{S}\bPs^{\ell,.}(v-u)dv\right)\left(\int_{0}^{u}\bPs(u-v)\bM(v)dv + \bM(u) \right)du.
