\end{prop}
\begin{proof}
Applying 	Theorem  \ref{prop:correlationZ}  for  $\bZeta = \boldsymbol{\bI_d}$ ($\boldsymbol{H}$ is a counting process) %Let $\boldsymbol{H}$ a $(\bZeta,\bM,\bP)-$MSPD with $\bP$ a separable kernel such that $\bP(t,y)= \boldsymbol{\Phi}(t)\star\boldsymbol{B}(y)$, then from Theorem  \ref{prop:correlationZ} we have that
	\begin{equation}\label{eq:covcounting}
		Cov\left(\boldsymbol{H}^i_T,\boldsymbol{H}^\ell_S\right) = \E[(\boldsymbol{Z}^{\boldsymbol{\bZeta\rho_\ell}}_T)^i] + \int_{0}^T\boldsymbol{\bI_d}^{i,.}\left(\int_{0}^{v}\bPs(v-w)\E[\boldsymbol{Z}^{\boldsymbol{\bP\rho_\ell}}_{w}]dw + \E[\boldsymbol{Z}^{\boldsymbol{\bP\rho_\ell}}_{v}] \right)dv,
	\end{equation}
where $\boldsymbol{\bZeta\rho_\ell}:=(\boldsymbol{\bZeta\rho_\ell})^T $ is the diagonal matrix whose  diagonal elements are the components of the vector  $\boldsymbol{\rho_\ell}$  given below,
	 $\boldsymbol{Z^{\bZeta\rho_\ell}}$ is a $(\boldsymbol{\bZeta\rho_\ell},\bM,\bP)-$MSPD ,  $\boldsymbol{Z}^{\boldsymbol{\bP\rho_\ell}}$ is a $(\boldsymbol{\bP\rho_\ell},\bM,\bP)-$MSPD and 
	\begin{align*}
		\boldsymbol{\rho_\ell}(k,t,y)&=\ind{\ell=k}
		+ \int_{t}^{S}\boldsymbol{\bI_d}^{\ell,.} \left(\bP^{.,k}(v-t,y) + \int_{t}^{v}\bPs(v-w) \bP^{.,k}(w-t,y)dw \right)dv\\
		&= \ind{\ell=k}
		+ \int_{t}^{S}\left(\bP^{\ell,k}(v-t,y) + \int_{t}^{v}\bPs^{\ell,.}(v-w) \bP^{.,k}(w-t,y)dw \right)dv.
	\end{align*}
	The proof is  divided in four  steps,  first calculating in steps 1 and 2 the expectation of the corresponding MSPDs  $\E[\boldsymbol{Z}^{\boldsymbol{\bZeta\rho_\ell}}_T]$ and $\E[\boldsymbol{Z}^{\boldsymbol{\bP\rho_\ell}}_{w}]$,  then step 3 computes $\int_{0}^{v}\bPs(v-w)\E[\boldsymbol{Z}^{\boldsymbol{\bP\rho_\ell}}_{w}]dw$ and finally step 4  gathers the previous expressions  to give the final result.\\
%following we will remark in step 3 that $\int_{0}^{v}\bPs(v-w)\E[\boldsymbol{H}^{\boldsymbol{\bP\rho}}_{w}]dw$ will simplify the expression of the covariance, finally we will compute the final result and remark an extra simplification by adding an assumption on the covariance of the random variables $\boldsymbol{B}^{i,\ell}(Y)$.\\
Steps 1 and 2 rely on the assumption of  a  separable excitation kernel $\bP(t,y)= \boldsymbol{\Phi}(t)\star\boldsymbol{B}(y)$. We recall the notation $\overline{\boldsymbol{B}}^{\ell,k}:= \int_{\R_+}\boldsymbol{B}^{\ell,k}(y)\bnu^{k}(dy)$.
	In what follows, the ratio $\frac{\boldsymbol{B}^{\ell,k}(y)}{\boldsymbol{\overline{B}}^{\ell,k}}$ represents   the relative value of the outcome   $\boldsymbol{B}^{\ell,k}(y)$ with respect  to its mean value $\boldsymbol{\overline{B}}^{\ell,k}$.\\


	%we make an abuse of notation by writing $\boldsymbol{B}:= \boldsymbol{B}(y)$
\noindent \underline{Step 1:} Computing  $\E[(\boldsymbol{Z}^{\boldsymbol{\bZeta\rho_\ell}}_T)^i]$.\\
	By  putting the relative quantity  $\frac{\boldsymbol{B}^{\ell,k}(y)}{\boldsymbol{\overline{B}}^{\ell,k}}$ in factor (thanks to the separability of the kernel) and then by using the convolution relation \eqref{eq:magic_convol}
	%In this step we make an abuse of notation by writing $\boldsymbol{B}:= \boldsymbol{B}(y)$,
	\begin{align*}
	&	\boldsymbol{\bZeta\rho_\ell}^{i,k}(u,y)=\ind{i=k} \left(\ind{\ell=k} +\int_{u}^{S} \left(\bP^{\ell,k}(v-u,y) + \int_{u}^{v}\bPs^{\ell,.}(v-w) \bP^{.,k}(w-u,y)dw \right)dv\right)\\
		&=\ind{i=k} \left(\ind{\ell=k} +\int_{u}^{S} \left(\bPE^{\ell,k}(v-u)\frac{\boldsymbol{B}^{\ell,k}(y)}{\boldsymbol{\overline{B}}^{\ell,k}} + \left[\int_{u}^{v}\bPs(v-w) \bPE(w-u)dw\right]^{\ell,k}\frac{\boldsymbol{B}^{\ell,k}(y)}{\boldsymbol{\overline{B}}^{\ell,k}}  \right)dv\right)\\
		&= \ind{i=k} \left(\ind{\ell=k} +\frac{\boldsymbol{B}^{\ell,k}(y)}{\boldsymbol{\overline{B}}^{\ell,k}}\int_{u}^{S}\bPs^{\ell,k}(v-u)dv\right); \quad u \leq T.
	\end{align*}
Integrating with respect to  $\bnu^{k}(dy)$  then yields
	$$
	\overline{\boldsymbol{\bZeta\rho_\ell}}^{i,k}(u) = \ind{i=k} \left(\ind{\ell=k} +\int_{u}^{S}\bPs^{\ell,k}(v-u)dv\right),  \quad u \leq T,
	$$
and using Proposition \ref{prop:expectation} for a $(\boldsymbol{\bZeta\rho_\ell},\bM,\bP)-$MSPD 
	\begin{align*}
		\E[(\boldsymbol{Z}^{\boldsymbol{\bZeta\rho_\ell}}_T)^i]= \int_{0}^{T}\boldsymbol{\bI_d}^{i,.}\star\left(\boldsymbol{\bI_d}^{\ell,.}+ \int_{u}^{S}\bPs^{\ell,.}(v-u)dv\right)\left(\int_{0}^{u}\bPs(u-v)\bM(v)dv + \bM(u) \right)du.
	\end{align*}
\underline{Step 2:} Computing $\E[(\boldsymbol{Z}^{\boldsymbol{\bP\rho_\ell}}_T)^i]$.\\
	By repeating the same methodology as in Step 1, we have 
	\begin{align*}
		\boldsymbol{\bP\rho_\ell}^{i,k}(u,y)
		%&= \bP^{i,k}(T-u,y)\left(\ind{\ell=k} + \int_{u}^{S}\boldsymbol{\bI_d}^{\ell,.} \left(\bP^{.,k}(v-t,y) + \int_{u}^{v}\bPs(v-w) \bP^{.,k}(w-t,y)dw \right)dv\right)\\
		&= \bP^{i,k}(T-u,y) \left(\ind{\ell=k} + \frac{\boldsymbol{B}^{\ell,k}(y)}{\boldsymbol{\overline{B}}^{\ell,k}}\int_{u}^{S}\bPs^{\ell,k}(v-u)dv\right).
		%&= \bP^{i,k}(T-u,y)\ind{\ell=k} + \bP^{i,k}(T-u,y)\frac{\boldsymbol{B}^{\ell,k}}{\boldsymbol{\overline{B}}^{\ell,k}}\int_{u}^{S}\bPs^{\ell,k}(v-u)dv.
	\end{align*}
	Integrating with respect to  $\bnu^{k}(dy)$ yields 
	\begin{align*}
		\overline{\boldsymbol{\bP \rho_\ell}}^{i,k}(u) &= \bPE^{i,k}(T-u)\ind{\ell=k} + \int_{\R_+}\boldsymbol{\Phi}^{i,k}(T-u)\boldsymbol{B}^{i,k}(y)\frac{\boldsymbol{B}^{\ell,k}(y)}{\boldsymbol{\overline{B}}^{\ell,k}}\int_{u}^{S}\bPs^{\ell,k}(v-u)dv \nu^{k}(dy)\\
		&= \bPE^{i,k}(T-u)\ind{\ell=k} + \bPE^{i,k}(T-u)\int_{u}^{S}\bPs^{\ell,k}(v-u)dv \int_{\R_+}\frac{\boldsymbol{B}^{i,k}(y)}{\overline{\boldsymbol{B}}^{i,k}}\frac{\boldsymbol{B}^{\ell,k}(y)}{\boldsymbol{\overline{B}}^{\ell,k}}\nu^{k}(dy)\\
		&= \bPE^{i,k}(T-u)\left(\ind{\ell=k} +     \boldsymbol{\mathfrak{C}}^k  \int_{u}^{S}\bPs^{\ell,k}(v-u)dv\right)
	\end{align*}
	%We define the vector $\boldsymbol{\mathfrak{C}}:=\frac{\int_{\R_+}\boldsymbol{B}^{i,.}(y)\star \boldsymbol{B}^{\ell,.}(y)\bnu^{.}(dy)}{\int_{\R_+}\boldsymbol{B}^{i,.}(y)\bnu^{.}(dy)\star\int_{\R_+}\boldsymbol{B}^{\ell,.}(y)\bnu^{.}(dy)}$. Hence we have that,
that is $$
	\overline{\bP\rho}^{i,.}(u)=\bPE^{i,.}(T-u)\star\left( \boldsymbol{\bI_d}^{\ell,.}+ \boldsymbol{\mathfrak{C}}\star\int_{u}^{S}\bPs^{\ell,.}(v-u)dv\right),
	$$
	and  using Proposition \ref{prop:expectation} for a $(\boldsymbol{\bP\rho_\ell},\bM,\bP)-$MSPD
	\begin{align*}
		\E[(\boldsymbol{Z}^{\boldsymbol{\bP\rho_\ell}}_T)^i]= \int_{0}^{T}\bPE^{i,.}(T-u)\star\left( \boldsymbol{\bI_d}^{\ell,.}+ \boldsymbol{\mathfrak{C}}\star\int_{u}^{S}\bPs^{\ell,.}(v-u)dv\right)\left(\int_{0}^{u}\bPs(u-v)\bM(v)dv + \bM(u) \right)du.
	\end{align*}
	\underline{Step 3:} Computing $\int_{0}^{t}\bPs(t-w)\E[\boldsymbol{Z}^{\boldsymbol{\bP\rho_\ell}}_{w}]dw $.\\
	Using Step 2 and again the  convolution relation \eqref{eq:magic_convol}, we have
	\begin{align*}
		&{\sum_{k=1}^{d}\int_{0}^{t}\bPs^{j,k}(t-w)\E[(\boldsymbol{Z}^{\boldsymbol{\bP\rho_\ell}}_w)^k]dw}\\
		&\hspace{-1.2cm}=\sum_{k=1}^{d}\int_{0}^{t}\bPs^{j,k}(t-w)\int_{0}^{w}\bPE^{k,.}(w-u)\star\left( \boldsymbol{\bI_d}^{\ell,.}+ \boldsymbol{\mathfrak{C}}\star\int_{u}^{S}\bPs^{\ell,.}(v-u)dv\right)\left(\int_{0}^{u}\bPs(u-v)\bM(v)dv + \bM(u) \right)dudw\\
		&\hspace{-1.2cm}=\int_{0}^{t}\left[\int_{u}^{t}\bPs(t-w)\bPE(w-u)dw\right]^{j,.}\star\left( \boldsymbol{\bI_d}^{\ell,.}+ \boldsymbol{\mathfrak{C}}\star\int_{u}^{S}\bPs^{\ell,.}(v-u)dv\right)\left(\int_{0}^{u}\bPs(u-v)\bM(v)dv + \bM(u) \right)du\\
		&\hspace{-1.2cm}=\int_{0}^{t}\left(\bPs^{j,.}(t-u)-\bPE^{j,.}(t-u)\right)\star\left( \boldsymbol{\bI_d}^{\ell,.}+ \boldsymbol{\mathfrak{C}}\star\int_{u}^{S}\bPs^{\ell,.}(v-u)dv\right)\left(\int_{0}^{u}\bPs(u-v)\bM(v)dv + \bM(u) \right)du\\
		&\hspace{-1.2cm}=\int_{0}^{t}\bPs^{j,.}(t-u)\star\left( \boldsymbol{\bI_d}^{\ell,.}+ \boldsymbol{\mathfrak{C}}\star\int_{u}^{S}\bPs^{\ell,.}(v-u)dv\right)\left(\int_{0}^{u}\bPs(u-v)\bM(v)dv + \bM(u) \right)du - \E[(\boldsymbol{Z^{\bP\rho_\ell}_t})^{j}].
	\end{align*}
\underline{Step 4:} Final result. 	\\
Coming back to \eqref{eq:covcounting}, and integrating the  results of the previous steps,
	\begin{align*}
		&Cov\left(\boldsymbol{H}^i_T,\boldsymbol{H}^\ell_S\right)- \E[(\boldsymbol{Z}^{\boldsymbol{\bZeta\rho_\ell}}_T)^i]= \int_{0}^T\boldsymbol{\bI_d}^{i,.}  \left(\int_{0}^{t}\bPs(t-w)  E[\boldsymbol{Z}^{\boldsymbol{\bP\rho_\ell}}_{w}]dw + \E[\boldsymbol{Z}^{\boldsymbol{\bP\rho_\ell}}_{t}]\right)dt\\
		&\hspace{-1.5cm}=\sum_{j=1}^{d}\int_{0}^T\boldsymbol{\bI_d}^{i,j}  \int_{0}^{t}\bPs^{j,.}(t-u)\star\left( \boldsymbol{\bI_d}^{\ell,.}+ \boldsymbol{\mathfrak{C}}\star\int_{u}^{S}\bPs^{\ell,.}(v-u)dv\right)\left(\int_{0}^{u}\bPs(u-v)\bM(v)dv + \bM(u) \right)dudt\\
		%&\hspace{-1.5cm}=\int_{0}^T\int_{0}^{t}\sum_{j=1}^{d}\bZetaE^{i,j}(T-t)\bPs^{j,.}(t-u)\star\left( \boldsymbol{\bI_d}^{\ell,.}+ \boldsymbol{\mathfrak{C}}\star\int_{u}^{S}\bPs^{\ell,.}(v-u)dv\right)\left(\int_{0}^{u}\bPs(u-v)\bM(v)dv + \bM(u) \right)dudt\\
		&\hspace{-1.5cm}=\int_{0}^T\int_{0}^{t}\sum_{j=1}^{d}\ind{i=j}\bPs^{j,.}(t-u)\star\left( \boldsymbol{\bI_d}^{\ell,.}+ \boldsymbol{\mathfrak{C}}\star\int_{u}^{S}\bPs^{\ell,.}(v-u)dv\right)\left(\int_{0}^{u}\bPs(u-v)\bM(v)dv + \bM(u) \right)dudt\\
		&\hspace{-1.5cm}=\int_{0}^T\int_{u}^{T}\bPs^{i,.}(t-u)dt\star\left( \boldsymbol{\bI_d}^{\ell,.}+ \boldsymbol{\mathfrak{C}}\star\int_{u}^{S}\bPs^{\ell,.}(v-u)dv\right)\left(\int_{0}^{u}\bPs(u-v)\bM(v)dv + \bM(u) \right)du.
	\end{align*}       
By replacing the expression of $\E[(\boldsymbol{Z}^{\boldsymbol{\bZeta\rho_\ell}}_T)^i]$ computed in Step 1, we get 
	\begin{align*}
		&Cov\left(\boldsymbol{H}^i_T,\boldsymbol{H}^\ell_S\right)\\
		&=\int_{0}^T\int_{u}^{T}\bPs^{i,.}(t-u)dt\star\left( \boldsymbol{\bI_d}^{\ell,.}+ \boldsymbol{\mathfrak{C}}\star\int_{u}^{S}\bPs^{\ell,.}(v-u)dv\right)\left(\int_{0}^{u}\bPs(u-v)\bM(v)dv + \bM(u) \right)du\\
		&+ \int_{0}^{T}\boldsymbol{\bI_d}^{i,.}\star\left(\boldsymbol{\bI_d}^{\ell,.}+ \int_{u}^{S}\bPs^{\ell,.}(v-u)dv\right)\left(\int_{0}^{u}\bPs(u-v)\bM(v)dv + \bM(u) \right)du.
	\end{align*}
\end{proof}


\section{Conclusion}
In this paper,  we presented a general method for calculating  different quantities related to multidimensional self-exciting processes with dependencies (MSPD). This class of processes encompasses several quantities useful  for risk assessment, such as counting, loss,  intensity processes and their shifted versions, in a framework of cross-dependencies and impact of the severity component on the frequency component.  The methodology relies on the Poisson imbedding, the pseudo-chaotic expansion and Malliavin calculus, and is illustrated here to compute explicit formula for the correlations. A forthcoming companion paper will be dedicated to further developments such as the computation of moments of  higher order, as well as the pricing of insurance contracts with underlying asset a MSPD (e.g. stop-loss contracts).  



\section*{Appendix}
\begin{proof}[Proof of Lemma \ref{lemma:magic}]
The aim is to compute the following quantity
\begin{align*}
&A:=\sum_{n=1}^{+\infty} \frac{1}{n!} \int_{\bX_T^n} \T^n_{(\bx_1,\dots,\bx_n)} \myZ{T}\sum_{j=1}^n\boldsymbol{\rho}_\ell{(t_j,y_j,k_j)}\br^{\otimes n}(d\bx_1,\ldots,d\bx_n) \\
&=\sum_{n=1}^{+\infty}\int_{\Delta_T^n}\sum_{k_1=1}^d \dots \sum_{k_n=1}^d\int_{\R_+^2}\T^n_{(\bx_1,\dots,\bx_n)} \myZ{T}\sum_{j=1}^n\boldsymbol{\rho}_\ell{(t_j,y_j,k_j)}dt_1 d\theta_1 \bnu^{k_1}(dy_1)\cdots  dt_n d\theta_n \bnu^{k_n}(dy_n).
\end{align*}
where $\bx_i :=(k_i,t_i,\theta_i,y_i)$, $\Delta_T^n$  is  the simplex 
$$\Delta_T^n:=\{(\bx_1,\cdots,\bx_n)\in\bX^n,t_1 < \cdots< t_i<t_{i+1}<\cdots<t_n<T\}$$
so that for any symmetric map $f$, $\frac{1}{n!} \int_{[0,T]^n} f(t_1,\ldots,t_n) dt_1 \cdots dt_n = \int_{\Delta_T^n} f(t_1,\ldots,t_n) dt_1 \cdots dt_n$. 
The  proof is divided in 5 steps, by successively integrating  with respect to the $\theta_i$  (Step 1), then  the $y_i$  (Step 2), followed by the  $k_i$ (Step 3), and finally with respect to the $t_i$  (Step 4). The last step consists in summing all the previous  terms depending on $n$ (Step 5). \\
\underline{Step 1 :} Integration with respect to $\theta$.\\
	Since $\boldsymbol{\rho_\ell}$ does not depend on $\theta$, we integrate first $\T^n_{(\bx_1,\dots,\bx_n)} \myZ{T}$ with respect to the $\theta_i$ variables by making use of (\ref{eq:ckcounting}) and Remark \ref{remark:Tnlambda} we have
	\begin{align*}
		&\int_{\R^n_+} \T^n_{(\bx_{1}, \dots, \bx_{n})} \myZ{T} d\theta_1 \dots d\theta_n  \\
		&=\int_{\R^n_+} \bZeta^{i,k_n}(T-t_n,y_n)\T^{n-1}_{(\bx_1,\dots,\bx_{n-1})}\ind{\theta_{n}\leq \bLamb^{k_n}_{t_n}} d\theta_1 \dots d\theta_n  \\
		&= \bZeta^{i,k_n}(T-t_n,y_n) \int_{\R_+^{n-1}} \T^{n-1}_{(\bx_1,\dots,\bx_{n-1})}\bLamb^{k_n}_{t_n}d\theta_{1}\dots d\theta_{n-1}  \\
		&= \bZeta^{i,k_n}(T-t_n,y_n)\int_{\R_+^{n-1}}\bP^{k_n,k_{n-1}}(t_n-t_{n-1},y_{n-1})\T^{n-2}_{(\bx_1,\dots,\bx_{n-2})}\ind{\theta_{n-1} \leq \lambda_{t_{n-1}}^{k_{n-1}}}d\theta_1 \dots d\theta_{n-1}  \\
		&= \bZeta^{i,k_n}(T-t_n,y_n)\bP^{k_n,k_{n-1}}(t_n-t_{n-1},y_{n-1})\int_{\R_+^{n-2}}\T^{n-2}_{(\bx_1,\dots,\bx_{n-2})}\lambda_{t_{n-1}}^{k_{n-1}}d\theta_1 \dots d\theta_{n-2}.
		%&= \bZeta^{i,k_n}(T-t_n,y_n)  \bP^{k_n,k_{n-1}}(t_n-t_{n-1},y_{n-1}).
		%& \int_{(\R_+)^{n-2}}\bP^{k_{n-1},k_{n-2}}(t_{n-1}-t_{n-2},y_{n-2})\T^{n-3}_{(\bx_{1}, \dots, \bx_{n-3})}\ind{\theta_{n-2} \leq \bLamb_{t_{n-2}}^{k_{n-2}}}d\theta_1 ,\dots,d\theta_{n-2}. \\
	\end{align*}
	Hence by induction 
	\begin{align*}
		\int_{\R_+^n} \T^n_{(\bx_{1}, \dots, \bx_{n})} \myZ{T} d\theta_1 \dots d\theta_n =\bZeta^{i,k_n}(T-t_n,y_n) \prod_{m=2}^{n} \bP^{k_m,k_{m-1}}(t_m-t_{m-1},y_{m-1})\bM^{k_1}(t_1) =:F(\bold{k},\bold{t},\bold{y})
	\end{align*}
	with $\bold{k}:=k_1,\cdots,k_n$, $\bold{t}:=t_1,\cdots,t_n$, $\bold{y}:=y_1,\cdots,y_n$, and
\begin{align*}
&A= \sum_{n=1}^{+\infty}\int_{\Delta_T^n}\sum_{k_1=1}^d \dots \sum_{k_n=1}^d\int_{\R_+} F(\bold{k},\bold{t},\bold{y}) \sum_{j=1}^n\boldsymbol{\rho}_\ell{(t_j,y_j,k_j)}dt_1 \bnu^{k_1}(dy_1)\cdots  dt_n \bnu^{k_n}(dy_n) \\
\end{align*}
	\underline{Step 2:} Integration with respect to $y$. \\
	%Since $\boldsymbol{\rho}$ depends on all the other variables, in the following steps, 
	We  separately treat the cases where $\sum \boldsymbol{\rho}_\ell \equiv 1 $ and $\sum \boldsymbol{\rho}_\ell \not\equiv 1$, and we denote the corresponding values   respectively  $A^{\not\boldsymbol{\rho}}$ and $A^{\boldsymbol{\rho}}$.\\
	$\bullet$ If $\sum \boldsymbol{\rho}_\ell \equiv 1$,
	\begin{align*}
		&\int_{\R_+^n} \left[\bZeta^{i,k_n}(T-t_n,y_n)\prod_{m=2}^{n} \bP^{k_m,k_{m-1}}(t_m-t_{m-1},y_{m-1})\bM^{k_1}(t_1)\right] \bnu^{k_1}(dy_1)\dots\bnu^{k_n}(dy_n)\\
		&=\bZetaE^{i,k_n}(T-t_n)\prod_{m=2}^{n} \bPE^{k_m,k_{m-1}}(t_m-t_{m-1})\bM^{k_1}(t_1).
	\end{align*}
	So in that case 
	$$ A^{\not\boldsymbol{\rho}} = \sum_{n=1}^{+\infty}\int_{\Delta_T^n}\sum_{k_1=1}^d \dots \sum_{k_n=1}^d \bZetaE^{i,k_n}(T-t_n)\prod_{m=2}^{n} \bPE^{k_m,k_{m-1}}(t_m-t_{m-1})\bM^{k_1}(t_1) dt_1\cdots, dt_n.$$
	$\bullet$ If $\sum \boldsymbol{\rho}_\ell \not\equiv 1,$
	\begin{align*}
		&\hspace{-1.5cm}\int_{\R_+^n} \left[\bZeta^{i,k_n}(T-t_n,y_n)\prod_{m=2}^{n} \bP^{k_m,k_{m-1}}(t_m-t_{m-1},y_{m-1})\bM^{k_1}(t_1)\right]\sum_{j=1}^n\boldsymbol{\rho_\ell}{(t_j,y_j,k_j)} \bnu^{k_1}(dy_1) \dots\bnu^{k_n}(dy_n)\\
		&=\int_{\R_+^n} \left[\bZeta^{i,k_n}(T-t_n,y_n)\boldsymbol{\rho_\ell}{(t_n,y_n,k_n)}\prod_{m=2}^{n} \bP^{k_m,k_{m-1}}(t_m-t_{m-1},y_{m-1})\bM^{k_1}(t_1)\right]\bnu^{k_1}(dy_1)\dots\bnu^{k_n}(dy_n)\\
		&+\int_{\R_+^n} \left[\bZeta^{i,k_n}(T-t_n,y_n)\prod_{m=2}^{n} \bP^{k_m,k_{m-1}}(t_m-t_{m-1},y_{m-1})\bM^{k_1}(t_1)\right]\sum_{j=1}^{n-1}\boldsymbol{\rho_\ell}{(t_j,y_j,k_j)} \bnu^{k_1}(dy_1)\dots\bnu^{k_n}(dy_n)\\
		&= \overline{\bZeta\boldsymbol{\rho}_\ell}^{i,k_n}(t_n)\prod_{m=2}^{n} \bPE^{k_m,k_{m-1}}(t_m-t_{m-1})\bM^{k_1}(t_1)\\
		&+\sum_{j=1}^{n-1}\int_{\R_+^n}\bZeta^{i,k_n}(T-t_n,y_n)\bP^{k_{j+1},k_{j}}(t_{j+1}-t_{j},y_{j})\boldsymbol{\rho_\ell}{(t_j,y_j,k_j)}\\
		&\left( \prod_{m=2,m\neq j+1}^{n} \bP^{k_m,k_{m-1}}(t_m-t_{m-1},y_{m-1})\right)\bM^{k_1}(t_1)\bnu^{k_1}(dy_1) \dots\bnu^{k_n}(dy_n)\\
		&=  \overline{\bZeta\boldsymbol{\rho}_\ell}^{i,k_n}(t_n)\prod_{m=2}^{n} \bPE^{k_m,k_{m-1}}(t_m-t_{m-1})\bM^{k_1}(t_1)\\
		&+\sum_{j=1}^{n-1}\bZetaE^{i,k_n}(T-t_n)\overline{\bP\boldsymbol{\rho}_\ell}^{k_{j+1},k_{j}}(t_{j+1}-t_{j})\left( \prod_{m=2,m\neq j+1}^{n} \bPE^{k_m,k_{m-1}}(t_m-t_{m-1})\right)\bM^{k_1}(t_1)\\
		&=:F^{\boldsymbol{\rho}}(\bold{k},\bold{t})
	\end{align*}
	where by abuse of notation 
	$$ \overline{\bP\boldsymbol{\rho}_\ell}^{k_{j+1},k_{j}}(t_{j+1}-t_{j}):=   \int \bP^{k_{j+1},k_{j}}(t_{j+1}-t_{j}, y_j) \boldsymbol{\rho}_\ell (k_j, t_j, y_j  ) \bnu^{k_j}(dy_j).$$
So in that case 
\begin{align*}
	A^{\boldsymbol{\rho}} &= \sum_{n=1}^{+\infty}\int_{\Delta_T^n}\sum_{k_1=1}^d \dots \sum_{k_n=1}^d F^{\boldsymbol{\rho}}(\bold{k},\bold{t}) dt_1 \cdots dt_n.
\end{align*}
	\underline{Step 3:} Integration with respect to $k$.\\
	This step lies essentially in the identification of matrix products.\\
	$\bullet$  If $\sum \boldsymbol{\rho}_\ell \equiv 1$,
	\begin{align*}
		&\sum_{k_1=1}^d\dots\sum_{k_n=1}^d\bZetaE^{i,k_n}(T-t_n)\prod_{m=2}^{n} \bPE^{k_m,k_{m-1}}(t_m-t_{m-1})\bM^{k_1}(t_1)\\
		%&=\sum_{k_n=1}^d\bZetaE^{i,k_n}(T-t_n)\left(\prod_{m=2}^{n}\sum_{k_{m-1}=1}^d \bPE^{k_m,k_{m-1}}(t_m-t_{m-1})\bM^{k_1}(t_1)\right)\\
		&=\sum_{k_n=1}^d\bZetaE^{i,k_n}(T-t_n)\left(\prod_{m=2}^{n}\bPE(t_m - t_{m -1}) \boldsymbol{\bM}(t_1)\; \right)^{k_n,.}\\
		&= \bZetaE^{i,.}(T-t_n)\prod_{m=2}^{n}\bPE(t_m - t_{m -1})  \boldsymbol{\bM}(t_1).
	\end{align*}
	Hence
$$ A^{\not\boldsymbol{\rho}} = \sum_{n=1}^{+\infty}\int_{\Delta_T^n}\bZetaE^{i,.}(T-t_n)\prod_{m=2}^{n}\bPE(t_m - t_{m -1})  \boldsymbol{\bM}(t_1) dt_1 \cdots  dt_n.$$
	$\bullet$  If $\sum \boldsymbol{\rho}_\ell \not\equiv 1$,
	\begin{align*}
		&\sum_{k_1=1}^d\dots\sum_{k_n=1}^d\overline{\bZeta\boldsymbol{\rho}_\ell}^{i,k_n}(t_n)\prod_{m=2}^{n} \bPE^{k_m,k_{m-1}}(t_m-t_{m-1})\bM^{k_1}(t_1)\\
		&+\sum_{k_1=1}^d\dots\sum_{k_n=1}^d\sum_{j=1}^{n-1}\bZetaE^{i,k_n}(T-t_n)
		\overline{\bP\boldsymbol{\rho}_\ell}^{k_{j+1},k_{j}}(t_{j+1}-t_{j}) 
		\left( \prod_{m=2,m\neq j+1}^{n} \bPE^{k_m,k_{m-1}}(t_m-t_{m-1})\right)\bM^{k_1}(t_1)\\
		%&=\overline{\bZeta\boldsymbol{\rho}_\ell}(T,t_n)\prod_{m=2}^{n} \bPE(t_m-t_{m-1})\bM^{k_1}(t_1)\\
		%&+\sum_{k_1=1}^d \dots \sum_{k_n=1}^d \sum_{j=1}^{n-1}\bZetaE^{i,k_n}(T-t_n)\\
		%&\left( \prod_{m\in \{j+2,\cdots,n\}} \bPE^{k_m,k_{m-1}}(t_m-t_{m-1})\overline{\bP\boldsymbol{\rho}_\ell}^{k_{j+1},k_{j}}(t_{j+1},t_{j})\prod_{m\in \{2,\cdots, j\}} \bPE^{k_m,k_{m-1}}(t_m-t_{m-1})\right)\bM^{k_1}(t_1)\\
		&=\overline{\bZeta\boldsymbol{\rho}_\ell}^{i,.}(t_n)\prod_{m=2}^{n} \bPE(t_m-t_{m-1})\bM(t_1)\\
		&+\sum_{j=1}^{n-1}\bZetaE^{i,.}(T-t_n)\prod_{m = j+2}^n \bPE(t_m-t_{m-1})\overline{\bP\boldsymbol{\rho}_\ell}(t_{j+1}-t_{j}) \prod_{m = 2}^j\bPE(t_m-t_{m-1})\bM(t_1)\\
		&=:G^{\boldsymbol{\rho}}(\bold{t}).
	\end{align*}
	Hence, 
	$$ A^{\boldsymbol{\rho}} = \sum_{n=1}^{+\infty}\int_{\Delta_T^n}G^{\boldsymbol{\rho}}(\bold{t}) dt_1\dots dt_n.$$
	\underline{Step 4:} Integration with respect to $t$.\\
	The step	consists in identifying the convolution products that appear in the expressions.\\
	$\bullet$ If $\sum \boldsymbol{\rho}_\ell \equiv 1$,
$$\int_{\Delta_T^n}\bZetaE^{i,.}(T-t_n)\prod_{m=2}^{n}\bPE(t_m - t_{m -1})  \boldsymbol{\bM}(t_1) dt_1 \dots dt_n=\int_0^T \int_{t_1}^T\bZetaE^{i,.}(T-t_n)\bPE_{n-1}(t_n - t_{1})\boldsymbol{\bM}(t_1)dt_n dt_1.$$
	Hence,
	$$ A^{\not\boldsymbol{\rho}} = \sum_{n=1}^{+\infty}\int_0^T \int_{w}^T\bZetaE^{i,.}(T-v)\bPE_{n-1}(v - w)\boldsymbol{\bM}(w)dv dw.$$
	$\bullet$ If $\sum \boldsymbol{\rho}_\ell \not\equiv 1$,\\
	the first term in $G^{\boldsymbol{\rho}}(\bold{t})$ integrates as above:
	$$\int_{\Delta_T^n}\overline{\bZeta\boldsymbol{\rho}_\ell}^{i,.}(t_n)\prod_{m=2}^{n} \bPE(t_m-t_{m-1})\bM(t_1)dt_1 \dots dt_n
	=\int_0^T \int_{w}^T \overline{\bZeta\boldsymbol{\rho}_\ell}^{i,.}(v) \bPE_{n-1}(v-w)\bM(t_1) dv dw$$
	where we recall that
		$$ \overline{\bZeta\boldsymbol{\rho}_\ell}^{k_{j+1},k_{j}}(v):=   \int \bZeta^{k_{j+1},k_{j}}(T-v, y_j) \boldsymbol{\rho}_\ell (k_j, v, y_j  ) \bnu^{k_j}(dy_j).$$
	For the second term
	\begin{align*}
		&\int_{\Delta_T^n}\sum_{j=1}^{n-1}\bZetaE^{i,.}(T-t_n)\prod_{m = j+2}^n \bPE(t_m-t_{m-1})\overline{\bP\boldsymbol{\rho}_\ell}(t_{j+1}-t_{j}) \prod_{m = 2}^j\bPE(t_m-t_{m-1})\bM(t_1)dt_1 \dots dt_n\\
		&=\sum_{j=1}^{n-1}\int_{0}^{T}\bZetaE^{i,.}(T-t_n)\int_{0}^{t_n}\cdots\int_{0}^{t_{j+2}}\prod_{m = j+2}^n \bPE(t_m-t_{m-1})\int_{0}^{t_{j+1}}\overline{\bP\boldsymbol{\rho}_\ell}(t_{j+1}-t_{j})\int_{0}^{t_{j}}\dots\\
		&\hspace*{1cm}\int_{0}^{t_{2}} \prod_{m = 2}^j\bPE(t_m-t_{m-1})\bM(t_1)dt_1\cdots dt_n\\
		%&=\int_0^T \int_{t_1}^T \overline{\bZeta\boldsymbol{\rho}_\ell}(T,t_n) \bPE_{n-1}(t_n-t_{1})\bM^{k_1}(t_1) dt_n dt_1\\
		%&+\sum_{j=1}^{n-1}\int_{0}^{T}\bZetaE^{i,.}(T-t_n)\int_{0}^{t_n}\cdots\\
		%&\int_{0}^{t_{j+2}}\prod_{m = j+2}^n \bPE(t_m-t_{m-1})\int_{0}^{t_{j+1}}\overline{\bP\boldsymbol{\rho}_\ell}(t_{j+1},t_{j})\int_{0}^{t_{j}}\bPE_{j-1}(t_j-t_{1})\bM(t_1)dt_{1},dt_j,dt_{j+1}\cdots,dt_n\\	
		&=\sum_{j=1}^{n-1}\int_{0}^{T}\int_{t_j}^T\bZetaE^{i,.}(T-t_n)\int_{t_j}^{t_{n}}\bPE_{n-j-1}(t_n-t_{j+1})\overline{\bP\boldsymbol{\rho}_\ell}(t_{j+1}-t_{j}) \int_{0}^{t_{j}}\bPE_{j-1}(t_j-t_{1})\bM(t_1)dt_{1}dt_{j+1}dt_ndt_{j}.	\end{align*}
	Hence, denoting \begin{align*}
	&E^{\boldsymbol{\rho}}_n :=\\
	&\int_0^T \int_{w}^T \overline{\bZeta\boldsymbol{\rho}_\ell}^{i,.}(v) \bPE_{n-1}(v-w)\bM(t_1) dv dw\\
	&+ \sum_{j=1}^{n-1}\int_{0}^{T}\int_{t_j}^T\bZetaE^{i,.}(T-t_n)\int_{t_j}^{t_{n}}\bPE_{n-j-1}(t_n-t_{j+1})\overline{\bP\boldsymbol{\rho}_\ell}(t_{j+1}-t_{j}) \int_{0}^{t_{j}}\bPE_{j-1}(t_j-t_{1})\bM(t_1)dt_{1}dt_{j+1}dt_ndt_{j}
		\end{align*}
		$$ A^{\boldsymbol{\rho}} = \sum_{n=1}^{+\infty}E^{\boldsymbol{\rho}}_n.$$	
	\underline{Step 5 :} Summing in $n$. \\
	$\bullet$  If $\sum \boldsymbol{\rho}_\ell \equiv 1$, using that $\bPE_0$ is the Dirac  distribution in 0,
	\begin{align*}
		A^{\not\boldsymbol{\rho}} &=\sum_{n=1}^{+\infty}\int_0^T \int_{w}^T\bZetaE^{i,.}(T-v)\bPE_{n-1}(v - w)\boldsymbol{\bM}(w)dv dw\\
		&=\int_0^T \int_{w}^T\bZetaE^{i,.}(T-v)\left(\bPs(v - w) + \bPE_0(v - w)\right)\boldsymbol{\bM}(w)dv dw\\
		&=\int_0^T \bZetaE^{i,.}(T-v)\left(\boldsymbol{\bM}(v)+ \int_{0}^v\bPs(v - w)\boldsymbol{\bM}(w)dw\right) dv = \E[\boldsymbol{Z}^i_T].
	\end{align*}
	$\bullet$  If $\sum \boldsymbol{\rho}_\ell \not\equiv 1$,  the first term in $E^{\boldsymbol{\rho}}_n$ sums as above
$$\sum_{n=1}^{+\infty}\int_0^T \int_w^T \overline{\bZeta\boldsymbol{\rho}_\ell}^{i,.}(v) \bPE_{n-1}(v-w)\bM(w) dv dw=	
	\E\left[(\boldsymbol{Z}^{\boldsymbol{\bZeta\rho}_\ell}_T)^i\right] $$
	and the second term sums as, denoting $\boldsymbol{Z^{\bZeta \rho_\ell}}$ a $(\bZeta \boldsymbol{\rho}_\ell,\bM,\bP)-$MSPD
{\small	\begin{align*}
	&\hspace*{-0.6cm}\sum_{n=1}^{+\infty}\sum_{j=1}^{n-1}\int_{0}^{T}\int_{t_j}^T\bZetaE^{i,.}(T-t_n)\int_{t_j}^{t_{n}}\bPE_{n-j-1}(t_n-t_{j+1})\overline{\bP\boldsymbol{\rho}_\ell}(t_{j+1}-t_{j})
		\int_{0}^{t_{j}}\bPE_{j-1}(t_j-t_{1})\bM(t_1)dt_{1}dt_{j+1}dt_ndt_{j}\\
		&\hspace*{-0.6cm}=\sum_{j=1}^{+\infty}\sum_{n=j+1}^{+\infty}\int_{0}^{T}\int_{t_j}^T\bZetaE^{i,.}(T-t_n)\int_{t_j}^{t_{n}}\bPE_{n-j-1}(t_n-t_{j+1})\overline{\bP\boldsymbol{\rho}_\ell}(t_{j+1}-t_{j})
		\int_{0}^{t_{j}}\bPE_{j-1}(t_j-t_{1})\bM(t_1)dt_{1}dt_{j+1}dt_ndt_{j}\\
		&\hspace*{-0.6cm} =\int_{0}^{T} \hspace*{-2mm}  \int_{t_j}^T \hspace*{-2mm}  \bZetaE^{i,.}(T-t_n)\int_{t_j}^{t_{n}}\hspace*{-3mm}  \left(\bPs(t_n-t_{j+1}) + \bPE_{0}(t_n-t_{j+1}) \right)\overline{\bP\boldsymbol{\rho}_\ell}(t_{j+1},t_{j})
		\int_{0}^{t_j} \hspace*{-2mm} \left(\bPs(t_j-t_{1}) + \bPE_{0}(t_j-t_{1}) \right)\bM(t_1)dt_{1}dt_{j+1}dt_ndt_{j}\\
		&\hspace*{-0.6cm} =\int_{0}^T \hspace*{-2mm} \bZetaE^{i,.}(T-t_n)\int_{0}^{t_{n}}\hspace*{-2mm} \left(\bPs(t_n-t_{j+1}) + \bPE_{0}(t_n-t_{j+1}) \right)
		\int_{0}^{t_{j+1}}\hspace*{-4mm} \overline{\bP\boldsymbol{\rho}_\ell}(t_{j+1}-t_{j})\left(\int_{0}^{t_j}\bPs(t_j-t_{1})\bM(t_1)dt_1 + \bM(t_j) \right)dt_{j}dt_{j+1}dt_n\\
		&\hspace*{-0.6cm} =\int_{0}^T\bZetaE^{i,.}(T-t_n)\int_{0}^{t_{n}}\hspace*{-2mm}\left(\bPs(t_n-t_{j+1}) + \bPE_{0}(t_n-t_{j+1}) \right)\E[\boldsymbol{Z_{t_{j+1}}^{\bP\rho_\ell}}]dt_{j+1}dt_n\\
		&\hspace*{-0.6cm}=\int_{0}^T\bZetaE^{i,.}(T-v)\left(\E[\boldsymbol{Z_{v}^{\bP\rho_\ell}}] + \int_{0}^{v}\bPs(v-w)\E[\boldsymbol{Z_{w}^{\bP\rho_\ell}}]dw\right)dv
	\end{align*}
	}
which concludes the proof.	
\end{proof}

