In order to give an example that illustrates a concrete application of the previous result, we will consider the following univariate model : let $\bZeta(t,y) = 1$, $\bP(t,y)= \alpha e^{-\beta t}\ind{y>B}$ and $\bM(t)=\mu$. As metioned in the introduction, self-exciting models are now well used in many fields. With the given kernels $(\bZeta,\bP)$ et base line intensity ($\bM$), the resulting process will trigger his self-exciting feature only if the random variable $Y$ is large enough (above the barrier $B$). Hence, let $H$ the univariate $(\bZeta,\bM,\bP)-$MSPD given by, 
\begin{equation*}
	\left\lbrace
	\begin{array}{l}
		H_T := \int_{\bX_T}\ind{\theta \leq \lambda_t} \bN(dk,dt,d\theta,dy) \\ \hspace{12cm} T\geq 0 \\
		\lambda_T:= \mu + \int_{\bX_T}\alpha e^{-\beta (T-t)}\ind{y>B} \ind{\theta \leq \lambda_t} \bN(dk,dt,d\theta,dy). \\
	\end{array}
	\right. 
\end{equation*}
Hence by noting $P_B:=\P(Y>B)$ we have that, 

$$
\bPE(t) = \alpha P_B e^{-\beta t} \; ,\; \bPs(t)=\alpha P_B e^{(\alpha P_B  - \beta)t} \; \text{and that} \; \mathfrak{B}= \frac{1}{P_B}.
$$
Moreover, 
$$
\int_u^T \alpha P_B e^{(\alpha P_B  - \beta)t}dt = \frac{\alpha P_B}{(\alpha P_B  - \beta)} \left(e^{(\alpha P_B  - \beta)T} - e^{(\alpha P_B  - \beta)u} \right),
$$
and by  Proposition \ref{prop:cov_sep}(la bleu avec la factorisation full),
\begin{align*}
	&Cov\left(H_T, H_S\right)=\int_{0}^T\left(1 + \frac{1}{P_B}\int_{0}^{T-u}\bPs(v)dv\right)\left(P_B +\int_{0}^{S-u}\bPs(v)dv\right)\left(\int_{0}^{u}\bPs(v)dv + 1 \right)\mu du\\
	&= \int_0^T\bigg( P_B +\frac{\alpha P_B}{(\alpha P_B  - \beta)} \left(e^{(\alpha P_B  - \beta)(S-u)} + e^{(\alpha P_B  - \beta)(T-u)} - 2 \right)\\
	& \hspace{-1.7cm}+ \frac{\alpha^2 P_B^2}{(\alpha P_B  - \beta)^2} \left(e^{(\alpha P_B  - \beta)(T+S-2u)} - e^{(\alpha P_B  - \beta)(T-u)} - e^{(\alpha P_B  - \beta)(S-u)}+1 \right) \bigg)\left(\frac{\alpha P_B}{(\alpha P_B  - \beta)} \left(e^{(\alpha P_B  - \beta)u} - 1 \right) +1 \right)du\\
	&\hspace{-2cm}= \int_0^T\bigg( \frac{\alpha P_B^2}{(\alpha P_B  - \beta)} \left(e^{(\alpha P_B  - \beta)u} - 1 \right)  +\frac{\alpha^2 P^2_B}{(\alpha P_B  - \beta)^2} \big( e^{(\alpha P_B  - \beta)S}\left(1 - e^{(\beta-\alpha P_B)u}\right) + e^{(\alpha P_B  - \beta)T}\left(1 - e^{(\beta-\alpha P_B)u}\right)\\
	&- 2e^{(\alpha P_B -\beta)u}+2\big)\\
	& \hspace{-1.7cm}+ \frac{\alpha^3 P_B^3}{(\alpha P_B  - \beta)^3} \left(e^{(\alpha P_B  - \beta)(T+S-2u)} - e^{(\alpha P_B  - \beta)(T-u)} - e^{(\alpha P_B  - \beta)(S-u)}+1 \right) \bigg) du\\
\end{align*}

