\title[BPS polynomials and Welschinger invariants]{BPS polynomials and Welschinger invariants}


\author[H.\,Arg\"uz]{H\"ulya Arg\"uz}
\address{University of Georgia, Department of Mathematics, Athens, GA 30605}
\email{Hulya.Arguz@uga.edu}

\author[P.\,Bousseau]{Pierrick Bousseau}
