We will later make use of the following elementary result on floor diagrams in the proof of Theorem \ref{thm_floor_gw}:

\begin{lemma} \label{lem_floor}
A floor diagram $\Gamma$ of degree $d$ satisfies
$|V_2(\Gamma)|+2|V_4(\Gamma)|=d$.
\end{lemma}

\begin{proof}
We evaluate $\sum_{v\in V(\Gamma)} \mathrm{div}(v)$ in two different ways. Since $V(\Gamma)=V_2(\Gamma)\amalg V_4(\Gamma)$, we obtain $\sum_{v\in V(\Gamma)} \mathrm{div}(v)=2|V_2(\Gamma)|+4|V_4(\Gamma)|$. On the other hand, expressing $\mathrm{div}(v)$ as a difference of weights, all terms cancel except the contributions of the legs. 
This yields $\sum_{v\in V(\Gamma)} \mathrm{div}(v)= \sum_{l \in L(\Gamma)} w_l$. 
By Definition \ref{Def:floor diagram}iii), this sum equates $2d$, competing the proof.
\end{proof}


Recall that we denote by $\widetilde{S}_n$ the blow-up of $\PP^2$ along $n$ distinct points on a conic $\mathfrak{C}$, and by $\widetilde{\mathfrak{C}}$ the strict transform of $\mathfrak{C}$. 
We let $E_1, \ldots E_n$ denote the exceptional curves, and $H$ the pull-back in $\widetilde{S}_n$ of the class of a line in $\PP^2$.

\begin{definition}
\label{def: marking on floor}
Let $\beta \in H_2(\widetilde{S}_n,\ZZ)$ such that $H \cdot \beta \geq 1$, and $\mu$, $\nu$ as in \eqref{eq_mu_nu}.
A \emph{marking of class $\beta$ and type $(\mu,\nu)$} of a floor diagram $\Gamma$ of genus $g_0$ and degree $d=H \cdot \beta$, is given by the following data:
\begin{itemize}
    \item[i)] A decomposition of the set of legs
    \[ L(\Gamma) = L_\mu \amalg L_\nu \amalg A_1 \amalg \ldots \amalg A_n \,,  \]
    where $L_\mu$ (resp.\ $L_\nu$) is a set of $\ell(\mu)$ (resp.\ $\ell(\nu)$) legs with weights $(\mu_i)_{1\leq i \leq \ell(\mu)}$
    (resp.\ $(\nu_i)_{1\leq i \leq \ell(\nu)}$), and for any $1\leq j \leq n$,  $A_j$ is a set of $\beta \cdot E_j$ legs of weight $1$, which are adjacent to distinct vertices of $\Gamma$.
 \item[ii)] A bijection 
 \begin{equation}
   \label{eq:phi}
   \phi:  \{ 1,\ldots m_{\beta,(\mu,\nu)} \} \xrightarrow{\sim }  V_4(\Gamma) \cup E(\Gamma) \cup L_\nu,
 \end{equation}
 where $m_{\beta,(\mu,\nu)}:=H \cdot \beta -1 +\ell(\nu)$, which is \emph{increasing}, that is,
 \[  \phi(i) > \phi(j) \implies i>j \, \]
with respect to the partial ordering on $V_4(\Gamma) \cup E(\Gamma) \cup L_\nu$, as described at the beginning of \S\ref{subsec: marked floor}.
\end{itemize}
A \emph{marked floor diagram} is a floor diagram equipped with a marking.
\end{definition}


To emphasize the decomposition of the legs in Definition \ref{def: marking on floor}, when drawing a floor diagram $\Gamma$ with $\mu=\emptyset$, we plot the legs in $L_{\nu}$ with black, and the ones in $A_1 \amalg \ldots \amalg A_n$ in red. 
The images of the numbers ${1,\ldots, m_{\beta,(\mu,\nu)}}$ under the bijection $\phi$ in Definition \ref{def: marking on floor} are displayed in red, to distinguish them from the weights on the edges. 

\begin{definition}
\label{def: marked floor isomorphic}
    Two marked floor diagram are \emph{isomorphic} if there exists an isomorphism between the underlying weighted oriented graphs, which preserves the decompositions of the sets of legs and commutes with the increasing bijections.
\end{definition}

\begin{example}
\label{Ex: d=2 simple}
In the floor diagrams illustrated in Figure \ref{Fig2}, there is a unique marking 
up to isomorphism. On both figures, there is 
up to isomorphism  a unique decompposition of the legs, 
\[ L(\Gamma) = L_{(1,1)} \amalg A_1 \amalg \ldots A_6 \,,  \]
where each of the $6$ red legs corresponds to an element in $A_i$, for $1\leq i \leq 6$. We have $m_{\beta,(\mu,\nu)}=4-1+1+1=5$, and the increasing bijection $\phi: \{ 1,\ldots, 5 \} \to V_4(\Gamma) \cup E(\Gamma) \cup L_\nu$ is also uniquely determined, up to isomorphism.


