\subsubsection{Lines tangent to the conic}
\label{sec_line_tangent}

In this section, we compute another particular case of the relative Gromov--Witten invariants $GW_{g,\beta,(\mu,\nu)}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}$ defined in \eqref{def: gw}. 
We assume that $n=0$, that is $\widetilde{S}_n=\PP^2$ and $\widetilde{\mathfrak{C}}=\mathfrak{C}$. Moreover, we assume that $\beta=H$, $\mu=(2)$ and $\nu=\emptyset$, that is, we are considering stable maps to $
\PP^2$ whose image in is the line tangent at a given point to the conic $\mathfrak{C}$. 
In this case, there no marked point with contact order zero since 
$m_{\beta,(\mu,\nu)}=H \cdot \beta -1+\ell(\nu)=1-1+0=0$.
The corresponding relative Gromov--Witten invariants $GW_{g,H, ((2),\emptyset)}^{\PP^2/\mathfrak{C}}$ are calculated by the result below.

\begin{lemma}
\label{lem_gw_2}
We have 
\[ \sum_{g \geq 0} GW_{g,H, ((2),\emptyset)}^{\PP^2/\mathfrak{C}} u^{2g-1} 
=u^{-1}\cos \left( \frac{u}{2}\right) =u^{-1} \frac{1}{2}(q^{\frac{1}{2}}+q^{-\frac{1}{2}})=u^{-1}\frac{[2]_q}{2}\,,\]
where $q=e^{iu}$ and 
\[[2]_q :=
\frac{q^{\frac{2}{2}}-q^{-\frac{2}{2}}}{q^{\frac{1}{2}}-q^{-\frac{1}{2}}}
=q^{\frac{1}{2}}+q^{-\frac{1}{2}}\] 
is the $q$-integer version of $2$ -- see \eqref{eq_q_integer}. In particular, we have $BPS_{H, ((2),\emptyset)}^{\PP^2/\mathfrak{C}}(q)=1$.
\end{lemma}

\begin{proof}
Let $GW_{g,H}^{\PP^2,\psi}$ be the $1$-pointed genus $g$ Gromov--Witten invariant of $\PP^2$ of class $H$, with insertion of $(-1)^g \lambda_g$, a point constraint and a psi-class. Arguing as in the proof of Theorem \ref{thm_absolute_relative}, we obtain that 
$GW_{g,H}^{\PP^2,\psi}$ equals the corresponding log Gromov--Witten invariant of $\PP^2$ endowed with its toric boundary.
Hence, it follows from \cite[Theorem A]{refined_descendants} that
\begin{equation} \label{eq_gw_2}
\sum_{g \geq 0} GW_{g,H}^{\PP^2,\psi}u^{2g} = \cos\left( \frac{u}{2}\right)=\frac{1}{2}(q^{\frac{1}{2}}+q^{-\frac{1}{2}})\,.\end{equation}
On the other hand, we obtain a different expression for $GW_{g,H}^{\PP^2, \psi}$ using the degeneration of $\PP^2$ to the normal cone of the conic $\mathfrak{C}$, with central fiber $\PP^2 \cup \mathbb{F}_4$. 
By degenerating the point insertion to a point in $\mathbb{F}_4$, the degeneration formula in relative Gromov--Witten theory \cite{li2002degeneration}
implies that 
\begin{equation}\label{eq_gw_2_2}
\sum_{g \geq 0} GW_{g,H}^{\PP^2, \psi} u^{2g-2}=  2\left(\sum_{g \geq 0} GW_{g,H, ((2),\emptyset)}^{\PP^2/\mathfrak{C}} u^{2g-1} \right) 
\left( \sum_{g\geq 0} GW_{g,2F}^{\mathbb{F}_4/\mathfrak{C}_{-4}, \psi} u^{2g-1}\right)\,.\end{equation}
Here, $GW_{g,2F}^{\mathbb{F}_4/\mathfrak{C}_{-4},\psi}$ is the $1$-pointed genus $g$ Gromov--Witten invariant of $\mathbb{F}_4$ of class $2F$, relative to $\mathfrak{C}_{-4}$ at one point of contact order $2$, and with insertion of $(-1)^g \lambda_g$, a point constraint and a psi class, see Figure \ref{Fig5}. 
As in \cite[Lemma 14]{Bou2019}, the Mumford's relation $\lambda_g^2=0$ when $g>0$ implies that $GW_{g,2F}^{\mathbb{F}_4/\mathfrak{C}_{-4},\psi}=0$ when $g>0$.
On the other hand, taking the coefficient of $u^{-2}$ in \eqref{eq_gw_2_2}, we obtain
\[ GW_{0,H}^{\PP^2, \psi} = 2 \,GW_{0,H, ((2),\emptyset)}^{\PP^2/\mathfrak{C}}\,  GW_{0,2F}^{\mathbb{F}_4/\mathfrak{C}_{-4}, \psi}\,. \]
Since there is a unique line passing though a given point with given tangent line, we have $GW_{0,H}^{\PP^2, \psi}=1$. Moreover, since there is a unique line tangent to a given conic at a given point, we also have $GW_{0,H, ((2),\emptyset)}^{\PP^2/\mathfrak{C}}=1$. 
Consequently, we have $GW_{0,2F}^{\mathbb{F}_4/\mathfrak{C}_{-4}, \psi}=\frac{1}{2}$, and so Equation \eqref{eq_gw_2_2} can be rewritten as
\[\sum_{g \geq 0} GW_{g,H}^{\PP^2, \psi} u^{2g-2}=  \sum_{g \geq 0} GW_{g,H, ((2),\emptyset)}^{\PP^2/\mathfrak{C}} u^{2g-2} \,.\]
Therefore, Lemma \ref{lem_gw_2} follows from Equation \eqref{eq_gw_2}.
\end{proof}


