\subsubsection{Relative BPS polynomials from refined counts of floor diagrams}
\label{subsec_relative_floor}

In this section, we prove that the relative Gromov--Witten invariants $GW_{g,\beta, (\mu,\nu)}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}$ and the 
corresponding BPS polynomials $BPS_{\beta, (\mu,\nu)}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}(q)$ defined \S\ref{sec:relative_bps} can be computed in terms of marked floor diagrams as in Definition \ref{def: marking on floor}, counted with refined multiplicities defined as follows.
Recall that every nonnegative integer $N$, we denote by $[N]_q$ the corresponding $q$-integer defined by \eqref{eq_q_integer}.


\begin{definition} \label{def_q_mult}
The \emph{refined multiplicity} of a marked floor diagram $\Gamma$ of type $(\mu,\nu)$ is
\[ m_\Gamma(q):= 
\left( \prod_{j=1}^{\ell(\nu)} \nu_j\right) 
\prod_{e\in E(\Gamma)} [w_e]_q^2 \in \ZZ[q^\pm]\,.\]
\end{definition}

\begin{remark}
    In the limit $q \rightarrow 1$, the refined multiplicity of a marked floor diagram reduces to the multiplicity $\prod_{j=1}^{\ell(\nu)} \nu_j\prod_{e\in E(\Gamma)} w_e^2$ considered in \cite[Definition 3.5]{BrugFloorconic}
\end{remark}

\begin{definition} \label{def_count_floor}
The \emph{refined count with multiplicity} of marked floor diagrams of genus zero, class $\beta$, and type $(\mu,\nu)$
\[ N_{\beta, (\mu,\nu)}^{\mathrm{floor}}(q)=\sum_\Gamma m_\Gamma(q) \in \ZZ[q^\pm]\]
where the sum is over the isomorphism classes of marked floor diagrams of class $\beta$ and type $(\mu,\nu)$.
\end{definition}


\begin{theorem}\label{thm_floor_gw}
Let $\beta \in H_2(\widetilde{S}_n,\ZZ)$ such that $H \cdot \beta \geq 1$, and $\mu$, $\nu$ as in \eqref{eq_mu_nu}. Then, the relative Gromov--Witten invariants $GW_{g,\beta, (\mu,\nu)}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}$ satisfy
\begin{align*}
&\sum_{g \geq 0}GW_{g,\beta, (\mu,\nu)}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}} u^{2g-2+H \cdot \beta+\ell(\mu)+\ell(\nu)} \\
&= 
\left(\prod_{j=1}^{\ell(\mu)} \frac{[\mu_j]_q}{\mu_j} \right) 
\left(\prod_{j=1}^{\ell(\nu)} \frac{[\nu_j]_q}{\nu_j} \right)
((-i)(q^{\frac{1}{2}}-q^{-\frac{1}{2}}))^{-2+H\cdot \beta+\ell(\mu)+\ell(\nu)} N_{\beta, (\mu,\nu)}^{\mathrm{floor}}(q) \,,
\end{align*}
where $q=e^{iu}$ and $N_{\beta, (\mu,\nu)}^{\mathrm{floor}}(q)$ is the refine
count with multiplicity of marked floor diagrams 
of genus zero, class $\beta$, and type $(\mu,\nu)$.
\end{theorem}

\begin{proof}
We calculate the relative Gromov--Witten invariants
$GW_{g,\beta, (\mu,\nu)}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}$ using the degeneration
$\widetilde{\epsilon}: \widetilde{\mathcal{F}} \rightarrow \CC$ constructed in 
\S\ref{subsub: a degeneration}, with central fiber $\widetilde{\epsilon}^{-1}(0)=\PP^2 \cup \mathbb{F}_4^{(m)} \cup \cdots \cup \mathbb{F}_4^{(1)} \cup \mathrm{Bl}_n \mathbb{F}_4$.
To do this, we apply the general degeneration formalism in log Gromov--Witten theory. We endow $\CC$ with the divisorial log structure defined by the divisor $\{0\}\subset \CC$, and $\widetilde{\mathcal{F}} \rightarrow \CC$ with the divisorial log structure defined by the normal crossing divisor $\overline{\widetilde{\mathfrak{C}}\times \CC^\star} \cup \widetilde{\epsilon}^{-1}(0)$, where 
$\overline{\widetilde{\mathfrak{C}}\times \CC^\star}$ denote the closure of $\widetilde{\mathfrak{C}}\times \CC^\star$ in $\widetilde{\mathcal{F}}$. Then, $\widetilde{\epsilon}: \widetilde{\mathcal{F}} \rightarrow \CC$ is a log smooth morphism. 

By the decomposition formula of \cite{ACGS_decomposition}, the relative Gromov--Witten invariants $GW_{g,\beta}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}(\mu,\nu)$ can be expressed as a sum
of $h$-marked log Gromov--Witten invariants of the central fiber $\widetilde{\epsilon}^{-1}(0)$ endowed with the restricted log structure, where $h$ are rigid tropical maps to the tropicalization of $\widetilde{\epsilon}^{-1}(0)$. Using the vanishing properties of lambda class, we show as in \cite[\S 5.3]{bousseau_floor} that the only contributing rigid tropical maps are in natural one-to-one correspondence with the marked floor diagrams $\Gamma$ of genus zero, class $\beta$, and type $(\mu,\nu)$. The contribution of each floor diagrams can then be decomposed as a product of vertex and edge contributions as in \cite[\S 5.3]{bousseau_floor}. We refer to \S \ref{subsec: marked floor} for the notation $V(\Gamma)=V_2(\Gamma)\amalg V_4(\Gamma)$, $V_2(\Gamma)=V_2^{(2)}(\Gamma) \amalg V_2^{(1,1)}(\Gamma)$, $E(\Gamma)$, and $L(\Gamma) = L_\mu \amalg L_\nu \amalg A_1 \amalg \ldots \amalg A_n$ describing the sets of vertices, edges, and legs of a marked floor diagram $\Gamma$.

Explicitly, the contribution of a marked floor diagram $\Gamma$ to the generating series 
\[\sum_{g \geq 0}GW_{g,\beta, (\mu,\nu)}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}} u^{2g-2+\beta \cdot \widetilde{\mathfrak{C}}}\] 
is the product of the following factors:
\begin{itemize}
    \item[i)] A factor $w_e^2$ for each edge $e \in E(\Gamma)$.
    \item[ii)] A factor $w_l$ for each leg $l \in L_\nu$.
    \item[iii)] By Lemma \ref{lem_gw_11}, a factor \[\sum_{g \geq 0} GW_{g,H, ((1,1),\emptyset)}^{\PP^2/\mathfrak{C}} u^{2g}=u^{-1 }2 \sin \left( \frac{u}{2}\right) =u^{-1} (-i)(q^{\frac{1}{2}}-q^{-\frac{1}{2}}),\] for each vertex $v \in V_2^{(1,1)}(\Gamma)$.
    \item[iv)] By Lemma \ref{lem_gw_2}, a factor
    \[ \sum_{g \geq 0} GW_{g,H, ((2),\emptyset)}^{\PP^2/\mathfrak{C}} u^{2g-1}=u^{-1}\cos \left( \frac{u}{2}\right) =u^{-1} \frac{1}{2}(q^{\frac{1}{2}}+q^{-\frac{1}{2}})=u^{-1}\frac{[2]_q}{2}\,\] 
    for each vertex $v\in V_2^{(2)}(\Gamma)$
\end{itemize}

\begin{itemize}
\item[v)] A factor \[ \sum_{g \geq 0} GW_{g, \mathfrak{C}_{4}+|m_v|F, (m_v, n_v)}^{\mathbb{F}_4/\mathfrak{C}_{-4}\cup \mathfrak{C}_4} u^{2g-2+\ell(m_v)+\ell(n_v)}\] for each vertex $v \in V_4(\Gamma)$, where
$m_v=(m_{v,j})_{1\leq j \leq \ell(m_v)}$ is the partition formed by the edge weights adjacent to $v$ oriented away from $v$, $|m_v|=\sum_{j=1}^{\ell(m_v)} m_{v,j}$, and
$n_v=(n_{v,j})_{1\leq j \leq \ell(n_v)}$ is the partition formed by the edge or leg weights adjacent to $v$ oriented towards $v$. 
Moreover,
\[ GW_{g, \mathfrak{C}_{4}+|m_v|F, (m_v, n_v)}^{\mathbb{F}_4/\mathfrak{C}_{-4}\cup \mathfrak{C}_4}\]
is the genus $g$ Gromov--Witten invariant of $\mathbb{F}_4$, relative to $\mathfrak{C}_{-4}\cup \mathfrak{C}_4$, of class $\mathfrak{C}_{4}+|m_v|F$, with the following insertions -- see Figure \ref{Fig10}: $(-1)^g \lambda_g$, one point constraint in $\mathbb{F}_4$ away from
$\mathfrak{C}_{-4}\cup \mathfrak{C}_4$, $\ell(m_v)$ point constraints at marked points with contact orders $(m_v)_{1\leq l \leq\ell(m_v)}$ along $\mathfrak{C}_{-4}$, and $\ell(n_v)$ point constraints at marked points with contact orders $(n_v)_{1\leq l \leq\ell(n_v)}$ along $\mathfrak{C}_{4}$.
By \cite[Theorem 4.4]{bousseau_floor}, this factor equals 
\[ u^{-2} \left((-i)(q^{\frac{1}{2}}-q^{-\frac{1}{2}})\right)^{\ell(m_v)+\ell(n_v)} \prod_{j=1}^{\ell(m_v)} \frac{[m_{v,j}]_q}{m_{v,j}} \prod_{j=1}^{\ell(n_v)} \frac{[n_{v,j}]_q}{n_{v,j}} \,.\]
\item[vi)] By \cite[Lemma 6.3]{BP_local_curves}, a factor 
\[\frac{1}{2 \sin \left(\frac{u}{2}\right)}=((-i)(q^{\frac{1}{2}}-q^{-\frac{1}{2}}))^{-1}\] 
for each leg $l \in \amalg_{i=1}^n A_i$ corresponding to maps to the $(-1)$-curve in $\mathrm{Bl}_n(\mathbb{F}_4)$ intersecting the exceptional curve $E_i$.
\end{itemize} 


Consequently, the contribution of the marked floor diagram $\Gamma$ is given by
\[ \left( \prod_{e\in E(\Gamma)} w_e^2 \prod_{l \in L_\nu}w_l\right)
u^{-|V_2(\Gamma)|-2|V_4(\Gamma)|} 
((-i)(q^{\frac{1}{2}}-q^{-\frac{1}{2}}))^{|V_2^{(1,1)}(\Gamma)|+\sum_{v\in V_4(\Gamma)}(\ell(m_v)+\ell(n_v)) -\sum_{i=1}^n|A_i|} \]
\[ \times \left(\frac{[2]_q}{2}\right)^{|V_2^{(2)}(\Gamma)|}
\prod_{j=1}^{\ell(m_v)} \frac{[m_{v,j}]_q}{m_{v,j}} \prod_{j=1}^{\ell(n_v)} \frac{[n_{v,j}]_q}{n_{v,j}} \,.\]
Every edge $e$ of $\Gamma$ with weight $w_e\neq 1$ is adjacent to either two vertices in $V_4(\Gamma)$ or to one vertex in $V_4(\Gamma)$ and one vertex in $V_2^{(2)}(\Gamma)$. Similarly, every leg $l$ of $\Gamma$ with $w_l \neq 1$ is adjacent to either a vertex $v \in V_4(\Gamma)$ or to a vertex $v\in V_2^{(2)}(\Gamma)$. 
Thus, we obtain
\begin{align*}
   & \left( \prod_{e\in E(\Gamma)} w_e^2 \prod_{l \in L_\nu}w_l\right)\left(\frac{[2]_q}{2}\right)^{|V_2^{(2)}(\Gamma)|}
\prod_{j=1}^{\ell(m_v)} \frac{[m_{v,j}]_q}{m_{v,j}} \prod_{j=1}^{\ell(n_v)} \frac{[n_{v,j}]_q}{n_{v,j}}
\\=& \left(\prod_{j=1}^{\ell(\mu)} \frac{[\mu_j]_q}{\mu_j} \right) 
\left(\prod_{j=1}^{\ell(\nu)} [\nu_j]_q \right) \prod_{e\in E(\Gamma)} [w_e]_q^2\\=& m_\Gamma(q) \,.
\end{align*}
By Lemma \ref{lem_floor}, we have $|V_2(\Gamma)|+2|V_4(\Gamma)|=H \cdot \beta$, and so the 
contribution of
$\Gamma$ simplifies to 
\[ u^{-H \cdot \beta}\left(\prod_{j=1}^{\ell(\mu)} \frac{[\mu_j]_q}{\mu_j} \right) 
\left(\prod_{j=1}^{\ell(\nu)} \frac{[\nu_j]_q}{\nu_j} \right)((-i)(q^{\frac{1}{2}}-q^{-\frac{1}{2}}))^{|V_2^{(1,1)}(\Gamma)|+\sum_{v\in V_4(\Gamma)}(\ell(m_v)+\ell(n_v)) -\sum_{i=1}^n|A_i|} m_\Gamma(q)\,,\]
where we used the Definition \ref{def_q_mult} of $m_\Gamma(q)$.

Therefore, to prove Theorem \ref{thm_floor_gw}, it remains only to show that 
\begin{equation}\label{eq_combinatorics}
|V_2^{(1,1)}(\Gamma)|+\sum_{v\in V_4(\Gamma)}(\ell(m_v)+\ell(n_v)) -\sum_{i=1}^n|A_i|= -2+H \cdot \beta +\ell(\mu)+\ell(\nu)\,.
\end{equation}
We first observe that $\sum_{v\in V_4(\Gamma)}(\ell(m_v)+\ell(n_v))$ equals the total number of half-edges or legs adjacent to vertices in $V_4(\Gamma)$, that is, all half-edges of legs except the ones adjacent to vertices in $V_2(\Gamma)$. Hence, we have 
\[ \sum_{v\in V_4(\Gamma)}(\ell(m_v)+\ell(n_v)) = 2|E(\Gamma)|+|L(\Gamma)|-2 |V_2^{(1,1)}(\Gamma)|-|V_2^{(2)}(\Gamma)|\,.\]
Thus, we have 
\begin{align*}
   & |V_2^{(1,1)}(\Gamma)|+\sum_{v\in V_4(\Gamma)}(\ell(m_v)+\ell(n_v)) -\sum_{i=1}^n|A_i| \\
   & = 2|E(\Gamma)|+|L(\Gamma)|-|V_2^{(1,1)}(\Gamma)|-|V_2^{(2)}(\Gamma)|-\sum_{i=1}^n|A_i|
    \\&=2|E(\Gamma)|
+|L(\Gamma)|-|V_2(\Gamma)|-\sum_{i=1}^n|A_i|\,.
\end{align*}
Since the graph $\Gamma$ is of genus zero, we have $|E(\Gamma)|=|V(\Gamma)|-1$, so we obtain
\[|V_2^{(1,1)}(\Gamma)|+\sum_{v\in V_4(\Gamma)}(\ell(m_v)+\ell(n_v))-\sum_{i=1}^n|A_i|=2|V(\Gamma)|-2+|L(\Gamma)|-|V_2(\Gamma)|-\sum_{i=1}^n|A_i|\,.\]
Using that  $|V(\Gamma)|=|V_2(\Gamma)|+|V_4(\Gamma)|$, 
$|L(\Gamma)|-\sum_{i=1}^n|A_i|=\ell(\mu)+\ell(\nu)$, and $|V_2(\Gamma)|+2|V_4(\Gamma)|=H \cdot \beta$ by Lemma \ref{lem_floor}, we finally
obtain Equation \eqref{eq_combinatorics}, and this concludes the proof of Theorem \ref{thm_floor_gw}.
\end{proof}


