\begin{corollary} \label{cor_bps_floor}
    Let $\beta \in H_2(\widetilde{S}_n,\ZZ)$ such that $H \cdot \beta \geq 1$, and $\mu$, $\nu$ as in \eqref{eq_mu_nu}.  Then, the relative BPS polynomial $BPS_{\beta,(\mu,\nu)}^{\widetilde{S}_n/\mathfrak{C}}(q)$ 
    is equal to the refined count with multiplicity $N_{\beta, (\mu,\nu)}^{\mathrm{floor}}(q)$ of marked floor diagrams:
\[ BPS_{\beta}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}(q) =N_{\beta, (\mu,\nu)}^{\mathrm{floor}}(q) \,. \]
In particular, $BPS_{g,\beta}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}(q)$ is a Laurent polynomial with integer coefficients:
\[ BPS_{g,\beta}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}(q) \in \ZZ[q^\pm] \,.\]
\end{corollary}

\begin{proof}
The result follows from comparing Theorem \ref{thm_floor_gw} with Definitions \ref{def_relative_bps_inv}-\ref{def_relative_BPS}, which define the relative BPS invariants and relative BPS polynomials.
\end{proof}

\subsection{Relative BPS polynomials and relative Welschinger counts}
\label{sec_relative_bps_w}

In this section, we first define relative Welschinger counts of real rational curves in $(\widetilde{S}_n, \widetilde{\mathfrak{C}})$. 
Then, we prove in Theorem \ref{thm: relative_BPS_W} that the specialization at $q=-1$ of the relative BPS polynomials of $(\widetilde{S}_n,\widetilde{\mathfrak{C}})$ can be expressed in terms of these relative Welschinger counts.

\subsubsection{Relative Welschinger counts}
\label{subsec:relative Welschinger counts}
In this section, we equip $\PP^2$ with its standard real structure whose real locus is $\RR\PP^2$, and we fix $\mathfrak{C}$ a smooth real conic in $\PP^2$ with non-empty real locus.
We denote by $\widetilde{S}_n$ the real surface obtained by blowing up $\PP^2$ at $n$ general real points of $\mathfrak{C}$, and we denote by 
$\widetilde{\mathfrak{C}}$ the strict transform of $\mathfrak{C}$ in $\widetilde{S}_n$.

\begin{definition}
\label{def: real points}
Let $\beta \in H_2(\widetilde{S}_n,\ZZ)$ such that $H \cdot \beta \geq 1$, and $\mu$, $\nu$ as in \eqref{eq_mu_nu}. 
A \emph{configuration of real points} of type $(\beta,\mu,\nu)$ is given by a disjoint union 
\[   \mathbf{x} =  \mathbf{x}^0 \amalg  \mathbf{x}^{\widetilde{\mathfrak{C}}} \,,\]
where $ \mathbf{x}^0=(x_1^0,\ldots, x^0_{m_{\beta,(\mu,\nu)}})$ is a set of $m_{\beta,(\mu,\nu)}:=H \cdot \beta -1+\ell(\nu)$ real points in $\widetilde{S}_n \setminus \widetilde{\mathfrak{C}}$, and $\mathbf{x}^{\widetilde{\mathfrak{C}}} = (x_1^{\widetilde{\mathfrak{C}}},\ldots, x_{\ell(\nu)}^{\widetilde{\mathfrak{C}}} )$ is a set of $\ell(\mu)$ real points on $\widetilde{\mathfrak{C}}$.
\end{definition}

Given a configuration of real points $\mathbf{x}$ of type $(\beta,\mu,\nu)$, we consider the set $M^{\RR}_{0,\beta}(\widetilde{S}_n/\widetilde{\mathfrak{C}}, \mu,\nu,\mathbf{x})$ of real genus zero stable maps 
\begin{equation}
\label{eq: f}
f: (C,(p_i^0)_{1\leq i \leq m_{\beta,(\mu,\nu)}} , (p_j^{\widetilde{\mathfrak{C}}})_{1\leq j \leq \ell(\mu)} , (p_k)_{1\leq k \leq \ell(\nu)} ) \to \widetilde{S}_n  \,,    
\end{equation}
of class $\beta$ satisfying the following:
\begin{itemize}
    \item[1)] $f(p_i^0)  = x_i^0$
\item[2)] $f(p_j^{\widetilde{\mathfrak{C}}})  = x_j^{\widetilde{\mathfrak{C}}} ~ \text{and the contact order of} ~ f(p_j^{\widetilde{\mathfrak{C}}}) ~ \text{with} ~ \widetilde{\mathfrak{C}} ~ \text{is} ~ \mu_j,$
\item[3)] $f(p_k)$ has contact order $\nu_k$ with $\widetilde{\mathfrak{C}}$,
\item[4)] $\widetilde{\mathfrak{C}}$ is not a component of $f(C)$: In particular, $f(C)$ intersects $\widetilde{\mathfrak{C}}$ only at the union of points $f(p_j^{\widetilde{\mathfrak{C}}})$ for $1\leq j \leq \ell(\mu)$ and $f(p_k)$ for $1\leq k \leq \ell(\nu)$.
\end{itemize}
If $\mathbf{x}$ is a generic configuration of real points of type $(\beta,\mu,\nu)$, then, by \cite[Proposition 2.1]{SS}, then the domain curve $C$ of such a stable map is smooth and irreducible, hence $C \cong \PP^1$. Moreover, $f$ is an immersion, birational onto its image, $f(C)$ intersects $\widetilde{\mathfrak{C}}$ only at non-singular points, and the set $M^{\RR}_{0,\beta}(\widetilde{S}_n/\widetilde{\mathfrak{C}}, \mu,\nu,\mathbf{x})$ is finite. Hence, as in \cite[\S2.3]{BrugFloorconic}, we can define a relative Welschinger count
$W_{\beta, (\mu,\nu), \mathbf{x}}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}$
by 
\[W_{\beta,(\mu,\nu),\mathbf{x}}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}} 
= \sum_{f \in M^{\RR}_{0,\beta}(\widetilde{S}_n/\widetilde{\mathfrak{C}}, \mu,\nu,\mathbf{x})} w(f)\,, \]
Here, $w(f) \in \{\pm 1\}$ is the Weslchinger sign
defined as in \cite[\S 3.6]{IKS2} by  
\[w(f)=(-1)^{s(f)}\,,\]
where
\begin{equation}
s(f)= \sum_{z \in \text{Sing(f(C))}}     s(f,z) \,,
\end{equation}
where the sum runs over all points $z$ in the singular locus $\text{Sing}(f(C))$ of $f(C)$, and $s(f,z)$ denotes the number of pairs of imaginary complex conjugate local branches of $f(C)$ at $z$, each pair being counted with the weight equal to the intersection number of the branches.

As noted in \cite[\S 2.3]{BrugFloorconic}, the relative Welschinger counts $W_{\beta, (\mu,\nu), \mathbf{x}}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}$ may vary with the choice of $\mathbf{x}$.



\subsubsection{Relative Welschinger counts from relative BPS polynomials at $q=-1$}

In the following result, we relate the specialization at $q=-1$ of the relative BPS polynomial $BPS_{\beta,(\mu,\nu)}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}(q)$ with the relative Welschinger counts 
$W_{\beta, (\mu,\nu),\mathbf{x}}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}$.
We use the following notation: for every positive integer $k$, we set $[k]_\RR=1$ if $k$ is odd, and $[k]_\RR=2$ if $k$ is even.


\begin{theorem}
\label{thm: relative_BPS_W}
 Let $\beta \in H_2(\widetilde{S}_n,\ZZ)$ such that $H \cdot \beta \geq 1$, and $\mu$, $\nu$ as in \eqref{eq_mu_nu}.  
 There exists a generic configuration of real points $\mathbf{x}$ of type $(\beta,\mu,\nu)$, such that the specialization at $q=-1$ of the relative BPS polynomial $BPS_{\beta,(\mu,\nu)}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}(q)$ and the relative Welschinger counts of $W_{\beta, (\mu,\nu),\mathbf{x}}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}$ of real rational curves passing through $\mathbf{x}$ are related by:
    \[ BPS_{\beta, (\mu,\nu)} ^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}(-1)=
    \left( \prod_{j=1}^{\ell(\nu)} \frac{v_j}{[\nu_j]_\RR}\right)
    W_{\beta, (\mu,\nu), \mathbf{x}}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}} \]
\end{theorem}

\begin{proof}
By \cite[Theorem 3.12]{BrugFloorconic}, there exists a generic configuration of real points $\mathbf{x}$ of type $(\beta,\mu,\nu)$, such that the relative Welschinger counts of $W_{\beta, (\mu,\nu), \mathbf{x}}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}$ is given by 
\[ W_{\beta, (\mu,\nu), \mathbf{x}}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}} = \sum_\Gamma m_{\Gamma,\RR}\,,\]
where the sum is over the marked floor diagrams of genus zero, class $\beta$, and type $(\mu,\nu)$.
The real multiplicity $m_{\Gamma,\RR}$ is determined as described in \cite[Definition 3.10]{BrugFloorconic}. 
Using the notation of \cite[Definition 3.10]{BrugFloorconic}, we only consider the case $(s,\kappa)=(0,0)$, corresponding to purely real constraints and to the standard real structure. This leads to the simple result that
$m_{\Gamma,\RR}=0$ if $\Gamma$ contains an edge of even weight, and $m_{\Gamma,\RR}=\prod_{j=1}^{\ell(\nu)} [\nu_j]_\RR$ else.

On the other hand, by Corollary \ref{cor_bps_floor}, we have $BPS_{\beta, (\mu,\nu)} ^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}(-1)=N_{\beta, (\mu,\nu)}^{\mathrm{floor}}(-1)$. Applying Definition \ref{def_q_mult}, we then deduce 
\[BPS_{\beta, (\mu,\nu)} ^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}(-1)= \sum_\Gamma m_\Gamma(-1) \,,\]
where $m_\Gamma(-1)=\left( \prod_{j=1}^{\ell(\nu)} \nu_j \right) \prod_{e \in E(\Gamma)} [w_e]^2_{q=-1}$.
By \eqref{eq_q_integer}, we have $[w_e]^2_{q=-1}=0$ if $w_e$ is even, and $[w_e]^2_{q=-1}=1$ if $w_e$ is odd. Therefore, for every marked floor diagram $\Gamma$, we obtain
\[ m_\Gamma(-1)= \left( \prod_{j=1}^{\ell(\nu)} \frac{v_j}{[\nu_j]_\RR}\right) m_{\Gamma, \RR}\,,\]
and so \[ BPS_{\beta, (\mu,\nu)} ^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}(-1)=
  \left( \prod_{j=1}^{\ell(\nu)} \frac{v_j}{[\nu_j]_\RR}\right)
    W_{\beta, (\mu,\nu),\mathbf{x}}^{\widetilde{S}_n/\widetilde{\mathfrak{C}}}\,. \]
\end{proof}



