\section{BPS polynomials and Welschinger invariants of del Pezzo surfaces}
\label{section_bps_welschinger}

In \S \ref{sec_ABV}, we prove a refined version of the 
Abramovich--Bertram--Vakil formula which relates the BPS polynomials of the cubic surface $S_6$ with the relative BPS polynomials of $(\widetilde{S}_6, \widetilde{\mathfrak{C}})$. We use this result to prove Theorem \ref{thm_main} in 
\S \ref{sec_thm_main}, showing that the specialization at $q=-1$ of the BPS polynomials of the surfaces $S_n$ with $n\leq 6$ coincides with the Welschinger invariants.

\subsection{Refined Abramovich--Bertram--Vakil formula}
\label{sec_ABV}

In this section, we study the BPS polynomials of the surface $S_6$ obtained from $\PP^2$ by blowing-up $6$ points in general position, that is, of a smooth cubic surface in $\PP^3$. Recall from \S\ref{sec:relative_bps} that we denote by 
$\widetilde{S}_6$ the blow-up of $\PP^2$ at 6 points lying on a smooth conic, and by $\widetilde{\mathfrak{C}}$ the strict transform of the conic, so that, $\widetilde{\mathfrak{C}}^2
=2^2-6=-2$. In \cite[\S 9.2]{vakil2000counting}, Vakil studies the Gromov--Witten invariants of $S_6$ by degeneration to $(\widetilde{S}_6, \widetilde{\mathfrak{C}}^2)$, generalizing a previous formula of Abramovich-Bertram \cite{AB_12} which relates Gromov--Witten invariants of $\mathbb{F}_0$ and $\mathbb{F}_2$. The following result is a refined version of the Abramovich--Bertram--Vakil formula for $S_6$.

\begin{theorem} \label{thm_refined_ABV}
    For every $\beta \in H_2(S_6,\ZZ)$ such that $\beta \cdot \widetilde{\mathfrak{C}} \geq 1$ and for every $g \geq 0$, we have 
    \[ GW_{g,\beta}^{S_6}
    =\sum_{k \geq 0} \binom{\beta \cdot \widetilde{\mathfrak{C}}+2k}{k}
GW^{\widetilde{S}_6/\widetilde{\mathfrak{C}}}_{g,\beta-k \widetilde{\mathfrak{C}}, (\emptyset, \nu_k)}\,,\]
    where $\nu_k$ is the partition consisting of $(\beta \cdot \widetilde{\mathfrak{C}}+2k)$ parts equal to $1$. In particular, we have 
     \[ BPS_{\beta}^{S_6}(q)
    =\sum_{k \geq 0} \binom{\beta \cdot \widetilde{\mathfrak{C}}+2k}{k}
    BPS^{\widetilde{S}_6/\widetilde{\mathfrak{C}}}_{\beta-k \widetilde{\mathfrak{C}}, (\emptyset, \nu_k)}(q)\,.\]
\end{theorem}


\begin{proof}
The refined version of the original Abramovich-Bertram formula relating Gromov--Witten invariants of $\mathbb{F}_0$ and $\mathbb{F}_2$ is proved in \cite[Theorem 8.3]{bousseau_floor}. An analogous degeneration argument applied to $S_6$ and $(\widetilde{S}_6, \widetilde{\mathfrak{C}}^2)$ proves Theorem \ref{thm_refined_ABV}.
\end{proof}

\subsection{Welschinger invariants from BPS polynomials at $q=-1$}
\label{sec_thm_main}
Recall that we denote by $S_n$ a surface obtained from $\PP^2$ by blowing-up $n$ general real points.
Conjecture \ref{conj_bps_w} states that, for any $n$, the specialization at $q=-1$ of the BPS polynomials of $S_n$ is equal to the Welschinger invariants of $S_n$. Below we prove that this is true for $n \leq 6$.

\begin{theorem} \label{thm_main}
Let $S_n$ be a blow-up of $\PP^2$ at $n$ general real points. Then, for every $n \leq 6$ and $\beta \in H_2(S_n, \ZZ)$ such that $m_{\beta}:= -1 + c_1(S_n) \cdot \beta \geq 0$, the following holds:
     \[ BPS_{\beta}^{S_n}(-1)=W_{\beta}^{S_n} \,,\]
that is, Conjecture \ref{conj_bps_w} holds for $n \leq 6$.
\end{theorem}

\begin{proof}
By the refined Abramovich--Bertram--Vakil formula of Theorem \ref{thm_refined_ABV}, we have
\begin{equation} \label{eq_ABV}
BPS_{\beta}^{S_6}(q)
    =\sum_{k \geq 0} \binom{\beta \cdot \widetilde{\mathfrak{C}}+2k}{k}
    BPS^{\widetilde{S}_6/\widetilde{\mathfrak{C}}}_{\beta-k \widetilde{\mathfrak{C}}, (\emptyset, \nu_k)}(q)\,.\end{equation}
On the other hand, by the real Abramovich--Bertram--Vakil formula, proved symplectically in \cite[Theorem 2.2]{BP1}, \cite[Theorem 7]{BP2}, and algebraically in \cite[\S 4]{IKS2}, for every generic configuration of real points $\mathbf{x}_k$ of type $(\beta -k \widetilde{\mathfrak{C}}, \emptyset, \nu_k)$,
we have \begin{equation} \label{eq_real_ABV}
W_{\beta}^{S_6}
    =\sum_{k \geq 0} \binom{\beta \cdot \widetilde{\mathfrak{C}}+2k}{k}
    W^{\widetilde{S}_6/\widetilde{\mathfrak{C}}}_{\beta-k \widetilde{\mathfrak{C}}, (\emptyset, \nu_k), \mathbf{x}_k}\,.\end{equation}
For every $k \in\ZZ_{\geq 0}$, Theorem \ref{thm: relative_BPS_W} ensures the existence of $\mathbf{x}_k$ such that, given that all parts of $\nu_k$ are equal to one, the following holds:
\begin{equation} \label{eq_relative}BPS^{\widetilde{S}_6/\widetilde{\mathfrak{C}}}_{\beta-k \widetilde{\mathfrak{C}}, (\emptyset, \nu_k)}(-1)=W^{\widetilde{S}_6/\widetilde{\mathfrak{C}}}_{\beta-k \widetilde{\mathfrak{C}}, (\emptyset, \nu_k), \mathbf{x}_k}\,.\end{equation}
The result for $S_6$ follows by combination of \eqref{eq_ABV}, \eqref{eq_real_ABV}, and \eqref{eq_relative}. This implies the result for all $n \leq 6$ by Lemma \ref{lem_blow_up}.
\end{proof}

\begin{example} \label{example_3240_refined}
Consider $\beta=2c_1(S_6)=6H-2\sum_{i=1}^6 E_i \in H_2(S_6,\ZZ)$.
We have $\beta \cdot \widetilde{\mathfrak{C}}=0$, and so,
by Theorem \ref{thm_main}, 
we obtain 
\[ BPS_\beta^{S_6}(q)=BPS_\beta^{\widetilde{S}_6/\widetilde{\mathfrak{C}}}(q) + 
2\, BPS_{\beta'}^{\widetilde{S}_6/\widetilde{\mathfrak{C}}}(q)+6 \,, \]
where $\beta'=\beta-\widetilde{\mathfrak{C}}
=4H-\sum_{i=1}^6 E_i$.
The relative BPS polynomials $BPS_\beta^{\widetilde{S}_6/\widetilde{\mathfrak{C}}}(q)$ and $BPS_{\beta'}^{\widetilde{S}_6/\widetilde{\mathfrak{C}}}(q)$ are calculated in Examples \ref{ex_relative_6} and \ref{ex_relative_4} respectively. Using these results, we obtain
\[ BPS_\beta^S(q)=q^{-4}+13q^{-3}+100 q^{-2}+547 q^{-1}+1918+547 q+100 q^2+13 q^3+q^4 \,,\]
interpolating between $GW_{0,\beta}^{S_6}=3240$
at $q=1$ (see Example \ref{ex_3240_complex}) and $W_\beta^{S_6}=1000$ at $q=-1$ (see Example \ref{ex_3240_real}).
\end{example}


\section{BPS polynomials and K-theoretic refined BPS invariants}
\label{section_refined_dt}

Under suitable positivity assumptions, the Block-G\"ottsche polynomials of toric surfaces are conjectured to be related to polynomials defined in terms of Hirzebruch genera of relative Hilbert schemes of points on universal curves over linear systems \cite[Conjecture 6.12]{GSrefined}. In this section, we formulate a version of this conjecture in the broader context of BPS polynomials of surfaces defined in \S\ref{section_bps_surfaces}.

\subsection{BPS polynomials and K-theoretic refined BPS invariants}

As in \S\ref{section_bps_surfaces}, let $S$ be a smooth projective surface, and $\beta \in H_2(S,\ZZ)$ such that $m_\beta:=-1+c_1(S)\cdot \beta \geq 0$. 
The associated BPS polynomial $BPS_\beta^S(q)\in \ZZ[q^\pm]$ is defined in Definition \ref{Defn:BPSS} in terms of higher genus Gromov--Witten theory of the 3-fold $S \times \PP^1$, or equivalently the $\CC^\star$-equivariant higher genus Gromov--Witten theory of the 3-fold $S \times \CC$.

On the other hand, let $K_S$ be the non-compact Calabi--Yau 3-fold obtained by considering the total space of the canonical line bundle of $S$. There is a natural $\CC^\star$-action on $K_S$ scaling the fibers of the projection $K_S \rightarrow S$. The $K$-theoretic refined genus $0$ BPS invariant $\Omega_\beta^{K_S}(q) \in \ZZ[q^{\pm}]$ of $K_S$ with $m_\beta$ point insertions is given by
\[ \Omega_\beta^{K_S}(q)=\chi_q(M_{\beta,1}^{K_S}, \hat\cO^\vir \otimes \bigotimes_{i=1}^{m_\beta} \tau(p_i)) \,,\]
where $M_{\beta,1}^{K_S}$ is the moduli space of stable one-dimensional sheaves on $S$ of class $\beta$ and Euler characteristic one, $\hat\cO^\vir$ is the corresponding Nekrasov-Okounkov twisted virtual structure sheaf, and $\tau(p_i)$ are tautological classes imposing the $m_\beta$ point constraints. Finally, $\chi_q$ is the $\CC^\star$-equivariant Euler characteristic with respect to the $\CC^\star$-action on $K_S$, and we denote by $q$ the equivariant parameter. We refer to \cite{NO, Thomas_K_VW, thomas2024refined} for the details of the definition,  and in particular to \cite{afgani2020refinements} for a discussion of point constraints.
Alternatively, one could use moduli spaces of stable pairs on $K_S$, with the conjectural expectation that they yield the same invariants. 

\begin{conjecture} \label{conj_DT}
    Let $S$ be a smooth projective surface, and $\beta \in H_2(S,\ZZ)$ such that $m_\beta:=-1+c_1(S)\cdot \beta \geq 0$. Then, the BPS polynomial $BPS_\beta^S(q)$ of $S$ coincides with the refined genus $0$ BPS invariant of $K_S$ with $m_\beta$ point insertions:
    \[ BPS_\beta^S(q) = \Omega_\beta^{K_S}(q)\,. \]
\end{conjecture}


This conjecture suggests a striking connection between the Gromov--Witten theory of $S \times \CC$ and refined sheaf counting on $K_S$.
From a physics perspective, this conjecture aligns with expectations about the fully refined topological string on $K_S$, which is anticipated to be a $\CC^\star_{\epsilon_1} \times \CC^\star_{\epsilon_2}$-equivariant theory of the Calabi--Yau $5$-fold $K_S \times \CC^2$. In this setting, the action on $\CC^2$ has weights $\epsilon_1$ and $\epsilon_2$, while the action
on the fibers of $K_S$ has weight $-\epsilon_1 - \epsilon_2$. For initial developments using sheaf counting, see \cite{NO}, and for a Gromov--Witten-based formulation, see \cite{brini2024refined}. Mathematically, the fully refined topological string should encode the refined BPS invariants of $K_S$ in all genera.

In the limit $\epsilon_1 \to 0$, known in the physics literature as the Nekrasov-Shatashvili limit, only the genus $0$ refined BPS invariants of $K_S$ should contribute, with the K-theoretic definition using the remaining action of $\CC^\star_{\epsilon_2}$ on the fibers of $K_S$ with weight $\epsilon_2$. 
Meanwhile, in this limit, the fixed locus of $\CC^\star_{\epsilon_2}$ acting on 
$K_S \times \CC^2$ is $S \times \mathbb{C}$, with normal weights $-\epsilon_2$ and 
$\epsilon_2$. An expected property of the refined topological string is that, in such cases, it should recover the standard (unrefined) Gromov--Witten theory of 
$S \times \CC$, where $\epsilon_2$ plays the role of the genus expansion parameter \cite[\S 2.3]{NO}. These two different interpretations of the limit $\epsilon_1 \rightarrow 0$ of the refined topological string theory, either using the 3-fold $K_S \subset K_S \times \CC^2$ or the 3-fold $S \times \CC \subset K_S \times \CC^2$, lead to a relationship between enumerative invariants of the form predicted by Conjecture \ref{conj_DT}.



Finally, we note that a version of Conjecture \ref{conj_DT} without point insertions is proved for $S=\PP^2$ and conjectured for del Pezzo surfaces in \cite[Theorem 1.10]{bousseau_tak}.

\subsection{K3 surfaces and refined DT invariants}
Let $S$ be a smooth projective K3 surface. In this case, the natural analogue of Conjecture \ref{conj_DT}, formulated using reduced invariants, is known to hold. 
Indeed, for every algebraic $\beta \in H_2(S,\ZZ)$ with $\beta^2=2h-2$, the Laurent polynomials $BPS_\beta^S(q)$ and $\Omega_\beta^{K_S}(q)$ both coincide with the coefficient of $u^h$ in the power series expansion of 
\begin{equation}\label{eq_kkv}
\prod_{n \geq 1} \frac{1}{(1-u^n)^{20}(1-qu^n)^2(1-q^{-1}u^n)^2}\,.\end{equation}
For $BPS_\beta^S(q)$, this follows from the KKV conjecture \cite{KKV}, proved in \cite{KKV_proof}, while the corresponding result for $\Omega_\beta^{K_S}(q)$ is proved in \cite[Remark 4.7]{thomas2024refined}. 
We also refer to \cite[\S 7, Theorems 25-28]{bousseau2017tropical} 
for additional results involving point insertions for K3 and abelian surfaces  which can be viewed as special cases of Conjecture \ref{conj_DT}. 
While these results for K3 and abelian surfaces may initially appear coincidental, Conjecture \ref{conj_DT} suggests that similar results should hold in a much broader context. 
The only coincidence is that $K_S=S\times \CC$ for K3 and abelian surfaces, whereas in general these two 3-folds play distinct roles. 


\subsection{Real K3 surfaces and Welschinger invariants}
\label{sec_K3_real}
Conjecture \ref{conj_bps_w} predicts that the specialization of the BPS polynomials
at $q=-1$ for rational surfaces coincides with Welschinger invariants counting real rational curves. This naturally leads to the broader question of whether the specialization of BPS polynomials at $q=-1$ still has a meaningful interpretation within 
real algebraic geometry for more general surfaces. In general, the answer is unclear due to the lack of generality of the definition of Welschinger invariants. However, we remark in this section that the answer is positive when $S$ is a smooth projective K3 surface.

Indeed, consider a smooth projective real K3 surface, and an algebraic primitive class $\beta \in H_2(S,\ZZ)$ with $\beta^2=2h-2$.
Then, there exist only finitely many rational curves in $S$ of class $\beta$, all with $h$ nodes.
The count $W_\beta^S$ of the corresponding real curves with Welschinger sign is determined by
\cite[Corollary 0.1 (2)]{KR_realK3} as the coefficient of $u^h$ in the power series expansion of
\begin{equation}\label{eq_K3}
\prod_{r\geq 1} \frac{1}{(1+u^r)^{e_\RR}} 
\prod_{s \geq 1} 
\frac{1}{(1-u^{2s})^{\frac{e_\CC -e_\RR}{2}}}=\prod_{n \geq 1} \frac{1}{(1+u^n)^{\frac{e_\CC+e_\RR}{2}}(1-u^n)^{\frac{e_\CC-e_\RR}{2}}}\,,\end{equation}
where $e_\CC=24$ is the topological Euler characteristic of $S$, and $e_\RR$ is the topological Euler characteristic of the real locus of $S$.
The formula \eqref{eq_K3} agrees with the specialization at $q=-1$ of \eqref{eq_kkv} if and only if $e_\RR=-16$.
Therefore, we have $BPS_\beta^S(-1)=W_\beta^S$ for real K3 surfaces with $e_\RR=-16$.
By \cite[p85, Figure 3]{real_enriques}, real K3 surfaces with $e_\RR=-16$ exist and have real loci given by either a genus $9$ surface, or the union of a sphere and a genus $10$ surface.  
The latter case is distinguished in several ways. For example, the corresponding real K3 surfaces are maximal, meaning that they saturate the Smith-Thom inequality 
$\dim H_\star(S(\RR),\ZZ/2) \leq \dim H_\star(S,\ZZ/2\ZZ)$. 
Moreover, these real K3 surfaces can be explicitly constructed from toric degenerations with trivial choices of real gluing data by 
\cite[Proposition 9.1]{hulya_real_KN}.


Finally, note that $-16$ is also the signature $\sigma$ of a K3 surface, and so the condition $e_\RR=-16$ can be rewritten as $e_\RR=\sigma$. All the rational surfaces $S_n$ with their standard real structure appearing in Conjecture \ref{conj_bps_w} also satisfy the condition $e_\RR=1-n=\sigma$.
This raises the question of whether there exists a more general real interpretation of $BPS_\beta^S(-1)$ applicable to all real surfaces 
with $e_\RR=\sigma$. 






