\title{Hazel Deriver: A Live Editor for Constructing Rule-Based Derivations}

\author{\IEEEauthorblockN{Zhiyao Zhong}
\IEEEauthorblockA{\textit{Computer Science and Engineering} \\
\textit{University of Michigan}\\
Ann Arbor, MI, USA \\
zhzy@umich.edu}
\and
\IEEEauthorblockN{Cyrus Omar}
\IEEEauthorblockA{\textit{Computer Science and Engineering} \\
\textit{University of Michigan}\\
Ann Arbor, MI, USA \\
comar@umich.edu}
