\begin{eqnarray*}
\mbox{Bias}(\widehat{\bm{\eta}}, \widehat{\bm{\eta}}^\text{W}) &=& 100 \times\frac{1}{B} \sum_{b=1}^{B}  (\widehat{\eta}_b - \widehat{\eta}^\text{W}_b)  \\
\mbox{Absolute Bias}(\widehat{\bm{\eta}}, \widehat{\bm{\eta}}^\text{W}) &=& 100 \times \frac{1}{B} \sum_{b=1}^{B} 100 \times |\widehat{\eta}_b - \widehat{\eta}^\text{W}_b| \\
\mbox{Relative Bias}(\widehat{\bm{\eta}}, \widehat{\bm{\eta}}^\text{W}) &= & 100\% \times\frac{1}{B} \sum_{b=1}^{B}  \frac{\widehat{\eta}_b - \widehat{\eta}^\text{W}_b}{\widehat{\eta}^\text{W}_b} \\
\mbox{Absolute Relative Bias}(\widehat{\bm{\eta}}, \widehat{\bm{\eta}}^\text{W}) &= &100\% \times \frac{1}{B} \sum_{b=1}^{B}  \left|\frac{\widehat{\eta}_b - \widehat{\eta}^\text{W}_b}{\widehat{\eta}^\text{W}_b}\right| \\
\mbox{RMSE}(\widehat{\bm{\eta}}, \widehat{\bm{\eta}}^\text{W}) &=& \sqrt{\frac{1}{B} \sum_{b=1}^{B} (\widehat{\eta}_b - \widehat{\eta}^\text{W}_b)^2}
\end{eqnarray*}

