\subsection{Simplicial Complex}
Let $\K$ be an abstract simplicial complex.
We denote by $|\K|$ the geometric realization of $\K$.
\begin{definition}[(Ambient) \v{C}ech Complex]\label{def:cech}
Let $(\mathcal{X},d_\mathcal{X})$ be a metric space and $\mathcal{A}\subset\mathcal{X}$ be a subset.
For scale $\beta >0$, the (ambient) \emph{\v{C}ech complex}, denoted $\check{\mathcal{C}}_\beta(\mathcal A)$, is defined as the abstract simplicial complex whose simplices are the finite subsets of points of $\mathcal A$ such that the (open) $\beta$-balls about those points have a common intersection in $\mathcal{X}$.
\end{definition}

\subsection{Metric Space}


\begin{definition}[Hausdorff Distance]\label{def:dH}
Let $(\mathcal X,d_\mathcal{X})$ be a metric space. 
Let $\mathcal A$ and $\mathcal B$ be compact, non-empty subsets. 
The \emph{Hausdorff distance} between them, denoted $d^\mathcal{X}_H(\mathcal A, \mathcal B)$, is defined as
\[
d^\mathcal{X}_H(\mathcal A, \mathcal B) \coloneqq 
\max\left\{\sup_{a\in\mathcal A}\inf_{b\in \mathcal B}d_\mathcal{X}(a,b),\sup_{b\in \mathcal B}\inf_{a\in\mathcal A}d_\mathcal{X}(a,b)\right\}.
\]
In case $\mathcal X\subset\mathbb{R}^N$ and $\mathcal A,\mathcal B,\mathcal{X}$ are all equipped with the Euclidean metric, we simply write $d_H(\mathcal A,\mathcal B)$.
\end{definition}


