\subsection{Embedded Metric Graphs}\label{sec:metric-graphs}
Let $\G\subset\R^N$ be an embedded metric graph. 
$\G$ comes equipped with the standard Euclidean metric $\|\bullet-\bullet\|$.
Using the notion of the length $L(\gamma)$ of a continuous path $\gamma$ in $\R^N$, we can define the intrinsic or shortest path metric $d_\G$ on $\G$ as follows:
For any two points $a,b\in \G$, it is the infimum of the lengths of paths $[0,1]\to\G$ joining $a,b$. 
In this metric, the diameter of a bounded subset $\mathcal A\subset\G$ is denoted by $\diam_\G(\mathcal A)$.
If $\G$ is path-connected, $d_\G$ defines a metric on $\G$, called the \emph{length} metric. 
Using the above definition, we are also allowing $\G$ to have single-edge cycles and multiple edges between a pair of vertices.
%In this paper, we only consider path-connected, compact metric graphs $(\G,d_\G)$ with finitely many edges. The metric graphs we consider are geodesic (i.e., for every $x,y\in G$ there is an isometric embedding $\gamma\colon[0,d(x,y)]\to G$ such that $\gamma(0)=x$ and $\gamma(d(x,y))=y$) since they are compact (a compact length space is geodesic). For an edge $e\in E$, its length $|e|$ is the length of the corresponding metric segment.
%Note that the length can be different from the distance between the endpoints of $e$ according to the metric $d$.
%Extending the definition of length for a continuous path $\gamma:[a,b]\to G$, we define the length $|\gamma|$ as the sum of the (full or partial) lengths of the edges that $\gamma$ traverses. 
%For a vertex $v$ of a graph, its \emph{degree}, denoted $deg(v)$, is the number of edges incident to $v$. A self-loop at $v$ contributes $2$ to the degree of $v$. 
We denote by $\ell(\G)$ the length of the smallest simple cycle (systole) of $\G$. In case $\G$ is contractible, we use the convention that $\ell(\G)=\infty$. 

We also denote by $\mathscr{V}(\G)$ and $\mathscr{E}(\G)$ the vertices and edges of $\G$, respectively.
We assume throughout the paper that $\G$ is compact with $\mathscr{E}(\G)<\infty$.
As a result, $\ell(\G)>0$.


\subsection{Hausmann-Type Theorem for Metric Graphs}\label{subsec:circumcenter} We begin with the definition of circumradius and circumcenter in $(\G,d_\G)$, with respect to the length metric. 
For a bounded subset $\mathcal A\subset \G$, we define its \emph{circumradius} to be the radius of the smallest (closed) $d_\G$-metric ball enclosing $\mathcal A$. More formally,
\[
\rad(\mathcal A)\coloneqq\inf_{g\in \G}\ \sup_{a\in\mathcal A}d_\G(a, g).
\]
A point $g\in \G$ satisfying $\max_{a\in\mathcal A}d_\G(a ,g)=\rad(\mathcal A)$ is called a \emph{circumcenter} of $\mathcal A$, and is denoted by $c(\mathcal A)$. 
%For $A$ compact, a circumcenter may not uniquely exist. 
The reader must be warned that these terms may not always match their usual meaning in plane geometry.

For any $\mathcal A\subset\G$ is compact, there exist $a,b\in\mathcal A$ such that $\diam_\G(\mathcal A)=d_\G(a,b)$.
In addition, if $d_\G(a,b)<\ell(\G)/3$, then the unique geodesic $\gamma\subset\G$ joining $a$ and $b$ must contain $\mathcal A$ entirely. 
Conseqently, the midpoint of $\gamma$ is the unique circumcenter of $\mathcal A$, and that the circumradius is $\frac{1}{2}d_\G(a,b)$. The above observation yields the following important proposition.
\begin{proposition}[Circumcenter Existence]\label{prop:center} Let
$\mathcal A\subset(\G,d_\G)$ be a (non-empty) compact subset with $\diam_\G(\mathcal A)<\ell(\G)/3$. 
Then, the circumcenter of $\mathcal A$ exists uniquely. Moreover, the circumradius is $\frac{1}{2}\diam_\G(\mathcal A)$.
\end{proposition}
A proof of the following crucial proposition is presented in the appendix.
\begin{proposition}[Circumcenter Distances]\label{prop:radius} If $\mathcal A$ is a (non-empty) compact subset of $(\G, d_\G)$ with $\diam_\G(\mathcal A)<\ell(\G)/3$, then for any non-empty subset $\mathcal A'\subset \mathcal A$, we have
\[d_\G\left(c(\mathcal A'),c(\mathcal A)\right) \leq\tfrac{1}{2}\diam_\G(\mathcal A).\]
\end{proposition}

As a consequence of Proposition~\ref{prop:center}, we get the following improved result for graphs in the style of Hausmann's theorem~\cite{hausmann1995vietoris}.
Throughout the paper, $\check{\mathcal C}^L_\beta(\G)$ and $\Ri^L_\beta(\G)$ are used to denote the \v{C}ech and Vierotis--Rips complex of $\G$ with respect to the length metric $(\G, d_\G)$, respectively.
\begin{theorem}[Hausmann-Type Theorem for Metric Graphs]\label{thm:hausmann-graph}
For any compact metric graph $(\G,d_\G)$ and $0<\beta<\ell(\G)/3$, we have $\Ri^L_\beta(\G)\simeq\G$.

Furthermore, if $0<\beta\leq\beta'<\ell(\G)/3$, then the natural inclusion $\Ri^L_\beta(\G)\xhookrightarrow{\iota}\Ri^L_{\beta'}(\G)$ is a homotopy equivalence. 
\end{theorem}
\begin{proof}
For  any $\beta>0$, we have the natural inclusion $\check{\mathcal{C}}^L_{\beta/2}(\G)\hookrightarrow\mathcal{R}^L_{\beta}(\G)$, but in general $\check{\mathcal{C}}^L_{\beta/2}(\G)$ is a proper subcomplex of $\mathcal{R}^L_{\beta}(G)$. 
However, if $0<\beta <\ell(\G)/3$, we can apply proposition \ref{prop:center} to also get $\Ri^L_{\beta}(\G)\hookrightarrow\check{\mathcal{C}}^L_{\beta/2}(\G)$.
So, $\Ri^L_{\beta}(\G)=\check{\mathcal{C}}^L_{\beta/2}(\G)$.
On the other hand, $\check{\mathcal{C}}^L_{\beta/2}(\G)\simeq\G$ due to the Nerve lemma and the fact that the intrinsic balls of radius less than $\ell(\G)/4$ form a good cover.
\end{proof}

\subsection{The $\eps$-path Metric}
%For any $X \subset (\mathcal{Z},d)$, one has the induced length metric $d^L_X(x_1,x_2)$. 
Let $\mathcal A\subset\R^N$ be any subset, equipped with the standard Euclidean metric.
The notion of an $\eps$--path was introduced in~\cite{majhi2023vietoris,fasy2022reconstruction} as a family of piecewise Euclidean segments formed by ``hopping over'' the points in $\mathcal A$. 
The family gives rise to yet another alternative (possibly non-Euclidean) metric on $\mathcal A$. For a positive number $\eps$, we first introduce the notion of an $\eps$-path and then the $d^\eps_{\mathcal A}$-metric.

Let $\mathcal A\subset\R^N$ be non-empty and $\eps>0$ a number. 
For $p,q\in\mathcal A$, an \emph{$\eps$--path} of $\mathcal A$ from $p$ to $q$ is a finite sequence $\mathcal{P}=\{a_i\}_{i=0}^{k+1}\subseteq\mathcal A$ such that $a_0=p$, $a_{k+1}=q$, and $\|a_i-a_{i+1}\|<\eps$ for all $i=0,1,\ldots,k$. 
We define the length of the path by $L(\mathcal{P})\coloneqq\sum_{i=0}^k\|a_i-a_{i+1}\|$ and the set of all $\eps$--paths of $\mathcal A$ joining any pair $p,q\in\mathcal A$ by $\mathscr{P}_{\mathcal A}^\eps(p,q)$.
\begin{definition}[The $d^\eps_{\mathcal A}$-metric]\label{def:eps-path}
Let $\mathcal A\subset\R^N$ be non-empty and $\eps>0$ a number. 
The $\eps$--path metric on $\mathcal A$, denoted $d^\eps_{\mathcal A}$, between any $p,q\in\mathcal A$ is defined by 
\begin{equation*}\label{eq:d^eps}
d^\eps_{\mathcal A}(p,q)\coloneqq\inf\left\{L(\mathcal{P})\mid \mathcal{P}\in \mathscr{P}^\eps_{\mathcal A}(p,q)\right\}.
\end{equation*}
\end{definition}
We use $\diam^\eps_\S(\mathcal A)$ to denote the diameter of a subset $\mathcal A\subset\S\subset\R^N$ in the $d^\eps_\S$ metric.

