\begin{proposition}[Comparison of Path Metrics \cite{majhi2023vietoris}]\label{prop:d^esp-d^L-estimate} Let $\G \subset \mathbb{R}^N$ be a graph and $\S \subset \mathbb{R}^N$ such that $d_H(\S, \G) < \frac{1} {2}\xi\varepsilon$ for some $\xi \in (0,1)$ and $\eps > 0$. 
For any $a, b \in \G$ and corresponding $A, B \in \S$ with $||a-A||, ||b-B||<\frac{1}{2}\xi\eps$, we have
\begin{equation}\label{eq:d^eps-d^L-si-eps}
\norm{A-B}\leq d^\eps_\S(A,B)\leq \dfrac{d_\G(a,b) + \xi\varepsilon}{1-\xi}.
\end{equation}
\end{proposition}

