\subsection{The Large-Scale Distortion}
Following the definition of~\cite{MajhiStability}, we now define
the large-scale distortion of $\G\subset\R^N$, denoted $\delta^\eps_R(\G)$, is parametrized by $\eps>0$ and $R>0$.
%Roughly speaking, it is supremum the ratio of the induced length of metrics on $X$ and (Euclidean) $\eps$-thickening of $X$, between points of $X$ that are at least $R$ distance away.
%More formally, we present the following definition.
\begin{definition}[Large-scale Distortion]\label{def:lc-dist}
For $\eps>0$ and $R>0$, the \emph{large-scale distortion} or \emph{$(\eps,R)$-distortion} $\mathcal \G\subset\R^N$ is defined by
\begin{equation}\label{eq:delta-eps-R}
\delta^\eps_R(\G)\coloneqq \sup_{d_\G(a,b)\geq R} \frac{d_\G(a,b)}{d_{\G^\eps}(a,b)},
%,\qquad \delta^\eps(x_1,x_2)=\frac{d_X^L(x_1,x_2)}{d^L_{X^{\eps}}(x_1,x_2)}
\end{equation}
where $\G^\eps$ and $d_{\G^\eps}(a,b)$ denote, respectively, the Euclidean thickening of $\G$ and the length metric thereof induced from the Euclidean metric. 
\end{definition}
For more details on the length metric on the thickening and the large-scale distortion, see~\cite{MajhiStability}.
For the purpose of our paper, we only note here that
\begin{enumerate}[(a)]
    \item $\delta^\eps_R(\G)$ is a non-decreasing function of $\eps$ and that $\delta^\eps_R(\G)$ is a non-increasing function of $R$, and
    \item if $\G\subset\R^N$ compact, then for any $R>0$, the large-scale distortion $\delta^\eps_R(\G)\to1$ as $\eps\to0$.
\end{enumerate}
To conclude the preliminaries, we state the following relevant fact, which has been proved in~\cite{MajhiStability} for general geodesic spaces.
For completeness, a proof is laid out in the appendix.
\begin{proposition}\label{prop:delta_path}
Let $\G\subset\R^N$ and $\S\subset\R^N$ compact with $d_H(\G, \S)<\alpha$. 
Let $\eps>2\alpha$ and $R$ be positive numbers. 
For any $a,b\in \G$ with $d_\G(a,b)\geq R$ and $A,B\in\S$ such that $\max\{\|a-A\|,\|b-B\|\}<\alpha$, we must have
\[
d_\G(a, b)\leq\delta^\eps_R(\G)\left[d^\eps_\S(A, B)+2\alpha\right].
\]
\end{proposition}


\section{Topological Reconstruction via Vietoris--Rips Complexes}\label{sec:top}
We first present our topological reconstruction result for graphs using Vietoris--Rips complexes.
Throughout this section, we always assume that $\G\subset\R^N$ is a compact, connected Euclidean graph and $\S\subset\R^N$ a compact sample with a small Hausdorff distance to $\G$.

When endowed with the length metric $d_\G$, we denote the Vietoris--Rips complex of $\G$ by $\Ri_\beta^L(\G)$. 
And, the Vietoris--Rips complex of $(\S,d^\eps_\S)$ is denoted by $\Ri_\beta^\eps(\S)$.

\homeq

\begin{proof} [Proof of Theorem \ref{thm:hom-eq}]
Since $d_H(\G,\S)<\tfrac{1}{2}\xi\eps$, we can define a function $\Phi\colon\G\to\S$ such that $\|g-\Phi(g)\|<\tfrac{1}{2}\xi\eps$ for any $g\in\G$. 
Similarly, we can define a function $\Psi\colon\S\to\G$ such that $\|\Psi(s)-s\|< \tfrac{1}{2}\xi\eps$ for any $s\in \S$. 

We can (linearly) extend these maps to simplicial maps to get the following chain of simplicial maps, which we justify shortly:
\begin{align}\label{eq:rips_chain}
\Ri^L_{(1-\xi)\beta - \xi\eps}(\G) 
\xrightarrow{\quad\Phi\quad}\Ri^{\eps}_{\beta}(\S) \xrightarrow{\quad\Psi\quad}\Ri^L_{4\beta/3}(\G).
\end{align}
To justify the map $\Phi$, take $g_1,g_2\in\G$ with $d_\G(g_1,g_2) < (1-\xi)\beta - \xi\eps$. 
The second inequality in \eqref{eq:d^eps-d^L-si-eps} then implies 
\begin{equation}\label{eq:phi_beta}
d_\S^\eps(\Phi(g_1),\Phi(g_2))\leq \dfrac{d_\G(g_1,g_2) + \xi\varepsilon}{1-\xi} < \frac{[(1-\xi)\beta - \xi\eps]+\xi\eps}{1-\xi}= \beta.
\end{equation}
Consequently, for any simplex $\sigma\in\Ri^L_{(1-\xi)\beta - \xi\eps}(\G)$,
we must have that $\Phi(\sigma)\in\Ri^{\eps}_{\beta}(\S)$.

We argue similarly to justify the map $\Psi$. 
Take $s_1, s_2\in \S$ with $d^\eps_\S(s_1, s_2)<\beta$. 
In case we already have $d_\G(\Psi(s_1),\Psi(s_2)) < 4\beta/3$, there is nothing to show. 
Otherwise, if $d_\G((\Psi(s_1),\Psi(s_2))\geq4\beta/3>\beta$, then we get from Proposition~\ref{prop:delta_path}:
\begin{align}
d_\G(\Psi(s_1), \Psi(s_2)) 
& \leq \delta^{\eps}_{\beta}(\G) [d^\eps_\S(s_1, s_2)+\xi\eps]\nonumber \\
& \leq \frac{1+2\xi}{1+\xi}(d^\eps_\S(s_1, s_2)+\xi\eps),\text{ due to the choice of }\eps\nonumber \\
& < \frac{1+2\xi}{1+\xi}(\beta+\xi\eps)\label{eq:diam-estimate-1}\\
& \leq \frac{(1+2\xi)(3+\xi)}{3(1+\xi)}\beta,\text{ since }\eps\leq\beta/3\nonumber \\ 
%& \leq \frac{3+9\xi-4\xi^2-2\xi^3}{(1+\xi)(3+4\xi)}\beta,\text{ since }\eps\leq\frac{1-2\xi-2\xi^2}{\xi(3+4\xi)}\beta\nonumber \\
&<\frac{4}{3}\beta,\text{ since }0<\xi<1/4\label{eq:diam-estimate-2}.
\end{align}
For any $s_1, s_2\in \S$ with $d^\eps_\S(s_1, s_2)<\beta$, this shows that $d_\G((\Psi(s_1),\Psi(s_2)) \leq4\beta/3$, This implies $\Psi$ is a well-defined simplicial map as claimed.

\noindent{\bf Contiguity.}\ The composition $(\Psi\circ\Phi)$ is contiguous to the natural inclusion:
\[
\iota:\Ri^L_{(1-\xi)\beta - \xi\eps}(\G)\hookrightarrow\Ri^L_{4\beta/3}(\G).
\]
Indeed, for any $m$-simplex $\sigma_m\coloneqq[g_0, \ldots, g_m]\in \Ri^L_{(1-\xi)\beta - \xi\eps}(\G)$, it suffices to show 
\[
\operatorname{diam}_\G(\iota(\sigma) \cup \Psi \circ \Phi(\sigma)) < 4\beta/3.
\]
For any $0\leq i,j\leq m$, it suffices to establish that $d_\G(g_i, \Psi\circ\Phi(g_j))<4\beta/3$. 
Without any loss of generality, we assume that  $d_\G(g_i,\Psi\circ\Phi(g_j))\geq4\beta/3>\beta$. 
Then, we have from Proposition~\ref{prop:delta_path}
\begin{equation*}\label{eq:contiguity-ineq}
\begin{split}
d_\G(g_i, \Psi\circ\Phi(g_j)) 
&\leq \delta^{\eps}_{\beta}(\G)[d^\eps_\S(\Phi(g_i), \Phi(g_j))+\xi\eps]
\leq \frac{1+2\xi}{1+\xi}\cdot[d^\eps_\S(\Phi(g_i), \Phi(g_j))+\xi\eps]\\
&\leq \frac{1+2\xi}{1+\xi}\left[\frac{d_\G(g_i,g_j)+\xi\eps}{1-\xi}+\xi\eps\right]\\
&<\frac{1+2\xi}{1+\xi}\left[\frac{(1-\xi)\beta-\xi\eps+\xi\eps}{1-\xi}+\xi\eps\right],\text{ by~(\ref{eq:phi_beta})}\\
&<\frac{1+2\xi}{1+\xi}\left[\beta\xi+\xi\eps\right]\\
& < \frac{4}{3}\beta,\text{ from~(\ref{eq:diam-estimate-2})}.\\
%& \leq \tfrac{8}{49}(1-\xi)(8-\xi)\beta,\text{ since }\eps\leq\tfrac{1}{7}\left(\tfrac{1-\xi}{\xi}\right)\beta\\.
\end{split}
\end{equation*}

\noindent{\bf Injectivity.}\  
Since we have assumed $4\beta/3 < \ell(\G)/3$, Theorem~\ref{thm:hausmann-graph} implies that the natural inclusion $\iota: \Ri^L_{(1-\xi)\beta - \xi\eps}(\G) 
\hookrightarrow\Ri^L_{4\beta/3}(\G)$ is a homotopy equivalence. 
Since the composition $(\Psi\circ\Phi)$ is contiguous to $\iota$, the map $\Phi$ must induce an injective homomorphism on all the homotopy groups.

\noindent{\bf Surjectivity.}\ Since the geometric realizations $|\Ri^L_{(1-\xi)\beta-\xi\eps}(\G)|$ and $|\Ri^\eps_\beta(\S)|$ are path-connected (due to Proposition~\ref{prop:path-connected} and $\beta\geq\eps$), the result holds for $m=0$.

For $m\geq1$, let us take an abstract simplicial complex $\K$ such that $|\K|$ is a triangulation of the $m$--dimensional sphere $\mathbb S^m$. 
In order to show surjectivity of $\pi_m(\Phi)$ on $\pi_m(\Ri^L_{(1-\xi)\beta-\xi\eps}(\G))$, we start with a simplicial map  $g\colon\K\to\Ri^\eps_\beta(\S)$, which, by Simplicial Approximation Theorem \cite{munkres2018elements}, approximates any given continuous map $\mathbb S^m=|\K|\longrightarrow |\Ri^\eps_{\beta}(\S)|$ up to homotopy. 
We claim that there exists a simplicial map
$\widetilde{g}\colon\sd\K\to\Ri^L_{(1-\xi)\beta-\xi\eps}(\G)$ such that the following
diagram commutes up to homotopy:
