% https://q.uiver.app/#

% https://q.uiver.app/#
\begin{equation}\label{eq:rips_comm_diagram}
\begin{tikzcd}
	{\Ri^L_{(1-\xi)\beta-\xi\varepsilon}(\G)} && {\Ri^\varepsilon_{\beta}(\S)} && {\Ri^L_{4\beta/3}(\G)} \\
	\\
	{\operatorname{sd} \K} && {\K}
	\arrow["g"', from=3-3, to=1-3]
	\arrow["{\widetilde{g}}", from=3-1, to=1-1]
	\arrow["{\sd}"', from=3-3, to=3-1]
	\arrow["\Phi", from=1-1, to=1-3]
	\arrow["\Psi", from=1-3, to=1-5]
	\arrow["{\Phi \circ \widetilde{g}}", from=3-1, to=1-3]
\end{tikzcd}
\end{equation}
where the linear homeomorphism $\sd^{-1}:\sd{\K}\longrightarrow\K$ maps each vertex of $\sd{\K}$ to the corresponding point of $\K$. 
Recall that each vertex of $\sd{\K}$ is the barycenter,
$\widehat{\sigma}_l$, of an $l$--simplex $\sigma_l$ of $\K$. In order to construct the simplicial map $\widetilde{g}$, we need to define it on the vertices of $\sd{\K}$ and prove that it extends to the simplicial map valued in 
$\Ri^L_{(1-\xi)\beta-\xi\varepsilon}(\G)$. 

Let $\sigma_l=[v_0,v_1,\ldots,v_l]$ be an $l$--simplex of $\K$. 
Since $g$ is a simplicial map, we have that the image
$g(\sigma_l)=[g(v_0),g(v_1),\ldots,g(v_l)]$ is a subset of $\S$ with 
$d^\eps_\S(g(v_i), g(v_j))<\beta$ for any  $0\leq i,j\leq l$. 
We note from (\ref{eq:diam-estimate-2}) that $\diam_\G \bigl(\Psi\circ g(\sigma_l)\bigr)<\frac{\ell(\G)}{4}$. 
Proposition~\ref{prop:center} implies that the circumcenter $c((\Psi\circ g)(\sigma_l))$ exists, and we define the value of $\widetilde{g}$ at the barycenter $\widehat{\sigma}_l$.
\[
\widetilde{g}(\widehat{\sigma}_l)\coloneqq c((\Psi\circ g)(\sigma_l)).
\] 
For any $0\leq j\leq l$, it also follows from Proposition~\ref{prop:radius} that given $\sigma_j\prec\sigma_l$:
\begin{equation}\label{eq:sigma-1}
d^L_\G\bigl(c(\Psi\circ g(\sigma_j)), c(\Psi\circ g(\sigma_l))\bigr)\leq\tfrac{1}{2}\diam^L_\G{(\Psi\circ g)(\sigma_l)}.
\end{equation} 
Now, to see that $\widetilde{g}$ extends to a simplicial map, consider a typical $l$--simplex $\tau_l=[\widehat{\sigma}_0$, $\widehat{\sigma}_1$, $\ldots$, $\widehat{\sigma}_l]$ of $\sd\K$, where $\sigma_{i-1}\prec\sigma_i$ for $1\leq i\leq l$ and $\sigma_i\in\K$, we have
\begin{align*}
\diam_\G\bigl(\widetilde{g}(\tau_l)\bigr)
&=\diam_\G\bigl\{\widetilde{g}(\widehat{\sigma_0}), \widetilde{g}(\widehat{\sigma_1}),\ldots,\widetilde{g}(\widehat{\sigma_l})\bigr\}  \\
&=\max_{1\leq i< j\leq l}{d_\G(\widetilde{g}(\widehat{\sigma_i}), \widetilde{g}(\widehat{\sigma_j}))} \leq\max_{1\leq j\leq l}{\frac{1}{2}\diam_\G{(\Psi\circ g)(\sigma_j})} \leq\tfrac{1}{2}\diam_\G{(\Psi\circ g)(\sigma_l}) \\
& \leq \frac{1}{2}\cdot\frac{1+2\xi}{1+\xi}(\beta+\xi\eps),\text{ from (\ref{eq:diam-estimate-1})}\\
&\leq(1-\xi)\beta-\xi\eps,\text{ since }\quad\eps\leq\beta/3\text{ and }0<\xi<1/4.    
%&\leq(1-\xi)\beta-\xi\eps,\quad\text{ since }\quad\eps\leq\frac{1-2\xi-2\xi^2}{\xi(3+4\xi)}\beta.    
\end{align*}
Thus, $\widetilde{g}(\tau_l)$ is a simplex of $\Ri^L_{(1-\xi)\beta-\xi\eps}(\G)$, which implies that $\widetilde{g}$ is a simplicial map.  
Naturally, $\Phi\circ\widetilde{g}: \operatorname{sd}(\K) \rightarrow \Ri^\eps_\beta(\S)$ is a simplicial map. Next, we intend to apply Lemma~\ref{lem:barycenter-map-lemma}, to the subdiagram of \eqref{eq:rips_comm_diagram} corresponding to maps $\Phi \circ \widetilde{g}$, $\sd$ and $g$. The assumption (1) of Lemma \ref{lem:barycenter-map-lemma} holds by definition of $\widetilde{g}$, we need to show the second condition (2) holds as well i.e. show that vertices in $g(\sigma_l) \cup \{(\Phi\circ\widetilde{g})(\widehat{\sigma_l})\}$ form a simplex $[(\Phi\circ\widetilde{g})(v_0), (\Phi\circ\widetilde{g})(v_1), \ldots,(\Phi\circ\widetilde{g})(v_l), (\Phi\circ\widetilde{g})(\widehat{\sigma}_l)]$ in $\Ri^\eps_\beta(\S)$. Observe
\begin{align*}
d^\eps_\S((\Phi\circ \widetilde{g})(v_i), (\Phi\circ\widetilde{g})(\widehat{\sigma}_l)) \leq \dfrac{d_\G(\widetilde{g}(v_i), \widetilde{g}(\widehat{\sigma}_l)) + \xi\eps}{(1-\xi)} < \beta,
\end{align*}
since $d_\G(\widetilde{g}(v_i), \widetilde{g}(\widehat{\sigma}_l))<(1-\xi)\beta-\xi\eps$ by the fact that $\widetilde{g}$ is simplicial. Since $g(v_i)=(\Phi\circ\widetilde{g})(v_i)$
\[[g(v_0), g(v_1), \ldots, g(v_l), (\Phi\circ\widetilde{g})(\widehat{\sigma}_l)]\]
is a simplex in $\Ri^\eps_{\beta}(\S)$.
Thus the assumptions of Lemma~\ref{lem:barycenter-map-lemma} are satisfied implying implies that $g$ and $\Phi\circ\tilde{g}$ induce homotopic maps and 
\[
\pi_\ast(\Phi)([\widetilde{g}])=[\Phi\circ\widetilde{g}]=[g],
\]
which yields the claim that $\pi_\ast(\Phi)$ is an epimorphism. 

Applying Whitehead's Theorem yields the desired homotopy equivalence 
$\Ri^\eps_\beta(\S)\simeq \G$.
\end{proof}
%For completeness, we provide the proof in Appendix.
Fixing $\xi=1/6$, we get a simpler but weaker statement.
\begin{corollary}[Simpler Topological Reconstruction]\label{cor:rips}
Let $\G \subset \mathbb{R}^N$ be a compact, connected metric graph.  
For any positive $\beta<\ell(\G)/4$, choose a positive $\eps\leq\beta/3$ such that $\delta^{\eps}_{\beta}(\G)\leq8/7$. 
If $\S\subset \R^N$ is compact and $d_H(\G,\S)<\eps/12$, then have a homotopy equivalence $\Ri^\eps_\beta(\S)\simeq\G$.
\end{corollary}

\section{Shadow of Simplicial Complexes}\label{sec:shadow}
Let $\K$ be an abstract simplicial complex with vertices in $\R^N$, i.e., $\K^{(0)}\subset\R^N$. 
In this section, we define the shadow (or \emph{geometric projection}) of $\K$ as a subset of $\R^N$ and study the natural shadow projection map. 
%We begin by defining the shadow projection map on the geometric realization $|\K|$ of an abstract simplicial complex $\K$.

The \emph{shadow projection} map $p\colon|\K|\to\mathbb{R}^N$ sends a vertex $v\in\K^{(0)}$ to the corresponding point in $\mathbb{R}^N$ then extends linearly to all points of the geometric realization $|\K|$.
Note that the project map is continuous.
\begin{definition}[Shadow]
We define the \emph{shadow} of $\K$ as its image under the projection map $p$, i.e.,
\[
\sh(\K)\coloneqq
\bigcup_{\sigma=[v_0,v_1,\ldots,v_k]\in\K}\mathrm{CH}(\sigma),
\]
where $\mathrm{CH}(\cdot)$ denotes the convex hull of a subset in $\mathbb{R}^N$. 
\end{definition}
Since the shadow is a polyhedral subset of $\R^N$, it can be realized by an $N$-dimensional simplicial complex.
We now describe a special simplicial complex decomposition of the \emph{shadow} in $\R^2$; see Figure~\ref{fig:shadow}.
We call it the \emph{shadow complex} and denote it by $\sc(\K)$.
\begin{enumerate}[(A)]
\item A \emph{shadow vertex} $v\in\sc(\K)$ is either $v\in\K^{(0)}$ or a transverse intersection of $p(e_1)$ and $p(e_2)$ for edges $e_1,e_2\in\K^{(1)}$. The transverse intersections are shown in red in Figure~\ref{fig:shadow}.
%\item[Edge:] A \emph{shadow edge} is an edge between two shadow vertices such that it does not contain another vertex of the shadow. 
\item Triangulate the planar shadow using the shadow vertices such that a shadow edge or face does not contain any other vertices of the shadow. 
Consequently, the realization of any shadow simplex $\sigma\in\sc(\K)$ is contained in $p(\tau)$ for some $\tau\in\K$.
\end{enumerate}

