\section{Geometric Reconstruction using Vietoris--Rips Shadow}\label{sec:geom}
This section considers the geometric reconstruction of a Euclidean graph $\G$ from a noisy Euclidean sample $\S$ using the shadow of Vietoris--Rips complexes.
We assume that both the graph and sample are hosted in the plane, i.e., $N=2$.
For topological reconstruction in Section~\ref{sec:top}, $\G$ is assumed to be only compact and connected.
However, for geometric reconstruction, we impose a few more assumptions on $\G$.

\subsection{Assumptions}\label{sec:assumptions}
\begin{enumerate}
\item[(A1)] $\G$ is compact and connected with finitely many edges;
\item[(A2)] any two edges of $\G$ are incident to at most one vertex;
\item[(A3)] each (open) edge of $\G$ is locally Lipschitz and at least $C^1$;
\item[(A4)] the tangents of each pair of incident edges $e_1,e_2\in\mathscr{E}(\G)$ of $(\G)$ make an angle in $(0,\pi)$, and is denoted by $\angle{e_1e_2}$.
We set $\angle{e_1e_2}=\infty$ if $e_1,e_2$ are not incident.
\end{enumerate}

\subsection{Shadow Radius}
For a graph $\G$ having properties (A1--A4), we first define the following quantity:
\begin{equation}\label{eq:theta}
\Theta\coloneqq
\cos^2{\left(\frac{1}{2}\min_{e_1,e_2\in \mathscr{E}(\G)}\angle{e_1e_2}\right)}.
%\min\left\{\frac{2}{3}, \cos^2{\left(\frac{1}{2}\min_{e_1,e_2\in \mathscr{E}(\G)}\angle{e_1e_2}\right)}\right\}.
\end{equation}
Clearly, $0<\Theta<1$, due to the fact that $\angle{e_1e_2}\in(0, \pi)$ for $e_1, e_2\in\mathscr{E}(\G)$.
%\sush{Justify why $\theta\leq\frac{\pi}{2}$}
We are now ready to define the shadow radius.
\begin{definition}[Shadow Radius]\label{def:shadow}
Let $\G\subset\R^2$ be a graph. 
The \emph{shadow radius} of $\G$, denoted $\Delta(\G)$, is defined as the least upper bound of $r\geq0$ satisfying the following property:

($\star$) For $a, b\in \G$ with $d_\G(a,b)\leq r$ if $q\in \G\cap ab^\eps$ for some $0\leq\eps\leq\frac{1}{2}(1-\Theta)^{3/2}d_\G(a,b)$, then 
\[\min\left\{d_\G(a, q),d_\G(b,q)\right\}\leq\frac{1+\Theta}{2} d_\G(a,b)+\frac{\eps}{1-\Theta}.\]
\end{definition}
Here, $ab^\eps$ denotes the Euclidean $\eps$-thickening of the segment $ab$.
If $\G$ satisfies assumptions (A1--A4), we show that its shadow radius is positive.
\begin{proposition}[Positivity of Shadow Radius]\label{prop:shadow-radius}
For a planar graph $\G$ having properties (A1--A4), its shadow radius $\Delta(\G)>0$.
\end{proposition}
\begin{proof}
Let $\delta$ be a small positive number such that 
\begin{equation}\label{eq:delta}
\text{(i) }\delta\leq\Theta,
\text{ (ii) }(1+\delta)\leq\frac{1}{\sqrt{1-\Theta}}, \text{ (iii) }2\delta+\Theta\leq 1,
\text{ and (iv) }(1+\delta)(\Theta+\delta)\leq\frac{1+\Theta}{2}.
\end{equation}
Such $\delta$ can be chosen since $0<\Theta<1$.

Next, we pick sufficiently small $0<r<\ell(\G)/4$ such that: 
\begin{itemize}
\item due to the assumption that each edge is $C^1$ and locally Lipschitz, both $a,b$ lying on the same edge of $\G$ with $\norm{a-b}\leq r$ implies
\begin{equation}\label{eq:C^1-appx}
\text{(i) }d_\G(a,b)\leq (1+\delta)\overline{ab}~\text{ and (ii) }
ab^\frac{d_\G(a,b)}{2}\text{ contains the geodesic joining }a,b.
\end{equation} 
\item if $a,b\in\G$ with $d_\G(a,b)\leq r$ lie on two distinct edges $e_a,e_b$ of $\G$ incident to a vertex $v$, respectively,then
\begin{equation}\label{eq:C^1-angle}
\left|\cos^2{\frac{\angle{avb}}{2}}-\cos^2{\frac{\angle{e_ae_b}}{2}}\right|\leq\delta.
\end{equation} 
\item if $d_\G(a,b)\leq r$ and $q\in \G\cap ab^\eps$ for some $0\leq\eps\leq[2(1-\Theta)]^{3/2}d_\G(a,b)$, then one of the following must happen:
\begin{enumerate}[(A)]
\item at least one of the pairs $(a,q)$ or $(b,q)$ belong to the same edge of $\G$ as Figure~\ref{fig:shadow-rad-cases}(A);
%with \[\min\{d_\G(a, q), d_\G(b, q)\}\leq(1+\delta)\eps;\]
\item $a,b$ belong to the same edge $e_a$ but $q$ belongs to a different edge $e_q$ Figure~\ref{fig:shadow-rad-cases}(B);
\item $a, b, q$ lie on three distinct edges of $\G$ incident to a common vertex $v\in\mathscr{V}(\G)$ as Figure~\ref{fig:shadow-rad-cases}(C). 
\end{enumerate}
\end{itemize}

