In the rest of the proof, we show that the property ($\star$) of Definition~\ref{def:shadow} holds in each of the above two cases.


\subsection*{Case (A)}
In this case, if $q$ lies on the geodesic joining $a$ and $b$, then we trivially get
\[\min\{d_\G(a, q), d_\G(b, q)\}\leq\frac{1+\Theta}{2}d_\G(a,b).\]
Otherwise, if $q$ lies outside the geodesic as in Figure~\ref{fig:shadow-rad-cases}(A), then $\max\{\norm{q-a}, \norm{q-b}\}\leq(d_\G(a,b)/2+\eps)$ due to~[\ref{eq:C^1-appx}(ii)].
Since $d_\G(a,b)/2+\eps\leq r$,~[\ref{eq:C^1-appx}(i)] implies 
\begin{align*}
\min\{d_\G(a,q), d_\G(b,q)\}&\leq(1+\delta)(d_\G(a,b)/2+\eps)\\
&=\frac{1+\delta}{2}d_\G(a,b))+(1+\delta)\eps \\
&\leq\frac{1+\Theta}{2}d_\G(a,b)+\frac{\eps}{\sqrt{1-\Theta}},\text{ due to~[\ref{eq:delta}(i)] and due to~[\ref{eq:delta}(ii)], resp.}\\
&\leq\frac{1+\Theta}{2}d_\G(a,b)+\frac{\eps}{1-\Theta}.
\end{align*}

\subsection*{Case (B)}
In this case, we assume $a,b\in e_a$ and $q\in e_b$.
due to~[\ref{eq:C^1-appx}(ii)], there exists a point $p$ on the geodesic joining $a,b$ such that $\overline{pq}\leq d_\G(a,b)/2+\eps$.
We note that
\[
\frac{\overline{pv}}{\sin{\angle{pqv}}}
=\frac{\overline{qv}}{\sin{\angle{vpq}}}
=\frac{\overline{pq}}{\sin{\angle{pvq}}}.
\]
So, 
\begin{align*}
\overline{pv}+\overline{qv} &=\frac{\sin{\angle{pqv}}+\sin{\angle{vpq}}}{\sin{\angle{pvq}}}\overline{pq} \leq\frac{\sin{\angle{pqv}}+\sin{\angle{vpq}}}{\sin{\angle{pvq}}}(d_\G(a,b)/2+\eps)\\
&=\frac{2\sin{\frac{\angle{pqv}+\angle{vpq}}{2}}\cos{\frac{\angle{pqv}-\angle{vpq}}{2}}}{2\sin{\frac{\angle{pvq}}{2}}\cos{\frac{\angle{pvq}}{2}}}(d_\G(a,b)/2+\eps) \\
&=\frac{\cos{\frac{\angle{pvq}}{2}}\cos{\frac{\angle{pqv}-\angle{vpq}}{2}}}{\sin{\frac{\angle{pvq}}{2}}\cos{\frac{\angle{pvq}}{2}}}(d_\G(a,b)/2+\eps)\\
&\leq\frac{d_\G(a,b)/2+\eps}{\sin{\frac{\angle{pvq}}{2}}}
=\frac{d_\G(a,b)/2+\eps}{\sqrt{1-\cos^2{\frac{\angle{pvq}}{2}}}}
\leq\frac{d_\G(a,b)/2+\eps}{\sqrt{1-\Theta-\delta}}
\text{ from \eqref{eq:C^1-angle}}\\
&<\frac{d_\G(a,b)/2+\eps}{\sqrt{1-\Theta}}.
\end{align*}
From~[\ref{eq:C^1-appx}(i)], we get using~[\ref{eq:delta}(ii)]
\[
d_\G(p,q)\leq\frac{(1+\delta)(d_\G(a,b)/2+\eps)}{\sqrt{1-\Theta}}
\leq\frac{1+\delta}{2\sqrt{1-\Theta}}d_\G(a,b)+\frac{(1+\delta)}{\sqrt{1-\Theta}}\eps
\leq\frac{d_\G(a,b)}{2(1-\Theta)}+\frac{\eps}{1-\Theta}.
\]
Since $q$ lies on the geodesic joining $a$ and $b$, conclude \[
\min\{d_\G(a,q), d_\G(b,q)\}
\leq
\frac{d_\G(a,b)}{2(1-\Theta)}+\frac{\eps}{1-\Theta}
<\frac{1+\Theta}{2}d_\G(a,b)+\frac{\eps}{1-\Theta}.
\]


\subsection*{Case (C)}
In this case, we have, without any loss of generality, from Proposition~\ref{prop:optimization} that 
\begin{align}
\overline{av}+\overline{pv}
&\leq\cos^2{\left(\tfrac{\min\{\phi,\varphi\}}{2}\right)}(\overline{av}+\overline{bv})\nonumber\\
&\leq\left[\cos^2{\left(\tfrac{\min\{\angle{e_ae_b},\angle{e_be_c}\}}{2}\right)}+\delta\right](\overline{av}+\overline{bv}),~\text{ due to \eqref{eq:C^1-angle}}\nonumber\\
&\leq(\Theta+\delta)(\overline{av}+\overline{bv}),~\text{ from the definition of}~\Theta\nonumber\\
&\leq(\Theta+\delta)[d_\G(a,v)+d_\G(v,b)]
=(\Theta+\delta)d_\G(a,b),~\text{ since }d_\G(a,b)\leq r<\ell(\G)/2
\label{eq:estimate-1}.
\end{align}
%So, $\overline{pv}\leq(\Theta+\delta)d_\G(a,b)$.
On the other hand, since $q\in ab^\eps$, again from Proposition~\ref{prop:optimization} we get 
\begin{equation}\label{eq:estimate-2}
\overline{pq}
\leq\frac{\eps}{\sqrt{2(1-\cos^2{(\min\{\angle{e_ae_b}, \angle{e_b,e_c}\}/2)})}}
\leq\frac{\eps}{\sqrt{2(1-\Theta-\delta)}}
\leq\frac{\eps}{\sqrt{1-\Theta}}.    
\end{equation}
The last inequality is due to~[\ref{eq:delta}(iii)].
From~\eqref{eq:estimate-1} and~\eqref{eq:estimate-2}, we now get
\[
\overline{vq}\leq(\overline{av}+\overline{vp})+\overline{pq}
\leq(\Theta+\delta)d_\G(a,b)+\tfrac{\eps}{\sqrt{1-\Theta}}
\leq\left[(\Theta+\delta)+\tfrac{(1-\Theta)^{3/2}}{2\sqrt{1-\Theta}}\right]r
=\tfrac{1}{2}(2\delta+\Theta+1)r\leq r.
\]
Again, the last inequality is due to~[\ref{eq:delta}(iii)].

As a result, \eqref{eq:C^1-appx} implies $d_\G(v,q)\leq(1+\delta)\overline{qv}$.
Putting everything together, we finally get
\begin{align*}
d_\G(a, q) &= d_\G(a,v)+d_\G(v, q),\text{ since }d_\G(a,q)\leq2r<\ell(\G)/2\\ 
&\leq (1+\delta)(\overline{av}+\overline{vq}),~\text{due to \eqref{eq:C^1-appx}}\\ 
&=(1+\delta)(\overline{av}+[\overline{vp}+\overline{pq}])
=(1+\delta)([\overline{av}+\overline{vp}]+\overline{pq})\\
&\leq(1+\delta)\left[(\Theta+\delta)d_\G(a,b)+\tfrac{\eps}{\sqrt{1-\Theta}}\right],~\text{ adding \eqref{eq:estimate-1} and \eqref{eq:estimate-2} }\\
&\leq(1+\delta)(\Theta+\delta)d_\G(a,b)+\tfrac{(1+\delta)}{\sqrt{1-\Theta}}\eps\\
&\leq\frac{1+\Theta}{2} d_\G(a,b)+\frac{\eps}{1-\Theta},\text{ from~[\ref{eq:delta}(iv)] and~[\ref{eq:delta}(ii)], respectively}.
\end{align*}
Hence the proof.
\end{proof}

\begin{proposition}\label{prop:optimization}
Let $\triangle avp$ and $\triangle bvp$ be two triangles as shown in Figure~\ref{fig:shadow-rad} with $\angle{avp}=\phi$, $\angle{bvp}=\varphi$, and $\overline{av}+\overline{vb}=r$. 
Then, 
\[
\min\left\{\overline{av}+\overline{pv}, \overline{bv}+\overline{pv}\right\}
%\leq
%\frac{1}{1+\tan{\frac{\phi}{2}}\tan{\frac{\varphi}{2}}}r
\leq\cos^2{\left(\frac{\min\{\phi,\varphi\}}{2}\right)}r.
\]
Moreover, if $q\in ab^\eps$, then 
$\overline{pq}\leq\eps/\sqrt{2\left[1-\cos^2{\frac{\min\{\phi,\varphi\}}{2}}\right]}$.
\end{proposition}
\begin{proof}
Without any loss of generality, we assume that 
$\phi\geq\varphi$.
Let $\theta\coloneqq\angle{apv}$ and 
$a(\theta)\coloneqq\overline{av}$, $b(\theta)\coloneqq \overline{bv}$, $p(\theta)\coloneqq\overline{pv}$.
We immediately note from the triangles that $\theta\in(\varphi, \pi-\phi)$.

Under the constraints that (i) $\phi,\varphi$ are fixed angles and (ii) the sum $a(\theta)+b(\theta)=r$ is constant, we find the maximum value of $\min\left\{a(\theta)+p(\theta),b(\theta)+p(\theta)\right\}$ for $\theta\in(\varphi, \pi-\phi)$.

From the smaller triangles in Figure~\ref{fig:shadow-rad}, we have
\begin{equation}\label{eq:a-p-b}
\frac{p(\theta)}{\sin{(\theta+\phi)}}=\frac{a(\theta)}{\sin{\theta}}\text{ and }
\frac{p(\theta)}{\sin{(\theta-\varphi)}}=\frac{b(\theta)}{\sin{\theta}}.
\end{equation}

