Adding them, we get
\begin{align*}
& p(\theta)\left[ \frac{\sin{\theta}}{\sin{(\theta+\phi)}} + \frac{\sin{\theta}}{\sin{(\theta-\varphi)}} \right]=a(\theta)+b(\theta)\coloneqq r \\
\implies &p(\theta)=\frac{r}{\sin{\theta}}\bigg/\left[ \frac{1}{\sin{(\theta+\phi)}} + \frac{1}{\sin{(\theta-\varphi)}} \right].
\end{align*}
Note from \eqref{eq:a-p-b} that $a(\theta)=b(\theta)$ implies $\theta=\frac{\pi}{2}-\frac{\phi-\varphi}{2}$. 
We divide the domain $(\varphi,\pi-\phi)$ of $\theta$ into $I_a\coloneqq\left(\varphi,\frac{\pi}{2}-\frac{\phi-\varphi}{2}\right]$ and $I_b\coloneqq\left(\frac{\pi}{2}-\frac{\phi-\varphi}{2}, \pi-\phi\right)$.

\subsection*{($\pmb{I_a}$)}
For $\theta\in I_a$, we maximize 
\[x(\theta)\coloneqq p(\theta)+a(\theta)=r\left[ \frac{1}{\sin{\theta}} + \frac{1}{\sin{(\theta+\phi)}} \right]\bigg/\left[ \frac{1}{\sin{(\theta+\phi)}} + \frac{1}{\sin{(\theta-\varphi)}} \right].\]
We argue that $x(\theta)$ is an increasing function by showing the positivity of its derivative:
%\begin{align*}
%x'(\theta)=[\cot{\theta}\csc{\theta}\{\csc{(\varphi-\theta)}-\csc{(\phi+\theta)}\} 
%+\cot{(\phi+\theta)}\csc{(\phi+\theta)}\{\csc{(\varphi-\theta)}+\csc{\theta}\}+ \\
%\{\csc{(\phi+\theta)}+\csc{\theta}\}\cot{(\varphi-\theta)}\csc{(\varphi-\theta)}]/[\csc{(\phi+\theta)}-\csc{(\varphi-\theta)}]^2.
%\end{align*}
\begin{align*}
x'(\theta)=\tfrac{1}{2}\cos{\tfrac{\phi}{2}}\sin{\tfrac{\varphi}{2}}\sec{\tfrac{\phi+\varphi}{2}}\csc^2{\theta}
\csc^2{\tfrac{\phi-\varphi+2\theta}{2}}
\big[1+\cos{(\varphi-2\theta)-\cos{(\phi-\varphi+2\theta)}-\cos{(\phi+2\theta)}}\big].
\end{align*}
The last term (under brackets) is always positive. 
Indeed, its derivative is $2\sin{(\phi-\varphi+2\theta)}+2\sin{(\phi+2\theta)}+2\sin{(\varphi-2\theta)}>0$ and its value at $\theta=0$ is $4\sin{\frac{\phi}{2}}\cos{\frac{\varphi}{2}}\sin{\frac{\phi-\varphi}{2}}>0$ since $\varphi/2<\pi/2$. 
So, we conclude that $x(\theta)$ is an increasing function of $\theta$.

\subsection*{($\pmb{I_b}$)}
For $\theta\in I_b$, we maximize 
\[y(\theta)\coloneqq p(\theta)+b(\theta)=r\left[ \frac{1}{\sin{\theta}} + \frac{1}{\sin{(\theta-\varphi)}} \right]\bigg/\left[ \frac{1}{\sin{(\theta+\phi)}} + \frac{1}{\sin{(\theta-\varphi)}} \right].\]
We argue that $y(\theta)$ is a decreasing function by showing the negativity of its derivative:
\begin{align*}
y'(\theta)=\tfrac{1}{2}\cos{\tfrac{\phi}{2}}\sin{\tfrac{\varphi}{2}}\sec{\tfrac{\phi+\varphi}{2}}\csc^2{\theta}
\csc^2{\tfrac{\phi-\varphi+2\theta}{2}}
\big[\cos{(\phi-\varphi+2\theta)}-\cos{(\phi+2\theta)}+\cos{(\varphi-2\theta)}-1\big].
\end{align*}
The last term (under brackets) is always negative. 
Indeed, $\theta\geq\frac{\pi}{2}-\frac{\phi-\varphi}{2}$ implies that $\cos{(\phi-\varphi+2\theta)}\leq\cos{(\phi+2\theta)}$ since the cosine function is increasing in the interval $[\pi, 2\pi]$.

As a consequence, for any $\theta\in(\varphi, \pi-\phi)$:
\begin{align*}
\min\{x(\theta), y(\theta)\} &\leq
x\left(\tfrac{\pi}{2}-\frac{\phi-\varphi}{2}\right)
=y\left(\tfrac{\pi}{2}-\frac{\phi-\varphi}{2}\right) \\
&=r\left[ \frac{1}{\cos{\frac{\phi-\varphi}{2}}} + \frac{1}{\cos{\frac{\phi+\varphi}{2}}} \right]\bigg/\frac{2}{\cos{\frac{\phi+\varphi}{2}}}\\
&=\frac{\cos{\frac{\phi+\varphi}{2}}+\cos{\frac{\phi-\varphi}{2}}}{2\cos{\frac{\phi-\varphi}{2}}}r
=\frac{2\cos{\frac{\phi}{2}}\cos{\frac{\varphi}{2}}}{2\cos{\frac{\phi-\varphi}{2}}}r\\
&=\frac{\cos{\frac{\phi}{2}}\cos{\frac{\varphi}{2}}}{\cos{\frac{\phi}{2}}\cos{\frac{\varphi}{2}}+\sin{\frac{\phi}{2}}\sin{\frac{\varphi}{2}}}r\\
&=\frac{1}{1+\tan{\frac{\phi}{2}}\tan{\frac{\varphi}{2}}}r\leq\frac{1}{1+\tan^2{\frac{\varphi}{2}}}r,\text{ since }\phi\geq\varphi\\
&=\cos^2\frac{\varphi}{2}r.
\end{align*}

Finally, if $q\in ab^\eps$, then the top-most triangle implies that $\overline{pq}\leq\csc{(\alpha)}\eps$, where is $\alpha<\pi/2$ is either $\theta$ or $(\pi-\theta)$.
Since $\theta\in(\varphi, \pi-\phi)$, we then have $\csc{\alpha}\leq\csc{\varphi}$. Therefore, $\overline{pq}\leq\csc{(\varphi)}\eps=\eps/\sqrt{2[1-\cos^2{(\varphi/2)}]}$.

This completes the proof.
\end{proof}

\subsection{Homotopy Equivalence}
We now present our $1$-connectivity argument for the shadow projection.
We start with the following technical lemma.
\begin{proposition}[Intersection]
\label{prop:intersection} Let $\G \subset \mathbb{R}^2$ be a planar graph having properties (A1--A4) and $\S \subset \mathbb{R}^2$ such that $d_H(\S,\G) < \frac{1}{2}\xi\varepsilon$ for some $\xi \in (0,1)$ and $0\leq\eps<\frac{1}{2(1+\xi)}(1-\Theta)^{3/2}\Delta(\G)$. 
Let $A, B, C, D \in \S$ such that $\max\{d_\G(a,b), d_\G(c,d)\}<\Delta(\G)$ and $AB$ intersects $CD$.
Then, there exist $E,F\in \S$ such that either
\begin{enumerate}[(A)]
\item $\max\{\diam^\eps_\S\{A, B, E\},\diam^\eps_\S\{C, D, E\}\}\leq\max\{d^\eps_\S(A,B),d^\eps_\S(C,D)\}$, or
\item $\diam^\eps_\S\{C, D, E, F\}\leq d^\eps_\S(C, D)$ and $EF$ intersects $AB$ with \[
\diam^\eps_\S\{A, E, F\}\leq\frac{(1-\Theta^2) d_\G(a,b)+2(1+2\xi-\xi\Theta)\eps}{2(1-\xi)(1-\Theta)}.
\]
\end{enumerate}
%As a consequence, $\diam_\eps\{A, B, C, D\}\leq2\max\left\{d^\eps_\S(A,B),d^\eps_\S(C,D), \frac{\Theta(\G)d_\G(a,b)+(2-\xi)\eps}{1-\xi}\right\}$.
\end{proposition}

\begin{proof}
Let $\mathcal{P}=\{P_i\}_{i=0}^{n+1}\in\mathscr{P}^\eps_\S(A,B)$ and $\mathcal{Q}=\{Q_j\}_{j=0}^{m+1}\in\mathscr{P}^\eps_\S(C,D)$ be the shortest $\eps$-paths, i.e., $d^\eps_\S(A,B)=L(\mathcal P)$ and $d^\eps_\S(C,D)=L(\mathcal Q)$. We now consider the following two cases, depending on whether the images of $\mathcal P$ and $\mathcal Q$ intersect as subsets of $\mathbb{R}^2$. \\

\noindent\textbf{Case A.}
Let us assume that the $\eps$--paths intersect at a point $I\in\R^2$ in this case.
Consequently, there exist $0\leq i\leq n$ and $0\leq j\leq m$ such that $I$ is the point of intersection of the segments $P_iP_{i+1}$ and $Q_jQ_{j+1}$, creating four (possibly degenerate) half-segments: $P_iI, P_{i+1}I, Q_jI, Q_{j+1}I$. 

Without any loss of generality, we assume that $P_iI$ is the shortest of the four.
As a result, we note from the triangle inequality that 
\[\overline{P_iQ_j}\leq \overline{P_iI}+ \overline{Q_jI}\leq \overline{Q_{j+1}I}+ \overline{Q_jI}=\overline{Q_iQ_{j+1}}\leq\eps.\] 
Similarly, $\overline{P_iQ_{j+1}}\leq\eps$.

Set $E\coloneqq P_i$ to immediately note that $d^\eps_\S(A,B,E)\leq d^\eps_\S(A,B)$.
Moreover, it implies that $\mathcal Q'\coloneqq\{C=Q_0, Q_1, \ldots, Q_{j}, P_i=E\}$ and $\mathcal Q''\coloneqq\{E=P_i, Q_{j+1}, \ldots, Q_{m}, Q_{m+1}=D\}$ are $\eps$--paths with their length at most $L(\mathcal Q)$, implying $\diam^\eps_\S(C, D, E)\leq d^\eps_\S(C,D)$. 

Therefore, we get $\max\{\diam^\eps_
S\{A, B, E\},\diam^\eps_\S\{C, D, E\}\}\leq\max\{d^\eps_\S(A,B),d^\eps_\S(C,D)\}$. \\

\noindent\textbf{Case B.}
In this case, we assume the $\eps$--paths don't interact.
The Jordan curve theorem \cite{Moise1977} implies, without any loss of generality, that the image of $AB$ transversely intersects $\mathcal Q$ as subsets of the plane.
Consequently, there exists $0\leq j\leq m$ such that $Q_iQ_{j+1}$ transversely intersects $AB$.
Since $\norm{Q_j-Q_{j+1}}<\eps$, we note that both $Q_j,Q_{j+1}\in AB^{\eps}$.
Let $a,b,q_j,q_{j+1}\in \G$ be such that $\max\{|A-a|, |B-b|,|Q_j-q_j|,|Q_{j+1}-q_{j+1}|\}<\frac{1}{2}\xi\eps$.
The triangle inequality implies that both $q_j,q_{j+1}\in ab^{(1+\xi)\eps}$.

By the definition of $\Delta(\G)$ and the fact that $(1+\xi)\eps<(1-\Theta)^{3/2}\Delta(\G)/2$, we have
\[
\max\{d_\G(a,q_j),d_\G(a,q_{j+1})\leq\tfrac{1+\Theta}{2}d_\G(a,b)+\tfrac{(1+\xi)\eps}{1-\Theta}.
\]
So, Proposition~\ref{prop:d^esp-d^L-estimate} implies that 
\[
\max\{d^\eps_\S(A,Q_j),d^\eps_\S(A,Q_{j+1})\}
\leq\tfrac{\max\{d_\G(a,q_j),d_\G(a,q_{j+1})\}+\xi\eps}{1-\xi}
\leq\tfrac{(1-\Theta^2) d_\G(a,b)+2(1+2\xi-\xi\Theta)\eps}{2(1-\xi)(1-\Theta)}.
\]
Set $E\coloneqq Q_j$ and $F\coloneqq Q_{j+1}$ to immediately note that $\diam_\eps(C,D,E, F)\leq d^\eps_\S(C,D)$.
Our argument above implies 
\[
\diam_\eps(A, E, F)\leq\frac{(1-\Theta^2) d_\G(a,b)+2(1+2\xi-\xi\Theta)\eps}{2(1-\xi)(1-\Theta)}.
\]
This completes the proof.
\end{proof}

We immediately note the following consequence.
\begin{corollary}[Intersection]\label{cor:intersection} 
Under the assumptions of Proposition~\ref{prop:intersection}, we have 
\[\diam_\eps\{A, B, C, D\}\leq2\max\left\{d^\eps_\S(A,B),d^\eps_\S(C,D),\frac{(1-\Theta^2) d_\G(a,b)+2(1+2\xi-\xi\Theta)\eps}{2(1-\xi)(1-\Theta)}.
\right\}.\]
\end{corollary}

Using the lifting condition introduced in Definition~\ref{def:lifting-cond}, we now show the surjectivity of the shadow projection.
\begin{lemma}[Surjectivity]\label{lem:surjection}
Let $\G \subset \mathbb{R}^2$ a graph having properties (A1--A4). 
Fix any $\xi\in\left(0,\frac{1-\Theta}{6}\right)$.
For any positive $\beta<\Delta(\G)$, choose\footnote{It is possible to choose such small $\eps$, as $\delta^\eps_\beta(\G)\to1$ as $\eps\to0$} 
a positive $\eps\leq\frac{(1-\Theta)(1-\Theta-6\xi)}{12}\beta$ such that $\delta^{\eps}_{\beta}(\G)\leq\frac{1+2\xi}{1+\xi}$. 
If $\S\subset \R^2$ is compact and $d_H(\G,\S)<\tfrac{1}{2}\xi\eps$, then we the shadow projection of $\mathcal{K}=\Ri^\eps_\beta(\S)$ induces a surjective homomorphism on $\pi_1$. 
\end{lemma}
\begin{proof}
%We first note \sush{from $\Theta(\G)\geq1/2$} that
%\[
%\eps\leq\frac{[1-\Theta(\G)]-2\Theta(\G)\xi-\xi^2}{2+[1+\Theta(\G)]\xi+[2\Theta(\G)-1]\xi^2}\beta
%\leq\frac{1-\xi-\Theta(\G)}{2-\xi^2}\beta
%<\frac{1-\xi-\Theta(\G)}{2-\xi}\beta.
%\]
Let $[AB],[CD]\in\K$ such that $AB$ and $CD$ intersect in the shadow of $\K$.
From the definition of $\K$, we have $\max\{d^\eps_\S(A,B), d^\eps_\S(C,D)\}<\beta$.
Since $\beta<\Delta(\G)$ and 
\begin{align*}
\eps &\leq\frac{(1-\Theta)(1-\Theta-6\xi)}{12}\beta
<\frac{(1-\Theta)^2}{12}\beta\leq\frac{(1-\Theta)^{3/2}}{12}\beta,\text{ since }\Theta<1 \\
&<\frac{(1-\Theta)^{3/2}}{2(1+\xi)}\beta,
\text{ since }\xi<1\\
&<\frac{(1-\Theta)^{3/2}}{2(1+\xi)}\Delta(\G),
\end{align*}
Proposition~\ref{prop:intersection} implies that there must exist $E, F\in \S$ such that 
\begin{enumerate}[(A)]
\item $\max\{\diam_\eps\{A, B, E\},\diam_\eps\{C, D, E\}\}\leq\max\{d^\eps_\S(A,B),d^\eps_\S(C,D)\}<\beta$, or
\item $\diam^\eps_\S\{C, D, E, F\}\leq d^\eps_\S(C, D)$ and $EF$ intersects $AB$ with 
\begin{equation}\label{eq:diameter-1}
\diam^\eps_\S\{A, E, F\}\leq\tfrac{(1-\Theta^2) d_\G(a,b)+2(1+2\xi-\xi\Theta)\eps}{2(1-\xi)(1-\Theta)}.
\end{equation}
\end{enumerate}
In the latter case, we argue that $\diam^\eps_\S\{A, E, F\}<\beta$.
The fact is true if $d_\G(a,b)<\frac{2(1-\xi)(1-\Theta)\beta-2(1+2\xi-\xi\Theta)\eps}{(1-\Theta)^2}$. 
This can be easily checked by plugging the estimate in \eqref{eq:diameter-1}.
So, we consider the non-trivial case by assuming $d_\G(a,b)\geq\frac{2(1-\xi)(1-\Theta)\beta-2(1+2\xi-\xi\Theta)\eps}{(1-\Theta)^2}$ to get
\begin{align*}
d_\G(a,b)&\geq\frac{2(1-\xi)(1-\Theta)\beta-2(1+2\xi-\xi\Theta)\eps}{(1-\Theta)^2}\\
&\geq\frac{2(1-\xi)(1-\Theta)\beta-6\eps}{(1-\Theta)^2},
\text{ since }(1+2\xi-\xi\Theta)\leq(1+2\xi)\leq3\\
&\geq\frac{2(1-\xi)(1-\Theta)\beta-6\frac{(1-\Theta)(1-\Theta-6\xi)}{12}\beta}{(1-\Theta)^2}
,\text{ since }\eps\leq\frac{(1-\Theta)(1-\Theta-6\xi)}{12}\\
&=\frac{4(1-\xi)-(1-\Theta-6\xi)}{2(1-\Theta)}\beta\\
&=\frac{3+2\xi+\Theta}{2(1-\Theta)}\beta\\
&\geq\frac{3}{2}\beta>\beta.\\
\end{align*}
Therefore, in this case:
\begin{align*}
\diam_\eps\{A, E, F\} &\leq\frac{(1-\Theta^2) d_\G(a,b)+2(1+2\xi-\xi\Theta)\eps}{2(1-\xi)(1-\Theta)}\\
&\leq\frac{(1-\Theta^2)\delta^\eps_\beta(\G)(\beta+\xi\eps)+2(1+2\xi-\xi\Theta)\eps}{2(1-\xi)(1-\Theta)},\text{ since }d_\G(a,b)\geq\beta\\
&\leq\beta,\text{ since }\delta^\eps_\beta(\G)\leq\frac{1+2\xi}{1+\xi}\text{ and }\eps\leq\frac{(1-\Theta)(1-\Theta-6\xi)}{12}\beta.
\end{align*}


Consequently, $\K$ satisfies the lifting condition (Definition~\ref{def:lifting-cond}). 
Using Theorem~\ref{thm:shadow-surjection}, we then conclude the result.
\end{proof}

\begin{lemma}[Injectivity]\label{lem:injection}
Let $\G \subset \mathbb{R}^2$ a graph having properties (A1--A4).
Fix any $\xi\in\left(0,\frac{1-\Theta}{6}\right)$.
For any positive $\beta<\min\left\{\Delta(\G),\frac{\ell(\G)}{12}\right\}$, choose 
a positive $\eps\leq\frac{(1-\Theta)(1-\Theta-6\xi)}{12}\beta$ such that $\delta^{\eps}_{\beta}(\G)\leq\frac{1+2\xi}{1+\xi}$. 
If $\S\subset \R^2$ is compact and $d_H(\G,\S)<\tfrac{1}{2}\xi\eps$, then we the shadow projection of $\mathcal{K}=\Ri^\eps_\beta(\S)$ induces an injective homomorphism on $\pi_k$ for any $k\geq0$. 
\end{lemma}
\begin{proof}
We first note that $\xi\in\left(0,\frac{1}{4}\right)$ and $\eps\leq\beta/3$.
We can reuse Diagram~\ref{eq:rips_comm_diagram} from the proof of Theorem~\ref{thm:hom-eq}.
Consequently, we have the top row of the following diagram:
\begin{equation}\label{eq:rips_shadow_diagram}
\begin{tikzcd}
{|\Ri^L_{(1-\xi)\beta-\xi\varepsilon}(\G)|} && {|\Ri^\varepsilon_{\beta}(\S)|} && {|\Ri^L_{4\beta}(\G)|} \\ \\
&& {\sc(\Ri^\eps_\beta(\S))} &&
\arrow["p"', from=1-3, to=3-3]
\arrow["|\Psi|", from=1-3, to=1-5]
\arrow["|\Phi|", from=1-1, to=1-3]
\arrow[blue, "|\Psi'|"', from=3-3, to=1-5]
\end{tikzcd}
\end{equation}
Here, $\sc(\Ri^\eps_\beta(\S))$ denotes the shadow \emph{complex} of $\Ri^\eps_\beta(\S)$ as defined in Definition~\ref{def:shadow}.
We first define a simplicial map $\Psi'\colon\sc(\Ri^\eps_\beta(\S))\to\Ri^L_{4\beta}(\G)$ such that Diagram~\ref{eq:rips_shadow_diagram} of geometric realizations commutes up to homotopy.

Recall that the vertex set of $\sc(\Ri^\eps_\beta(\S))$ is $\S\sqcup \mathcal{I}$, where $\mathcal{I}$ denotes the set of new vertices due to transverse intersections of edges of $\Ri^\eps_\beta(\S)$ in the shadow.

Define the vertex map $\Psi'\colon \S\to \G$ so that $\Psi'|_\S\coloneqq\Psi$. 
For any $I\in \mathcal{I}$, there must exist $1$-simplices $\sigma=[AB]$ and $\tau=[CD]$ of $\Ri^\varepsilon_{\beta}(\S)$ so that $I$ lies on the intersection of the two Euclidean segments $AB$ and $CD$. 
Define $\Psi'(P)\coloneqq\Psi(A)$.

Now, we show that the map extends to a simplicial map.
Let $\sigma=[U,V]\in\sc(\Ri^\eps_\beta(\S))$ be a shadow $1$-simplex to show that $[\Psi'(U), \Psi'(V)]$ is a simplex of $\Ri^L_{4\beta}(\G)$. 
If both $U,V\in \S$, then there is nothing to show since $\Psi'|_\S=\Psi$ is already a simplicial map. 

Otherwise, by the construction of the shadow complex, there exists (possibly generate) $[ABC]\in\Ri^\eps_\beta(\S)$ with $\max\{d^\eps_\S(A,U),d^\eps_\S(B,V)\}\leq2\beta$
by Corollary~\ref{cor:intersection}.
Since $d_\S^\eps(A,B)<\beta$, the triangle inequality implies $d^\eps_\S(U,V)<3\beta$.
Following the same argument given in the proof of Theorem~\ref{thm:hom-eq}, we get $d_\G(\Psi'(U), \Psi'(V))<4\beta$ using \eqref{eq:diam-estimate-2}.
So, $\Psi'$ is a simplicial map.

Since $\Psi'|_\S=\Psi$ and the restriction of shadow projection $p|_\S$ is the identity on $\S$, the triangle in the diagram of realizations commutes up to homotopy.
Using the fact that $4\beta<\ell(\G)/3$ and following the injectivity argument used in the proof of Theorem~\ref{thm:hom-eq}, we conclude that $\Psi$ induces injective homomorphisms on homotopy groups. 
Since the diagram commutes up to homotopy, $p$ must also induce surjections on $\pi_k$ for any $k\geq0$.
\end{proof}

