\begin{proof}[Proof of Proposition~\ref{prop:radius}]
In the proof of Proposition~\ref{prop:center}, we saw that $c(A')$ is the (geodesic) midpoint of the two farthest points of $\mathcal A'$. 
Letting $r=\frac{1}{2}\diam_\G(\mathcal A)$, we note from Proposition~\ref{prop:center} that $\mathcal A'\subset \mathcal A\subset\overline{\B_\G(c(\mathcal A),r)}$. 
Also, the metric ball $\overline{\B_\G(c(\mathcal A),r)}$ is a geodesically convex subset of $\G$, due to the fact that $r<\ell(\G)/3$. 
So, we have that $c(\mathcal A')\in\overline{\B_\G(c(\mathcal A),r)}$. Hence, $d_\G(c(\mathcal A'),c(\mathcal A))\leq r=\frac{1}{2}\diam_\G(\mathcal A)$.
\end{proof}

\begin{proof}[Proof of Proposition~\ref{prop:delta_path}]
We consider the path $\gamma\colon[0,1]\to\R^N$ joining $a$ and $b$ by concatenating three pieces: the segment $[a,A]$ (of length $\leq\alpha$) with an $\eps$--path connecting $A$ and $B$ (of length $d^\eps_\S(A, B)$), and the segment $[B,b)]$ (of length $\leq \alpha$).

Since $\alpha<\eps/2$, it's not difficult to see that the image of $\gamma\subset \G^\eps$. 
This implies that $d_{\G^\eps}(a, b)\leq L(\gamma)\leq[d^\eps_\S(A,B)+2\alpha]$.
Since $d_\G(a,b)\geq R$, from the definition of restricted distortion, we now get
\[
d_\G(a,b)\leq\delta^\eps_R(\G)d_{\G^\eps}(a,b)\leq\delta^\eps_R(\G)\left[d^\eps_\S(A,B)+2\alpha\right].
\]
\end{proof}

\begin{proposition}[Path-connectedness]\label{prop:path-connected} 
Let $(\G,d_\G)$ be a path-connected graph and $(\S,d_\S)$ with $d_H(\G,\S)<\alpha$. 
Then the geometric complex of $\Ri^\eps_{\beta}(\S)$ is
path-connected for any $\beta\geq\eps>2\alpha$.
\end{proposition}

\begin{proof}
Let us denote by $\Ri_\beta(\G)$ and $\Ri_\beta(\S)$ the Euclidean Vietoris--Rips complexes of $\G$ and $\S$, respectively.

Let $A,B\in \S$ be arbitrary points.
Then, there exist points $a,b\in\G$ such that $\max\{\norm{a-A},\norm{b-B}<\alpha$. 
Since $\G$ is assumed to be path-connected, so is $\Ri_{\eps-2\alpha}(\G)$. 
As a result, there exists a sequence
$\{x_i\}_{i=0}^{m+1}\subset\G$ forming a path in $\Ri_{\eps-2\alpha}(\G)$ joining $a$ and $b$. 
In other words, $x_0=a$, $x_{m+1}=b$, and $\norm{x_i-x_{i+1}}<\eps-2\alpha$ for $0\leq i\leq m$. 
There is also a corresponding sequence $\{X_i\}_{i=0}^{m+1}\subset\S$ such that $X_0=A$, $X_{m+1}=B$, and
$\norm{X_i-x_i}<\alpha$ for all $i$. 
We note that
\[
\norm{X_i-X_{i+1}}\leq\norm{x_i-x_{i+1}}+2\alpha<(\eps-2\alpha)+2\alpha=\eps.
\]
Thus, the sequence $\{X_i\}$ produces a path in $\Ri_{\beta+2\eps}(\S)$ joining $A$ and $B$. 
So, the geometric complex of $\Ri_{\beta+2\eps}(\S)$ is path-connected.
Since $\beta\geq\eps$, we have
the inclusion $\Ri_{\eps}(\S)\hookrightarrow\Ri^\eps_{\beta}(\S)$.
We conclude that $\Ri^\eps_\beta(\S)$ is path-connected.
\end{proof}


