\section{Annex}\label{Annex}
\subsection{Force and pressure before relaxation}\label{Force and pressure before relaxation}
We start with the equations of mechanical equilibrium before compression of the cell. The longitudinal $\epsilon_{LL,0}$ and circumferential $\epsilon_{\Theta\Theta,0}$ strains in the cell wall can be written as:
\begin{eqnarray}
\left(\begin{array}{c}
 \epsilon_{LL,0}  \\
\epsilon_{\Theta\Theta,0}
\end{array} \right)=\left(\begin{array}{c}
(1-2\nu)P_{0}R^*(1+\epsilon_{\Theta\Theta,0})/(2Eh) \\
(2-\nu)P_{0}R^*(1+\epsilon_{\Theta\Theta,0})/(2Eh)
\end{array} \right)
\label{eq_0}
\end{eqnarray}
with $\epsilon_{LL,0}=L_0/L^*-1$ and $\epsilon_{\Theta\Theta,0}=R_0/R^*-1$. At the first order in strain, (\ref{eq_0}) rewrites:
\begin{eqnarray}
\left(\begin{array}{c}
 \epsilon_{LL,0}  \\
\epsilon_{\Theta\Theta,0}
\end{array} \right)=\left(\begin{array}{c}
(1-2\nu)P_{0}R^*/(2Eh) \\
(2-\nu)P_{0}R^*(2Eh)
\end{array} \right)
\label{eq_0trunc}
\end{eqnarray}
leading to:
\begin{eqnarray}
R_0&=&R^*(1+(2-\nu)P_{0}R^*/(2Eh)),
\label{eq_R0}
\end{eqnarray}
\begin{eqnarray}
L_0&=&L^*(1+(1-2\nu)P_{0}R^*/(2Eh)).
\label{eq_L0}
\end{eqnarray}

Then we write the equations following the instantaneous compression before the relaxation occurs. The volume is conserved which implies:
\begin{eqnarray*}
R_{br}&=&R_0\sqrt{L_0/L_{ind}}.
\end{eqnarray*}
At first order,
\begin{eqnarray*}
R_{br}=R_0+R^*\frac{(L_0-L_{ind})}{2L^*}
\end{eqnarray*}
substituting with the values of (\ref{eq_R0},\ref{eq_L0}), it gives: 
\begin{eqnarray}
R_{br}=R^*\left(1+\left(2-\nu+\frac{1-2\nu}{2}\right)P_{0}R^*/(2Eh)-\frac{1}{2}(L_{ind}/L^*-1)\right)
\label{Rbr_inf}
\end{eqnarray}
Developing the formula (\ref{mechanica_equilibrium_br}) of the mechanical equilibrium, it gives:
\begin{eqnarray*}
\left(\begin{array}{c}
 L_{ind}/L^*-1  \\
 R_{br}/R^*-1
\end{array} \right)=\left(\begin{array}{c}
(1-2\nu)P_{br}R^*/(2Eh) -F_{br}/(2\pi E R^* h) \\
(2-\nu)P_{br}R^*/(2Eh)+\nu F_{br}/(2\pi E R^* h)
\end{array} \right)
\end{eqnarray*}
The force $F_{br}$ can be expressed: 
\begin{eqnarray*}
F_{br}&=&(\pi ER_{br}h) \frac{(-2+\nu)(L_{ind}/L^*-1)+(1-2\nu)(R_{br}/R^*-1)}{1-\nu^2},
\end{eqnarray*}
Substituting the expression for $R_{br}$ (\ref{Rbr_inf}) gives:
\begin{eqnarray*}
F_{br}&=&(\pi ER_{br}h) \frac{(-2+\nu)(L_{ind}/L^*-1)+(1-2\nu)\left(\left(2-\nu+\frac{1-2\nu}{2}\right)P_{0}R^*/(2Eh)-\frac{1}{2}(L_{ind}/L^*-1)\right)}{1-\nu^2}
\end{eqnarray*}
which rewrites neglecting second order terms: 
\begin{eqnarray*}
F_{br}&=&(\pi ER^*h) \frac{(-2+\nu)(L_{ind}/L^*-1)+(1-2\nu)\left(\left(2-\nu+\frac{1-2\nu}{2}\right)P_{0}R^*/(2Eh)-\frac{1}{2}(L_{ind}/L^*-1)\right)}{1-\nu^2}.
\end{eqnarray*}
It can be simplified by reintroducing $L_0$:
\begin{eqnarray}
F_{br}=(\pi ER^*h)\left(\frac{5}{2}-2\nu\right) \frac{(L_0-L_{ind})}{L^*(1-\nu^2)}
\label{F_br}
\end{eqnarray}
The mechanical equilibrium also provides the pressure:
\begin{eqnarray*}
P_{br}=(Eh)\frac{( R_{br}/R^*-1)+\nu ( L_{ind}/L^*-1)}{(1-\nu^2)R^*}
\end{eqnarray*}
Substituting the expression for $R_{br}$ and rearranging the term to make appear $L_0$ gives:
\begin{eqnarray}
P_{br}=P_0+Eh\frac{(1-2\nu)}{2(1-\nu^2)}\frac{L_0-L_{ind}}{L^*R^*}.
\label{P_br}
\end{eqnarray}

\subsection{Force and pressure after relaxation}\label{Force and pressure after relaxation}
The equation (\ref{mech_eq_osm_eq}) can be rewritten as:
\begin{eqnarray}
\left(\begin{array}{c}
\epsilon_{LL,ind}  \\
\epsilon_{\Theta\Theta,ar}
\end{array} \right)&=&\left(\begin{array}{c}
(1-2\nu)\mathcal{R} T N_i/(2E h\pi R^*(1+\epsilon_{\Theta\Theta,ar})L_{ind}) -F_{ar}/(2\pi E R^*(1+\epsilon_{\Theta\Theta,ar}) h) \\
(2-\nu)\mathcal{R} T N_i/(2E h\pi R^*(1+\epsilon_{\Theta\Theta,ar}) L_{ind}) +\nu F_{ar}/(2\pi E R^*(1+\epsilon_{\Theta\Theta,ar}) h)
\end{array} \right)
\label{eq_ar}
\end{eqnarray}
with $\epsilon_{LL,ind}= L_{ind}/L^*-1$ and $\epsilon_{\Theta\Theta,ar}= R_{ar}/R^*-1$. Multiplying the both sides of (\ref{eq_ar}) by $(1+\epsilon_{\Theta\Theta,ar})$ and truncating at the first order in strain gives:
\begin{eqnarray*}
\left(\begin{array}{c}
\epsilon_{LL,ind}  \\
\epsilon_{\Theta\Theta,ar}
\end{array} \right)&=&\left(\begin{array}{c}
(1-2\nu)\mathcal{R} T N_i/(2E h\pi R^*L_{ind}) -F_{ar}/(2\pi E R^* h) \\
(2-\nu)\mathcal{R} T N_i/(2E h\pi R^* L_{ind}) +\nu F_{ar}/(2\pi E R^* h)
\end{array} \right)
\end{eqnarray*}
which can be expanded in:
\begin{eqnarray}
\left(\begin{array}{c}
L_{ind}/L^*-1 \\
R_{ar}/R^*-1
\end{array} \right)&=&\left(\begin{array}{c}
(1-2\nu)\mathcal{R} T N_i/(2E h\pi R^*L_{ind}) -F_{ar}/(2\pi E R^* h) \\
(2-\nu)\mathcal{R} T N_i/(2E h\pi R^* L_{ind}) +\nu F_{ar}/(2\pi E R^* h)
\end{array} \right).
\label{eq_ar_trunc}
\end{eqnarray}
Substracting (\ref{eq_0trunc}) from (\ref{eq_ar_trunc}) gives:
\begin{eqnarray*}
\left(\begin{array}{c}
(L_{ind}-L_0)/L^* \\
(R_{ar}-R_0)/R^*-1
\end{array} \right)&=&\left(\begin{array}{c}
 -F_{ar}/(2\pi E R^* h) \\
\nu F_{ar}/(2\pi E R^* h)
\end{array} \right).
\end{eqnarray*}
which provides easily:
\begin{eqnarray}
R_{ar}&=&R_0+\nu R^* \frac{(L_0-L_{ind})}{L^*},
\label{Rar}
\end{eqnarray}
\begin{eqnarray}
F_{ar}&=&(2\pi ER^*h)
\frac{(L_0-L_{ind})}{L^*}.
\label{Far}
\end{eqnarray}
The apparent stiffness after relaxation $k_{ar}$ equals $(2\pi ER^*h)/L^*$.
The pressure after relaxation reads:
\begin{eqnarray*}
P_{ar}=\mathcal{R} T N_i/(\pi R_{ar}^2L_{ind})
\end{eqnarray*}
which at the first order in strain:
\begin{eqnarray*}
P_{ar}=P_0\left(1+(1-2\nu)\frac{(L_0-L_{ind})}{L^*}\right).
\label{Par}
\end{eqnarray*}

\subsection{First order solution for the osmotic equilibrium and the mechanical equilibrium with an obstacle}\label{osmotic equilibrium and mechanical}
Substituting (\ref{Pressure}) in (\ref{stress_axial_growth},\ref{stress_radial_growth}) gives:
\begin{equation}
\left(\begin{array}{c}
 L/L^*-1  \\
 R/R^*-1
\end{array} \right)=\left(\begin{array}{cc}
 1& -\nu  \\
-\nu& 1
\end{array} \right)\left(\begin{array}{c}
\mathcal{R} T N_i/(2Eh\pi R L)-k/(2\pi E R h)(L-L_c)_+   \\
\mathcal{R} T N_i/(Eh\pi R L)
\end{array} \right)
\label{mechanicaL_{obs}quilibrium_plus osmotic}
\end{equation}
Introducing the small deformations $\epsilon_{LL}$ and $\epsilon_{\Theta\Theta}$ gives:
\begin{equation}
\left(\begin{array}{c}
 \epsilon_{LL}  \\
\epsilon_{\Theta\Theta}
\end{array} \right)=\left(\begin{array}{cc}
 1& -\nu  \\
-\nu& 1
\end{array} \right)\left(\begin{array}{c}
\mathcal{R} T N_i/(2Eh\pi R^* L^*(1+\epsilon_{LL})(1+ \epsilon_{\Theta\Theta}))-k(L^*(1+\epsilon_{LL})-L_c)_+/(2\pi E R^*(1+\epsilon_{\Theta\Theta}) h)   \\
\mathcal{R} T N_i/(Eh\pi R^* L^*(1+\epsilon_{LL})(1+\epsilon_{\Theta\Theta}))
\end{array} \right)
\label{equilibre_epsilon}
\end{equation}
Multiplying both sides by $(1+\epsilon_{LL})(1+\epsilon_{\Theta\Theta})$ gives:
\begin{equation}
\left(\begin{array}{c}
 \epsilon_{LL} (1+\epsilon_{LL})(1+\epsilon_{\Theta\Theta}) \\
\epsilon_{\Theta\Theta}(1+\epsilon_{LL})(1+\epsilon_{\Theta\Theta})
\end{array}\right)= \left(\begin{array}{c}
(1-2\nu)\mathcal{R} T N_i/(2Eh\pi R^* L^*)-k(1+\epsilon_{LL})(L^*(1+\epsilon_{LL})-L_c)_+/(2\pi E R^* h)   \\
(2-\nu)\mathcal{R} T N_i/(2Eh\pi R^* L^*)+\nu k(1+\epsilon_{LL})(L^*(1+\epsilon_{LL})-L_c)_+/(2\pi E R^* h)
\end{array} \right)
\label{equilibre_epsilon_inter}
\end{equation}
At the first order  in $\epsilon_{LL}$ and $\epsilon_{\Theta\Theta}$:
\begin{equation}
\left(\begin{array}{c}
 \epsilon_{LL} \\
\epsilon_{\Theta\Theta}
\end{array}\right)= \left(\begin{array}{c}
(1-2\nu)\mathcal{R} T N_i/(2Eh\pi R^* L^*)-k(L^*(1+2\epsilon_{LL})-L_c(1+\epsilon_{LL}))_+/(2\pi E R^* h)   \\
(2-\nu)\mathcal{R}T N_i/(2Eh\pi R^* L^*)+\nu k(L^*(1+2\epsilon_{LL})-L_c(1+\epsilon_{LL}))_+/(2\pi E R^* h)
\end{array} \right)
\label{equilibre_epsilon_order_1}
\end{equation}
It rewrites:
$$\left(1+k(2L^*-L_c))/(2\pi E R^* h)\right)\epsilon_{LL}=(1-2\nu)\mathcal{R} T N_i/(2Eh\pi R^* L^*)-k(L^*-L_c)/(2\pi E R^* h) $$
which yields:
\begin{equation}
\epsilon_{LL}=\frac{(1-2\nu)\mathcal{R} T N_i/(2Eh\pi R^* L^*)-k(L^*-L_c)/(2\pi E R^* h)}{1+k(2L^*-L_c)/(2\pi E R^* h)}.
\label{First_order_strain}
\end{equation}
Exploiting:
\begin{equation}
\epsilon_{\Theta\Theta}+\nu \epsilon_{LL}=(2-2\nu^2)\mathcal{R} T N_i/(2Eh\pi R^* L^*),
\end{equation}
it provides $\epsilon_{\Theta\Theta}$:
\begin{equation}
\epsilon_{\Theta\Theta}=(1-\nu^2)\mathcal{R} T N_i/(Eh\pi R^* L^*)-\nu\epsilon_{LL}.
\end{equation}
The longitudinal stress reads:
\begin{equation}
\sigma_{LL}/E=(\epsilon_{LL}+\nu\epsilon_{\Theta\Theta})/(1-\nu^2)=\epsilon_{LL}+\nu\mathcal{R} T N_i/(Eh\pi R^* L^*).
\label{First_order_stress}
\end{equation}
\subsection{First order expression of the Lockhart's model}
Substituting (\ref{First_order_stress}) in the time derivative of the plasmolyzed length corresponding to the stress-based formulation Lockhart's law gives:
\begin{equation}
f_\sigma=m_\sigma E\left(\frac{(1-2\nu)\mathcal{R} T N_i/(2Eh\pi R^* )-kL^*(L^*-L_c)/(2\pi E R^* h)}{1+k(2L^*-L_c)/(2\pi E R^* h)}+\frac{\nu\mathcal{R} T N_i}{\pi E R^*h }-\frac{Y_\sigma L^*}{E}\right)_+.
\label{Lockhart_trunc}
\end{equation}
The growth ODE (\ref{Lockhart_stress}) thus reads:
\begin{equation*}
\frac{d L^*}{d t}=m_\sigma E\left(\frac{(1-2\nu)\mathcal{R} T N_i/(2Eh\pi R^* )-kL^*(L^*-L_c)/(2\pi E R^* h)}{1+k(2L^*-L_c)/(2\pi E R^* h)}+\frac{\nu\mathcal{R} T N_i}{\pi E R^*h }-\frac{Y_\sigma L^*}{E}\right)_+.
\end{equation*}
At $t=0$, the contact time, the force exerted by the obstacle is zero and  the classical formula (\ref{eq_L0}) for a turgid cylinder is applicable: $$L_c=L^*_c(1+(1-2\nu)\mathcal{R}TN_{i}(0))/(2\pi R^* hL_{c}^*E)).$$
Introducing the variables $\hat{P}_c=\mathcal{R}TN_{i}(0)/(2\pi R^* hL_{c}^*E)$,  $\hat{Y}_\sigma=Y_\sigma/E$, and substituting with the expression for $L_c$ provides:
\begin{equation}
\frac{d L^*}{d t}=m_\sigma E\left(\frac{(1-2\nu)\hat{P}_c\exp(\gamma t)L^*_c-kL^*(L^*-L^*_c(1+(1-2\nu)\hat{P}_c))/(2\pi E R^* h)}{1+k(2L^*-L^*_c(1+(1-2\nu)\hat{P}_c))/(2\pi E R^* h)}+2\nu \hat{P}_c\exp(\gamma t)L^*_c-\hat{Y}_\sigma L^*\right)_+.
\label{eqtLoc}
\end{equation}
The obstacle stiffness can be non-dimensionalized with $k_{ar}=2\pi R^* hE/L^*_c$, the cell stiffness after relaxation at contact (\ref{stiff_ar}), by introducing $\hat{k}=k/k_{ar}$:
\begin{equation}
\frac{d L^*}{d t}=m_\sigma E\left(\frac{(1-2\nu)\hat{P}_c\exp(\gamma t)L^*_c-\hat{k}L^*(L^*/L^*_c-(1+(1-2\nu)\hat{P}_c))}{1+\hat{k}(2L^*/L^*_c-(1+(1-2\nu)\hat{P}_c))}+2\nu \hat{P}_c\exp(\gamma t)L^*_c-\hat{Y}_\sigma L^*\right)_+.
\label{eqtLoc2}
\end{equation}
The growth ODE (\ref{eqtLoc2}) can be rewritten with the non-dimensional time and length variables $\hat{t}=m_\sigma E t$ and $\hat{L}^*=L^*/L_c^*$:
\begin{equation}
\frac{d \hat{L}^*}{d \hat{t}}=\left(\frac{(1-2\nu)\hat{P}_c\exp(\hat{\gamma} \hat{t})-\hat{k}\hat{L}^*(\hat{L}^*-(1+(1-2\nu)\hat{P}_c))}{1+\hat{k}(2L^*-(1+(1-2\nu)\hat{P}_c))}+2\nu \hat{P}_c\exp(\hat{\gamma} \hat{t})-\hat{Y}_\sigma \hat{L}^*\right)_+.
\label{eqtLoc3}
\end{equation}
with: $\hat{\gamma}=  \left(\hat{P_c}-\hat{Y}_\sigma\right)_+$.\\
It corresponds to a non-dimensional growth ODE function (\ref{Lockhart_stress_adim}):
\begin{equation}
\hat{f}_\sigma(\hat{L}^*,\hat{t})=\left(\frac{(1-2\nu)\hat{P}_c\exp(\hat{\gamma}\hat{t})-\hat{k}\hat{L}^*(\hat{L}^*-1-(1-2\nu)\hat{P}_c)}{1+\hat{k}(2\hat{L}^*-1-(1-2\nu)\hat{P}_c)}+2\nu\hat{P}_c\exp(\hat{\gamma}\hat{t})-\hat{Y}_\sigma\hat{L}^*\right)_+.
\end{equation}
The longitudinal elastic strain (\ref{First_order_strain}) can be rewritten in term of the non-dimensional variables:
\begin{equation}
\epsilon_{LL}=\frac{(1-2\nu)\hat{P}_c/\hat{L}^*\exp(\hat{\gamma}\hat{t})-\hat{k}(\hat{L}^*-1-(1-2\nu)\hat{P}_c)}{1+\hat{k}(2\hat{L}^*-1-(1-2\nu)\hat{P}_c)}.
\label{First_order_strain-st}
\end{equation}
The $\hat{L}^*$ derivative of $\hat{f}_\sigma$ reads:
\begin{equation}
\partial_{\hat{L}^*}\hat{f}_\sigma=-\left(\frac{\hat{k}\left(2\hat{L}^*-1-(1-2\nu)\hat{P}_c+2\hat{L}^*\epsilon_{LL}\right)}{1+\hat{k}\left(2\hat{L}^*-1-(1-2\nu)\hat{P}_c\right)}+\hat{Y}_\sigma \right).
\end{equation}
making use of (\ref{First_order_strain-st}) to introduce $\epsilon_{LL}$.\\
For $\hat{t}>0$ and a length which equals the contact length, the normalized length derivative reads:
\begin{equation}
\hat{f}_\sigma(\hat{L}^*=1,\hat{t})=\left(\frac{(1-2\nu)\hat{P}_c\exp(\hat{\gamma}\hat{t})+\hat{k}(1-2\nu)\hat{P}_c}{1+\hat{k}(1-(1-2\nu)\hat{P}_c)}+2\nu\hat{P}_c\exp(\hat{\gamma}\hat{t})-\hat{Y}_\sigma\right)_+,
\end{equation}
\begin{equation}
\partial_{\hat{L}^*}\hat{f}_\sigma(\hat{L}^*=1,\hat{t})=-\left(\frac{\hat{k}\left(1-(1-2\nu)\hat{P}_c+2\epsilon_{LL}\right)}{1+\hat{k}\left(1-(1-2\nu)\hat{P}_c\right)}+\hat{Y}_\sigma \right).
\end{equation}
Following the hypothesis of linear elasticity, longitudinal elastic strain  $\epsilon_{LL}=(1-2\nu)\hat{P}_c$ is small. Keeping the dominant order provides:
\begin{equation}
\hat{f}_\sigma(\hat{L}^*=1,\hat{t})=\left(\exp(\hat{\gamma}\hat{t})\hat{P}_c\left(\frac{1+2\nu\hat{k}}{1+\hat{k}}\right)+\hat{P}_c\left(\frac{(1-2\nu)\hat{k}}{1+\hat{k}}\right)-\hat{Y}_\sigma\right)_+,
\label{f_hat_first}
\end{equation}
\begin{equation}
\partial_{\hat{L}^*}\hat{f}_\sigma(\hat{L}^*=1,\hat{t})=-\left(\frac{\hat{k}}{1+\hat{k}}+\hat{Y}_\sigma \right).\label{df_hat_first}
\end{equation}

\subsection{Analytical solution of the linearized problem}\label{Analytical solution}
The equation (\ref{eqtLoc3}) linearized at $(\hat{L}^*=1,\hat{t})$ reads:
\begin{equation}
\frac{d \hat{L}^*}{d \hat{t}}\approx \hat{f}_\sigma\left(1,\hat{t}\right)+(\partial_{\hat{L}^*} \hat{f}_\sigma)\left(1,\hat{t}\right)\left(\hat{L}^*-1\right).
\label{lin_Lockhart_0}
\end{equation}
(\ref{f_hat_first}) tells $\partial_{\hat{L}^*} \hat{f}_\sigma$ is independent of the time at first order. The solution of (\ref{lin_Lockhart_0}) reads:
\begin{equation}
\hat{L}^*=1+\exp\left(\partial_{\hat{L}^*} \hat{f}_\sigma(1,0)\hat{t}\right)\int_{u=0}^{\hat{t}}\hat{f}_\sigma\left(1,u\right)\exp\left(-\partial_{\hat{L}^*} \hat{f}_\sigma(1,0)u\right)du.
\end{equation}
Once substituted with (\ref{lin_Lockhart_0}), the integral reads:
\begin{equation}
\int_{u=0}^{\hat{t}}\left(\exp\left((\hat{\gamma}+\hat{\gamma}_i)u\right)\hat{P}_c\left(\frac{1+2\nu\hat{k}}{1+\hat{k}}\right)+\exp\left(\hat{\gamma}_iu\right)\left(\hat{P}_c\left(\frac{(1-2\nu)\hat{k}}{1+\hat{k}}\right)-\hat{Y}_\sigma\right)\right)du
\end{equation}
with $\hat{\gamma}=\hat{P}_c-\hat{Y}_\sigma$ and $\hat{\gamma}_i=\frac{\hat{k}}{1+\hat{k}}+\hat{Y}_\sigma$.
The solution can be explicited:
\begin{equation}
\hat{L}^*(\hat{t})\approx 1+\hat{\beta}\left(\exp\left(\hat{\gamma} \hat{t}\right)-1\right)+(1-\hat{\beta})\frac{\hat{\gamma}}{\hat{\gamma}_i}\left(1-\exp\left(-\hat{\gamma}_i \hat{t}\right)\right),
\label{Analyticd}
\end{equation}
with:
\begin{equation*}
\hat{\beta}=\frac{\hat{P_c}\left(1+2\nu\hat{k}\right)}{(1+\hat{k})\hat{P_c}+\hat{k}}.
\end{equation*}
For a $\textit{Chara corallina}$ internode of length at contact $L_c=1cm$, the mechanical parameters are of the following order of magnitude  \citep{huang2012modelling}:
\begin{equation*}
E=1GPa,\ h=10\mu m,\ \nu=0.3,\ R^*=500\mu m.
\end{equation*}
The Lockhart's parameters expressed in pressure read:
\begin{equation*}
P=0.55MPa,\ Y_P=0.5MPa,\ m_P=2.6000\times 10^{-5} (MPa)^{-1} s^{-1},
\end{equation*}
which correpond to Lockhart's parameters expressed in stresses obtained with these formula:
\begin{equation*}
\sigma_{LL}=\frac{PR}{2h},\ Y_\sigma=\frac{Y_PR}{2h},\ m_\sigma=\frac{2 hm_P}{R}.
\end{equation*}
It corresponds to a cell stiffness after relaxation: $k_{ar}=\pi\times 10^3N/m$.

The hypothesis of our model do not apply to a maiz root growth zone. Nonetheless  we provide its parameters in order to provide a qualitative comparison point with \textit{Chara corallina}. Approximating the maize root growth zone by a single cell of contact length $L_c=1cm$,  the mechanical parameters of the root taken as a plain rod are the following (Paragraph 4.2.6.3 of \citep{quiros2023biomecanique} ):
\begin{equation*}
E_{rod}=24MPa,\ R^*=450\mu m.
\end{equation*}
It corresponds to a stiffness
\begin{equation*}
k_{cell}=\frac{\pi (R^*)^2 E_{rod}}{L_c}=1527N/m
\end{equation*}
The Lockhart's parameters expressed in pressure read \citep{frensch_rapid_1995}:
\begin{equation*}
P=0.7MPa,\ Y_P=0.6MPa,\ m_P=8\times 10^{-4} (MPa)^{-1} s^{-1}.
\end{equation*}
