\subsection{Asymptotic behavior of the Lockhart's model with an obstacle}\label{Asymptotic behavior}
The time derivative of (\ref{Lockhart_stress}) gives:
\begin{equation*}
\frac{d^2 L^*}{d t^2}=\partial_t f_\sigma(L^*,t)+\partial_L^* f_\sigma(L^*,t)\frac{d L^*}{d t}.
\end{equation*}
Let suppose $\frac{d L^*}{d t}$ equals zero for a given $t_{zero}$:
\begin{equation*}
\frac{d^2 L^*}{d t^2}(t_{zero})=\partial_t f_\sigma(L^*(t_{zero}),t_{zero})
\end{equation*}
The time derivative reads:
\begin{equation*}
\partial_t f_\sigma(L^*(t_{zero}),t_{zero})=m_\sigma \gamma \frac{\mathcal{R} T N_i(t_{zero})}{2h\pi R^* L^*} \left(\frac{1+2\nu k(2L^*-L_c)/(2\pi ER^* h)}{1+k(2L^*-L_c)/(2\pi ER^* h)}\right),
\end{equation*}
which implies:
\begin{equation*}
\frac{d^2 L^*}{d t^2}(t_{zero})>0.
\end{equation*}
$L^*$ is thus strictly increasing with no fixed point; $L^*$ asymptotic limit reads:
\begin{equation*}
\lim_{t\to \infty}L^*=+\infty.
\end{equation*}
The longitudinal stress reads:
\begin{equation*}
\sigma_{LL}= \left(\frac{(1-2\nu)\mathcal{R} T N_i/(2Eh\pi R^* L^*)-k(L^*-L_c)/(2\pi R^* h)}{1+k(2L^*-L_c)/(2\pi E R^* h)}+\frac{\nu\mathcal{R} T N_i}{\pi R^*h L^*}\right).
\end{equation*}
When $t\to \infty$ it can be rewritten:
\begin{equation*}
\sigma_{LL}= -\frac{E}{2}+\frac{\nu\mathcal{R} T N_i}{\pi E R^*h L^*}+o_{t\to\infty}\left(\frac{\mathcal{R} T N_i}{\pi  R^*h L^*}\right).
\end{equation*}
(\ref{Lockhart_trunc}) can be rewritten:
\begin{equation}
\frac{d L^*}{d t}=m_\sigma\left( -\frac{EL^*}{2}+\frac{\nu\mathcal{R} T N_i}{\pi R^*h }-Y_\sigma L^*+o_{t\to\infty}\left(\frac{\mathcal{R} T N_i}{\pi R^*h}\right)\right)_+.
\label{eq_asymp}
\end{equation}
Let write the time derivative of $\rho=L^*/N_i$:
\begin{equation*}
\frac{d \rho}{d t}=\frac{1}{N_i}\frac{dL^*}{dt}-\frac{L^*}{N_i^2}\frac{dN_i}{dt}
\end{equation*}
Substituting the value of $N_i$ and of $\dot{L^*}$:
\begin{equation*}
\frac{d \rho}{d t}=m_\sigma\left( -\frac{E}{2}\rho+\frac{\nu\mathcal{R} T}{\pi R^*h }-Y_\sigma \rho+o_{t\to\infty}\left(\frac{\mathcal{R} T }{\pi R^*h}\right)\right)_+-\gamma\rho
\end{equation*}
Substituting the value of $\gamma=m\sigma(P_0R^*/(2h)-Y_\sigma)$ gives:
\begin{equation}
\frac{d \rho}{d t}=m_\sigma\left( -\frac{E}{2}-P_0R^*/(2h)\right)\rho+m_\sigma\frac{\nu\mathcal{R} T}{\pi R^*h }+o_{t\to\infty}\left(m_\sigma\frac{\mathcal{R} T }{\pi R^*h}\right)
\label{ode_eq}
\end{equation}
Let take a very high $t_o$, and integrate the ODE from the time $t_o$ (\ref{ode_eq}): 
\begin{equation}
\rho=\exp\left(m_\sigma\left( -\frac{E}{2}-P_0R^*/(2h)\right)(t-t_o)\right)\left(\rho_0-\frac{2\nu\mathcal{R} T}{\pi R^*h(Eh+P_0R^*)}\right)+\frac{2\nu\mathcal{R} T}{\pi R^*h(Eh+P_0R^*)}
\end{equation}
Finally, $L^*$ has a simple equivalent for high $t$:
\begin{equation}
L^*\sim_{t\to\infty} \frac{2\nu \mathcal{R} T N_i(t)}{\pi R^*(P_0R^*+Eh)},
\end{equation}
it corresponds to a value of elastic strain outside of the range of linear elasticity:
\begin{equation}
\lim_{t\to\infty}\epsilon_{LL}= -1/2,
\end{equation}
and an asymptotic pressure:
\begin{equation}
\lim_{t\to\infty}P= \frac{P_0+Eh/R^*}{2}.
\end{equation}

\subsection{Cell buckling and barreling}\label{non_linearities}
The Euler criterion that gives the force threshold for buckling of an hollow cylinder is provided by \citep{landau1959theory}:
\begin{eqnarray}
F_b=\frac{\pi^2(R^*)^3h E}{(L^*)^2}
\end{eqnarray}
The force exerted by the obstacle remains well under the Euler criterion during the whole growth (Figure \ref{Simu_analytique_Euler}, Right Panel).\\

The barreling criterium can be calculated by a complex numerical procedure described in \citep{goriely2008nonlinear} but not repeated herein. In \citep{goriely2008nonlinear} Figure 3 for a slightly different constitutive law (neo-Hookean $C_1=1$) and a slightly different geometry ($h/R=0.01$ instead of $h/R=0.02$ for \textit{Chara corallina}),  the barreling criterium expressed lays under the Euler criterium for the ratio ($R/L=0.05$) of \textit{Chara corallina} meaning the force for barreling is higher than the Euler criterion; this result should remain valid for a $1\ cm$ internode.

\subsection{Elastic growth model}\label{Elastic growth model}
The contact scenario is modeled by one spring of a constant stiffness $k_{cell}$ and an increasing target length $L_{tar}$ and one spring of constant rest length $L_c$ and a constant stiffness $k$ (See Figure \ref{Experiences}c). The observed length $L_{obs}$ is provided by the mechanical equilibrium:
\begin{equation}
    k_{cell}(L_{obs}-L_{tar})+k(L_{obs}-L_c)=0,
\end{equation}
thus:
\begin{equation}
    L_{obs}=\frac{kL_c+k_{cell}L_{tar}}{k_{cell}+k}.
    \label{L_obslastic_growth}
\end{equation}

To retrieve the phenomenology, we suppose the target length evolution rate decreases linearly with the force:
\begin{equation}
    \dot{L}_{tar}=L_{tar}f(L_{tar})
     \label{Target_growth_law}
\end{equation}
with $f(L_{tar})= (c_1-c_2 k(L_{obs}-L_c))$ the growth rate. 
$c_1$ corresponds to the growth rate before the contact:
\begin{equation}
c_1=m_\sigma\left(\frac{P_c R}{2h}-Y_\sigma\right).
\end{equation}
$c_2$ can be estimated by considering the growth rate tangent at the contact time:
\begin{equation}
c_2=\frac{(\frac{\dot{L}}{L}-c_1)}{F}.
\end{equation}
Approximating $dL/dt/L$ by $ dL^*/dt/L^*$ at a contact time which is reasonable according to the analytical solution for the Lockhart model:
\begin{equation}
c_2=\frac{m_\sigma}{2\pi R h}.
\end{equation}
Substituting  (\ref{L_obslastic_growth}) in (\ref{Target_growth_law}) gives:
\begin{equation}
 \frac{d L_{tar}}{d t}   =L_{tar}\left(m_\sigma\left(\frac{P_c R}{2h}-Y_\sigma\right)- \frac{m_\sigma}{2\pi R h}\frac{ k_{cell}k}{k_{cell}+k}(L_{tar}-L_c)\right)_+.
     \label{Target_growth_equation}
\end{equation}
The equation can be non-dimensionalized using the following non-dimensional variables:
\begin{equation}
\hat{t}=m_\sigma E t,\ \hat{L}_{tar}=\frac{L_{tar}}{L_c^*},\ \hat{P}_c=\frac{\mathcal{R}TN_{i}(0)}{2\pi R^* hL_{c}^*E},\ \hat{Y}_\sigma=\frac{Y_\sigma}{E},
\label{nondim3}
\end{equation}
\begin{equation}
\hat{k}=\frac{k}{k_{cell}},\ \hat{\gamma}=  \left(\hat{P_c}-\hat{Y}_\sigma\right)_+,\ \hat{\gamma}_{el}=\hat{\gamma}+\frac{ \hat{k}}{1+\hat{k}}\hat{L}_c.
\label{nondim4}
\end{equation}
The non-dimensionalized equation reads:
\begin{equation}
 \frac{d \hat{L}_{tar}}{d\hat{t}}=\hat{L}_{tar}\left(\hat{\gamma}_{el}- \frac{ \hat{k}}{1+\hat{k}}\hat{L}_{tar}\right)_+.
     \label{Target_growth_equation_adim}
\end{equation}
It rewrites:
\begin{equation*}
 \frac{d \hat{L}_{tar}}{d\hat{t}}\left(\frac{1}{\hat{L}_{tar}}+\frac{\frac{ \hat{k}}{1+\hat{k}}}{\hat{\gamma}_{el}- \frac{ \hat{k}}{1+\hat{k}}\hat{L}_{tar}}\right)=\hat{\gamma}_{el}.
\end{equation*}
We suppose the contact takes place at time $t=0$; it implies $L_{tar}(0)=L_c$.
The expression (\ref{Target_growth_equation_adim}) can be integrated:
\begin{eqnarray*}
    \log(\hat{L}_{tar}/\hat{L}_c)-\log\left(\frac{\hat{\gamma}_{el}- \frac{ \hat{k}}{1+\hat{k}}\hat{L}_{tar}}{\hat{\gamma}}\right)
 =\hat{\gamma}_{el}\hat{t}.
     \label{Target_growth_integration}
\end{eqnarray*}
Finally:
\begin{eqnarray}
 \hat{L}_{tar}(\hat{t})=\frac{\hat{L}_c\hat{\gamma}_{el}\exp(\hat{\gamma}_{el}\hat{t})}{\hat{\gamma}+\frac{ \hat{k}\hat{L}_c}{1+\hat{k}}\exp(\hat{\gamma}_{el}\hat{t})}.
     \label{Target_growth_solutiona}
\end{eqnarray}
The solution saturates for an increment:
\begin{eqnarray*}
 \Delta \hat{L}_{tar}=\frac{\hat{\gamma}_{el}(1+\hat{k})}{\hat{k}}-\hat{L}_c.
\end{eqnarray*}
Substituting with the value of $\gamma$
and $ \Delta \hat{L}_{tar}$ rewrites:
\begin{eqnarray*}
 \Delta \hat{L}_{tar}=\frac{\hat{\gamma}(1+\hat{k})}{\hat{k}}.
\end{eqnarray*}
Combining     (\ref{Target_growth_solutiona}, \ref{L_obslastic_growth}) provides the observed length dynamics:
\begin{eqnarray}
\hat{L}_{obs}(\hat{t})=\frac{\hat{k}\hat{L}_c}{1+\hat{k}}+\frac{\hat{L}_c\hat{\gamma}_{el}\exp(\hat{\gamma}_{el}\hat{t})}{(1+\hat{k})\hat{\gamma}+ \hat{k}\hat{L}_c\exp(\hat{\gamma}_{el}\hat{t})}
     \label{elasticgrowth_solutiona},
\end{eqnarray}
which saturates for a non-dimensionalized observed length increment:
\begin{eqnarray}
 \Delta\hat{L}_{obs}=\frac{\hat{\gamma}}{\hat{k}}.
\end{eqnarray}


