\section{The Volatility Process in the SABR Model}

Consider the process for $\mathrm{VIX}_T$, defined as in (\ref{VIXdef}). 
In the SABR model \eqref{SABR}, we have
\begin{equation}\label{VIX:v:eqn}
\mathrm{VIX}_{T}^{2}=\mathbb{E}\left[\frac{1}{\tau}\int_{T}^{T+\tau}v_{t}^{2}dt\Big|\mathcal{F}_{T}\right],   
\end{equation}
where $v_{t}$ is the \emph{volatility process} defined as
\begin{equation}
v_{t}:=S_{t}^{\beta-1}\sigma_{t}, 
\end{equation}
where $S_{t},\sigma_{t}$ are given in \eqref{SABR}.
An application of It\^{o}'s lemma gives that $v_t$ follows 
a one-dimensional stochastic differential equation (SDE).
\footnote{This observation was also noted in \cite{Lewis2}, see Section 8.3.2 where $v_t$ is called the effective log-normal volatility process for the SABR model.}

\begin{lemma}\label{lem:existence}
In the SABR model \eqref{SABR}, $v_t=\sigma_t S_t^{\beta-1}$ follows the SDE:
\begin{eqnarray}\label{vsde}
&&\frac{dv_t}{v_t} =  \sigma_V(v_t) d W_t + \mu_V(v_t) dt\,,
\end{eqnarray}
where $W_t$ is a standard Brownian motion different from $B_t$,
and the volatility and drift of this process are given by 
\begin{eqnarray}
&& \sigma_V(v) := \sqrt{\omega^2 + (\beta-1)^2 v^2 + 2\rho (\beta-1) \omega v}\,,\label{sigma:v:eqn} \\
&& \mu_V(v) := v (\beta-1)\left[ \frac12 (\beta - 2) v + \rho \omega \right] \,.\label{mu:v:eqn}
\end{eqnarray}
\end{lemma}

\begin{proof}
We have by It\^{o}'s lemma
\begin{align}
dv_t &= d(\sigma_t S_t^{\beta-1} ) \\
&= S_t^{\beta-1} d\sigma_t + 
\sigma_t dS_t^{\beta-1} +  \rho \frac{\partial^2 (\sigma_t S_t^{\beta-1})}{\partial\sigma_t \partial S_t} dt\nonumber\\
&= S_t^{\beta-1} \omega \sigma_t dZ_t + \sigma_t \Big( (\beta-1) \sigma_t S_t^{2\beta-2} dB_t + \frac12 (\beta-1)(\beta-2) \sigma_t^2 S_t^{3\beta-3} dt\Big) \nonumber \\
&\qquad\qquad\qquad+  \rho \omega (\beta-1) \sigma_t^2 S_t^{2\beta-2} dt\,, \nonumber
\end{align}
where the last term was computed as
\begin{align}
\frac{\partial^2 (\sigma_t S_t^{\beta-1})}{\partial\sigma_t \partial S_t} =(\beta-1) S_t^{\beta-1} (\omega \sigma_t) (\sigma_t S_t^\beta) =
\omega (\beta-1) \sigma_t^2 S_t^{2\beta-2}\,.
\end{align}
This can be written equivalently as
\begin{align}
    \frac{dv_t}{v_t} &= \omega dZ_t + (\beta-1) v_t dB_t + 
    (\beta-1) v_t \Big( \rho \omega + \frac12 (\beta-2) v_t\Big) dt \\
    &= \sigma_V(v_t) dW_t + \mu_V(v_t) dt\,, \nonumber
\end{align}
where $W_t:=\int_{0}^{t}\frac{ \omega dZ_s + (\beta-1) v_s dB_s}{\sigma_V(v_{s})}$ is another standard Brownian motion due to L\'{e}vy's characterization of Brownian motion.
This reproduces the stated result (\ref{vsde}).
\end{proof}


We will show in Section~\ref{sec:existence:uniqueness} that under the assumption that $0\leq\beta<1$ and $\rho<0$, the SDE \eqref{vsde} has a unique solution.
In Section~\ref{sec:2.4} we prove that $(v_{t})_{t\geq 0}$
%Moreover, $(v_{t})_{t\geq 0}$
is explosive, i.e. $\mathbb{P}(\tau_{\infty}<\infty)>0$
where $\tau_{\infty}:=\sup\{t\geq 0:v_{t}<\infty\}$. 
As an immediate consequence, for any $\tau>0$, by the definition of $\mathrm{VIX}_{T}$ in \eqref{VIX:v:eqn}, we have $\mathrm{VIX}_{T}=\infty$
with probability one.
 %{\color{blue} On the other hand, with $\tau=0$, we have $\mathrm{VIX}_{T}=\infty$  with non-zero probability but less than one.}
%{\color{red} As a result} 
%{\color{blue} For both cases} 
As a result, the VIX forward price $F_V(T)$ and the
VIX call option price are infinite.
In Section~\ref{sec:3} we will present a modification of the process \eqref{vsde} which avoids these issues.

\subsection{Existence and Uniqueness of the Volatility Process}\label{sec:existence:uniqueness}

We study in this section the existence and uniqueness for the volatility process $v_{t}$ in (\ref{vsde}). 
%For simplicity we will denote $\tilde W_t$ in (\ref{vsde}) simply as $W_t$, with the understanding that this is different from the standard Brownian motion appearing in the definition of the SABR model.
Note that since the solution to the SABR model 
exists\footnote{Conditional on a realization of the volatility process $\sigma_t$, the SABR model with $0\leq \beta < 1$ reduces to the CEV model, which is related to a squared Bessel process by a change of variable \cite{Linetsky2010}. The conditions for existence and uniqueness of the solutions of this model are given for example in Section 2 in Chen, Oosterlee, van der Weide (2012) \cite{Chen2012}; see also \cite{Andersen2000}.}, 
Lemma~\ref{lem:existence} already shows the existence
of the solution for the SDE \eqref{vsde}.
%{\color{red} we need to be careful here. we only need existence of weak solution. it seems the result you quote provides existence already. in addition, we can mention the existence of weak solution by quoting the existence of solution of SABR model, and we should add more details how to use Itos formula to derive the SDE for $v_t$, which shows the existence of a weak solution. Finally, I feel that a lot of notations, and calculations in the existence section can be relegated to the Feller Test of Explosion section.}
This SDE has the form
\begin{equation}
dv_t = (\alpha v_t^3 + \delta v_t^2) dt + v_t \sigma_V(v_t) dW_t\,,
\end{equation}
with the coefficients 
\begin{equation}\label{alpha:delta}
\alpha := \frac12 (1-\beta)\,,\quad
\delta := -(1-\beta) \rho \omega \,.
\end{equation} 



In the rest of this section, we make the following assumption on the model parameters.

\begin{assumption}\label{assump:1}
Assume $0 \leq \beta < 1$ and $\rho<0$.
\end{assumption}
With this assumption, the coefficients in the drift \eqref{alpha:delta} are positive, i.e. $\alpha,\delta >0$ and the volatility function $\sigma_V(v)$ in \eqref{sigma:v:eqn} does not vanish for $v \geq 0$.

The drift and volatility in \eqref{sigma:v:eqn}-\eqref{mu:v:eqn} are not sub-linear so we cannot use Theorem~2.9 in Karatzas and Shreve \cite{KS} to prove the existence and uniqueness.
Instead, we will use Theorem~5.15 in Karatzas and Shreve \cite{KS} to show the existence and uniqueness in the weak sense.
%{\color{blue} We use the approach in Section 5.5.B (p.339) of Karatzas and Shreve \cite{KS} to relate the solutions of the sde \eqref{vsde} to those of a driftless diffusion with a modified volatility.}
%\subsubsection{Existence and uniqueness} 
Consider the SDE 
\begin{equation}\label{general:SDE}
dX_t = b(X_t) dt + \sigma(X_t)dW_t, 
\end{equation}
satisfying non-degeneracy \eqref{ND} and local integrability \eqref{LI} conditions,
defined as
\begin{equation}\label{ND}\tag{ND}
\sigma^2(x) > 0\,,\qquad\text{for every $x \in (0,\infty)$}\,,
\end{equation}
and
\begin{equation}\label{LI}\tag{LI}
\text{for any $x \in (0,\infty)$, there exists some $\varepsilon>0$ such that $\int_{x-\varepsilon}^{x+\varepsilon} \frac{|b(y)| dy}{\sigma^2(y)} < \infty$}\,.
\end{equation}


For our case we have $b(x) = \alpha x^3 + \delta x^2$ and $\sigma(x) = x \sigma_V(x)$, where $\alpha,\delta$ are defined in \eqref{alpha:delta} and $\sigma_{V}(\cdot)$ is defined in \eqref{sigma:v:eqn}.
These conditions are satisfied by our process under Assumption~\ref{assump:1}, which ensures the non-vanishing of $\sigma_V(x)$ for $x\geq 0$. 

By Theorem~5.15 in Karatzas and Shreve \cite{KS} (reproduced below for convenience) the solution of \eqref{vsde} exists and is unique in weak sense.

\begin{theorem}[Theorem~5.15 in Karatzas and Shreve \cite{KS}]
Assume that $\sigma^{-2}$ is locally integrable at every point in $[0,\infty)$, and conditions~\eqref{ND} and \eqref{LI} hold. 
Then for every initial distribution for $X_0$, the SDE~\eqref{general:SDE} for $X_t$ has a weak solution up to an explosion time, 
and this solution is unique in the sense of probability law.
\end{theorem}

