\subsection{Reduction to the Natural Scale}


We present in this section the reduction of the diffusion \eqref{vsde} to its natural scale. The approach used is described, for example, in Section 5.5.B (p.339) of Karatzas and Shreve \cite{KS}. We introduce and study several functions which will be required for the application of the Feller explosion criterion in Section \ref{sec:2.4}.

Define the \textit{scale} function
\begin{equation}\label{pdef}
p(x) := \int_c^x e^{-2 \int_c^\xi \frac{b(y) dy}{\sigma^2(y)} } d\xi\,,
\end{equation}
with $c$ an arbitrary value in $[0,\infty)$. %I will take in the following $c=0$.
By Proposition~5.13 in \cite{KS}, $Y_t = p(X_t)$ follows the driftless process $dY_t = \bar \sigma(Y_t) dW_t$ with volatility:
\begin{equation}
\bar\sigma(y) :=
\begin{cases}
p'(q(y)) \sigma(q(y)) & \text{if $y \in (0,p_\infty)$}, \\
0 & \text{otherwise}, \\
\end{cases}
\end{equation}
where $q(y)$ is the inverse of $p(x)$ and $p_\infty=\lim_{x\rightarrow\infty}p(x)$ (see Proposition~\ref{prop:p}). 
The diffusion process $Y_t$ is in its natural scale, since its scale function is simply $x$.

Denote the integral in the exponent of (\ref{pdef}) as
\begin{equation}
F(x;c) := \int_c^x \frac{b(y) dy}{\sigma^2(y)} = 
\int_c^x \frac{\alpha y + \delta}{\sigma_V^2(y)} dy \,.
\end{equation}
Under Assumption~\ref{assump:1}, the denominator does not vanish for $y\geq 0$.
Thus the integrand is well-behaved as $y\to 0$ and we can take without any loss of generality $c=0$.
The value of the integral for any other $c>0$ can be recovered as $F(x;c) = F(x;0) - F(c;0)$.
Denote for simplicity $F(x) := F(x;0)$, which can be evaluated in closed form with the result 
\begin{eqnarray}
F(x) =\frac{1}{(1-\beta)^2} \left\{
\frac{\alpha}{2} \log \frac{R(x)}{\omega^2} 
- \frac12 \beta(1-\beta) \frac{|\rho|}{\rho_\perp}
\left( \arctan\frac{(1-\beta) x + \bar\omega}{\omega\rho_\perp} - \arctan \frac{\bar\omega}{\omega\rho_\perp}\right) \right\}\,,
\end{eqnarray}
where 
\begin{equation}\label{R:eqn}
R(x) := \sigma_V^2(x) = \omega^2  + 2 \bar\omega (1-\beta) x + (1-\beta)^2 x^2\,,
\end{equation}
with
$\bar\omega := \omega |\rho|$ and $\rho_\perp := \sqrt{1-\rho^2}$.
%Also, we denote $R(x) = \sigma_V^2(x)$.
We note the lower and upper bounds on $e^{-2F(x)}$:
\begin{equation}\label{boundsF}
\left( \frac{\omega^2}{R(x)} \right)^{\frac{\alpha}{(1-\beta)^2}} \leq
e^{-2F(x)} \leq
\kappa
\left( \frac{\omega^2}{R(x)} \right)^{\frac{\alpha}{(1-\beta)^2}}\,,
\end{equation}
where 
\begin{equation}\label{kappa:defn}
\kappa := \exp \left( \frac{\pi}{2} \frac{\beta}{1-\beta} \frac{|\rho|}{\rho_\perp}\right) > 1\,.
\end{equation}


\begin{proposition}\label{prop:p}
Take $c=0$ and assume the conditions in Assumption~\ref{assump:1} for $\beta,\rho$.
The scale function $p(x)$ has the following properties:

i) $p(0)=0$. $p(x)$ is monotonically increasing and approaches a finite limit 
$\lim_{x\to \infty} p(x) = p_\infty < \infty$ as $x\to \infty$.

ii) The large $x$ asymptotics has the form
\begin{equation}\label{largex}
p(x)=p_\infty - \frac{c_1}{x^{\frac{1}{1-\beta}}}+o\left(x^{-1/(1-\beta)}\right)\,,
\end{equation}
as $x\rightarrow\infty$, with $c_1>0$ a positive constant.

iii) The inverse function $q(y)$ diverges to $+\infty$ as
\begin{equation*}
q(y) \sim \left(\frac{c_1}{p_\infty - y} \right)^{1-\beta}\,,
\end{equation*}
as $y\to p_\infty$.
\end{proposition}

\begin{proof}
The scale function is 
\begin{equation}
p(x) = \int_0^x e^{-2F(y)} dy\,.
\end{equation}


i) The function $p$ is clearly increasing since $p'(x) = e^{-2F(x)} \geq 0$.
From (\ref{boundsF}), the scale function is bounded from above by the convergent integral
\begin{equation}
p(x) \leq \kappa \int_0^x 
\left( \frac{\omega^2}{R(y)} \right)^{\frac{\alpha}{(1-\beta)^2}} dy\,,
\end{equation}
where $\kappa$ is given in \eqref{kappa:defn}.
By the monotone convergence theorem, $p(x)$ converges to a finite limit $p_\infty$ since it 
is monotonically increasing and bounded from above.

ii) Large $x$ asymptotics. The upper and lower bounds on $p(x)$ are proportional to a common integral
\begin{equation}
I(x) := \int_0^x 
\left( \frac{\omega^2}{R(y)} \right)^{\frac{\alpha}{(1-\beta)^2}} dy\,.
\end{equation}
The large-$x$ asymptotics of this integral is
\begin{equation}
I(x) = c_0 - \frac{1}{1-\beta} \left( \frac{\omega}{1-\beta} \right)^{\frac{2-\beta}{1-\beta}}
\cdot \frac{1}{x^{\frac{1}{1-\beta}}}+o\left(x^{-1/(1-\beta)}\right)\,, \quad x\to \infty\,.
\end{equation}
The large $x$ asymptotics for $p(x)$ is the same, up to a multiplicative constant, which yields the result (\ref{largex}).


iii) Inverting the leading term asymptotics (\ref{largex}) of $p(x)$ for $x\to \infty$,  
gives the stated $y\to p_\infty$ asymptotics for $q(y)$.
\end{proof}

\begin{remark}
The choice $c=0$ in the definition of the scale function is not essential and can be relaxed. Denoting $p(x;c)$ the scale function with an arbitrary value of $c\geq 0$, this is related to $p(x)$ defined with $c=0$ as
\begin{equation}
p(x;c) = e^{-2F(c)} (p(x) - p(c)) \,.
\end{equation}
\end{remark}



\begin{proposition}\label{prop:sig}
The volatility in natural scale $\bar\sigma(y)$ has the following properties:

i) For small $y\to 0$ argument it has the form $\bar\sigma(y) = \omega y + O(y^2)$.

ii) As $y\to p_\infty$ it has the asymptotic form $\bar\sigma(y) \sim (p_\infty - y)^\beta$.
\end{proposition}

\textit{Numerical example.} Figure~\ref{Fig:p} shows the functions $p(x)$ and $\bar\sigma(y)$ for the SABR 
model with $\beta=\frac12$ and parameters $\omega=1$, $\rho = -0.7$.
The large $x$ limit of the scale function is $p_\infty=1.5614$.

