%To do: study the nature of the boundary at $y=p_\infty$ using the Feller criterion, and determine if it can be reached. 

\subsection{Nature of Boundary Points}

We established above that the process for $Y_t = p(X_t)$
takes values in the bounded range $Y_t \in [0,p_\infty]$. The asymptotics of the volatility in the natural scale $\bar \sigma(y)$ from Proposition~\ref{prop:sig} determines the nature of the boundary points.

The $y=0$ boundary is similar to that of a geometric Brownian motion process and is a natural boundary.

The point $y=p_\infty$ is similar to the origin for the CEV process. Recall the classification of the solutions for this case \cite{Linetsky2010}: 

a) $\beta \in (0,\frac12)$. 
The point $y=p_\infty$ is a regular boundary point. The fundamental solution is not unique.
The problem is well-posed only if an additional boundary condition is imposed, for example, absorbing or reflecting boundary.

b) $\beta \in [ \frac12, 1)$. 
The point $y=p_\infty$ is an exit boundary point.
There is a unique fundamental solution with decreasing norm and mass at $y=p_\infty$
corresponding to the absorption at this point.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Feller Test of Explosion for the Volatility Process}
\label{sec:2.4}

In this section, we study the explosion for the volatility process $v_{t}$ in \eqref{vsde}.
A sufficient condition for the absence of explosions is expressed in terms of the scale function as $p_{\infty} = \infty$ \cite{KS}. 
By point (i) in Proposition \ref{prop:p}, the $x\to \infty$ limit of the scale function is finite, so explosions cannot be excluded. However the finiteness of $p_\infty$ is only a necessary, but not sufficient criterion for the existence of explosions. 
Using the Feller test of explosion \cite{Feller1952}, 
we show in this section that the process $v_t$ in \eqref{vsde} explodes in finite time with non-zero probability. 


\begin{proposition}\label{prop:explosion}
The process $v_t$ in \eqref{vsde} explodes in finite time with non-zero probability.
\end{proposition}

\begin{proof}
Recall the Feller test for explosions of the solutions of a SDE. Define the function
\begin{equation}\label{nudef}
\nu(x) := \int_c^x p'(y) \int_c^y \frac{2dz}{p'(z) \sigma^2(z)} dy\,.
\end{equation}

\begin{theorem}[Feller’s (1952) Test of Explosion \cite{Feller1952}, Theorem~5.29 \cite{KS}]\label{thm:Feller}
Assume that the nondegeneracy \eqref{ND} and local integrability \eqref{LI} conditions
hold, %\footnote{{\color{blue} The statement in the Karatzas, Shreve book denotes $(v,W)$ for the solution of the SDE for $v_t$, where $W_t$ is the Brownian motion. Perhaps we can just say $v_t$.}}, and let $v_t$, %{\color{red}what are $(X,Z)$?} 
%(\Omega,\mathcal{F},\mathbb{P},(\mathcal{F}_t)_{t\geq 0})$ 
and let $X_t$ be a weak solution in $I = (0,\infty )$ of the SDE \eqref{general:SDE} with nonrandom initial condition $X_0> 0$. Then $\mathbb{P}(\tau_{\infty}=\infty) = 1$ or
$\mathbb{P}(\tau_{\infty}=\infty) < 1$, according to whether $\nu(0+) = \nu(\infty -) = \infty$ or not, where $\tau_{\infty} = \sup\{
t\geq 0 : X_t < \infty\}$.
\end{theorem}

We prove an upper bound on the function $\nu(x)$, and will show that it is finite for all $x$. 
Using $p'(y) = e^{-2F(y)}$ and the bounds (\ref{boundsF}) on $e^{-2F}$ we have
\begin{equation}\label{nubound}
\nu(x) \leq \kappa \int_0^x \left( \frac{\omega^2}{R(y)}\right)^{\alpha/(1-\beta)^2}
\left( \int_0^y \left( \frac{\omega^2}{R(z)}\right)^{-\alpha/(1-\beta)^2}\frac{2dz}{z^2 R(z)} 
\right) dy\,.
\end{equation}

Recall from \eqref{R:eqn} that $R(y) = (1-\beta)^2 y^2 + 2\bar\omega (1-\beta) y + \omega^2$ 
and 
\begin{equation}
\frac{\alpha}{(1-\beta)^2} = \frac{2-\beta}{2(1-\beta)} \geq 0\,,\qquad\mbox{ for } 0 \leq \beta < 1\,.
\end{equation}

Denote the $z$ integral 
\begin{equation}
I_z(y) := \int_0^y
\left( \frac{\omega^2}{R(z)}\right)^{-\frac{\alpha}{(1-\beta)^2}} \frac{2dz}{z^2 R(z)} \,.
\end{equation}
The integrand has the large $z$ asymptotics $\sim \frac{2}{\omega^2} 
z^{-4 +\frac{2\alpha}{(1-\beta)^2} } = \frac{2}{\omega^2} 
z^{-\frac{2-3\beta}{1-\beta}} $ as $z\to \infty$. This gives the large $y$ asymptotics
\begin{equation}
I_z(y) = 
\begin{cases}
\mbox{const } + \frac{2(1-\beta)}{\omega^2(2\beta-1)} 
y^{\frac{2\beta-1}{1-\beta}}\,, & \beta\neq \frac12\,, \\
\mbox{const } + \frac{2}{\omega^2} \log y\,, & \beta = \frac12\,.
\end{cases}
\end{equation}

We distinguish between two cases:

i) $\beta=\frac12$. For this case the integral $I_z(y)$ has logarithmic growth as $y\to \infty$.
The bound (\ref{nubound})
has the large $x$ asymptotics, i.e. there exists some $\kappa'>0$ such that
\begin{equation}
\nu(x) \leq \kappa \int_0^x \left( \frac{\omega^2}{R(y)}\right)^{\alpha/(1-\beta)^2}I_z(y) dy 
\leq\kappa'
\int_{1}^x \frac{\log y}{y^{\frac{2-\beta}{1-\beta}}} dy \,,
\end{equation}
for any sufficiently large $x$, where $\kappa$ is given in \eqref{kappa:defn} and the integral is
\begin{equation}
\int_{1}^x \frac{\log y}{y^{\frac{2-\beta}{1-\beta}}} dy 
= \mbox{const }
- (1-\beta) \frac{\log x + (1-\beta)}{x^{\frac{1}{1-\beta}}}\,,
\end{equation}
which is bounded as $x\to \infty$.

We conclude that for this case $\nu(x)<\infty$ for all $x$.

ii) $\beta \neq \frac12$. For this case the integrand in the upper bound (\ref{nubound}) on 
$\nu(x)$ has the large $y$ asymptotic form
\begin{equation}
\frac{1}{y^{\frac{2-\beta}{1-\beta}}} \left( \mbox{ const } + \frac{1}{2\beta-1} \cdot
\frac{1}{y^\frac{1-2\beta}{1-\beta}} \right)\,,\quad y \to \infty\,.
\end{equation}
Consider the two cases of $\beta<\frac12 $ and $\beta> \frac12$ separately.

a) For $\beta<\frac12$ the second term in the brackets is $o(1)$ and can be neglected for the large $x$ asymptotics of the integral. This is $\nu(x) \leq \nu_0 - \nu_1 \frac{1}{x^{\frac{1}{1-\beta}}}$ with $\nu_{0},\nu_{1}>0$ and is thus bounded as $x\to \infty$.

b) For $\beta > \frac12$ the second term in the brackets dominates over the first term, 
and the 
integrand has the form $\frac{dy}{y^3}$. The large $x$ asymptotics of the integral giving the upper bound on $\nu(x)$ is
$\nu(x) \leq \nu_0 - \nu_1 \frac{1}{x^2}$, which has a finite limit as $x\to \infty$.

For both cases, the function $\nu(x)$ is bounded from above by a finite value,
which implies $\nu(x) <\infty$ for all $x$. By the Feller test of explosion (Theorem~\ref{thm:Feller}), this
implies that the process $v_t$ explodes in finite time with non-zero probability.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


\begin{remark}\label{remark:explosion}
Since the process for $v_t$ in \eqref{vsde} explodes in finite time with non-zero probability, we have
$\mathbb{E}[(v_t)^p]=\infty$ for all $p>0$. In particular, the expectation $\mathbb{E}[v_t]$ is infinite.
\end{remark}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Capped Volatility Process and VIX Option Pricing}
\label{sec:3}

The result of Proposition~\ref{prop:explosion} is a surprising negative result. It implies that the VIX futures prices $F_V(T)$ in \eqref{VIX:F} and VIX call option prices $C_V(K,T)$ in \eqref{VIX:call} are infinite, and VIX put option prices $P_V(K,T)$ in \eqref{VIX:put} are zero for any maturity $T>0$ and strike $K>0$. This limits the practical usefulness of the SABR model with $\beta<1$ for pricing these products. 

On the other hand, the SABR model with $\beta=1$ has well behaved VIX options and futures. The predictions for this case have been discussed in e.g. \cite{Forde2023} and \cite{VIXpaper}.

As a remedy for the SABR model with $\beta<1$, we propose the cap
the drift and diffusion terms in the $v_{t}$ process to make it non-explosive
such that one can price the VIX options in practice.
In particular, based on the volatility process $v_{t}$ in \eqref{vsde}, 
we propose the following modification, the \emph{capped volatility process}:
\begin{eqnarray}\label{vsde:modification}
&&\frac{dv_t}{v_t} =  \hat{\sigma}_V(v_t) d W_t + \hat{\mu}_V(v_t) dt\,,
\end{eqnarray}
with \emph{capped} volatility and drift
\begin{eqnarray}
&& \hat{\sigma}_V(v) := \min\left(a,\sigma_V(v)\right)\,, 
\\
&& \hat{\mu}_V(v) := \min\left(b,\mu_V(v)\right)\cdot 1_{\mu_V(v)>0}
+\max\left(-b,\mu_V(v)\right)\cdot 1_{\mu_V(v)\leq 0}\,,
\end{eqnarray}
where $\sigma_V(v)$ and $\mu_V(v)$ are given in \eqref{sigma:v:eqn}-\eqref{mu:v:eqn} and $a,b>0$ are given caps.
Under Assumption~\ref{assump:1}, $\sigma_{V}(v)$ is monotonically
increasing in $v\geq 0$, and we assume that $a>\sigma_{V}(0)=\omega$
such that
\begin{equation}
\hat{\sigma}_V(v)=
\begin{cases}
\sigma_{V}(v)=\sqrt{\omega^2 + (\beta-1)^2 v^2 + 2\rho (\beta-1) \omega v} &\text{if $v\leq\hat{v}$},
\\
a &\text{if $v>\hat{v}$},
\end{cases}
\end{equation}
where
\begin{equation}\label{vhat}
\hat{v}:=\frac{\rho\omega+\sqrt{a^{2}+(\rho^{2}-1)\omega^{2}}}{1-\beta}.
\end{equation}

With $v_{t}$ defined in \eqref{vsde:modification},
the $T,\tau\to 0$ asymptotics of the VIX call and put options can be achieved by quoting the results 
of the short-maturity European call and put options for the local volatility model. 
First, we will show that $\mathrm{VIX}_{T}\rightarrow v_{T}$ almost surely
as $\tau\rightarrow 0$, and indeed we have the following result.

\begin{proposition}\label{prop:VIX:approx}
For any $\tau,T>0$, we have
\begin{equation}
v_{T}e^{-b\tau}\leq\mathrm{VIX}_{T}\leq v_{T}e^{b\tau+\frac{1}{2}a^{2}\tau}.
\end{equation}
\end{proposition}

\begin{proof}
First, we notice that for any $v$, 
$0\leq\hat{\sigma}_{V}(v)\leq a$
and $|\hat{\mu}_{V}(v)|\leq b$.
Next, it follows from \eqref{vsde:modification} that
for any $t\geq T$, 
\begin{equation}
v_{t}=v_{T}e^{\int_{T}^{t}(\hat{\mu}_{V}(v_{s})-\frac{1}{2}\hat{\sigma}_{V}^{2}(v_{s}))ds+\int_{T}^{t}\hat{\sigma}_{V}(v_{s})dW_{s}}.
\end{equation}
Therefore, we have
\begin{align*}
\mathbb{E}[v_{t}^{2}|\mathcal{F}_{T}]
&=v_{T}^{2}\mathbb{E}\left[e^{\int_{T}^{t}(2\hat{\mu}_{V}(v_{s})-\hat{\sigma}_{V}^{2}(v_{s}))ds+2\int_{T}^{t}\hat{\sigma}_{V}(v_{s})dW_{s}}|\mathcal{F}_{T}\right]
\\
&\leq
v_{T}^{2}e^{2b(t-T)+a^{2}(t-T)}\mathbb{E}\left[e^{-\int_{T}^{t}\frac{1}{2}(2\hat{\sigma}_{V})^{2}(v_{s})ds+\int_{T}^{t}2\hat{\sigma}_{V}(v_{s})dW_{s}}|\mathcal{F}_{T}\right]
=v_{T}^{2}e^{2b(t-T)+a^{2}(t-T)},
\end{align*}
and similarly, 
\begin{align*}
\mathbb{E}[v_{t}^{2}|\mathcal{F}_{T}]
\geq
v_{T}^{2}e^{-2b(t-T)}\mathbb{E}\left[e^{-\int_{T}^{t}\frac{1}{2}(2\hat{\sigma}_{V})^{2}(v_{s})ds+\int_{T}^{t}2\hat{\sigma}_{V}(v_{s})dW_{s}}|\mathcal{F}_{T}\right]
=v_{T}^{2}e^{-2b(t-T)}.
\end{align*}
Hence, we conclude that
\begin{align*}
\mathrm{VIX}_{T}
\leq\left(v_{T}^{2}\frac{1}{\tau}\int_{T}^{T+\tau}e^{2b(t-T)+a^{2}(t-T)}dt\right)^{1/2}
\leq v_{T}e^{b\tau+\frac{1}{2}a^{2}\tau},
\end{align*}
and
\begin{align*}
\mathrm{VIX}_{T}
\geq\left(v_{T}^{2}\frac{1}{\tau}\int_{T}^{T+\tau}e^{-2b(t-T)}dt\right)^{1/2}
\geq v_{T}e^{-b\tau}.
\end{align*}
This completes the proof.
\end{proof}

Proposition~\ref{prop:VIX:approx} implies that $|\mathrm{VIX}_{T}-v_{T}|=O(\tau)$ almost surely as $\tau\rightarrow 0$.
We can leverage this result and the short-maturity asymptotics
for European options in the local volatility model \cite{BBFpaper} to obtain the following result for short-maturity asymptotics for OTM VIX options.

Before addressing the short-maturity asymptotics of VIX options we discuss the forward VIX $F_V(T)$ defined as in (\ref{VIX:F}). In the $\tau \to 0$ limit this becomes $\mathbb{E}[v_T]$. Due to the explosion of $v_t$ in \eqref{vsde}, this expectation is infinite (Remark~\ref{remark:explosion}). However, the expectation of the capped process gives a finite but $a$-dependent value, which we denote $F_V(T,a) := \mathbb{E}[v_T]$
with the capped process $v_T$ given in \eqref{vsde:modification}.
We prove next a result for the short-maturity limit of $F_V(T,a)$ at finite $a$.

\begin{proposition}\label{prop:FVT:smallT}
We have
\begin{equation}
\lim_{T\to 0} F_V(T,a) = v_0\,.
\end{equation}
\end{proposition}

\begin{proof}
For any $T>0$, it follows from \eqref{vsde:modification} that
\begin{equation}
v_{T}=v_{0}e^{\int_{0}^{T}(\hat{\mu}_{V}(v_{s})-\frac{1}{2}\hat{\sigma}_{V}^{2}(v_{s}))ds+\int_{0}^{T}\hat{\sigma}_{V}(v_{s})dW_{s}},
\end{equation}
where $0\leq\hat{\sigma}_{V}(v)\leq a$
and $|\hat{\mu}_{V}(v)|\leq b$ for any $v$.
Therefore, we have
\begin{equation}
F_{V}(T,a)=\mathbb{E}[v_{T}]
\leq v_{0}e^{bT}\mathbb{E}\left[e^{-\int_{0}^{T}\frac{1}{2}\hat{\sigma}_{V}^{2}(v_{s})ds+\int_{0}^{T}\hat{\sigma}_{V}(v_{s})dW_{s}}\right]=v_{0}e^{bT},
\end{equation}
and
\begin{equation}
F_{V}(T,a)=\mathbb{E}[v_{T}]
\geq v_{0}e^{-bT}\mathbb{E}\left[e^{-\int_{0}^{T}\frac{1}{2}\hat{\sigma}_{V}^{2}(v_{s})ds+\int_{0}^{T}\hat{\sigma}_{V}(v_{s})dW_{s}}\right]=v_{0}e^{-bT},
\end{equation}
which completes the proof.
\end{proof}

This implies that for sufficiently small $T$, OTM VIX call options have $K>v_0$ and OTM VIX put options have $K< v_0$.


\begin{theorem}\label{thm:VIX:option}
Let $C_{V}(K,T)$ and $P_{V}(K,T)$ denote the VIX call and put option prices under the capped volatility model \eqref{vsde:modification}. 
Then
\begin{eqnarray}
&&\lim_{\tau,T\to 0} T \log C_V(K,T) = - J_V(K)\,,\quad K > v_0\,,\label{VIX:call:OTM} \\
&&\lim_{\tau,T\to 0} T \log P_V(K,T) = - J_V(K)\,,\quad K < v_0\,,\label{VIX:put:OTM}
\end{eqnarray}
where the rate function is
\begin{equation}\label{J:V:eqn}
J_{V}(K) = \frac12 \left( \int_{v_0}^K \frac{dz}{z \hat{\sigma}_V(z)} \right)^2\,.
\end{equation}    
\end{theorem}

\begin{proof}
By Proposition~\ref{prop:VIX:approx} and short-maturity asymptotics for European options in the local volatility model \cite{BBFpaper}, 
we can compute that for any $\tau>0$ and $K>v_{0}$,
\begin{align*}
\limsup_{T\rightarrow 0}T\log C_{V}(K,T)
&=\limsup_{T\rightarrow 0}T\log\mathbb{E}[(\mathrm{VIX}_{T}-K)^{+}]
\\
&\leq\limsup_{T\rightarrow 0}T\log\mathbb{E}[(v_{T}e^{b\tau+\frac{1}{2}a^{2}\tau}-K)^{+}]
\\
&=\limsup_{T\rightarrow 0}T\log\mathbb{E}[(v_{T}-Ke^{-b\tau-\frac{1}{2}a^{2}\tau})^{+}]
=-J_{V}\left(Ke^{-b\tau-\frac{1}{2}a^{2}\tau}\right),
\end{align*}
where $J_{V}(\cdot)$ is defined in \eqref{J:V:eqn}.
Similarly, we can compute that for any $\tau>0$ and $K>v_{0}$,
\begin{align*}
\liminf_{T\rightarrow 0}T\log C_{V}(K,T)
&=\liminf_{T\rightarrow 0}T\log\mathbb{E}[(\mathrm{VIX}_{T}-K)^{+}]
\\
&\geq\liminf_{T\rightarrow 0}T\log\mathbb{E}[(v_{T}e^{-b\tau}-K)^{+}]
\\
&=\liminf_{T\rightarrow 0}T\log\mathbb{E}[(v_{T}-Ke^{b\tau})^{+}]
=-J_{V}\left(Ke^{b\tau}\right).
\end{align*}
Since it holds for any $\tau>0$, by letting $\tau\rightarrow 0$, 
we showed that \eqref{VIX:call:OTM} holds.
Similarly, we can show that \eqref{VIX:put:OTM} holds. 
This completes the proof.
\end{proof}

In particular, for OTM call options, i.e. $K>v_{0}$, we have
\begin{equation}
J_{V}(K)=
\begin{cases}
\frac{1}{2}\left(\int_{v_{0}}^{K}\frac{dz}{z\sigma_{V}(z)}\right)^{2} &\text{if $\hat{v}\geq K>v_{0}$},
\\
\frac{1}{2}\left(\int_{v_{0}}^{\hat{v}}\frac{dz}{z\sigma_{V}(z)}+\frac{\log(K/\hat{v})}{a}\right)^{2} &\text{if $K>\hat{v}>v_{0}$},
\\
\frac{1}{2}\left(\frac{\log(K/v_{0})}{a}\right)^{2} &\text{if $K>v_{0}\geq\hat{v}$},
\end{cases}
\end{equation}
and for OTM put options, i.e. $K<v_{0}$, we have
\begin{equation}
J_{V}(K)=
\begin{cases}
\frac{1}{2}\left(\frac{\log(K/v_{0})}{a}\right)^{2} &\text{if $\hat{v}\leq K<v_{0}$},
\\
\frac{1}{2}\left(\int_{K}^{\hat{v}}\frac{dz}{z\sigma_{V}(z)}+\frac{\log(v_{0}/\hat{v})}{a}\right)^{2} &\text{if $K<\hat{v}<v_{0}$},
\\
\frac{1}{2}\left(\int_{K}^{v_{0}}\frac{dz}{z\sigma_{V}(z)}\right)^{2}  &\text{if $K<v_{0}\leq\hat{v}$}.
\end{cases}
\end{equation}

We define the implied volatility of the VIX options $\sigma_{\mathrm{VIX}}(K,T)$ in the capped volatility model \eqref{vsde:modification} as
\begin{align}\label{sigVIX:def}
    C_V(K,T) &= e^{-rT } c_{\mathrm{BS}}(K,T;F_V(T,a),\sigma_{\mathrm{VIX}}(K,T))\,, \\
    P_V(K,T) &= e^{-rT } p_{\mathrm{BS}}(K,T;F_V(T,a),\sigma_{\mathrm{VIX}}(K,T))\,, \nonumber
\end{align}
where $c_{\mathrm{BS}}(K,T;F,\sigma)$ and $p_{\mathrm{BS}}(K,T;F,\sigma)$ are the undiscounted Black-Scholes option prices with forward $F$ and volatility $\sigma$ and $F_V(T,a) = \mathbb{E}[v_T]$.

The short-maturity option pricing result of Theorem \ref{thm:VIX:option} translates in the usual way into a short-maturity result for the VIX implied volatility. 
Assume that the cap $a$ is sufficiently large, such that $\hat{v}>K$ and $\hat{v}>v_{0}$. Then, the short-maturity asymptotics for the VIX call and put options is equivalent with the
short-maturity asymptotics of the VIX implied volatility
\begin{equation}\label{BBF}
\lim_{T\to 0} \sigma_{\mathrm{VIX}}(x,T) := \sigma_{\mathrm{VIX}}(x)=\frac{\log(K/v_0)}{\int_{v_0}^K \frac{dz}{z \hat{\sigma}_V(z)}} = \frac{\log(K/v_0)}{\int_{v_0}^K \frac{dz}{z \sigma_V(z)}}\,,
\end{equation}
where $x = \log(K/v_0)$ is the log-strike. 
We used here the result of Proposition~\ref{prop:FVT:smallT} to take the limit $\lim_{T\to 0} F_V(T,a)=v_0$ for any finite $a$. 

The integral in the denominator in \eqref{BBF} can be evaluated exactly with the result
\begin{equation}
\int_{v_0}^K \frac{dz}{z \sigma_V(z)} = \frac{1}{\omega}
\left\{\arctanh\left(\frac{\rho(\beta-1) v_0 + \omega}{\sigma_V(v_0)}\right)
-\arctanh\left(\frac{\rho (\beta-1) K + \omega}{\sigma_V(K)}\right) 
\right\} \,.
\end{equation}

The VIX implied volatility \eqref{BBF} can be expanded in log-strike
\begin{equation}
\sigma_{\mathrm{VIX}}(x) = \sigma_{\mathrm{VIX}}(0) + s_{\mathrm{VIX}}\cdot x + \frac12 \kappa_{\mathrm{VIX}}\cdot x^2 +O(x^3)\,,
\end{equation}
as $x\rightarrow 0$, where the ATM level, skew and convexity of the VIX implied volatility are
\begin{align}
\sigma_{\mathrm{VIX}}(0) &:= \sigma_V(v_0)\,,\\
\label{skewVIX}
s_{\mathrm{VIX}} &:= v_0 \frac{d}{dv} \sigma_{\mathrm{VIX}}(v_0) = v_0 (\beta-1) \frac{\rho\omega + (\beta-1) v_0}{2\sigma_{V}(v_0)} \,,
\end{align}
and 
\begin{equation}\label{cvxVIX}
\kappa_{\mathrm{VIX}} := \frac{v_0 (\beta-1)}{3\sigma_V^4(v_0)}
\left( 2\omega^3 \rho + (\beta-1) \omega^2 (4 + \rho^2) v_0 +
4 (\beta-1)^2 \omega \rho v_0^2 + (\beta-1)^3 v_0^3 \right) \,.
\end{equation}

These results for the ATM level, skew and convexity are reproduced by
Proposition~6.2 in \cite{VIXpaper} by taking $\eta(x) = x^{\beta-1}$ in that result,  
although, strictly speaking, they do not follow from Proposition 6.2 of \cite{VIXpaper} since the CEV local volatility function $\eta(x)$ does not satisfy the technical conditions required for its validity.

\begin{remark}\label{rmk:vix}
For $\beta<1$ and $\rho<0$, the VIX skew (\ref{skewVIX}) is positive, which agrees with the empirical evidence: the observed VIX smile is up-sloping. 
On the other hand, the VIX convexity (\ref{cvxVIX}) is positive,
which unfortunately disagrees with empirical evidence: the observed VIX smile is concave. This disfavors the SABR model as a realistic model for VIX smiles.
\end{remark}
