\renewcommand{\arraystretch}{2}
  \begin{tabular}{c|ccc}
    & $\dd y^i \wedge \dd^{n-1}x_\mu$& $\dd p^\mu_i \wedge \dd^{n-1}x_\mu$  & $\dd^n x$\\
    \hline
    $ \dd y^j \wedge \dd^n x$ & $0$ & $\delta^j_i \dd^n x$ & $ 0$\\
