\title {\Large On scaling factor for $^{28}$Si + $^{12}$C charge-changing cross sections at 90-1296 MeV/nucleon: Toward finding energy-dependent scaling factor for other elements}

\author{Z. \surname{Hasan}$^1$}\email{zafaramu@gmail.com}
