\section{Identification Proofs}\label{ap:idproofs}

\noindent 
Proof of Theorem 1:
\begin{proof}
Suppose the relevant assumptions hold. For $a\in\A$, we have
    \begin{align}
        \E[Y|Z,A=a,X] &= \E[\E[Y|U,Z,A=a,X]|Z,A=a,X]\\
        &= \E[\E[Y(a)|U,Z,A=a,X]|Z,A=a,X]\\
        &= \E[\E[Y(a)|U,X]|Z,A=a,X]
    \end{align}
using the law of iterated expectation, consistency, and conditional independence. 

By Assumption~4.2, there exist $\tau(a,X)$ so that $\E[Y(a)|U,X] = \tau(a,X) g(U,X)$ for each $a \in \A$. Therefore,
\begin{align*}
    \E[Y|Z,A=a,X]
        = \tau(a,X)\E[g(U,X)|Z,A=a,X].
\end{align*}
Note that the left hand side is a function of the observed distribution, whereas 

\noindent
$\E[g(U,X)|Z,A=a,X]$ can be identified by the observed distribution by Assumption~4.1. Provided $\tau(a,X)$ is the unique solution to the above equation, then we can identify $\tau(a,X)$ from the observed distribution.
Then, consider 
\begin{align*}
    \E[Y(a)|Z,X] &= \E[\E[Y(a)|U,Z,X]|Z,X]\\
    &= \E[\E[Y(a)|U,X]|Z,X]\\
    &= \E[\tau(a,X)g(U,X)|Z,X]\\
    &= \tau(a,X)\E[g(U,X)|Z,X].
\end{align*} 
The first step comes from the law of iterated expectation, the second from conditional independence, the third by Assumption~4.2, and finally by linearity of expectations. Again by linearity, $$\mathbb{E}[Y(a)-Y(a')|Z=z,X]=(\tau(a,X)-\tau(a',X))\mathbb{E}[g(U)|Z=z,X].$$
It remains to argue that $\mathbb{E}[g(U,X)|Z=z,X]$ can be identified from the observed distribution. This comes from Assumption~4.1. Since $\E[g(U,X)|Z,A,X]$ can be identified from the observed distribution for $(Z,A,X)$, then $\E[g(U,X)|Z=z,X] = \E[\E[g(U,X)|Z=z,A,X]|Z=z,X]$ can be identified from the observed distribution as well.
\end{proof}

\section{Multiple Indicators Multiple Causes Model Properties}\label{ap:mimic}
\begin{observation}
    From the definitions of the MIMIC model, it must be true that $$Z|U \sim MVN(\Lambda U+\nu, \Psi)$$ and $$Z\sim MVN(\nu, \Lambda\Lambda'+\Psi).$$  We also have 
\begin{align*}
    \E[U|X] = \E[\Gamma X + \varepsilon_U|X] = \Gamma X
\end{align*}
and 
\begin{align*}
    \E[(U-\Gamma X)(U-\Gamma X)'|X] = \E[\varepsilon_U\varepsilon_U'] = I.
\end{align*}
\end{observation} 


For the moment, we reduce MIMIC to the usual factor analysis model by ignoring $X$.
\begin{observation}\label{matrixaug}
    Let $A=b'U+c+\varepsilon_A$. If we augment the necessary matrices, we can write $$\begin{bmatrix}
    Z\\A
\end{bmatrix} = \begin{bmatrix}
    \Lambda\\
    b'
\end{bmatrix}U + \begin{bmatrix}
    \nu\\c
\end{bmatrix} + \begin{bmatrix}
    \Psi^{1/2}\varepsilon_Z\\\varepsilon_A
\end{bmatrix}.$$
    Therefore it must be true that 

    $$\begin{bmatrix}
        Z\\A
    \end{bmatrix}|U\sim MVN\left(\begin{bmatrix}
    \Lambda\\
    b'
\end{bmatrix}U + \begin{bmatrix}
    \nu\\c
\end{bmatrix}, \begin{bmatrix}
        \Psi & \overset{\rightharpoonup}{0}\\
        \overset{\rightharpoonup}{0}' & 1
    \end{bmatrix}\right)$$

    and
    $$\begin{bmatrix}
        Z\\A
    \end{bmatrix}\sim MVN\left(\begin{bmatrix}
        \nu\\c
    \end{bmatrix},
    \begin{bmatrix}
        \Lambda\\b'
    \end{bmatrix} 
    \begin{bmatrix}
        \Lambda'&b
    \end{bmatrix}  +    
    \begin{bmatrix}
        \Psi & \overset{\rightharpoonup}{0}\\
        \overset{\rightharpoonup}{0}' & 1
    \end{bmatrix}\right)$$ where $\overset{\rightharpoonup}{0}$ is a $p\times1$ vector of zeros.      

    We will denote the covariance matrix $$\begin{bmatrix}
        \Psi & \overset{\rightharpoonup}{0}\\
        \overset{\rightharpoonup}{0}' & 1
    \end{bmatrix}$$ by $\Psi^*$.
\end{observation}

\begin{lemma}\label{Minvertible}
    Define $M:=(\Lambda'\Psi^{-1}\Lambda+I).$ If $\Lambda$ is full rank, $M$ is invertible.
\end{lemma}
\begin{proof}
    We will show $\Lambda'\Psi^{-1}\Lambda$ is positive definite since the sum of positive definite matrices is also positive definite, and therefore invertible.  Clearly $\Lambda'\Psi^{-1}\Lambda$ is symmetric.
    As an invertible covariance matrix, $\Psi$ must be positive definite. The inverse must also be positive definite since the inverse of the eigenvalues of a matrix are the eigenvalues of the matrix inverse. Since $\Lambda$ is full rank, $\Lambda v=0$ if and only if $v$ is the zero vector. For a nonzero vector $v\in\mathbb{R}^k$,
    \begin{align*}
        v'\Lambda'\Psi^{-1}\Lambda v &= (\Lambda v)'\Psi^{-1}(\Lambda v) > 0
    \end{align*} since $\Lambda v\neq0$ and $\Psi^{-1}$ is positive definite.
\end{proof}

\begin{lemma}\label{ufromz}
    Let $U\sim MVN(0,I)\in\mathbb{R}^k$, and $Z|U\sim MVN(\Lambda U+\nu,\Psi)\in\mathbb{R}^p$. Fix $z\in \mathbb{R}^p$ and let $d:=\Lambda'\Psi^{-1}(z-\nu)$. If $M:=(\Lambda'\Psi^{-1}\Lambda+I)$ is invertible, then $$U|Z=z\sim MVN(M^{-1}d, M^{-1}).$$ 
\end{lemma}
\begin{proof}
    Since $Z$ and $U$ have densities, we can consider 
    $f_{U|Z=z}(u) = f_{Z|U=u}(z)f_U(u)/f_Z(z)$ using Bayes rule. 
    Then, up to a constant in $z$,
    \begin{align*}
        \frac{f_{Z|U=u}(z)f_U(u)}{f_Z(z)} &\propto \exp\left(-\frac{1}{2}\left(z-\Lambda u-\nu\right)'\Psi^{-1}\left(z-\Lambda u-\nu)\right)\right)\exp\left(-\frac{1}{2}u'u\right)\\
        &= \exp\left(-\frac{1}{2}\left((z-\nu)'\Psi^{-1}(z-\nu)+u'(\Lambda'\Psi^{-1}\Lambda+I)u-2(z-\nu)'\Psi^{-1}\Lambda u\right)\right)\\
        &\propto \exp\left(-\frac{1}{2}\left(u - M^{-1} d\right)'M\left(u-M^{-1}d\right)\right) 
    \end{align*}
\end{proof}

Using the matrix augmentation from Observation \ref{matrixaug}, we arrive at the following corollary.

\begin{corr}\label{ufromzastar}
    Let $A=b'U+c+\varepsilon_A$ where $U,b,c,\varepsilon_A,$ and $Z$ are defined as in Assumption 4.3. If $M^*=\begin{bmatrix}
        \Lambda'&b
    \end{bmatrix}
   (\Psi^*)^{-1} 
    \begin{bmatrix}
        \Lambda\\b'
    \end{bmatrix}
    +I
    $ is invertible then $U|Z=z,A=a\sim MVN((M^*)^{-1}d^*,(M^*)^{-1})$ where $d^*=\begin{bmatrix}
        \Lambda' & b
    \end{bmatrix}
    (\Psi^*)^{-1}\begin{bmatrix}
        z-\nu\\a-c
    \end{bmatrix}
    $.
\end{corr}



We can compute $U|Z,X$ for the MIMIC model in a similar manner to the computation for $U|Z$ above.  We have
\begin{align*}
    f_{U|Z,X}(u) = \frac{f_{U,Z,X}(u, z, x)}{f_{Z,X}(z, x)} = \frac{f_{Z|U}(z)f_{U|X}(u)f_X(x)}{f_{Z|X}(z)f_X(x)} = \frac{f_{Z|U}(z)f_{U|X}(u)}{f_{Z|X}(z)} \propto f_{Z|U}(z)f_{U|X}(u).
\end{align*}

Therefore
\begin{align*}
    f_{U|Z,X}(u) &\propto \exp\left(-\frac{1}{2}\left[(z-\Lambda U - \nu)'\Psi^{-1}(z-\Lambda U - \nu)' + (U - \Gamma X)'(U-\Gamma X)\right]\right) \\
    &\propto \exp\left(-\frac{1}{2}\left[U'\Lambda'\Psi^{-1}\Lambda U - 2 (z-\nu)'\Psi^{-1}\Lambda U + U'U -2X'\Gamma'U\right]\right)\\
    &\propto \exp\left(-\frac{1}{2}\left[U'(\Lambda'\Psi^{-1}\Lambda + I)U -2\left((z-\nu)'\Psi^{-1}\Lambda + X'\Gamma'\right)U\right]\right)\\
    &\propto \exp\left(-\frac{1}{2}(U'MU -2(d' + X'\Gamma')U\right)\\
    &\propto \exp\left(-\frac{1}{2}\left(U - M^{-1}(d+\Gamma X)\right)'M\left(U - M^{-1}(d+\Gamma X)\right)\right)
\end{align*}

so $U|Z,X\sim MVN(M^{-1}(d + \Gamma X), M^{-1})$.

Similarly to the process for incorporating $A$ previously, if we augment our matrices we can show that $U|Z,X,A\sim MVN((M^*)^{-1}(d^*+\Gamma X), (M^*)^{-1}).$

