\subsection*{Comparison methods}\label{app:compmethods}
We provide R code used for the comparison methods to enable replication.  Each function requires a dataframe of observations of $Z,A,Y$.

\vspace{.25in}
\noindent
We use a modification of the usual IPW algorithm to allow for continuous treatments.  Note that for binary treatments we use the usual IPW algorithm with logistic regression.
\begin{verbatim}
continuousIPWest <- function(df) {
  AZ <- subset(df, select = -c(Y))
  Z <- subset(AZ, select = -c(A))

  m1 <- glm(formula = A ~ ., family = gaussian(link = "identity"), data = AZ)
  meanAZ <- predict(m1, newdata = Z, type = "response")
  varAZ <- var(df$A - meanAZ)
  weightings <- dnorm(df$A, mean = meanAZ, sd = sqrt(varAZ))

  m2 <- glm(formula = A ~ 1, family = gaussian(link = "identity"), data = AZ)
  meanA <- predict(m2, newdata = df, type = "response")
  varA <- var(df$A - meanA)
  numerators <- dnorm(df$A, mean = meanA, sd = sqrt(varA))

  df$full.weights <- numerators / weightings
  df$A2 <- df$A^2
  design <- svydesign(
    id = ~1,
    weights = ~full.weights,
    data = df
  )

  m3 <- svyglm(
    formula = formula(paste("Y ~ A + A2 + ",
    paste0(colnames(Z), collapse = " +"))),
    family = gaussian(link = "identity"),
    data = df, design = design)

  newdata1 <- data.frame("A" = 1, Z, "A2" = 1)
  EY1 <- mean(predict(m3, newdata1))
  newdata0 <- data.frame("A" = 0, Z, "A2" = 0)
  EY0 <- mean(predict(m3, newdata0))

  return(EY1 - EY0)
}
\end{verbatim}

\vspace{.25in}
\noindent
We use a simple linear model for $Y$ in terms of $A$ and $Z$, and extract the coefficient on $A$ for the ATE estimate.
\begin{verbatim}
linearEst <- function(df) {
  m1 <- lm(Y ~ ., df)
  linear.ATE <- m1$coefficients["A"]

  return(linear.ATE)
}
\end{verbatim}

\vspace{.25in}
\noindent 
For proximal causal inference, you must additionally provide lists of the NCOs and NCEs that are included in the dataframe.

\begin{verbatim}
proximal_causal <- function(df, nco.names, nce.names){
  wformulas <- paste(nco.names,
                    " ~ A + ", paste0(nce.names, sep = "",
                    collapse = " + "),
                    " + ", paste0("A * ", nce.names, sep = "",
                    collapse = " + "), sep = "")
  m.hW <- lapply(wformulas, lm, data = df)
  wav <- sapply(m.hW, predict, data = df[,c("A", "Y", nce.names)])

  prior.names <- colnames(df)
  df <- cbind(df, wav)
  colnames(df) <- c(prior.names,
                    paste("wav", 1:length(nco.names), sep = ""))

  # estimate tau_a
  m1formula <- paste("Y ~ A + ",
                     paste0("wav", 1:length(nco.names), collapse = " + "),
                     " + ",
                     paste0("A * ", paste("wav", 1:length(nco.names),
                     sep = ""), collapse = " + "),
                     sep = "")
  m1 <- lm(m1formula, df)
  alpha <- m1$coefficients[c("(Intercept)",
                           paste("wav", 1:length(nco.names), sep = ""))]
  gamma <- m1$coefficients[c("A", paste("A:wav", 1:length(nco.names),
                           sep = ""))]

  # calc CATE
  mWVformulas <- paste(nco.names,
                      " ~ ", paste0(nce.names, collapse = " + "))
  m.WVs <- lapply(mWVformulas, lm, data = df)
  WVs <- lapply(m.WVs, predict, data = df)
  CATE <- gamma[1] + gamma[2:(1 + length(nco.names))] %*% 
            t(sapply(WVs, unlist))
  return(mean(CATE))
}

\end{verbatim}

\vspace{.25in}
\noindent
We implement a standard IV algorithm.
\begin{verbatim}
IVest <- function(df) {
  AZ <- subset(df, select = -c(Y))

  m1 <- lm(formula = A ~ ., data = AZ)
  df$x <- predict(m1, newdata = df)

  m2 <- lm(formula = Y ~ x, data = df)

  IV_ATE <- m2$coefficients[["x"]]
  return(IV_ATE)
}
\end{verbatim}

