\subsection{Permutation tables}
As is standard, we denote the set of all permutations of $[n] = \{1,\ldots,n\}$ by $S_n$ and we define the sign $\sgn(\pi)$ of a permutation $\pi \in S_n$ to be $1$ if $\pi$ is the product of an even number of transpositions and $-1$ if $\pi$ is the product of an odd number of transpositions.
\begin{definition}
We say $\tau$ is a permutation ($k$-)table with $n$ columns %$n=\operatorname{col}(\tau)$ columns, 
if $\tau$ is a $k \times n$ table and there are permutations $\pi_1,\ldots,\pi_k \in S_n$ such that the $j$th row of $\tau$ is $(\pi_j(1),\ldots,\pi_j(n))$. 
%rows are permutations $\pi_j, j = 1,\ldots,k$ of order $n$. 
We denote the set of all such $k$-tables with $n$ columns by $F_{k,n}$. Equivalently, $F_{k,n} = S_n \times \cdots\times S_n$ ($k$ copies of $S_n$). Finally, we denote $k$-tables with any number of columns by $F_k$. %We denote $F_{k,n}$ the set of all such $k$-tables with $n$ columns and by $F_k$ we denote $k$-tables with any number of columns. 
That is, structurally, $F_k = \cup_{n=0}^\infty F_{k,n}$.
\end{definition}
\begin{definition}
We define the sign of a table as the product of the signs of the permutations in its rows.
\end{definition}
\begin{definition}
We define the weight of the $i$-th column of $\tau \in F_k$ to be the expectation $\Exx \left[\prod_{j=1}^k A_{i\pi_j(i)}\right]$. We define the weight $w(\tau)$ of the whole table $\tau$ to be the product of the weights of its columns.
\end{definition}

