\begin{definition}
We say $\sigma$ is a \emph{marked permutation} if it is either in $S_n$ (i.e., $\sigma$ is a permutation of $[n]$) or $\sigma$ is formed from some $\pi \in S_n$ by replacing at most one element by the mark ``$\times$''. %in which we replaced at most one element by the mark ``$\times$''. 
We define $\sgn(\sigma) = \sgn(\pi)$ and $B^\times_{i\sigma(i)} = m_1$ if $i$ is marked and $B^\times_{i\sigma(i)} = B_{i\pi(i)}$ otherwise. We write $S^\times_n$ for the set of all marked permutations.
\end{definition}
\begin{proposition} In terms of marked permutations, $\det(A) = \sum_{\sigma \in S^\times_n} \sgn(\sigma) \prod_{i=1}^n B_{i \sigma(i)}^\times$.
\end{proposition}

\begin{definition}
We say $\tau$ is a marked $k$-table with $n$ columns if its rows are marked permutations $\sigma_j, j = 1,\ldots,k$ of order $n$. We define $G^{\times}_{k,n}=S_n^\times\times\cdots \times S_n^\times$ ($k$ copies) to be the set of all such tables and let $G^\times_k=\sum_{n=0}^\infty G_{k,n}^\times$ be the set of all marked tables with $k$ rows. We define the marked weight $w$ of the $i$-th column of $\tau \in G_{k,n}^{\times}$ as the expectation $\Exx \left[\prod_{j=1}^k B^\times_{i\sigma_j(i)}\right]$. Similarly, we define the sign $\sgn(\tau)$ of $\tau$ to be the product of the signs of $\sigma_j, j=1,\ldots,k$ and we define the marked weight $w(\tau)$ of $\tau$ to be the product of the weights of its individual columns.
\end{definition}

