\section{Fourth moment central}
Note that when $m_1 = 0$, the number of tables with nontrivial weight is reduced significantly. As a consequence, we can easily derive the result of Nyquist, Rice and Riordan \cite{nyquist1954distribution}, namely $F_4^{\mathrm{sym}}(t)$ and the corresponding $f_4^{\mathrm{sym}}(n)$.
\begin{proposition}[Nyquist, Rice and Riordan \cite{nyquist1954distribution}]\label{Prop:NRR}
\begin{equation}
    F_4^{\mathrm{sym}}(t) = \frac{e^{t(m_4-3 m_2^2)}}{(1-m_2^2 t)^3}.
\end{equation}
\end{proposition}
\begin{corollary}
\begin{equation}
    f^{\mathrm{sym}}_4(n) = n!^2 m_2^{2n} \sum_{j=0}^n \frac{1}{j!} \left(\frac{m_4}{m_2^2} - 3\right)^j \binom{n-j+2}{2}.
\end{equation}    
\end{corollary}
\begin{remark}
In fact, those formulae holds even if $A_{ij}$'s follow just a centered distribution. That is, $ f^{\mathrm{cen}}_4(n) =  f^{\mathrm{sym}}_4(n)$ and $F^{\mathrm{cen}}_4(t) =  F^{\mathrm{sym}}_4(t)$. This is due to the fact that $m_3$ appears always as a product $m_1 m_3$ in the $f_4(n)$ polynomial.
\end{remark}


\begin{proof}[Proof of Proposition \ref{Prop:NRR}]
Let $a,b$ be different integers, then there are two types of columns we need to consider which give rise to tables with nontrivial weights (see the diagram below). It is convenient to denote those tables as $F_4^{\mathrm{sym}}$ (or $\mathcal{F}_4^{\mathrm{sym}}$ if we do not care about the order of columns).
