\section{General fourth moment%Fourth moment general
}
In this section, we generalise the result for $F_4(t)|_{m_1=0}$ by Nyquist, Rice and Riordan.
\begin{theorem}[Beck 2023 \cite{beck2022fourth}]\label{Thm:FourthMoment}
For any distribution of $\Omega$,
\begin{equation*}
F_4(t) = \frac{e^{t(\mu_4-3 \mu _2^2)}}{(1-\mu_2^2 t)^3} \left((1+m_1\mu_3 t)^4+6m_1^2\mu_2 t\frac{(1+m_1 \mu_3t)^2}{1-\mu _2^2 t}+m_1^4 t\frac{1+7 \mu_2^2 t+4 \mu _2^4 t^2}{(1-\mu _2^2 t)^2}\right).
\end{equation*}
\end{theorem}
\begin{corollary}
Furthermore, defining $d_0(c) = 2+c$, $d_1(c) = c(2+c)$ and $d_2(c) = c^3$,
\begin{equation*}
f_4(n) = n!^2 \sum _{w=0}^2 \sum _{s=0}^{4-2w} \sum _{c=0}^{n-s} \binom{4-2 w}{s}\frac{(1+c) m_1^{s+2 w} \mu_2^{2c-w} \mu _3^s \left(\mu _4-3\mu_2^2\right){}^{n-c-s}}{(n-c-s)!(2-w)! w!} d_w(c).
\end{equation*}
\end{corollary}

\begin{proof}
Without the loss of generality, we set $\mu_2 = 1$ (the general case is obtained by the scaling property of determinants). Let $a,b$ denote different numbers selected from $[n]=\{1,2,3,\ldots,n\}$. Up to a permutation of rows, the only ways how the columns of $4$ by $n$ tables with nonzero weight could look like are as follows:
