\section{Sixth moment when $m_1 = 0$%central
}
The proof of the following theorem was already established in our paper \cite{LP2022}. In this section, we provide a more compact version of the proof based on inclusion/exclusion and the fact we know the EGF for the special case where $A_{ij}$ is normally distributed.

\begin{theorem}[Beck, Lv, Potechin 2023 \cite{LP2022}]\label{thm:F6cen}
For any distribution of $\Omega$ with $m_1=0$,
\begin{equation*}
    F_6(t)|_{m_1 = 0} = (1+m_3^2t)^{10}\,\frac{e^{t \left(m_6-15m_4m_2-10m_3^2 + 30m_2^3\right)}}{\left(1+3m_2^3t-m_4m_2t\right)^{15}} N_6\left(\frac{m_2^3t}{\left(1+3m_2^3t-m_4m_2t\right)^{3}}\right).
\end{equation*}
where $N_6(t) = \frac{1}{48}\sum_{n=0}^\infty (n+1)(n+2)(n+4)! \,t^n$ is the exponential generating function for the sixth moment of random matrices with i.i.d. Gaussian entries.
\end{theorem}
\begin{corollary}
Furthermore, defining $q_6 = m_6 - 10m_3^2- 15m_4m_2+ 30m_2^3$ and $q_4 = m_4m_2- 3m_2^3$,
\begin{equation*}
f_6(n)|_{m_1=0} = n!^2 \sum _{j=0}^n \sum _{i=0}^j \sum_{k=0}^{n-j} \frac{(1+i) (2+i) (4+i)! }{48 (n-j-k)!}\binom{10}{k}\binom{14+j+2i}{j-i} q_6^{n-j-k} q_4^{j-i}m_3^{2k} m_2^{3i}.
\end{equation*}
\end{corollary}

\begin{proof}
Without the loss of generality, we assume $m_2 = 1$ throughout the proof. The fact that $m_1 = 0$ reduces the number of tables with nontrivial weight. It is convenient to denote $\mathcal{F}^\mathrm{cen}_6$ as the set of those tables (where the column order is irrelevant), which in turn contribute to the sum $f_6(n)|_{m_1=0}$. These tables can be constructed out of the following columns (up to permutations  of the rows):

