\section{The 2D Boussinesq-Peregrine equations}

In order to model the evolution of perturbed waves we consider surface waves in a homogeneous fluid within the scope of the non-dimensional 2D Boussinesq-Peregrine system \citep{P}, with flat bottom:
\begin{eqnarray}
\eta_t + \nabla \cdot \{(1 + \epsilon \eta) \mathbf{u} \} &&= 0,  \label{Bouss1} \\
\mathbf{u}_t + \epsilon (\mathbf{u} \cdot \nabla ) \mathbf{u} + \nabla \eta - \frac{\delta^2}{3} \nabla (\nabla \cdot \mathbf{u}_t ) &&= \mathbf{0}, \label{Bouss2}
\end{eqnarray}
where $\mathbf{u} = (u,v)^{\text{T}}$ are the depth averaged horizontal velocities, $\eta$ is the free surface elevation, $\epsilon$ is the small amplitude parameter, and $\delta$ is the long wavelength parameter. We numerically solve this system using the method outlined in Appendix \ref{appA}. 

It can be shown that this 2D Boussinesq-Peregrine system conserves mass exactly, while momentum and energy are conserved asymptotically, see \citet{KMS,KK}. The integral forms for these conservation laws can be written as
\begin{eqnarray}
\frac{\partial \mathcal{M}}{\partial t} &&= \frac{\partial}{\partial t} \iint_D  \eta ~ \mathrm{d}x \mathrm{d}y = 0, \\
\frac{\partial \mathcal{P}}{\partial t} &&= \frac{\partial}{\partial t} \iint_D  \left( 1 + \epsilon \eta \right) \mathbf{u} ~ \mathrm{d}x \mathrm{d}y = \textit{O}(\epsilon^2,\epsilon\delta^2,\delta^4), \\
\frac{\partial \mathcal{E}}{\partial t} &&= \frac{\partial}{\partial t} \iint_D  \frac{1}{2} \left( |\mathbf{u}|^2 + \eta^2 \right) ~ \mathrm{d}x \mathrm{d}y = \textit{O}(\epsilon,\delta^2),
\end{eqnarray}
respectively, where $D$ is the rectangular computation domain. See Appendix \ref{appB} for the details. In order to match the derivation of the reduced amplitude equations we choose the balance $\epsilon = \delta^2$. We therefore expect mass to be conserved  in numerical simulations to machine precision, and for the error in momentum and energy to scale as $\epsilon^2$ and $\epsilon$, respectively, and so numerical error is expected to be negligible for sufficiently small $\epsilon$. 

Here, we choose to derive the KdV$\theta$ and cKdV equations directly, in the slow radius form. We adopt the balance $\epsilon = \delta^2$ and apply the non-axisymmetric change of variables $(t,x,y) \rightarrow (t,r,\theta)$, to give
\begin{eqnarray}
\eta_t + U_r + \frac{U}{r} + \frac{V_{\theta}}{r} + \epsilon \left[U\eta_r + \eta U_r + \frac{U\eta + V\eta_{\theta} + \eta V_{\theta}}{r} \right] &&= 0, \label{trt1} \\
U_t + \eta_r + \frac{\epsilon}{3} \left[\frac{U_t + V_{t\theta}}{r^2} - \frac{U_{rt} - 3VU_{\theta} + 3V^2 - V_{rt\theta}}{r} - U_{rrt} + 3UU_r \right] &&= 0, \label{trt2} \\
V_t + \frac{\eta_{\theta}}{r} + \frac{\epsilon}{3}\left[-\frac{U_{t\theta} + V_{t\theta\theta}}{r^2} - \frac{3UV + 3VV_{\theta} - U_{tr\theta}}{r} + 3UV_r \right] &&= 0, \label{trt3}
\end{eqnarray}
where the variables $U$ and $V$ are the cylindrically projected velocity components of $\mathbf{u}$:
\begin{eqnarray}
u &&= U \cos\theta - V \sin\theta, \label{cartu} \\
v &&= U \sin\theta + V \sin\theta. \label{cartv}
\end{eqnarray}
To leading order we obtain
\begin{eqnarray}
    \eta_{tt} - \eta_{rr} - \frac{\eta_r}{r} - \frac{\eta_{\theta\theta}}{r^2} &&= 0, \label{Lo1} \\
    U_t + \eta_r &&= 0, \label{Lo2} \\
    V_t + \frac{\eta_{\theta}}{r} &&= 0,
\end{eqnarray}
where $\eta = \eta(\xi)$, given $\xi = rk(\theta) - t$, is an exact solution of (\ref{Lo1}) if $k(\theta)$ is the general solution $k(\theta) = a\cos\theta + b(a)\sin\theta$ and $a^2 + b^2 = 1$, e.g. $a = \cos \varphi$ and $b = \sin \varphi$, where $\varphi$ then has the meaning of the angle between the normal to the wavefront and the positive $x$ direction.

We then consider solutions in the far field such that $R = \epsilon k(\theta) r \sim \textit{O}(1)$ and apply the change of variables $(t,r,\theta) \rightarrow (R,\xi,\theta)$ where $k' = \mathrm{d}k/\mathrm{d}\theta$ to obtain
\begin{eqnarray}
-\eta_{\xi} + kU_{\xi} + k'V_{\xi} &&+ \epsilon \biggl[ kU_R + k\frac{U}{R} + k'V_R \nonumber \\
&&+ k\frac{V_{\theta}}{R} + k(U\eta)_{\xi} + k'(V\eta)_{\xi} \biggr] = O(\epsilon^2), \label{rxt1} \\
-U_{\xi} + k\eta_{\xi} &&+ \frac{\epsilon}{3}\biggl[3k\eta_R + 3k'VU_{\xi} \nonumber \\
&&+ kk' V_{\xi\xi\xi} + k^2 U_{\xi\xi\xi} + 3kUU_{\xi} \biggr] = O(\epsilon^2), \label{rxt2}  \\
-V_{\xi} + k'\eta_{\xi} &&+ \frac{\epsilon}{3}\biggl[3k'\eta_R + 3k\frac{\eta_{\theta}}{R} + 3k'VV_{\xi} \nonumber \\
&&+ kk' U_{\xi\xi\xi} + 3kUV_{\xi} + k'^2 V_{\xi\xi\xi} \biggr] = O(\epsilon^2). \label{rxt3}
\end{eqnarray}
We seek a solution of (\ref{rxt1})-(\ref{rxt3}) in the form of an asymptotic multiple-scale expansion 
\begin{equation}
    \eta = \eta^{(0)}(R,\xi,\theta) + \epsilon \eta^{(1)}(R,\xi,\theta) + \textit{O}(\epsilon^2) \quad \mbox{as} \  \epsilon \rightarrow 0,
\end{equation}
and similarly for $U$ and $V$. At leading order, $O(1)$, we obtain
\begin{eqnarray}
    \eta^{(0)} &&= \eta^{(0)}(R,\xi,\theta), \\
    U^{(0)} &&= k\eta^{(0)}, \label{LO11} \\
    V^{(0)} &&= k'\eta^{(0)}, \label{LO22}
\end{eqnarray}
assuming that any disturbances are generated only by the propagating waves, and at the next order, $O(\epsilon)$, we obtain
\begin{eqnarray}
    -\eta_{\xi}^{(1)} + kU_{\xi}^{(1)} + k'V_{\xi}^{(1)} &&= -kU_R^{(0)} - k\frac{U^{(0)}}{R} - k'V_R^{(0)} - k\frac{V_{\theta}^{(0)}}{R}  \nonumber \\
&& \quad - k(U^{(0)}\eta^{(0)})_{\xi} - k'(V^{(0)}\eta^{(0)})_{\xi}, \label{Oeps1} \\
U_{\xi}^{(1)} &&= k\eta_{\xi}^{(1)} + k\eta_R^{(0)} + k'V^{(0)}U^{(0)}_{\xi} \nonumber \\ 
&& \quad + \frac{1}{3}kk'V_{\xi\xi\xi}^{(0)} + \frac{1}{3}k^2U_{\xi\xi\xi}^{(0)} + kU^{(0)}U_{\xi}^{(0)}, \label{Oeps2} \\
V_{\xi}^{(1)} &&= k'\eta_{\xi}^{(1)} + k'\eta_R^{(0)} + k\frac{\eta_{\theta}^{(0)}}{R} + k'V^{(0)}V_{\xi}^{(0)}  \nonumber \\ 
&& \quad + \frac{1}{3}kk' U_{\xi\xi\xi}^{(0)} + k'^2V_{\xi\xi\xi}^{(0)} + kU^{(0)}V_{\xi}^{(0)}, \label{Oeps3}
\end{eqnarray}
from which substituting (\ref{LO11}) - (\ref{LO22}) and (\ref{Oeps2}) - (\ref{Oeps3}) into (\ref{Oeps1}), to eliminate $\eta^{(1)}$, $U^{(0)}$, $U^{(1)}$, $V^{(0)}$ and $V^{(1)}$, gives the KdV$\theta$ equation for surface plane waves propagating at an  angle $\varphi$ to the positive $x$-direction  as
\begin{align}
2\eta_R^{(0)} + 3 \eta^{(0)}\eta_{\xi}^{(0)} + \frac{1}{3}\eta_{\xi\xi\xi}^{(0)} + 2kk' \frac{\eta_{\theta}^{(0)}}{R} = 0.\label{Bouss_KdVT}
\end{align}
The corresponding leading order Cartesian velocities are calculated from (\ref{cartu})-(\ref{cartv}) and (\ref{LO11})-(\ref{LO22}) to be $u^{(0)} = \cos\varphi ~ \eta^{(0)}$ and $v^{(0)} = \sin\varphi ~ \eta^{(0)}$ for the propagation angle $\varphi$. If $x$ is chosen to be the direction of propagation, then $\varphi = 0$, and the equation takes the form 
\begin{equation}
2\eta_R^{(0)} + 3 \eta^{(0)}\eta_{\xi}^{(0)} + \frac{1}{3}\eta_{\xi\xi\xi}^{(0)} -2\sin\theta\cos\theta \frac{\eta_{\theta}^{(0)}}{R} = 0,
\end{equation}
where $ R = \epsilon r \cos\theta = \epsilon x$, $\xi = r\cos\theta - t = x-t$ and  the corresponding Cartesian velocities are $u^{(0)} = \eta^{(0)}$, and $v^{(0)} = 0$ 

The cKdV equation can be derived using a simpler asymptotic expansion (see  \citet{STCK} and the references therein). We apply the axisymmetric change of variables $(t,x,y) \rightarrow (t,r)$ to (\ref{Bouss1})-(\ref{Bouss2}) which yields
\begin{eqnarray}
\eta_t + U_r + \frac{U}{r}  + \epsilon \left[U\eta_r + \eta U_r + \frac{U\eta}{r} \right] &&= 0, \\
U_t + \eta_r + \frac{\epsilon}{3} \left[\frac{U_t}{r^2} - \frac{U_{rt}}{r} - U_{rrt} + 3UU_r \right] &&= 0,
\end{eqnarray}
where $U$ is the radial cylindrical velocity component of $\mathbf{u}$. To leading order we therefore obtain
\begin{eqnarray}
\eta_{tt} - \eta_{rr} - \frac{\eta_r}{r} &&= 0, \label{cKdVLO1} \\
u_t + \eta_r &&= 0, 
\end{eqnarray}
where $\eta = \eta(\xi)$, given $\xi = r - t$, is an exact solution of (\ref{cKdVLO1}). We then perform the change of variables $(t,r) \rightarrow (R,\xi)$, where $R = \epsilon r$ is the slow radius variable and $\xi = r-t$ is the fast spacial variable in a moving coordinate frame, giving
\begin{eqnarray}
-\eta_{\xi} + U_{\xi} + \epsilon\left[U_R + \frac{U}{R} + U\eta_{\xi} + \eta U_{\xi} \right] &&= O(\epsilon^2), \label{ckdvexp1} \\
-U_{\xi} + \eta_{\xi} + \frac{\epsilon}{3}\left[3\eta_R + 3UU_{\xi} + U_{\xi\xi\xi} \right] &&= O(\epsilon^2). \label{ckdvexp2}
\end{eqnarray}
We now seek solutions of (\ref{ckdvexp1}) and (\ref{ckdvexp2}) in the form:
\begin{equation}
\eta = \eta^{(0)} + \epsilon \eta^{(1)} + \textit{O}(\epsilon^2) \quad \mbox{as}\  \epsilon \rightarrow 0,
\end{equation}
and similarly for the variable $U$. We then consider solutions in the far field such that $R \sim \textit{O}(1)$ which to leading order yields
\begin{equation}
-\eta_{\xi}^{(0)} + U_{\xi}^{(0)} = 0, \label{LO_eta}
\end{equation}
giving that $U^{(0)} = \eta^{(0)}$, assuming that any disturbances are generated only by the propagating waves.  At the second order we find that
\begin{eqnarray}
-\eta_{\xi}^{(1)} + U_{\xi}^{(1)} &&= - U_R^{(0)} - \frac{U^{(0)}}{R} - 2\eta^{(0)}\eta^{(0)}_{\xi} , \label{Oeps11} \\
U_{\xi}^{(1)} &&= \eta_{\xi}^{(1)} + \eta_R^{(0)} + U^{(0)}U^{(0)}_{\xi} + \frac{1}{3}U_{\xi\xi\xi}^{(0)}, \label{Oeps22}
\end{eqnarray}
which after substituting (\ref{LO_eta}) and (\ref{Oeps22}) into (\ref{Oeps11}) gives the axisymmetric cKdV equation for surface waves as
\begin{equation}
2\eta_R^{(0)} + 3 \eta^{(0)}\eta_{\xi}^{(0)} + \frac{1}{3}\eta_{\xi\xi\xi}^{(0)} + \frac{\eta^{(0)}}{R} = 0. \label{Bouss_cKdV}
\end{equation}
Recalling that the depth averaged Cartesian velocities are given by a linear combination of the polar velocity projections $U$ and $V$ by the formulae (\ref{cartu}) and (\ref{cartv}), which gives the Cartesian velocity components to be
\begin{eqnarray}
u^{(0)} = \frac{x}{\sqrt{x^2 + y^2}} ~ \eta^{(0)}, \quad
v^{(0)} = \frac{y}{\sqrt{x^2 + y^2}} ~ \eta^{(0)}.
\end{eqnarray}

Finally, the KPII equation is derived using the change of variables $(t,x,y) \rightarrow (T,\xi,Y)$, where $T = \epsilon t$, $\xi = x - t$ and $Y = \sqrt{\epsilon} y$. We also scale the Cartesian velocity in the $y$-direction as $v \rightarrow \sqrt{\epsilon} v$ to remain consistent with the  coordinate scaling. Applying this change of variables to (\ref{Bouss1}) and (\ref{Bouss2}) gives
\begin{eqnarray}
u_{\xi} - \eta_{\xi} + \epsilon \left(v_Y + \eta u_{\xi} + u\eta_{\xi} + \eta_T \right) &&= O(\epsilon^2), \label{KPeqn1} \\
\eta_{\xi} - u_{\xi} + \epsilon \left(uu_{\xi} + \frac{1}{3}u_{\xi\xi\xi} + u_T \right) &&= O(\epsilon^2), \label{KPeqn2} \\
\eta_Y - v_{\xi} +  + \epsilon \left(uv_{\xi} + \frac{1}{3} u_{\xi\xi Y} + v_T \right) &&= O(\epsilon^2). \label{KPeqn3}
\end{eqnarray}
We now seek solutions of (\ref{KPeqn1})-(\ref{KPeqn3}) in the form:
\begin{equation}
\eta = \eta^{(0)} + \epsilon \eta^{(1)} + \textit{O}(\epsilon^2) \quad \mbox{as}\ \epsilon \rightarrow 0,
\end{equation}
and similarly for the variables $u$ and $v$. We then consider solutions in the far field such that $T \sim \textit{O}(1)$, and  to leading order, $O(1)$, we obtain
\begin{eqnarray}
u^{(0)}_{\xi} &&= \eta^{(0)}_{\xi}, \label{KPlo1} \\
v^{(0)}_{\xi} &&= \eta^{(0)}_Y, \label{KPlo2}
\end{eqnarray}
such that $u^{(0)} = \eta^{(0)}$, assuming that any disturbances are generated only by the propagating waves. At the following order, $O(\epsilon)$, we obtain
\begin{eqnarray}
u_{\xi}^{(1)} - \eta_{\xi}^{(1)} + v_Y^{(0)} + \eta^{(0)}u_{\xi}^{(0)} + u^{(0)}\eta_{\xi}^{(0)} + \eta_T^{(0)} &&= 0, \label{KPeps1} \\
-u_{\xi}^{(1)} + \eta_{\xi}^{(1)} + u^{(0)}u_{\xi}^{(0)} + \frac{1}{3} u_{\xi\xi\xi}^{(0)} + u_T^{(0)} &&= 0, \label{KPeps2}
\end{eqnarray}
from which, taking the sum of (\ref{KPeps1}) and (\ref{KPeps2}), and substituting (\ref{KPlo1}) to remove the higher-order terms gives 
\begin{equation}
2\eta^{(0)}_T + 3\eta^{(0)}\eta^{(0)}_{\xi} + \frac{1}{3}\eta^{(0)}_{\xi\xi\xi} + v^{(0)}_Y = 0. \label{nearlyKP}
\end{equation}
Taking the $\xi$-derivative of (\ref{nearlyKP}) and substituting the $Y$-derivative of (\ref{KPlo2}) gives the KPII equation for surface waves  
\begin{equation}
\left( 2\eta^{(0)}_T + 3\eta^{(0)}\eta^{(0)}_{\xi} + \frac{1}{3}\eta^{(0)}_{\xi\xi\xi}\right)_{\xi} + \eta^{(0)}_{YY} = 0.
\end{equation}
The slow time variable $T$ is more commonly used for the KPII equation and in the later sections makes comparisons to the 2D Boussinesq solutions simpler. For the KdV$\theta$ and cKdV equation the $R$ variable is used to compare to (\ref{A}) whose coefficients for the case of surface waves in a homogeneous fluid with no shear flow reduce to those of (\ref{Bouss_KdVT}) and (\ref{Bouss_cKdV}), respectively, for the choices of the general and singular solution.









