% \begin{align*}
%     \mathbb{V}(f_{1},\ldots,f_{m}) \, = \, \setcond{\bm{\alpha} \in \F^{n}}{f_{1}(\bm{\alpha}) = \ldots = f_{m}(\bm{\alpha}) = 0}.
