% The following is a standard fact about multilinear polynomials.\\

% \begin{fact}\label{fact:degree-d-witness-d-variables}
% Let $f \in \F[x_{1},\ldots,x_{n}]$ be a degree-$d$ multilinear polynomial. Then there exists a subset $T \subseteq [n]$ with $|T| = d$ such that $f$ restricted to the coordinates in $T$ is a degree-$d$ polynomial. In other words, if for every $j \notin T$, we set $x_{j} = 0$, then the resulting polynomial is a degree-$d$ polynomial.
