\noindent
We now prove \Cref{thm:ub-degree} using an almost straightforward application of \Cref{lemma:deg-inverse-poly}.\\

\begin{proof}[Proof of \Cref{thm:ub-degree}]
From \Cref{lemma:nullstellensatz-refutations}, it suffices to show that there exists coefficients $A(\mathbf{x})$ and $B_{j}(\mathbf{x})$'s in the ring $\F_{p^{k}}[\mathbf{x}]$ such that
\begin{align*}
    A(\mathbf{x}) \cdot \paren{\sum_{i=1}^{n} \alpha_{i} x_{i} - \beta} \, + \, \sum_{j=1}^{n} B_{j}(\mathbf{x}) \cdot (x_{j}^{2} - x_{j}) \; = \; 1,
\end{align*}
where $A(\mathbf{x})$ and $B_{j}(\mathbf{x})$'s have constant-depth circuits of size $\bigO(n/kp)^{\bigO(kp)}$ and degree $\bigO(kp)$.\\

Let $L(\mathbf{x}) := \sum_{i=1}^{n} \alpha_{i} x_{i} - \beta$. Let $A \in \F[\mathbf{x}]$ be the multilinear polynomial such that for every $\mathbf{x} \in \Boo^{n}$, $A(\mathbf{x})$ equals $1/L(\mathbf{x})$ (note that $L(\mathbf{x}) \neq 0$ for every $\mathbf{x} \in \Boo^{n}$ because $L$ is unsatisfiable over the Boolean cube). Applying \Cref{lemma:deg-inverse-poly}, we get that $\deg(A) \leq k\cdot(p-1)$.\newline
Since $A(\mathbf{x})$ is a $n$-variate multilinear polynomial of degree $\leq k(p-1)$, it has at most $\binom{n}{\leq D}$ monomials. Using Stirling's approximation, we get that the number of monomials is $\bigO(n/kp)^{\bigO(kp)}$, which implies a $\Sigma \Pi$ circuit for $A(\mathbf{x})$ of size $\bigO(n/kp)^{\bigO(kp)}$ and degree $\bigO(kp)$.\\

\noindent
Now it remains to argue for $B_{j}(\mathbf{x})$'s. Let $B_{1}(\mathbf{x})$ be the quotient and $R_{1}(\mathbf{x})$ be the remainder when $A(\mathbf{x}) \cdot L(\mathbf{x})$ is divided by $(x_{1}^{2}-x_{1})$,
\begin{align*}
    A(\mathbf{x}) \cdot L(\mathbf{x}) \; = \; B_{1}(\mathbf{x}) \cdot (x_{1}^{2} - x_{1}) + R_{1}(\mathbf{x}).
\end{align*}
Clearly $\deg(B_{1}), \deg(R_{1}) \leq \deg(A) + 1$. Next, let $B_{2}(\mathbf{x})$ denote the quotient and $R_{2}(\mathbf{x})$ denote the remainder when $R_{1}(\mathbf{x})$ is divided by $(x_{2}^{2} - x_{2})$, and so on. Since $A(\mathbf{x}) \cdot L(\mathbf{x}) - 1 \in (\mathbf{x}^{2} - \mathbf{x})$, we know that $R_{n}(\mathbf{x}) = 1$. In other words,
\begin{align*}
    A(\mathbf{x}) \cdot L(\mathbf{x}) \; = \; \sum_{j=1}^{n} B_{j}(\mathbf{x}) \cdot (x_{j}^{2} - x_{j}) + 1  \\
    \Rightarrow A(\mathbf{x}) \cdot \paren{\sum_{i=1}^{n} \alpha_{i} x_{i} - \beta} + \sum_{j=1}^{n} (-B_{j}(\mathbf{x})) \cdot (x_{j}^{2} - x_{j}) \; = \; 1.
\end{align*}
Here, for each $j \in [n]$, $\deg(B_{j})\leq \deg(A) + 1$. Similar to $A(\mathbf{x})$, each $B_{j}(\mathbf{x})$ has a $\Sigma \Pi$ circuit of size $\bigO(n/kp)^{\bigO(kp)}$ and degree $\bigO(kp)$. This finishes the proof of \Cref{thm:ub-degree}.
\end{proof}














\section{Symmetric Refutations in Constant Depth}
In this section, we will prove \Cref{thm:ubd-sym-const-depth}, which we recall below.
\symconstant*

 \paragraph{}One of the steps in our proof of \Cref{thm:ubd-sym-const-depth} is a \emph{multilinearization} step, i.e. given a polynomial $f(\mathbf{x})$, we want to find a certificate in constant-depth circuits certifying that $f(\mathbf{x})$ and $\ml[f(\mathbf{x})]$ agree on the Boolean cube $\Boo^{n}$. More formally, we are interested in finding polynomials $B_{j}(\mathbf{x})$'s such that
 \begin{align*}
     f(\mathbf{x}) \; = \; \ml[f(\mathbf{x})] + \sum_{j=1}^{n} B_{j}(\mathbf{x}) \cdot (x_{j}^{2} - x_{j}),
 \end{align*}
 and the polynomials $B_{j}(\mathbf{x})$ have a $\mathrm{poly}(n)$-sized constant-depth circuit.




\paragraph{}We also need a few standard facts about elementary symmetric polynomials in fields of positive characteristic. A standard fact that is useful in our proof is that a symmetric function over the Boolean cube in constant positive characteristic only depends on $\bigO(\log n)$ elementary symmetric polynomials (instead of $n$ elementary symmetric polynomials for symmetric polynomials over arbitrary domains). We now give a proof below for the sake of completeness.

\begin{lemma}[Lucas's Theorem \cite{Lucas}]\label{lemma:lucas}
Fix a prime number $p$ and any two natural numbers $a$ and $b$. Denote $a$ and $b$ in their unique $p$-ary representations as:
\begin{align*}
    a = \sum_{i = 0}^{\ell - 1} a_{i} p^{i}, \quad \quad b = \sum_{i = 0}^{\ell - 1} b_{i} p^{i}, \quad \quad  a_{i}, b_{i} \in \{0,1,\ldots, p-1\}
\end{align*}
Then,
\begin{align*}
    \displaystyle\binom{a}{b} \; \equiv \; \prod_{i = 0}^{\ell - 1} \displaystyle\binom{a_{i}}{b_{i}} \; \mod{p},
\end{align*}
where we define $\binom{x}{y}$ to be $0$ if $x < y$.
\end{lemma}

Next, we show that a symmetric function over the Boolean cube $\Boo^{n}$ in characteristic $p$ depends on $\bigO(\log n)$ elementary symmetric polynomials.

\begin{claim}[Symmetric functions over $\Boo^{n}$ in positive char]\label{claim:sym-char-p}
Fix a prime number $p$ and a field $\F$ with $\mathrm{char}(\F) = p$. Fix a variable parameter $n \in \mathbb{N}$.\newline
Let $f(\mathbf{x}) \in \F[x_{1},\ldots, x_{n}]$ be a multilinear and symmetric polynomial. Then $f(\mathbf{x})$ is a function of $\bigO(\log_{p} n)$ elementary symmetric polynomials on $n$ variables.
\end{claim}
\begin{proof}[Proof of \Cref{claim:sym-char-p}]
Fix any natural number $0 \leq d \leq n$ and consider the $d^{th}$ elementary symmetric polynomial, i.e., $e_{d}(x_{1},\ldots,x_{n})$. Fix an arbitrary point $\mathbf{a} \in \Boo^{n}$ and let $k = |\mathbf{a}|$, where $|\mathbf{a}|$ denotes the Hamming weight of $\mathbf{a}$. We know that $e_{d}(\mathbf{a}) = \binom{k}{d}$.
Denote $k$ and $d$ in their unique $p$-ary representation, i.e.
\begin{align*}
    k \; = \; \sum_{i = 0}^{\ell} k_{i} p^{i}, \quad \text{ and } \quad d \; = \; \sum_{i = 0}^{\ell} d_{i} p^{i}, \quad \quad k_{i}, d_{i} \in \set{0,1,\ldots,p-1}
\end{align*}
By Lucas's Theorem (\Cref{lemma:lucas}), we have,
\begin{align*}
    \binom{k}{d} \; = \; \binom{k_{\ell}}{d_{\ell}} \cdots \binom{k_{0}}{d_{0}} \mod{p}
\end{align*}
Note that $e_{d_{i} p^{i}}(\mathbf{a}) = \binom{k}{d_{i} p^{i}}$. For every $0 \leq i \leq \ell$, using Lucas's Theorem (\Cref{lemma:lucas}), we have,
\begin{equation}\label{eqn:sym-p-powers-1}
    \binom{k}{d_{i}p^{i}} \; = \; \binom{k_{i}}{d_{i}} \mod{p} \quad \Rightarrow \quad \binom{k}{d_{i}p^{i}} \; = \; \dfrac{1}{d_{i}!} \cdot \prod_{j = 0}^{d-1} \paren{\binom{k_{i}}{1} - j} \quad \quad (d_{i}! \neq 0 \mod{p})
\end{equation}
Using Lucas's Theorem (\Cref{lemma:lucas}), we have
\begin{equation}\label{eqn:sym-p-powers-2}
    \binom{k_{i}}{1} \; = \; \binom{k}{p^{i}} \mod{p}
\end{equation}
Define the polynomial $S_{d,i}(z) := \frac{1}{d_i!}\prod_{j = 0}^{d_i-1} \paren{z - j}$. Note that $e_{p^{i}}(\mathbf{a}) = \binom{k}{p^{i}} \mod{p}$.
Plugging in \Cref{eqn:sym-p-powers-2} in \Cref{eqn:sym-p-powers-1}, we get
\begin{align*}
    e_{d}(\mathbf{a}) \; = \; \binom{k}{d} \; = \; \prod_{i = 1}^{\ell} \, S_{d,i}(e_{p^{i}}(\mathbf{a}))
\end{align*}
We have shown that $e_{d}(\mathbf{a})$ is a polynomial of $e_{p^{i}}(\mathbf{a})$ for $i \in \set{0,1,\ldots,\ell}$. Since $\mathbf{a}$ was an arbitrarily chosen point in $\Boo^{n}$, we just argued that on the Boolean hypercube, $e_{d}(\mathbf{x})$ is a polynomial of $e_{p^{0}}(\mathbf{x}),\ldots,e_{p^{\ell}}(\mathbf{x})$. This holds for every $0 \leq d \leq n$. Hence, every symmetric function on $\Boo^{n}$ in characteristic $p$ is a polynomial of $e_{p^{0}}(\mathbf{x}),\ldots,e_{p^{\ell}}(\mathbf{x})$, i.e. of $\bigO(\log_{p} n)$ elementary symmetric polynomials.
\end{proof}


A key lemma in our proof is the multilinearization lemma \Cref{lemma:multilinearize-char-p}, which shows that multilinearization of a sparse polynomial in $\widehat{\mathbf{e}}(\mathbf{x})$ has a small constant-depth circuit.\\

\begin{restatable}[Multilinearization of polynomial of elementary symmetric polynomials]{lemma}{multsymposchar}\label{lemma:multilinearize-char-p}
Fix a prime number $p$ and a field $\F$ with $\mathrm{char}(\F) = p$. Fix a variable parameter $r \in \mathbb{N}$.\newline
Let $F(\mathbf{y}) \in \F[y_{1},\ldots,y_{r}]$ be a polynomial with individual degree strictly less than $p$. Then \break $\ml[F(e_{1}(\mathbf{y}), e_{p}(\mathbf{x}), \ldots, e_{p^{r-1}}(\mathbf{x}))]$ has a circuit of size $\bigO( n^{5} \log n)$ and depth $5$.    
\end{restatable}

\noindent
We will prove \Cref{lemma:multilinearize-char-p} later. For now, we show how it is useful in proving \Cref{thm:ubd-sym-const-depth}.

\begin{proof}[Proof of \Cref{thm:ubd-sym-const-depth}]
We will first prove in the setting when the underlying field $\F$ has a small positive char, i.e. $\mathrm{char}(\F) = p$ for a constant prime $p$. The proof of characteristic $0$ or $> n$ is similar and simpler too. We will come back to the setting $\mathrm{char}(\F) = 0$ or $> n$ towards the end of the proof.

\paragraph{}From \Cref{lemma:nullstellensatz-refutations}, we know that it suffices to prove there exists polynomials $A_{i}(\mathbf{x})$'s and $B_{j}(\mathbf{x})$'s in the ring $\F[x_{1},\ldots,x_{n}]$ such that:
\begin{align*}
    \sum_{i = 1}^{m} A_{i}(\mathbf{x}) \cdot f_{i}(\mathbf{x})  + \sum_{j=1}^{n} B_{j}(\mathbf{x}) \cdot (x_{j}^{2} - x_{j}) \; = \; 1,
\end{align*}
where $A_{i}(\mathbf{x})$'s and $B_{j}(\mathbf{x})$'s have $\mathrm{poly}(n)$-sized constant-depth circuits.

\paragraph{\underline{Reducing to few variables}}Let $r$ denote the number of digits when $n$ is expressed in $p$-ary representation. We have $r = \lfloor \log_{p} n \rfloor + 1 \leq 2 \log_{p} n$. \Cref{claim:sym-char-p} tells us that there exists polynomials $F_{1}(\mathbf{y}),\ldots,F_{m}(\mathbf{y}) \in \F[y_{1},\ldots,y_{r}]$ such that:
\begin{align*}
    f_{i}(\mathbf{x}) \; = \; F_{i}(e_{1}(\mathbf{x}), e_{p}(\mathbf{x}), \ldots, e_{p^{r-1}}(\mathbf{x})) \mod{\langle \mathbf{x}^{2} - \mathbf{x} \rangle}
\end{align*}
We will denote the tuple of polynomials $(e_{1}(\mathbf{x}), e_{p}(\mathbf{x}), \ldots, e_{p^{r-1}}(\mathbf{x}))$ by $\widehat{\mathbf{e}}(\mathbf{x})$.\newline
Since $f_{i}(\mathbf{x})$ and $F_{i}(\widehat{\mathbf{e}}(\mathbf{x}))$ agree on the Boolean cube $\Boo^{n}$, their multilinear components are equal, i.e. $\ml[f_{i}(\mathbf{x})] = \ml[F_{i}(\widehat{\mathbf{e}}(\mathbf{x}))]$ (see \Cref{fact:multilinear}). Since $f_{i}(\mathbf{x})$ is a \textbf{multilinear} polynomial, we have $f_{i}(\mathbf{x}) = \ml[F_{i}(\widehat{\mathbf{e}}(\mathbf{x}))]$.\\

\noindent
For every $1 \leq i \leq r$, the polynomial $e_{p^{i-1}}(\mathbf{x})$ take values in $\F_{p}$ over the Boolean cube. For every $j \in [r]$, let $p_{j}(t)$ be a univariate polynomial that vanishes on the set $\F_{p}$, i.e. $p_{j}(t) = \prod_{\alpha \in \F_{p}} (t - \alpha)$.\newline
For every $n < t < p^{r}-1$, define the polynomial $Q_{t} \in \F[\mathbf{y}]$ as follows:
\begin{align*}
    Q_{t}(\mathbf{y}) := \prod_{i=0}^{r-1} \; \dfrac{1}{t_i!}\prod_{j = 0}^{t_i-1} \paren{y_{i} - j}, \quad \quad \text{ where } t = \sum_{i=0}^{r-1} t_{i} p^{i-1}
\end{align*}

\noindent
Our first claim shows that if $f_{i}(\mathbf{x})$'s do not have a common Boolean solution, then $F_{i}(\mathbf{y})$'s along with some additional constraints do not have a common solution, even over the algebraic closure of $\F$.

\begin{claim}\label{claim:ubd-sym-lifting-char-p}
The system consisting of $F_{i}(\mathbf{y})$'s, $Q_{t}(\mathbf{y})$'s, and $p_{j}(y_{j})$'s have no common solution in the closure $\overline{\F}^{n}$, i.e.
\begin{align*}
    \mathbb{V}(F_{1}(\mathbf{y}), \ldots, F_{m}(\mathbf{y}),Q_{n+1}(\mathbf{y}),\ldots,Q_{p^{r}-1}(\mathbf{y}), p_{1}(y_{1}), \ldots, p_{r}(y_{r})) \; = \; \emptyset
\end{align*}
\end{claim}
\begin{proof}
We will prove this by contradiction. Assume for the sake of contradiction that there exists a common solution $\mathbf{b}$ to the above system of polynomials. Since for every $j \in [r]$, $p_{j}(b_{j}) = 0$, this implies that $\mathbf{b} \in \set{0,\ldots,p-1}^{r}$. We will now show the existence of a point $\mathbf{a} \in \Boo^{n}$ such that
\begin{equation}\label{eqn:ubd-const-char-p-surjective}
    \widehat{\mathbf{e}}(\mathbf{a}) = \mathbf{b}
\end{equation}
Observe that an $\mathbf{a} \in \Boo^{n}$ which satisfies \Cref{eqn:ubd-const-char-p-surjective} is a common Boolean solution to the system $\set{f_{1}(\mathbf{x}), \ldots, f_{m}(\mathbf{x})}$, which is a contradiction to our hypothesis of \Cref{thm:ubd-sym-const-depth}. So to finish the contradiction, all that remains is to show the existence of such a Boolean point $\mathbf{a}$.\\

\noindent
We are only interested in showing the existence of a Boolean point satisfying \Cref{eqn:ubd-const-char-p-surjective}, i.e. we are only interested in the evaluation of $\mathbf{a}$ on symmetric polynomials. Thus we can focus on showing the existence of an appropriate Hamming weight $0 \leq k \leq n$ such that
\begin{align*}
    \binom{k}{p^{i}} = \binom{k_{i}}{1} = b_{i} \mod{p}, \quad \quad \text{ for all } \; 0 \leq i \leq r-1 
\end{align*}
where we used Lucas's Theorem (\Cref{lemma:lucas}) for the first equality. Choose $k$ to be $\sum_{i = 0}^{\ell} b_{i} p^{i}$. If $k \leq n$, then $k$ satisfies all the $r$ constraints in \Cref{eqn:ubd-const-char-p-surjective}. In particular, we can set $\mathbf{a} = 1^{k} 0^{n-k}$ and it will satisfy \Cref{eqn:ubd-const-char-p-surjective}. Thus to complete the proof, we need to show that $k \leq n$.\\

\noindent
By assumption, $Q_{t}(\mathbf{b}) = 0$ for all $n < t \leq p^{r}-1$. Fix any $t = \sum_{i=0}^{r-1} t_{i} p^{i-1}$. By the definition of the polynomial $Q_{t}(\mathbf{y})$ (see the proof of \Cref{claim:sym-char-p}):
\begin{align*}
    Q_{t}(\mathbf{b}) \; = \; \prod_{i=0}^{r-1} \binom{b_{i}}{t_{i}} \; = \; 0.
\end{align*}
This means there exists an $i \in \set{0,1,\ldots,r-1}$ such that $b_{i} < t_{i}$. Since this holds for every $n < t \leq p^{r}-1$, this implies that for each coordinate $i$, $b_{i} \leq n_{i}$ where $n = \sum_{i=0}^{r-1} n_{i} p^{i}$. Thus $k \leq n$.\\

\noindent
Hence we have found a Boolean point $\mathbf{a} \in \Boo^{n}$ which satisfies \Cref{eqn:ubd-const-char-p-surjective}. Since for every $i \in [m]$, $f_{i}(\mathbf{x})$ and $F_{i}(\widehat{\mathbf{e}}(\mathbf{x}))$ agree on the Boolean cube $\Boo^{n}$, $\mathbf{a}$ is a common Boolean solution to $f_{i}(\mathbf{x})$'s. This is a contradiction to our assumption in \Cref{thm:ubd-sym-const-depth}.
\end{proof}


\paragraph{\underline{Low-variate Nullstellensatz}}We have shown that the unsatisfiability of the $n$-variate polynomials $f_{i}$'s over the Boolean cube implies the unsatisfiability of $\bigO(\log n)$-variate polynomials $F_{i}$'s (with some additional polynomials to reflect the Boolean cube restriction). Now we use Hilbert's Nullstellensatz to get a Nullstellensatz certificate for the $\bigO(\log n)$-variate polynomials and ``lift'' it to get a Nullstellensatz certificate for the original system of polynomial equations.\\

\noindent
\Cref{claim:ubd-sym-lifting-char-p} says that the system consisting of $F_{i}$'s, $Q_{t}$'s, and $p_{j}$'s do not have a common zero over the algebraic closure $\Bar{\F}$. Applying Hilbert's Nullstellensatz (\Cref{thm:nullstellensatz}) on this system, we know that there exist polynomials $\Tilde{A}_{i}(\mathbf{y})$'s, $\Tilde{S}_{t}(\mathbf{y})$'s, and $\Tilde{B}_{j}(\mathbf{y})$'s such that:
\begin{equation}\label{eqn:ubd-sym-constant-null}
    \sum_{i=1}^{m} \Tilde{A}_{i}(\mathbf{y}) \cdot F_{i}(\mathbf{y}) + \sum_{t=n+1}^{p^{r}-1} \Tilde{S}_{t}(\mathbf{y}) \cdot Q_{t}(\mathbf{y}) \, + \, \sum_{j=1}^{r} \Tilde{B}_{j}(\mathbf{y}) \cdot p_{j}(y_{j}) \; = \; 1
\end{equation}

\paragraph{\underline{Size analysis of low-variate certificate}}Next, we will show that the coefficients $\Tilde{A}_{i}$'s, $\Tilde{S}_{t}$'s, and $\Tilde{B}_{j}$'s in the Nullstellensatz certificate (\Cref{eqn:ubd-sym-constant-null}) have small constant-depth circuits. More precisely, we will show that $\Tilde{A}_{i}$'s, $\Tilde{S}_{t}$'s, and $\Tilde{B}_{j}$'s are polynomials with sparsity $\mathrm{poly}(n)$, which in turn implies that they have $\mathrm{poly}(n)$-sized depth $2$ circuits. Since these polynomials are $\bigO(\log n)$-variate polynomials, it will suffice to show that they have constant individual degrees. We will argue as follows:
\begin{itemize}
    \item \textbf{Step (a)} The polynomials $F_{i}$'s and $Q_{t}$'s have constant individual degree.
    \item \textbf{Step (b)} Use the low-variate Nullstellensatz certificate \Cref{eqn:ubd-sym-constant-null} to argue that the polynomials $\Tilde{A}_{i}$'s and $\Tilde{S}_{t}$'s can be assumed to have constant individual degree.
    \item \textbf{Step (c)} Use the previous two items to argue that the polynomials $\Tilde{B}_{j}$'s have sparsity at most $\mathrm{poly}(n)$.
\end{itemize}


\paragraph{Step (a)}We first argue that the individual degree of each $F_i(\mathbf{y})$ can be assumed to be $\leq (p-1)$. Recall that $f_{i}(\mathbf{x}) = F_{i}(\widehat{\mathbf{e}}(\mathbf{x}))$ over $\Boo^{n}$, i.e.: $f_{i}(\mathbf{x}) \equiv F_{i}(\widehat{\mathbf{e}}(\mathbf{x}))   \bmod  (\mathbf{x}^{2} - \mathbf{x})$.\newline
As we are working over a field of characteristic $p$, for any $i \in [n]$, $e_{i}(\mathbf{x}) \in \set{0,1,\ldots,p-1}$ for every $\mathbf{x} \in \Boo^{n}$. This implies that $\widehat{\mathbf{e}}(\mathbf{x})^{p} \equiv \widehat{\mathbf{e}}(\mathbf{x}) \bmod (\mathbf{x}^{2} - \mathbf{x})$ via Fermat's Little Theorem/Frobenius automorphism.\newline
Let $F_i'(\mathbf{y}) := F_i(\mathbf{y})/(\mathbf{y}^{p} - \mathbf{y})$ be a ``minimum individual-degree representative'' of $F_i(\mathbf{y})$ modulo the ideal $(\mathbf{y}^{p} - \mathbf{y})$.

Thus, $F_i(\mathbf{y})$ is a polynomial of individual-degree $\leq p-1$ such that $F'(\mathbf{y}) \equiv F(\mathbf{y}) \bmod (\mathbf{y}^{p} - \mathbf{y})$. Combining these together, we get,
\begin{equation}
    f_{i}(\mathbf{x}) \equiv F'_{i}(\widehat{\mathbf{e}}(\mathbf{x}))   \bmod  (\mathbf{x}^{2} - \mathbf{x})
\end{equation}
where $F'_i$ has individual-degree $\leq p-1$. With a slight abuse of notation, we will now use ``$F_i$'' to denote $F'_i$. 

\noindent
By the definition of the polynomial $Q_{t}(\mathbf{y})$, for each $t$, the individual degree of $Q_{t}(\mathbf{y})$ is $\leq p$

\paragraph{Step (b)}The polynomial $p_{j}(t)$, defined as $\prod_{\alpha \in \F_{p}} (t - \alpha)$, is equal to $(t^{p} - t)$ by Fermat's Little Theorem. From the Nullstellensatz certificate \Cref{eqn:ubd-sym-constant-null},
\begin{align*}
    \sum_{i = 1}^{m} \Tilde{A}_{i}(\mathbf{y}) \cdot F_{i}(\mathbf{y}) \, + \, \sum_{t=n+1}^{p^{r}-1} \Tilde{S}_{t}(\mathbf{y}) \cdot Q_{t}(\mathbf{y}) = 1 \mod{( \mathbf{y}^{p} - \mathbf{y} )}
\end{align*}
We would now argue that the polynomials $\Tilde{A}_{i}(\mathbf{y})$'s and $\Tilde{S}_{t}(\mathbf{y})$'s has individual degree $\leq (p-1)$. Suppose there exists an $i \in [m]$ for which $\Tilde{A}_{i}(\mathbf{y})$ has individual degree $> (p-1)$, then define $\Tilde{A}_{i}'(\mathbf{y}) := A_{i}(\mathbf{y})/(\mathbf{y}^{p} - \mathbf{y})$ to be a ``minimum individual-degree representative''. Observe that replacing the polynomial $\Tilde{A}_{i}$ with the polynomial $\Tilde{A}_{i}'$, the low-variate Nullstellensatz certificate \Cref{eqn:ubd-sym-constant-null} continues to holds.

Thus the sparsity of $\Tilde{A}_{i}(\mathbf{y})$ is at most $p^{r}$.
An analogous argument shows that for each $n < t \leq p^{r}-1$, the polynomial $\Tilde{S}_{t}(\mathbf{y})$ has individual degree $\leq (p-1)$ and thus has a $\bigO(n^{2})$-sized circuit of depth $2$ (a $\Sigma \Pi$ circuit).\\

\noindent
Using $r \leq 2 \log_{p} n$, we have that for every $i \in [m]$ and for every $n < t \leq p^{r}-1$, the polynomials $\Tilde{A}_{i}(\mathbf{y})$ and $\Tilde{S}_{t}(\mathbf{y})$ have sparsity at most $\bigO(n^{2})$. This also implies that the polynomials $\Tilde{A}_{i}(\mathbf{y})$'s and $\Tilde{S}_{t}(\mathbf{y})$'s have $\bigO(n^{2})$-sized circuits of depth $2$ (a $\Sigma \Pi$ circuit).

\paragraph{Step (c)}Now it remains to show that the polynomials $\Tilde{B}_{j}(\mathbf{y})$ have small constant-depth circuits. We will show that for each $j \in [n]$, the polynomial $\Tilde{B}_{j}(\mathbf{y})$ has sparsity at most $\mathrm{poly}(n)$. To show this, we will use the fact that $\sum_{i = 1}^{m} \Tilde{A}_{i}(\mathbf{y}) \cdot F_{i}(\mathbf{y}) + \sum_{t=n+1}^{p^{r}-1} \Tilde{S}_{t}(\mathbf{y}) \cdot Q_{t}(\mathbf{y})$ is a polynomial of constant individual degree.\\

\noindent
For a polynomial $H(\mathbf{y})$, the \emph{individual-degree-$p$} operator, denoted by $\mathsf{inddeg}_{p}$ outputs the following polynomial: For each variable $y_{j}$, every occurrence of $y_{j}^{p}$ in $H(\mathbf{y})$ is replaced by $y_{j}$ until the individual degree of the polynomial is $< p$. For $p = 2$, $\mathsf{inddeg}_{2}$ corresponds to multilinearization $\ml$.\newline
Our next claim shows that if there is a polynomial of low individual degree, then its individual-degree-$p$ component can be extracted using polynomials of small constant-depth circuits. The proof is via a simple induction. We omit the proof here and it can be found in \Cref{app:proof-ind-deg}.


\begin{restatable}{claim}{boundedinddegml}\label{claim:inddeg-p}
Let $H(\mathbf{y}) \in \F[y_{1},\ldots,y_{r}]$ denote a polynomial whose individual degree is at most $D$. Then there exists polynomials $G_{1}(\mathbf{y}), \ldots, G_{r}(\mathbf{y})$ such that the following holds:
\begin{align*}
    H(\mathbf{y}) \; = \; \mathsf{inddeg}_{p}[H(\mathbf{y})] \; + \; \sum_{j=1}^{r} G_{j}(\mathbf{y}) \cdot (y_{j}^{p} - y_{j}),
\end{align*}
and for each $j \in [r]$, the polynomial $G_{j}(\mathbf{y})$ has sparsity at most $D^{r+1}/(p-1)$.
\end{restatable}


\paragraph{}Define the polynomial $H(\mathbf{y}) = \sum_{i = 1}^{m} \Tilde{A}_{i}(\mathbf{y}) \cdot F_{i}(\mathbf{y}) + \sum_{t=n+1}^{p^{r}-1} \Tilde{S}_{t}(\mathbf{y}) \cdot Q_{t}(\mathbf{y})$. Observe that
\begin{align*}
    H(\mathbf{y}) = 1 + \sum_{j = 1}^{r} \Tilde{B}_{j}(\mathbf{y}) \cdot (y_{j}^{p} - y_{j})
\end{align*}
So the polynomials $G_{j}(\mathbf{y})$ from \Cref{claim:inddeg-p} correspond to the polynomials $\Tilde{B}_{j}(\mathbf{y})$ from the Nullstellensatz certificate.
Since both $\Tilde{A}_{i}(\mathbf{y})$ and $F_{i}(\mathbf{y})$ have individual degree at most $(p-1)$, $H(\mathbf{y})$ has individual degree at most $2(p-1)$ in each of the $r$ variables. Applying \Cref{claim:inddeg-p} on $H(\mathbf{y})$, we get that the polynomials $\Tilde{B}_{j}(\mathbf{y})$ has sparsity at most $(2(p-1))^{r} \cdot 2(p-1)/(p-1) = \mathrm{poly(n)}$ since $p \leq 2 \log_{p} n$. This implies that the polynomials $\Tilde{B}_{j}(\mathbf{y})$ has a circuit of size $\bigO(n^{2})$ and depth $2$ (a $\Sigma \Pi$ circuit).

\paragraph{\underline{Lifting the Nullstellensatz certificate}}By the definition of $F_{i}(\mathbf{y})$, we know that for every $i \in [m]$, $f_{i}(\mathbf{x}) = \ml[F_{i}(\widehat{\mathbf{e}}(\mathbf{x}))]$. Applying the multilinearization \Cref{lemma:multilinearize-char-p} on $F_{i}(\widehat{\mathbf{e}}(\mathbf{x}))$ for every $i \in [m]$, we know there exists polynomials $D_{ij}(\mathbf{x})$ for $i \in [m]$ and $j \in [n]$ such that:
\begin{align*}
    F_{i}(\widehat{\mathbf{e}}(\mathbf{x})) \; = \; f_{i}(\mathbf{x}) \; + \; \sum_{j = 1}^{n} D_{ij}(\mathbf{x}) \cdot (x_{j}^{2} - x_{j}),
\end{align*}
where each polynomial $D_{ij}(\mathbf{x})$ has a circuit of size $\bigO(n^{5} \log n)$ and depth $5$. This also implies that for each $i \in [m]$, the polynomial $f_{i}(\mathbf{x})$ has a circuit of size $\bigO(n^{5} \log n)$ and depth $5$.\newline
Similarly, applying the multilinearization lemma \Cref{lemma:multilinearize-char-p} on $Q_{t}(\widehat{\mathbf{e}}(\mathbf{x}))$ for every $n < t \leq p^{r}-1$, we know there exists polynomials $R_{t}(tj)(\mathbf{x})$ for $n < t \leq p^{r}-1$ and $j \in [n]$ such that:
\begin{align*}
    Q_{t}(\widehat{\mathbf{e}}(\mathbf{x})) \; = \; \ml[Q_{t}(\widehat{\mathbf{e}}(\mathbf{x}))] \; + \; \sum_{j=1}^{n} R_{tj}(\mathbf{x}) \cdot (x_{j}^{2} - x_{j}),
\end{align*}
where each polynomial $R_{tj}(\mathbf{x})$ has a circuit of size $\bigO(n^{5} \log n)$ and depth $5$.

\paragraph{}Next, we multilinearize the coefficients $\Tilde{A}_{i}(\widehat{\mathbf{e}}(\mathbf{x}))$'s to get a multilinear constant-depth-$\IPSLIN$ proof. Applying the multilinearization \Cref{lemma:multilinearize-char-p} on $\Tilde{A}_{i}(\widehat{\mathbf{e}}(\mathbf{x}))$ for every $i \in [m]$, we know there exists polynomials $\Tilde{D}_{ij}(\mathbf{x})$ for $i \in [m]$ and $j \in [n]$ such that:
\begin{align*}
    \Tilde{A}_{i}(\widehat{\mathbf{e}}(\mathbf{x})) \; = \; \ml[\Tilde{A}_{i}(\widehat{\mathbf{e}}(\mathbf{x}))] + \sum_{j=1}^{n} \Tilde{D}_{ij}(\mathbf{x}),
\end{align*}
where each polynomial $\Tilde{D}_{ij}(\mathbf{x})$ has a circuit of size $\bigO(n^{5} \log n)$ and depth 5. This also implies that for each $i \in [m]$, the polynomial $\ml[\Tilde{A}_{i}(\widehat{\mathbf{e}}(\mathbf{x}))]$ has a circuit of size $\bigO(n^{6})$ and depth $5$.\\
Similarly, we also multilinearize the coefficients $\Tilde{S}_{t}(\widehat{\mathbf{e}}(\mathbf{x}))$. Applying the multilinearization lemma \Cref{lemma:multilinearize-char-p} on $\Tilde{S}_{t}(\widehat{\mathbf{e}}(\mathbf{x}))$ for every $n < t \leq p^{r}-1$, we know there exists polynomials $\Tilde{R}_{tj}(\mathbf{x})$ for $n < t \leq p^{r}-1$ and $j \in [n]$ such that:
\begin{align*}
    \Tilde{S}_{t}(\widehat{\mathbf{e}}(\mathbf{x})) \; = \; \ml[\Tilde{S}_{t}(\widehat{\mathbf{e}}(\mathbf{x}))] \; + \; \sum_{j=1}^{n} \Tilde{R}_{tj}(\mathbf{x}) \cdot (x_{j}^{2} - x_{j}),
\end{align*}
where each polynomial $\Tilde{R}_{tj}(\mathbf{x})$ has a circuit of size $\bigO(n^{5} \log n)$ and depth $5$.\newline
For every $i \in [r]$, applying the multilinearization lemma \Cref{lemma:multilinearize-char-p} on $p_{i}(e_{p^{i-1}}(\mathbf{x}))$, we know that there exists polynomials $E_{i1}(\mathbf{x}), \ldots, E_{in}(\mathbf{x})$ such that:
\begin{align*}
    p_{i}(e_{p^{i-1}}(\mathbf{x})) \; = \; \sum_{j=1}^{n} E_{ij}(\mathbf{x}) \cdot (x_{j}^{2} - x_{j}),
\end{align*}
where for each $j \in [n]$, the polynomial $E_{ij}(\mathbf{x})$ has a circuit of size $\bigO(n^{5} \log n)$ and depth $5$.

\paragraph{}Substituting $\mathbf{y} = \widehat{\mathbf{e}}(\mathbf{x})$ in the low-variate Nullstellensatz certificate \Cref{eqn:ubd-sym-constant-null} and using the above polynomial relations, we get,
\begin{align*}
    \sum_{i = 1}^{m} \; \underbrace{\Tilde{A}_{i}(\widehat{\mathbf{e}}(\mathbf{x}))}_{:= A_{i}(\mathbf{x})} \; \cdot \; f_{i}(\mathbf{x}) \; + \; \sum_{j = 1}^{n} \, B_{j}(\mathbf{x}) \cdot (x_{j}^{2} - x_{j}) \; = \; 1, 
\end{align*}
where the polynomial $B_{j}(\mathbf{x})$ is:
\begin{align*}
    B_{j}(\mathbf{x}) \; = \;  \sum_{i = 1}^{m} (\ml[\Tilde{A}_{i}(\widehat{\mathbf{e}}(\mathbf{x}))] D_{ij}(\mathbf{x}) + f_{i}(\mathbf{x}) \Tilde{D}_{ij}(\mathbf{x})) \\ + \sum_{t=n+1}^{p^{r}-1} (\ml[Q_{t}(\widehat{\mathbf{e}}(\mathbf{x}))] \cdot \Tilde{S}_{t}(\widehat{\mathbf{e}}(\mathbf{x})) + Q_{t}(\widehat{\mathbf{e}})(\mathbf{x}) \cdot \ml[\Tilde{S}_{t}(\widehat{\mathbf{e}}(\mathbf{x}))]) \\ + \, \sum_{i = 1}^{m} \sum_{j' \leq j} \Tilde{D}_{ij'}(\mathbf{x}) D_{ij}(\mathbf{x}) + \sum_{i=1}^{r} \Tilde{B}_{i}(\widehat{\mathbf{e}}(\mathbf{x})) E_{ij}(\mathbf{x})
\end{align*}
We have,
\begin{itemize}
    \item For each $i \in [m]$, using Ben-Or's construction \Cref{thm:ben-or}, the polynomial $A_{i}(\mathbf{x})$ has a circuit of size $\bigO(n^{2})$ and depth $5$.
    \item For each $j \in [r]$, and again using Ben-Or's construction \Cref{thm:ben-or}, the polynomial $B_{j}(\mathbf{x})$ has a circuit of size $\bigO(m n^{5} \log n)$ and depth $7$.
\end{itemize}
This finishes the proof of \Cref{thm:ubd-sym-const-depth} in the setting when the underlying field has a positive characteristic $p$ for a constant prime $p$.

\paragraph{}We now discuss the proof of \Cref{thm:ubd-sym-const-depth} in the setting when the underlying field has characteristic $0$ or $> n$. The proof has the exact same steps as for positive characteristic. Instead of repeating the same steps again, for the sake of brevity, we only highlight the differences.

\paragraph{}Over characteristic $0$ or $> n$, every multilinear symmetric polynomial is a polynomial of $x_{1}+\ldots+x_{n}$, i.e. of $e_{1}(\mathbf{x})$. Thus $r$ in the above proof is just $1$ and $F_{i}$'s are univariate polynomials. Let $p(y) = \prod_{i=0}^{n} (y-i)$. Then it is easy to see that if $f_{i}(\mathbf{x})$ do not have a common Boolean solution, then the univariate polynomials $F_{i}(y)$'s and $p(y)$ do not have a common solution (following a similar strategy to the proof of \Cref{claim:ubd-sym-lifting-char-p}, if $b$ is a common solution, then there exists a common Boolean solution of Hamming weight $b$, which is a contradiction).\newline

\noindent
To argue about the circuit size of the coefficients of the univariate Nullstellensatz certificate, it suffices to argue about their degrees since they are all univariate polynomials. The coefficients of the univariate certificate have degree at most $\bigO(n)$ because of the polynomial $p(y)$ (it is quite similar and simpler to the degree analysis of the coefficients of the low-variate Nullstellensatz certificate in the above proof).\newline
In the end, we need to multilinearize $F_{i}(e_{1}(\mathbf{x}))$. This can again be done in a constant-depth circuit using \Cref{lemma:multilinearize-char-p}.
\end{proof}

\subsection{Multilinearization}
 To show our multilinearization lemma (\Cref{lemma:multilinearize-char-p}), it will be convenient to first define a notion of \emph{partial multilinearization}, i.e., multilinearize with respect to a subset of variables. A key lemma used in our proofs of multilinearization statements is constant-depth multilinearization when $f(\mathbf{x})$ is a \emph{product of univariate polynomials} (see \Cref{cor:ml-prod-uni}). We now define the partial multilinearization and then use it to prove \Cref{cor:ml-prod-uni}.\\

 \begin{definition}[Partial multilinearization]
Fix any field $\F$ and let $f(\mathbf{x}) \in \F[x_{1},\ldots,x_{n}]$. For any $j \in [n]$, let $f^{(\leq j)}(\mathbf{x}) \in \F[x_{j+1},\ldots,x_{n}][x_{1},\ldots,x_{j}]$ denote the polynomial $f(\mathbf{x})$ with variables $x_{1},\ldots,x_{j}$ and coefficients in $\F[x_{j+1},\ldots,x_{n}]$.\newline
The multilinearization of the polynomial $f(\mathbf{x})$ with respect to the variables $\set{x_{1},\ldots,x_{j}}$, denoted by $\ml_{\leq j}[f(\mathbf{x})]$, is defined to be:
\begin{align*}
    \ml_{\leq j}[f(\mathbf{x})] \; := \; \ml[f^{(\leq j)}(\mathbf{x})]
\end{align*}
Similarly, for any $k \in [n]$, let $f^{(k)}(\mathbf{x}) \in \F[x_{1},\ldots,x_{k-1},x_{k+1},\ldots,x_{n}][x_{k}]$ denote the polynomial $f(\mathbf{x})$ with variable $x_{k}$ only and coefficients in $\F[x_{1},\ldots,x_{k-1},x_{k+1},\ldots,x_{n}]$. The multilinearization of the polynomial $f(\mathbf{x})$ with respect to the variable $x_{k}$ only, denoted by $\ml_{k}[f(\mathbf{x})]$, is defined to be:
\begin{align*}
    \ml_{k}[f(\mathbf{x})] \; = \; \ml[f^{(k)}(\mathbf{x})]
\end{align*}
Sometimes we will denote $\ml_{k}[f(\mathbf{x})]$ by $\ml_{x_{k}}[f(\mathbf{x})]$ for sake of clarity.
\end{definition}
\noindent
\textbf{Example}: Let $f(\mathbf{x}) = x_{1}^{2} x_{2}^{3} + x_{2} x_{3}^{2}$. Then,
\begin{align*}
    \ml_{\leq 1}[f(\mathbf{x})] \; = \; x_{1}x_{2}^{3} + x_{2}x_{3}^{2}, \quad \ml_{\leq 2}[f(\mathbf{x})] \; = \; x_{1}x_{2} + x_{2}x_{3}^{2}, \quad
    \ml_{2}[f(\mathbf{x})] \; = \; x_{1}^{2}x_{2} + x_{2}x_{3}^{2}
\end{align*}
\noindent
We make one observation on partial multilinearization, which will be helpful in the proofs.
\begin{observation}\label{obs:partial-ml-sequence}
For every $j < n$, the following holds: For every polynomial $f(\mathbf{x})$,
\begin{align*}
    \ml_{\leq j+1}[f(\mathbf{x})] \; = \; \ml_{j+1}[\ml_{\leq j}[f(\mathbf{x})]]
\end{align*}
\end{observation}
\noindent
In the rest of the section, we will use the notation $\mathbf{x}_{\leq j}$ to denote $(x_{1},\ldots,x_{j})$ and $\mathbf{x}_{>j}$ to denote $(x_{j+1},\ldots,x_{n})$. 

\paragraph{}Now we show that a product of univariate polynomials can be multilinearized using constant-depth $\mathrm{poly}(n)$-sized circuits (see \Cref{cor:ml-prod-uni}). We start by showing that we can do partial multilinearization with respect to a single variable.

\begin{claim}[Multilinearize a single variable]
\label{claim:multilinearize-one-var}
Consider a univariate polynomial $h(z)$ of degree-$D$. Let $Q(\mathbf{y})$ be a polynomial with a circuit of size $s$ and depth $\Delta$. Let $\ml_{z}[h(z) \cdot Q(\mathbf{y})]$ denotes the partial multilinearization of the polynomial $h(z) \cdot Q(\mathbf{y})$ with respect to the $z$ variable.\newline
Then,
\begin{align*}
    h(z) \cdot Q(\mathbf{y}) \; = \; \ml_{z}[h(z) \cdot Q(\mathbf{y})] + B(z,\mathbf{y}) \cdot (z^{2} - z),
\end{align*}
\begin{itemize}
    \item The polynomial $\ml_{z}[h(z) \cdot Q(\mathbf{y})]$ is equal to $L(z)\cdot  Q(\mathbf{y})$, where $L(z)$ is a degree-$1$ univariate polynomial in $z$.
    \item The polynomial $B(z,\mathbf{y})$ is equal to $\Tilde{h}(z) \cdot Q(\mathbf{y})$ for a univariate polynomial $\Tilde{h}(z)$.
\end{itemize}
\end{claim}
\begin{proof}[Proof of \Cref{claim:multilinearize-one-var}]
Let $h(z) = a_{0} + a_{1} z + \cdots + a_{D} z^{D}$. Then for every $2 \leq j \leq D$, rewriting $a_{j} z^{j}$ as $a_{j}(z^{j} - z) + a_{j} z$, we get,
\begin{align*}
    h(z) \cdot Q(\mathbf{y}) \; = \; \paren{a_{0} + a_{1} z + \sum_{j=2}^{D} a_{j} (z^{j} - z + z)} \cdot Q(\mathbf{y}) \\
    =  \underbrace{\paren{a_{0} + \paren{\sum_{j=1}^{D} a_{j}} z}}_{:= L(z)} \cdot Q(\mathbf{y}) + \paren{\sum_{j=2}^{D} a_{j} (z^{j} - z)} \cdot Q(\mathbf{y})
\end{align*}
Observe that for any $j \geq 2$,
\begin{align*}
    z^{j} - z \; = \; \paren{z^{j-2} + \cdots + z + 1} \cdot (z^{2} - z)
\end{align*}
Using the above observation, we get,
\begin{align*}
    h(z) \cdot Q(\mathbf{y}) \; = \;  \underbrace{L(z) \cdot Q(\mathbf{y})}_{= \ml_{z}[h(z) \cdot Q(\mathbf{y})]} \; + \; \underbrace{Q(\mathbf{y}) \sum_{j=2}^{D} a_{j}  \paren{z^{j-1} + \cdots + z + 1} }_{= B(z, \mathbf{y})} \; \cdot \; (z^{2} - z)
\end{align*}
Let $\Tilde{h}(z) = \sum_{j=2}^{D} a_{j} (z^{j-1}+\cdots+z+1)$. Then the polynomial $B(z, \mathbf{y})$ is equal to $\Tilde{h}(z) \cdot Q(\mathbf{y})$. The partial multilinearization $\ml_{z}[h(z) \cdot Q(\mathbf{y})]$ is of the form $L(z) \cdot Q(\mathbf{y})$ for a degree-$1$ polynomial $L(z)$. This finishes the proof of \Cref{claim:multilinearize-one-var}.
\end{proof}

The next claim shows that if a product of univariate polynomials, then we can do partial multilinearization with respect to a subset of variables. It follows with a simple induction using \Cref{claim:multilinearize-one-var}. We omit the proof here and it can be found in \Cref{app:claim-partial-uni}.

\begin{restatable}[Partial multilinearization of product of univariates]{claim}{partialmlproduni}\label{claim:partial-multilinearize-prod-univariates}
Let $h_{1}(z_{1}),\ldots,h_{n}(z_{n})$ be univariate polynomials where each $h_{i}(z_{i})$ has degree at most $D$.\newline
Then there exists degree-$1$ univariate polynomials $L_{1}(z_{1}), \ldots, L_{n}(z_{n})$ and polynomials $B_{1}(\mathbf{z}), \ldots, B_{n}(\mathbf{z})$ satisfying the following: For every $k \in [n]$,
\begin{align*}
    h_{1}(z_{1}) \cdots h_{n}(z_{n}) \; = \; \ml_{\leq k}\brac{\prod_{i=1}^{n} h_{i}(z_{i})} \; + \; \sum_{j=1}^{k} B_{j}(\mathbf{z}) \cdot (z_{j}^{2} - z_{j}),
\end{align*}
where
\begin{align*}
    \ml_{\leq k}\brac{\prod_{i=1}^{n} h_{i}(z_{i})} \; = \; \prod_{i = 1}^{k} L_{i}(z_{i}) \cdot \prod_{i = k+1}^{n} h_{i}(z_{i}),
\end{align*}
and for each $j \in [n]$, the polynomial $B_{j}(\mathbf{z})$ has the following form:
\begin{align*}
    B_{j}(\mathbf{x}) \; = \; \prod_{i = 1}^{j-1} L_{i}(z_{i}) \cdot \Tilde{h}_{j}(z_{j}) \cdot \prod_{i = j+1}^{n} h_{i}(z_{i}),
\end{align*}
for some univariate polynomial $\Tilde{h}_{j}(z_{j})$.
\end{restatable}

\noindent
Setting $k = n$ in \Cref{claim:partial-multilinearize-prod-univariates} immediately gives us the following corollary.
\begin{corollary}[Multilinearization of product of univariates]\label{cor:ml-prod-uni}
Let $h_{1}(z_{1}),\ldots,h_{n}(z_{n})$ be univariate polynomials where each $h_{i}(z_{i})$ has degree at most $D$.\newline
Then there polynomials $B_{1}(\mathbf{z}), \ldots, B_{n}(\mathbf{z})$ such that,
\begin{align*}
    h_{1}(z_{1}) \cdots h_{n}(z_{n}) \; = \; \ml\brac{\prod_{i=1}^{n} h_{i}(z_{i})} \; + \; \sum_{j=1}^{k} B_{j}(\mathbf{z}) \cdot (z_{j}^{2} - z_{j}),
\end{align*}
where for each $j \in [n]$, the polynomial $B_{j}(\mathbf{z})$ has a circuit of size $\bigO(nD^{2})$ and depth $3$ (a $\Pi \Sigma \Pi$) circuit.
\end{corollary}



\noindent
In this section, we will prove the multilinearization lemma \Cref{lemma:multilinearize-char-p}. The key step in our proof of \Cref{lemma:multilinearize-char-p} is \Cref{lemma:ml-prod-two-elem} which is a special case of \Cref{lemma:multilinearize-char-p}. In particular, \Cref{lemma:ml-prod-two-elem} shows that the multilinearization of a product of two elementary symmetric polynomials has a small constant-depth circuit. Furthermore, it shows that the multlinearization of a product of two elementary symmetric polynomials has a nice structure which we use to prove \Cref{lemma:multilinearize-char-p}.\\ 


\begin{lemma}[Multilinearization of product of two elementary symmetric polynomials]\label{lemma:ml-prod-two-elem}
Fix any two natural numbers $\alpha$ and $\beta$. Then
\begin{itemize}
    \item There exists polynomials $R_{\alpha, \beta,j}(\mathbf{x})$'s such that
    \begin{align*}
        \ml[e_{\alpha}(\mathbf{x}) \cdot e_{\beta}(\mathbf{x})] \; = \; e_{\alpha}(\mathbf{x}) \cdot e_{\beta}(\mathbf{x}) - \sum_{j=1}^{n} R_{\alpha, \beta, j}(\mathbf{x}) \cdot (x_{j}^{2} - x_{j}),
    \end{align*}
    where each polynomial $R_{\alpha, \beta, j}(\mathbf{x})$ has a circuit of size $\bigO(n^{3})$ and depth $5$ (a $\Sigma \Pi \Sigma \Pi \Sigma$ circuit).
    \item There exists coefficients $c_{\alpha, \beta}^{(i)}$'s such that
    \begin{align*}
        \ml[e_{\alpha}(\mathbf{x}) \cdot e_{\beta}(\mathbf{x})] \; = \; \sum_{i = 1}^{n} c_{\alpha,\beta}^{(i)} \; e_{i}(\mathbf{x})
    \end{align*}
\end{itemize}
\end{lemma}


\begin{proof}[Proof of \Cref{lemma:ml-prod-two-elem}]
Using Ben-Or's construction (\Cref{thm:ben-or}) for $e_{\alpha}(\mathbf{x})$ and $e_{\beta}(\mathbf{x})$,
\begin{align*}
    e_{\alpha}(\mathbf{x}) \cdot e_{\beta}(\mathbf{x}) \; = \; \sum_{i_{1}, i_{2}} c_{\alpha,i_{1}}  c_{\beta,i_{2}} \prod_{j=1}^{n} (1+\gamma_{i_{1}} x_{j}) (1+\gamma_{i_{2}} x_{j}), \quad \quad \text{where all } \; c_{\alpha_{i_{1}}}, c_{\beta, i_{2}}, \gamma_{i_{1}}, \gamma_{i_{2}} \in \F
\end{align*}
\begin{equation}\label{eqn:ml-prod-two-elem-1}
 \Rightarrow e_{\alpha}(\mathbf{x}) \cdot e_{\beta}(\mathbf{x}) \; = \; = \sum_{i=1}^{(n+1)^{2}} \prod_{j=1}^{n} h_{i,j}^{\alpha,\beta}(x_{j}),
\end{equation}
where each polynomial $h_{i,j}^{\alpha,\beta}(x_{j})$ is a degree-$2$ \emph{univariate} polynomial. Fix any $i \in [(n+1)^{2}]$ and using \Cref{cor:ml-prod-uni} on $h_{i,1}^{\alpha,\beta}(x_{1}) \cdots h_{i,n}^{\alpha, \beta}(x_{n})$, we know that there exists polynomials $B_{i,j}^{\alpha, \beta}(\mathbf{x})$'s such that:
\begin{align*}
    h_{i,1}^{\alpha,\beta}(x_{1}) \cdots h_{i,n}^{\alpha,\beta}(x_{n}) \; = \; \ml[h_{i,1}^{\alpha,\beta}(x_{1}) \cdots h_{i,n}^{\alpha,\beta}(x_{n})] + \sum_{j=1}^{n} B_{i,j}^{\alpha, \beta}(\mathbf{x}) \cdot (x_{j}^{2} - x_{j}),
\end{align*}
where each polynomial $B_{i,j}(\mathbf{x})$ has a circuit of size $\bigO(n)$ and depth $3$ (a $\Pi \Sigma \Pi$ circuit). Now summing it over all $i \in [(n+1)^{2}]$ (see \Cref{eqn:ml-prod-two-elem-1}), we get,
\begin{align*}
    e_{\alpha}(\mathbf{x}) \cdot e_{\beta}(\mathbf{x}) \; = \; \ml[e_{\alpha}(\mathbf{x}) \cdot e_{\beta}(\mathbf{x})] + \sum_{j=1}^{n} R_{\alpha, \beta, j}(\mathbf{x}) \cdot (x_{j}^{2} - x_{j}),
\end{align*}
where each polynomial $R_{\alpha, \beta, j}(\mathbf{x})$ has a circuit of size $\bigO(n^{3})$ and depth $4$ (a $\Sigma \Pi \Sigma \Pi$ circuit). This shows the \emph{constant-depth circuit} item of \Cref{lemma:ml-prod-two-elem}.


\paragraph{}Next we argue about the \emph{structure} item of \Cref{lemma:ml-prod-two-elem}. Since $e_{\alpha}(\mathbf{x}) \cdot e_{\beta}(\mathbf{x})$ is a symmetric polynomial, its multilinearization $\ml[e_{\alpha}(\mathbf{x}) \cdot e_{\beta}(\mathbf{x})]$ is also a symmetric polynomial. The Fundamental Theorem of Symmetric Polynomials (see \Cref{thm:fundamental-sym}) implies that $\ml[e_{\alpha}(\mathbf{x}) \cdot e_{\beta}(\mathbf{x})]$ is a polynomial of $e_{k}(\mathbf{x})$'s. Note that any multilinear symmetric polynomial is a linear combination of $e_{k}(\mathbf{x})$'s. Thus $\ml[e_{\alpha}(\mathbf{x}) \cdot e_{\beta}(\mathbf{x})]$ is a linear combination of $e_{k}(\mathbf{x})$'s. This finishes the \emph{structure} item of \Cref{lemma:ml-prod-two-elem}. This finishes the proof of \Cref{lemma:ml-prod-two-elem}.
\end{proof}




\paragraph{}Now we are ready to prove \Cref{lemma:multilinearize-char-p}. The idea for the proof is as follows:
\begin{itemize}
    \item We use the fact that $F(\mathbf{y})$ has at most $\mathrm{poly}(n)$ sparsity. So for each monomial $\mathbf{y}^{\bm{\mu}}$, we multilinearize $\mathbf{y}^{\bm{\mu}} \circ \widehat{\mathbf{e}}(\mathbf{x})$ individually. 
    \item For any fixed monomial $\mathbf{y}^{\bm{\mu}} \circ \widehat{\mathbf{e}}(\mathbf{x})$, we note that it is a product of elementary symmetric polynomials. \Cref{lemma:ml-prod-two-elem} shows how to multilinearize a product of two elementary symmetric polynomials. We repeatedly apply this on $\mathbf{y}^{\bm{\mu}} \circ \widehat{\mathbf{e}}(\mathbf{x})$.
\end{itemize}
We recall the statement of \Cref{lemma:multilinearize-char-p} below and then proceed to prove it.

\multsymposchar*

\begin{proof}[Proof of \Cref{lemma:multilinearize-char-p}]
Suppose the polynomial $F(\mathbf{y}) \in \F[y_{1},\ldots,y_{r}]$ is:
\begin{align*}
    F(\mathbf{y}) \; = \; \sum_{\bm{\mu}} \, \lambda_{\bm{\mu}} \mathbf{y}^{\bm{\mu}},
\end{align*}
where $\bm{\mu} = (\mu_{1},\ldots,\mu_{r})$ denotes the exponent vector of a monomial. Recall that the individual degree of $F(\mathbf{y})$ is at most $\leq (p-1)$. Consider a monomial $\mathbf{y}^{\bm{\mu}}$ with a non-zero coefficient $\lambda_{\bm{\mu}}$ in $F(\mathbf{y})$. We will multilinearize $\mathfrak{m} = \prod_{i=1}^{r} e_{p^{i-1}}(\mathbf{x})^{\mu_{i}}$. We do it by multilinearizing two products at a time using \Cref{lemma:ml-prod-two-elem}. Defining $\mu_{0} := 1$, we have,
\begin{align*}
    \mathfrak{m} \; = \; \underbrace{e_{1}(\mathbf{x}) \cdots e_{1}(\mathbf{x})}_{\mu_{1} \text{ times}} \; \cdots \; \underbrace{e_{p^{r-1}}(\mathbf{x}) \cdots e_{p^{r-1}}(\mathbf{x})}_{\mu_{r} \text{ times}} \; = \; \prod_{\ell = 1}^{\bm{\mu}} e_{\alpha_{\ell}}(\mathbf{x}),
\end{align*}
where $\alpha_{\ell} = p^{i-1}$ if $\ell \in  \brac{\sum_{\ell=1}^{i-1} \mu_{\ell} + 1, \; \sum_{\ell=1}^{i} \mu_{i}}$.\\

\begin{claim}\label{claim:multilinearize-exponent-vector}
Let $\bm{\mu} \in \set{0,1,\ldots,p-1}^{r}$ denote an exponent vector as described above. Then for any $k \in [|\bm{\mu}|]$, the following holds:
\begin{itemize}
    \item (Constant-depth circuit). There exists polynomials $R_{\leq \alpha_{k}, j}(\mathbf{x})$'s such that
    \begin{align*}
        \ml\brac{\prod_{\ell = 1}^{k} e_{\alpha_{\ell}}(\mathbf{x})} \; = \; \prod_{\ell=1}^{k} e_{\alpha_{\ell}}(\mathbf{x}) - \sum_{j=1}^{n} R_{\leq \alpha_{k}, j}(\mathbf{x}) \cdot (x_{j}^{2} - x_{j}),
    \end{align*}
    and the polynomials $R_{\leq \alpha_{k}, j}(\mathbf{x})$'s have circuits of size $\bigO(n^{3} \cdot k)$ and depth $5$.
    \item (Structure). There exists coefficients $c_{\leq \alpha_{k}}^{(1)}, \ldots, c_{\leq \alpha_{k}}^{(n)}$ such that
    \begin{align*}
        \ml\brac{\prod_{\ell = 1}^{k} e_{\alpha_{\ell}}(\mathbf{x})} \; = \; \sum_{i=1}^{n} c_{\leq \alpha_{k}}^{(i)} \; e_{i}(\mathbf{x})
    \end{align*}
\end{itemize}
\end{claim}
\begin{proof}[Proof of \Cref{claim:multilinearize-exponent-vector}]
We will prove this using induction on $k$.
\paragraph{Base case:}For $k = 1$, we have $\ml[e_{\alpha_{1}}] = e_{\alpha_{1}}(\mathbf{x})$ and $R_{\leq \alpha_{1}, j}(\mathbf{x}) = 0$. The claim holds for the base case.

\paragraph{Induction step:}Now we assume the induction is true for $k$ and prove it for $(k+1)$. We will first prove the \emph{constant-depth circuit} item for $(k+1)$ and then prove the \emph{structure} item for $(k+1)$.\\

\noindent
Using the \textbf{structure} item of the induction hypothesis, we have,
\begin{equation}\label{eqn:ml-char-p-1}
    \ml\brac{\prod_{\ell = 1}^{k} e_{\alpha_{\ell}}(\mathbf{x})} \; = \; \sum_{i=1}^{n} c_{\leq \alpha_{k}}^{(i)} \; e_{i}(\mathbf{x})
\end{equation}
Using the third item of \Cref{fact:multilinear},
\begin{align*}
    \ml\brac{\prod_{\ell = 1}^{k+1} e_{\alpha_{\ell}}(\mathbf{x})} \; = \; \ml\brac{\ml\brac{\prod_{\ell = 1}^{k} e_{\alpha_{\ell}}(\mathbf{x})} \cdot e_{\alpha_{k+1}}(\mathbf{x})} \\ \\
    = \ml\brac{\sum_{i = 1}^{n} c_{\leq \alpha_{k}}^{(i)} \; e_{i}(\mathbf{x}) \cdot e_{\alpha_{k+1}}(\mathbf{x}) } && (\text{Using \Cref{eqn:ml-char-p-1}}) 
\end{align*}
\begin{equation}\label{eqn:partial-ml-8}
    = \sum_{i = 1}^{n} c_{\leq \alpha_{k}}^{(i)} \; \ml[e_{i}(\mathbf{x}) \cdot e_{\alpha_{k+1}}(\mathbf{x}) ]
\end{equation}
For each $i \in [n]$, we apply the \textbf{constant-depth circuit} item from \Cref{lemma:ml-prod-two-elem} on $e_{i}(\mathbf{x}) \cdot e_{\alpha_{k+1}}(\mathbf{x})$ to get:
\begin{align*}
    \ml[e_{i}(\mathbf{x}) \cdot e_{\alpha_{k+1}}(\mathbf{x})] \; = \; e_{i}(\mathbf{x}) \cdot e_{\alpha_{k+1}}(\mathbf{x}) - \sum_{j=1}^{n} D_{i,\alpha_{k+1}}(\mathbf{x}) \cdot (x_{j}^{2} - x_{j}),
\end{align*}
where the polynomials $D_{i,\alpha_{k+1}}(\mathbf{x})$ have a circuit of size $\bigO(n^{3})$ and depth $5$. Substituting it in \Cref{eqn:partial-ml-8},
\begin{align*}
    \ml\brac{\prod_{\ell = 1}^{k+1} e_{\alpha_{\ell}}(\mathbf{x})} \; = \; \sum_{i=1}^{n} c_{\leq \alpha_{k}}^{(i)} \; \paren{e_{i}(\mathbf{x}) \cdot e_{\alpha_{k+1}}(\mathbf{x}) - \sum_{j=1}^{n} D_{i,\alpha_{k+1}}(\mathbf{x}) \cdot (x_{j}^{2} - x_{j})} \\ \\
    = \paren{\sum_{i = 1}^{n} c_{\leq \alpha_{k}}^{(i)} e_{i}(\mathbf{x}) } e_{\alpha_{k+1}}(\mathbf{x}) - \sum_{j=1}^{n} \paren{\sum_{i = 1}^{n} c_{\leq \alpha_{k}}^{(i)}  D_{i,\alpha_{k+1}}(\mathbf{x})} \; \cdot \; (x_{j}^{2} - x_{j})
\end{align*}
Using \Cref{eqn:ml-char-p-1},
\begin{align*}
    \sum_{i = 1}^{n} c_{\leq \alpha_{k}}^{(i)} e_{i}(\mathbf{x}) \; = \; \ml\brac{\prod_{\ell = 1}^{k} e_{\alpha_{\ell}}(\mathbf{x})} \; = \; \prod_{\ell = 1}^{k} e_{\alpha_{\ell}}(\mathbf{x}) - \sum_{j=1}^{n} R_{\leq \alpha_{k}, j}(\mathbf{x}) \cdot (x_{j}^{2} - x_{j}),
\end{align*}
where we use the \textbf{constant-depth circuit} item from the induction hypothesis for the last equality. The polynomials $R_{\leq \alpha_{k}, j}(\mathbf{x})$'s have circuits of size $\bigO(n^{3} \cdot k)$ and depth $5$ (a $\Sigma \Pi \Sigma \Pi \Sigma$ circuit). Using this in the previous expression, we have
\begin{gather*}
    \ml\brac{\prod_{\ell = 1}^{k+1} e_{\alpha_{\ell}}(\mathbf{x})} \\ 
    = \; \paren{ \prod_{\ell = 1}^{k} e_{\alpha_{\ell}}(\mathbf{x}) - \sum_{j=1}^{n} R_{\leq \alpha_{k}, j}(\mathbf{x}) \cdot (x_{j}^{2} - x_{j}) } e_{\alpha_{k+1}}(\mathbf{x}) - \sum_{j=1}^{n} \paren{\sum_{i = 1}^{n} c_{\leq \alpha_{k}}^{(i)}  D_{i,\alpha_{k+1}}(\mathbf{x})} \; \cdot \; (x_{j}^{2} - x_{j}) \\
    = \; \prod_{\ell=1}^{k+1} e_{\alpha_{\ell}}(\mathbf{x}) - \sum_{j=1}^{n} \; \underbrace{\paren{\sum_{i = 1}^{n} c_{\leq \alpha_{k}}^{(i)}  D_{i,\alpha_{k+1}}(\mathbf{x}) + R_{\leq \alpha_{k}, j}(\mathbf{x})}}_{:= R_{\leq \alpha_{k+1}, j}(\mathbf{x})} \; \cdot \; (x_{j}^{2} - x_{j})
\end{gather*}
The polynomial $R_{\leq \alpha_{k+1},j}(\mathbf{x})$ has a circuit of size $\bigO(n^{3} \cdot (k+1))$ and depth $5$ (a $\Sigma \Pi \Sigma \Pi \Sigma$ circuit). This shows the \emph{constant-depth circuit} item of the induction.\\


\noindent
By applying the \textbf{structure item} of \Cref{lemma:ml-prod-two-elem} on $e_{i}(\mathbf{x}) \cdot e_{\alpha_{k+1}}(\mathbf{x})$, we get,
\begin{align*}
     \ml\brac{\prod_{\ell = 1}^{k} e_{\alpha_{\ell}}(\mathbf{x})} \; = \; \sum_{i=1}^{n} c_{\leq \alpha_{k}}^{(i)} \; e_{i}(\mathbf{x})
\end{align*}
Substituting it in \Cref{eqn:partial-ml-8},

\begin{align*}
    \ml\brac{\prod_{\ell = 1}^{k+1} e_{\alpha_{\ell}}(\mathbf{x})} \; = \; \sum_{i = 1}^{n} c_{\leq \alpha_{k}}^{(i)} \; \sum_{i'=1}^{n} d_{i}^{(i')} e_{i'}(\mathbf{x}) \; = \; \sum_{i = 1}^{n} c_{\leq \alpha_{k+1}}^{(i)} \; e_{i}(\mathbf{x}),
\end{align*}
where $c_{\leq \alpha_{k+1}}^{(i)} = \sum_{j=1}^{n} c_{\leq \alpha_{k}}^{(j)} d_{j}^{(i)}$. This completes the \emph{structure} item of the induction.\newline
This finishes the induction and thus we have finished the proof of \Cref{claim:multilinearize-exponent-vector}.
\end{proof}

\paragraph{}Now we employ \Cref{claim:multilinearize-exponent-vector} on each monomial $\bm{\mu}$ with non-zero coefficient and then sum them together. It is easy to verify that there exists polynomials $R_{j}(\mathbf{x})$'s such that
\begin{align*}
    F(\widehat{\mathbf{e}}(\mathbf{x})) \; = \; \ml[F(\widehat{\mathbf{e}}(\mathbf{x}))] \, + \, \sum_{j=1}^{n} R_{j}(\mathbf{x}) \cdot (x_{j}^{2} - x_{j}),
\end{align*}
where each polynomial $R_{j}(\mathbf{x})$ has a circuit of size $\bigO(p^{r} r 
 n^{3})$ and depth $5$ (a $\Sigma \Pi \Sigma \Pi \Sigma$ circuit). Using $r \leq 2 \log_{p} n$, we get that each polynomial $R_{j}(\mathbf{x})$ has a circuit of size $\bigO(n^{5} \log n)$ and depth $5$. This finishes the proof of \Cref{lemma:multilinearize-char-p}.
\end{proof}


