\section{Proof of Theorem~\ref{thm:counterexample}}\label{sec:counterexample_cd}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

We construct an Eulerian plane triangulation of order $n$ 
with connected domination number at least $\frac{3n}{8}-1$,
which shows that Question~\ref{Q:connected} is false.

\medskip
\noindent
{\bf Construction}:  % of a family $\mathcal{G}_k^{(2)}$}:
For any integer $k \ge 2$,
we construct the graph $T_k$ as follows.
We first prepare the graph $I$ shown in Figure~\ref{fig3},
where we set $T=\{ v_1, w_1 \}$.

\begin{figure}[ht]
\center
\input{fig/fig3.tex}
\caption{The graph $I$, where the two vertices enclosed in circles form the set 
corresponding to $T_{j,i}$ defined in Remark~\ref{rem:final}.}
\label{fig3}
\end{figure}

We next prepare the graph obtained from the Cartesian product $C_3 \Box P_k$ by adding diagonal edges.
More precisely,
%we let $k$ be an integer with $k\ge 2$, and 
we define the graph $T_k$ by
\begin{align*}
V(T_k)
&=\{ x_{j,i}, y_{j,i} \mid 1\le j\le k, 1\le i\le 3 \}\\
E(T_k)
&=\{ x_{j,i}x_{j,i+1}, y_{j,i}y_{j,i+1} \mid 1\le j\le k, 1\le i\le 3 \} \\
&\cup
\{ x_{j,i}y_{j,i} \mid 1\le j\le k, 1\le i\le 3 \}\\
&\cup
\{ y_{j,i}x_{j+1,i} \mid 1\le j\le k-1, 1\le i\le 3 \}\\
&\cup
\{ x_{j,i+1}y_{j,i} \mid 1\le j\le k, 1\le i\le 3 \} \\
&\cup
\{y_{j,i+1}x_{j+1,i} \mid 1\le j\le k-1, 1\le i\le 3 \},
\end{align*}
where we take $x_{j,4}=x_{j,1}$ and $y_{j,4}=y_{j,1}$ for each integer $1\le j\le k$.

\begin{figure}[ht]
\center
\input{fig/fig4.tex}
\caption{The graph $T_k$, where a copy of $I$ is embedded into each shaded triangle
and the vertices enclosed in circles form (a part of) the set $W$ 
defined in Remark~\ref{rem:final}.}
\label{fig4}
\end{figure}

For each integer $1\le j\le k$ and each integer $1\le i\le 3$,
we replace a face $F_{j,i}=x_{j,i}x_{j,i+1}y_{j,i}$ with a copy of $I$
by identifying the $3$-cycle of $F_{j,i}$ with the boundary cycle $u_1u_2u_3$ of $I$
so that $u_1 = x_{j,i}$, $u_2 = x_{j,i+1}$ and $u_3 = y_{j,i}$.
Then we denote by $I_{j,i}$ the copy of $I$ pasted in $F_{j,i}$.
The resulting graph is denoted by $T_k$~(see Figure~\ref{fig4}).
%and let $\mathcal{G}_k^{(2)}=\{ T_k \mid k\ge 2 \}$.
\medskip

Let $S$ be a minimum connected dominating set of $T_k$.
We show that $|S| \ge \frac{3n}{8} - 1$.
To dominate all vertices in $I$ except $u_1,u_2,u_3$,
we need to choose at least two of $v_1,v_2,v_3,w_1,w_2,w_3$ as a connected dominating set;
otherwise, if exactly only one of them is chosen,
then either at least one of them is not dominated or 
some $w_i$ chosen is not adjacent to any dominating vertex.
Therefore, for each integer $1\le j\le k$ and each integer $1\le i\le 3$,
\begin{align}
\label{eq:7.1}
|S \cap V(I_{j,i}) \setminus \{x_{j,i},x_{j,i+1},y_{j,i}\}| \ge 2. 
\end{align}


Let $L^x_{j,i} = \{x_{j,i},x_{j,i+1},x_{j,i+2}\}$
and
$L^y_{j,i} = \{y_{j,i},y_{j,i+1},y_{j,i+2}\}$.
Since $G[S]$ is connected, we have one of the following for each integer $1 \le j \le k-1$:
\begin{enumerate}
    \item $|S\cap L^x_{j,i}| \ge 2$ and $|S\cap L^y_{j,i}| \ge 1$.
    \item $|S\cap L^x_{j,i}| \ge 1$ and $|S\cap L^y_{j,i}| \ge 2$.
    \item $|S\cap L^y_{j,i}| \ge 3$.
\end{enumerate}
Otherwise, we easily see that for some $j,i$,
all vertices in $S \cap I_{j,i}$ is not adjacent to any other vertex in $S \setminus I_{j,i}$ by \eqref{eq:7.1},
or $S \cap (L^x_{j,i} \cup L^y_{j,i})$ is not connected to $S \cap (L^x_{j+1,i} \cup L^y_{j+1,i})$.
When $j = k$, $|S \cap (L^x_{k,i} \cup L^y_{k,i})| = 2$ suffice to connect all vertices in $S \cap \bigcup_{1\le i\le 3} I_{k,i}$.
Therefore, we can easily verify that
\begin{itemize}
\item
$|V(T_k)|=24k, \ |S| = (2 \cdot 3) \cdot  k + 3 \cdot  (k-1) + 2 = 9k -  1$, and then
\item
$\gamma_c(T_k) = |S| \ge \frac{3}{8}|V(T_k)| - 1$.
\end{itemize}

Furthermore, it can immediately be checked that $T_k$ is Eulerian.
This completes the proof of Theorem~\ref{thm:counterexample}.

\begin{rem}
\label{rem:final}
\rm
We also see that $\gamma_c(T_k) = \frac{3}{8}|V(T_k)| - 1$.
For each integer $1\le j\le k$ and each integer $1\le i\le 3$,
let $Z_{j,i}=\{ v_{j,i}, w_{j,i} \}$ be the subset of $V(I_{j,i})$ that corresponds to $\{ v_1, w_1\}$ of $I$.
Set $W = \{x_{j,i},x_{j,i+1},y_{j,i} | 1 \le j \le k - 1\} \cup \{x_{k,i},x_{k,i+1}\}$.
Then it is clear that $W \cup \bigcup_{1\le j\le k} \bigcup_{1\le i\le 3} Z_{j,i}$ 
is a connected dominating set and its cardinality is exactly $\frac{3}{8}|V(T_k)| - 1$.
\end{rem}


\begin{rem}
\label{rem:final2}
\rm
We also see that $s_{o'}(T_k) = \frac{5}{8}|V(T_k)| + 1$. 
By Remark~\ref{rem:final},
we have $s_{o'}(T_k) \ge \frac{5}{8}|V(T_k)| + 1$,
and then we suffice to show that $s_{o'}(T_k) < \frac{5}{8}|V(T_k)| + 2$.
Let $O$ be the largest induced outerplane subgraph of $T_k$.
For each $j \in \{1,2,\dots,k\}$,
let $L_j = L^x_{j,i} \cup L^y_{j,i}$ 
and let $A_j = L_j \cup I_{j,i}$, where $1 \le i \le 3$.
Suppose to the contrary that 
$|V(O)| \ge \frac{5}{8}|V(T_k)| + 2 = 15k + 2$.
By this assumption, we have either
(i) there is some $1 \le t \le k$ such that $|V(O) \cap (A_t)| \ge 17$
or 
(ii) there is some $1 \le t \le k-1$ such that $|V(O) \cap (A_t)| \ge 16$ and $|V(O) \cap (A_{\ell})| \ge 15$ for any other $\ell \ne t$.
For each integer $1\le j\le k$ and each integer $1\le i\le 3$, it is clear that $|V(O) \cap I_{i,j}| \leq 4$. 
Therefore, in both cases (i) and (ii),
we can easily find a separating cycle in $O$,
which contradicts that $O$ is outerplane.
\end{rem}

