        \leq & \mathbb{E}^{\alpha} \Bigr[K^p|P^{cl}|^2N^p_t\Bigr] + \mathbb{E}^{\alpha} \Bigr[|K^pP^{cl}_t\int_0^t P^p_{s}dN^p_s|\Bigr] + \mathbb{E}^{\alpha} \Bigr[|K^pP^{*}_tP^{cl}N^p_t|\Bigr]+\mathbb{E}^{\alpha} \Bigr[|K^p P^{*}_t  \int_0^t P^p_{s}dN^p_s|\Bigr]\\
        \leq & \mathbb{E}^{\alpha} \Bigr[K^p|P^{cl}|^2N^p_t\Bigr]+ \mathbb{E}^{\alpha} \Bigr[K^p|P^{cl}|N^p_t\check{P}_t\Bigr] + \mathbb{E}^{\alpha} \Bigr[|K^pP^{*}_tP^{cl}_tN^p_t|\Bigr]+\mathbb{E}^{\alpha} \Bigr[K^p|P^{*}_t|N^p_t\check{P}_t\Bigr]\\
        \leq & \mathbb{E}^{\alpha} \Bigr[K^p|P^{cl}|^2N^p_t\Bigr]+ \sqrt{\mathbb{E}^{\alpha} \Bigr[(K^pP^{cl}N^p_t)^2\Bigr] }(\sqrt{\mathbb{E}^{\alpha} \Bigr[(\check{P}_t^*)^2\Bigr]}+\sqrt{\mathbb{E}^{\alpha} \Bigr[(P_t^*)^2\Bigr]})\\
        &+\sqrt{\mathbb{E}^{\alpha} \Bigr[(K^pN^p_t
        )^2\Bigr]\mathbb{E}^{\alpha} \Bigr[ (P_t^*\check{P}_t)^2 ]},
    \end{align*}
where $\check{P}_t:= (|P_0^*|+ t \mu_{\infty} + \sigma W^{p}_{max} - \sigma W^{p}_{min})\Bigr]$.
For every $t \in [0,T]$, we know
\[ \lambda_t^a\leq \lambda_0 i^a(-\mu_\infty,-\mu_\infty)\iota(d),\;  \lambda_t^b\leq \lambda_0 i^b(\mu_\infty,\mu_\infty)\iota(d),\] and $\lambda^p_t$ and $\lambda_t^{q}$ are bounded by $\lambda_{\infty}$. Consequently, $\mathbb{E}^{\alpha}[N_t^a] + \mathbb{E}^{\alpha}[N_t^b] +  \mathbb{E}^{\alpha}[N^{p}_t]+\mathbb{E}^{\alpha}[N^{q}_t]$ are uniformly bounded in $t$. Note that
\[\mathbb{E}^{\alpha} \Bigr[(N_t^a)^2  \Bigr]  \leq e^{(t\lambda_0e^{(c_1+c_2)\mu_{\infty}}e^{-d})}\Bigr[ (t\lambda_0e^{(c_1+c_2)\mu_{\infty}}e^{-d})(t\lambda_0e^{(c_1+c_2)\mu_{\infty}}e^{-d}+1)\Bigr]    < \infty.\] Similarly, $\mathbb{E}^{\alpha} \Bigr[(N_t^b)^2  \Bigr]$, $\mathbb{E}^{\alpha} \Bigr[(N^p_t)^2  \Bigr]$, and $\mathbb{E}^{\alpha} \Bigr[(N^{q}_t)^2  \Bigr]$ are bounded. Moreover, $\mathbb{E}^{\alpha} \Bigr[W^{p}_{max}\Bigr] = \mathbb{E}^{\alpha} \Bigr[|\tilde W^{p}_T|\Bigr] = \sigma \sqrt{\frac{2T}{\pi}}$, $\mathbb{E}^{\alpha} \Bigr[(W^{p}_{max})^2\Bigr] =\mathbb{E}^{\alpha} \Bigr[(\tilde W^{p}_T)^2\Bigr] = \sigma^2T$, and $\mathbb{E}^{\alpha} \Bigr[(P^{*}_t)^2\Bigr] = \sigma^2 t + (P_0^*)^2$.

Moreover,
\begin{align*}
