& \leq \mathbb{E}^{\alpha} \Bigr[\frac{1}{K^2}((v^aN_t^a)^2 + (v^bN_t^b)^2 + 2v^av^bN_t^aN_t^b + 2K(v^a N_t^a+v^b N_t^b) N^p_t\check{P}_t+2K^{q}(v^a N_t^a+v^b N_t^b) N^{q}_t\check{P}_t\\
&\hspace{3em}+ (K^pN^p_t)^2|\check{P}_t|^2+(K^{q}N^{q}_t)^2|\check{P}_t|^2 + 2K^p K^{q}N^p_tN_t^{q} (|P_0^*|+ t \mu_{\infty} + \sigma W^{q}_{max} - \sigma W^{q}_{min})\check{P}_t\\
