\end{align*}

We prove that $\hat{\mu}^p$ and $\hat{\lambda}^p$ are the strategic trader $p$'s optimized controls for \eqref{eq:traderproblem}.


By using a similar approach as in Part (a) above, since $g(X_t)$ and $(X_t^4 - X_t^5P_t^{cl})^2$ are $\mathbb{P}^0$-integrable for every $t \in [0,T]$ we deduce from \cite[Proposition 2.10]{bjork2021point} and \cite[Theorem 4.3.1]{shreve2004stochastic} that $\int_0^t Z^1_s (dN^{a}_s - \lambda_0 ds)$, $\int_0^t Z^2_s (dN^{b}_s - \lambda_0 ds)$, $\int_0^t Z^3_s dW_s$, $\int_0^t Z^4_s (dN^p_s- \lambda_0 ds)$, $\int_0^t Z^5_s dW^{p}_s$, $\int_0^t  Z^6_s (dN^{q}_s - \lambda_0 ds)$, and $\int_0^t Z^7_s dW^{q}_s$ are $\mathbb{P}^0$-martingales. From \eqref{eq:xi_eq}, we deduce that $\hat \alpha^p = (\hat{\mu}^p, \hat{\lambda}^p)$ is the trader $p$'s optimal control.


    \textit{Part (d)}:  We show the representation $( Y_0, Z)$ of $\xi^p$ is unique. 

    Suppose there exists two representations $( Y_0, Z)$ and $(\tilde Y_0, \tilde Z)$ of $\xi^p$. Take any $t \in [0,T]$, define $V^{\circ,p}_t(\xi^p, \alpha^{q},d) : = \sup_{\alpha^p \in \mathcal{V}_t} V_t(\xi^p,\alpha^{q},\alpha^p,d)$, where $\mathcal{V}_t$ is the restriction of the collection of controls $\mathcal{V}$ to time $[t,T]$. Then $V_t^{\circ,p}(\xi^p,\alpha^{q},d) = \sup_{\alpha^p \in \mathcal{V}_t} \mathbb{E}^0 [V_t(\xi^p,\alpha^{q},\alpha^p,d) | \mathcal{F}_t]=  \sup_{\alpha^p \in \mathcal{V}_t} \mathbb{E}^0 [ \xi^p + \int_t^T f(X_s,Z_s,r_s,\alpha^p_s,\alpha_s^q,P_s^p,P_s^q,d) ds | \mathcal{F}_t ] \leq V_t(\xi^p,\alpha^{q},\hat \alpha^p,d)$. Then $Y_t = \tilde Y_t$, for every $t \in [0,T]$. We thus have $( Y_0, Z) = (\tilde Y_0, \tilde Z)$.


%This is because $\mathbb{E}^0 V_0(\xi, \hat{\delta},\hat{\lambda}) \geq \mathbb{E}^0 V_0(\xi, \delta,\lambda)$ for any $\delta$ and $\lambda \in \mathcal{V}$.

\end{proof}


\subsubsection{Nash Equilibrium between Strategic Traders}
\label{sec:nash}

We define the subset $U\subset \mathbb R^{7\times 2}$ as the set of $z$ such that for any $x,r,P,d\in \mathbb R^7\times  \mathbb R^2\times \mathbb R_+$ there exists $\hat a(x,z,r,P,d)=(\hat a^p(x,z,r,P,d);\hat a^q(x,z,r,P,d)):=(\hat \mu^p,\hat \lambda^p;\hat\mu^q,\hat\lambda^q)\in (\Delta\times \Lambda)^2$ defined as the fixed point to the following system

\[(FP)\begin{cases}
\hat a^p(x,z,r,P,d)\in \text{arg sup }_{\mu^p\in \Delta, \lambda^p\in \Lambda} F^p(x,z,r,P, \hat a^q(x,z,r,P,d),d;\mu^p,\lambda^p),\\
\hat a^q(x,z,r,P,d)\in \text{arg sup }_{\mu^q\in \Delta, \lambda^q\in \Lambda} F^q(x,z,r,P, \hat a^p(x,z,r,P,d),d;\mu^q,\lambda^q).
\end{cases}\]


We define the subset $U_{max} \subset U$ to be the set of $z$ such that for any $x,r,P,d\in \mathbb R^7\times  \mathbb R^2\times \mathbb R_+$ there exists $\hat a(x,z,r,P,d)=(\hat a^p(x,z,r,P,d);\hat a^q(x,z,r,P,d)):=(\hat \mu^p,\hat \lambda^p;\hat\mu^q,\hat\lambda^q)\in (\Delta\times \Lambda)^2$ with $\hat \mu^p, \hat \mu^q \not \in \{\mu_{\infty},- \mu_{\infty}\}$.


\begin{remark}\label{rem:Ucharacterization} We provide in this remark examples and conditions ensuring that $U$ (or $U_{max}$) is not empty
\begin{enumerate}
    \item \textit{Rebates indexed on investors' activity only and fixed point.} Take $z^{k,i}=0$ for any $k\in\{3,\dots,7\}$ and $i=p,q$. It means that only $z^{1,p},z^{1,q}$ and $z^{2,p},z^{2,q}$ are actively considered in the contract, that is the indexation with respect to the volume $v^a,v^b$ sent by buyer/seller investors redistributed to the Market Makers. Then, (FP) is equivalent to 
 \[ \begin{cases}
 &\big( Dg^{p,1}(x)+z^{1,p} \big) \frac{\partial{\lambda^a}}{\partial \mu^p} (\hat\mu,d)+\big( Dg^{p,2}(x)+z^{2,p} \big) \frac{\partial{\lambda^b}}{\partial \mu^p}(\hat\mu,d)=0 \textbf{, or } \hat \mu^p = \mu_{\infty} \textbf{, or } \hat \mu^p = -\mu_{\infty}\\
 &\hat\lambda^p=\big( \lambda_0+g^p(x + [0,0, 0, P^p,1,0,0]) - g(x) \big) \\
  &\big( Dg^{q,1}(x)+z^{1,q} \big) \frac{\partial{\lambda^a}}{\partial \mu^q} (\hat\mu,d)+\big( Dg^{q,2}(x)+z^{2,q} \big) \frac{\partial{\lambda^b}}{\partial \mu^q}(\hat\mu,d)=0 \textbf{, or } \hat \mu^q = \mu_{\infty} \textbf{, or } \hat \mu^q = -\mu_{\infty}\\
 &\hat\lambda^q=\big( \lambda_0+g^q(x + [0,0, 0, 0,0,P^q,1]) - g(x) \big),
    \end{cases}\] 

    where 
    \[Dg^{i,1}(x)=   g^i(x + [r^1 , 0,0, 0,0,0,0]) - g^i(x),\; Dg^{i,2}(x)= g^i(x + [0,r^2 ,0, 0,0,0,0]) - g^i(x).\]
   The solution in $\hat\lambda$ is explicit. It thus remains to choose $z^{1,p},z^{1,q},z^{2,p}, z^{2,q},\lambda^a,\lambda^b$ ensuring that this system admits a solution. For example, if we choose 
 \[\lambda^a = \lambda_0 e^{-c\mu^p - \tilde c\mu^q} e^{-d} \text{ and }\lambda^b = \lambda_0 e^{c\mu^p + \tilde c \mu^q}e^{-d},\] we get

 \[ \begin{cases}
 &e^{2c\hat\mu^p+2\tilde c\hat\mu^q}= \frac{Dg^{p,1}(x)+z^{1,p}}{Dg^{p,2}(x)+z^{2,p}}=\frac{Dg^{q,1}(x)+z^{1,q}}{Dg^{q,2}(x)+z^{2,q}}\textbf{, or } \hat \mu^p, \hat \mu^q \in \{\mu_{\infty}, -\mu_{\infty}\}\\
 &\hat\lambda^p=\big( \lambda_0+g^p(x + [0,0, 0, P^p,1,0,0]) - g(x) \big) \\
 &\hat\lambda^q=\big( \lambda_0+g^q(x + [0,0, 0, 0,0,P^q,1]) - g(x) \big).
    \end{cases}\]


The set $U_{max}$ hence contains all the $z\in \mathbb R^{7\time 2}$  such that $z^{k,i}=0$ for $k\in \{3,\dots,7\},\; i=p,q$ and
 \[ \begin{cases}
&\frac{Dg^{p,1}(x)+z^{1,p}}{Dg^{p,2}(x)+z^{2,p}}=\frac{Dg^{q,1}(x)+z^{1,q}}{Dg^{q,2}(x)+z^{2,q}}>0\\
&Dg^{p,1}(x)+z^{1,p} < 0\\
&Dg^{q,1}(x)+z^{1,q} < 0.
\end{cases}\]


\item \textit{Symmetric Market Makers.}
 Assume that $\Lambda=[0,\lambda_\infty]$ for some positive constant $\lambda_\infty$, $R_0^p=R_0^q$, $K^p=K^q$ and for any $\alpha=(\mu^p,\lambda^p;\mu^q,\lambda^q)\in \Delta\times \Lambda\times \Delta\times \Lambda$ we have \[\lambda^a(\mu^p,\mu^q,\lambda^p,\lambda^q)=\lambda^a(\mu^q,\mu^p,\lambda^q,\lambda^p),\; \lambda^b(\mu^p,\mu^q,\lambda^p,\lambda^q)=\lambda^b(\mu^q,\mu^p,\lambda^q,\lambda^p).\] 

Then, note that $Dg^{p,1}=Dg^{q,1}=:Dg^1$ and $Dg^{p,2}=Dg^{q,2}=:Dg^2$ so that (FP) is equivalent to
 \[ \begin{cases}
 &-\frac{z^{5,p}}\sigma+(Dg^1(x)+z^{1,p})\frac{\partial \lambda^a}{\partial \mu^p}(\hat\mu,d)+(Dg^2(x)+z^{2,p})\frac{\partial \lambda^b}{\partial \mu^p}(\hat\mu,d)=0 \textbf{, or } \hat \mu^p = \mu_{\infty} \textbf{, or } \hat \mu^p = -\mu_{\infty}\\
  &-\frac{z^{7,q}}\sigma+(Dg^1(x)+z^{1,q})\frac{\partial \lambda^a}{\partial \mu^p}(\hat\mu,d)+(Dg^2(x)+z^{2,q})\frac{\partial \lambda^b}{\partial \mu^p}(\hat\mu,d)=0 \textbf{, or } \hat \mu^q = \mu_{\infty} \textbf{, or } \hat \mu^q = -\mu_{\infty}\\
 &\hat\lambda^p=\big( \lambda_0+g(x + [0,0, 0, P^p,1,0,0]) - g(x)+z^{4,p} \big) \\
 &\hat\lambda^q=\big( \lambda_0+g(x + [0,0, 0, 0,0,P^q,1]) - g(x)+z^{6,q} \big).
    \end{cases}\]
In particular, if \[\lambda^a = \lambda_0 e^{-c(\mu^p+\mu^q)} e^{-d} \text{ and }\lambda^b = \lambda_0 e^{c(\mu^p +  \mu^q)}e^{-d},\] we get
\[ \begin{cases}
 &-\frac{z^{5,p}}\sigma-c(Dg^1(x)+z^{1,p})e^{-c(\hat\mu^p +  \hat\mu^q)}+c(Dg^2(x)+z^{2,p})e^{c(\hat\mu^p +  \hat\mu^q)}=0 \textbf{, or } \hat \mu^p = \mu_{\infty} \textbf{, or } \hat \mu^p = -\mu_{\infty}\\
  &-\frac{z^{7,q}}\sigma-c(Dg^1(x)+z^{1,q})e^{-c(\hat\mu^p +  \hat\mu^q)}+c(Dg^2(x)+z^{2,q})e^{c(\hat\mu^p +  \hat\mu^q)}=0 \textbf{, or } \hat \mu^q = \mu_{\infty} \textbf{, or } \hat \mu^q = -\mu_{\infty}\\
 &\hat\lambda^p=\big( \lambda_0+g(x + [0,0, 0, P^p,1,0,0]) - g(x)+z^{4,p} \big) \\
 &\hat\lambda^q=\big( \lambda_0+g(x + [0,0, 0, 0,0,P^q,1]) - g(x)+z^{6,q} \big).
    \end{cases}\]

If $z^{1,p}=z^{1,q}=z^1,\, z^{2,p}=z^{2,q}=z^2,\, z^{5,p}=z^{7,q}=\tilde z$ and there exists $\gamma$ such that 
\begin{equation}\label{gamma}-\frac{\tilde z}\sigma-c(Dg^1(x)+z^{1})\frac{1}\gamma+c(Dg^2(x)+z^{2})\gamma=0,\end{equation}
\begin{equation}\label{eq:z_condition} Dg^1(x)+z^{1} <0, \quad Dg^2(x)+z^{2}<0,\end{equation}
(FP) admits a solution in $U_{max}$. In this case, we get 
\[ \begin{cases}
 &\hat\mu^p+\hat\mu^q=\frac{\ln(\gamma)}{c}\\
 &\hat\lambda^p=\big( \lambda_0+g(x + [0,0, 0, P^p,1,0,0]) - g(x)+z^{4,p} \big) \\
 &\hat\lambda^q=\big( \lambda_0+g(x + [0,0, 0, 0,0,P^q,1]) - g(x)+z^{6,q} \big).
    \end{cases}\]

    \end{enumerate}
    Therefore, the set $U$ contains the set of $z$ such that $z^{1,p}=z^{1,q},\, z^{2,p}=z^{2,q},\, z^{5,p}=z^{7,q}$ and such that \eqref{gamma} and \eqref{eq:z_condition} admits a solution. 
    \end{remark}


%Furthermore, when $i^a$ and $i^b$ take the exponential format mentioned above, we should attain the $\argmax$ $\mu_s^p$ and $\mu_s^q$ of $f^p$ and $f^q$ at solutions to $\{\frac{\partial f^p}{\partial \mu^p}=0, \frac{\partial f^p}{\partial \mu^p}=0 \}$ instead of the boundary $-\mu_{\infty}$ or $\mu_{\infty}$ if the following are satisfied: \begin{equation}
%    g^i (X_{s} + [r_s^1 , 0,0, 0,0,0,0]) - g^i(X_{s}) -Z^{1,i}_s < 0
%    \label{eq:z_condition1}
%\end{equation} and \begin{equation}
%    g^i(X_{s} + [0,r_s^2 ,0, 0,0,0,0]) - g^i(X_{s}) ) -Z^{2,i}_s < 0,
%    \label{eq:z_condition2}
%\end{equation} for $i \in \{p,q\}$. 



Our goal is to characterize a set of rebates $(\xi,d)$ such that $NE(\xi,d)$ admits a solution.  Extending the deifnition of $\Xi^p$, we now consider the following set of contracts
\[\Xi:=\{Y_T^{Y_0,Z,d}, Z\in \mathcal Z, Y_0^i\geq R_0^i,\; i=p,q\},\]
where the process $Y_t^{Y_0, Z,d}:=(Y_t^{p; Z,d},Y_t^{q; Z,d})$ is defined by:
 \begin{align*}
        Y^{i;Z,d}_t =& Y^i_0 + \int_0^t Z^{1,i}_s (dN^{a}_s - \lambda_0 ds)+ \int_0^t  Z^{2,i}_s (dN^{b}_s -  \lambda_0 ds)+ \int_0^t  Z^{3,i}_s dW_s + \int_0^t  Z^{4,i}_s (dN^p_s- \lambda_0 ds) \\
        &+ \int_0^t Z^{5,i}_s dW^{p}_s + \int_0^t  Z^{6,i}_s (dN^{q}_s - \lambda_0 ds) + \int_0^t Z^{7,i}_s dW^{q}_s - \int_0^t F^i(X_s,Z_s,r_s,P_s, \hat \alpha^j_s,d;\hat \alpha^i_s) ds,
\end{align*} where $r_s := [v_{(N_{s^-}^a+1)}^a \mathbf 1_{A_{(N_{s^-}^a+1)} \leq \theta(T - s)}, v_{(N_{s^-}^b+1)}^b \mathbf 1_{B_{(N_{s^-}^b+1)} \leq \theta(T - s)} ]$, We denotes $\hat\alpha^i_s:=\hat a^i(X_s,Z_s,r_s,P_s,d)$ and where $\mathcal Z$ denotes the space of random $\mathbb F-$predictable processes $Z=(Z^p,Z^q)\in \mathcal Z^p\times \mathcal Z^q$. 


We recall that a pair of controls $\alpha = (\hat\alpha^p,\hat\alpha^q) \in \mathcal{A}$ is said to be a Nash equilibrium  for the two strategic traders if it solves
\[NE(\xi,d)
\begin{cases}
V^{p}_0(\xi^p,d,\hat\alpha^{q};\hat\alpha^{p}): &= \sup_{\alpha \in \mathcal{A},\; \alpha=(\alpha^p,\hat\alpha^{q})} V^p_0(\xi^p,d,\hat\alpha^{q}; \alpha^p)\\
V^{q}_0(\xi^q,d,\hat\alpha^{p};\hat\alpha^{q}): &= \sup_{\alpha \in \mathcal{A},\; \alpha=(\hat\alpha^{p},\alpha^{q})} V^q_0(\xi^q,d,\hat\alpha^{p}; \alpha^q).

\end{cases}\]

Lemma \ref{lemma:trader} shows that the optimal control for each strategic trader in solving $NE(\xi,d)$ depends on not only the exchange's incentive, the transaction fee, but also the action of the other trader. Therefore, we aim to identify the set of incentives and fees that could lead to a Nash equilibrium between the two strategic traders. Note that without the right incentive and fee, the strategic traders may otherwise engage in an endless search for a better trading strategy, that is why we need to characterize the set of $(\xi,d)$ such that $NE(\xi,d)\neq\emptyset$. We denotes by $\mathcal U$ the subset of $\mathcal Z$ such that $Z$ is $U-$valued.


\begin{theorem}
\label{thm:main}
For a given $\xi \in \mathcal{I}$ and $d \in \mathbb{R}_+$, the following are equivalent:

\begin{itemize}
    \item[(i)] there exists a Nash equilibrium $\alpha = ( \alpha^p,  \alpha^q)$, that is $NE(\xi,d)\neq \emptyset$;
\item[(ii)]there exists unique $Y_0 = (Y_0^p, Y_0^q) \in \mathbb{R} \times \mathbb{R}$ and unique $Z = (Z^{p},Z^{q}) \in \mathcal{U} \times \mathcal{U}$ such that $\xi = (\xi^p, \xi^q) = (Y_T^{p,Z^p,d}, Y_T^{q,Z^q,d})$, where for $i \in \{p,q\}$,
\begin{align*}
Y_t^{i,Z^i,d} =& Y^i_0 +\int_0^t Z^{1,i}_s (dN^{a}_s - \lambda_0 ds)+ \int_0^t  Z^{2,i}_s (dN^{b}_s -  \lambda_0 ds)+ \int_0^t  Z^{3,i}_s dW_s+ \int_0^t  Z^{4,i}_s (dN^p_s- \lambda_0 ds) \\
        &+ \int_0^t Z^{5,i}_s dW^{p}_s +\int_0^t  Z^{6,i}_s (dN^{q}_s - \lambda_0 ds) + \int_0^t Z^{7,i}_s dW^{q}_s - \int_0^t F^i(X_s,Z_s,r_s,P_s, \hat \alpha^j_s,d;\hat \alpha^i_s) ds,
\end{align*}
where $\hat \alpha^i_s=\hat a^i(X_s,Z_s,r_s,P_s,d)$ solves (FP).
\end{itemize}

In addition, if one of the above is satisfied, then $\alpha$ from (i) equals $\hat \alpha$ in (ii).

\end{theorem}


\begin{proof}
   Assume that there exists a Nash equilibrium $\alpha=(\alpha^p,\alpha^q)$. Then, (ii) is a direct consequence of Lemma \ref{lemma:trader} for both Market Maker $p$ and $q$ simultaneously under the assumption that there exists a solution to $(FP)$. Conversely, assume that (ii) is satisfied with the fixed point $\hat\alpha$. Then, $\hat\alpha^i$ is the best response of Market Maker $i$ regarding the control $\hat\alpha^j$ played by the other market maker regarding 2. in Lemma \ref{lemma:trader}. Hence, $\hat\alpha\in NE(\xi,d)$ where $\xi=(Y_T^{p;Z^p,Y_0^p,d},Y_T^{q;Z^q,Y_0^q,d})\in \Xi $.
\end{proof}



\begin{corollary}[Symmetric Market Makers and Nash equilibrium] Let $\alpha=(\mu^p,\lambda^p;\mu^q,\lambda^q)\in \Delta\times \Lambda\times \Delta\times \Lambda$ and assume that \[\lambda^a(\mu,d) = \lambda_0 e^{-c(\mu^p+\mu^q)} e^{-d} \text{ and }\lambda^b(\mu,d) = \lambda_0 e^{c(\mu^p +  \mu^q)}e^{-d},\]$R_0^p=R_0^q$, $K^p=K^q$. Then, there exists a Nash equilibrium, \textit{i.e.} $NE(\xi,d)\neq \emptyset$ if
$\xi=Y_T^{Y_0,Z,d},$ where 
$Z^{1,p}=Z^{1,q},\, Z^{2,p}=Z^{2,q},\, Z^{5,p}=Z^{7,q}$ and there exists $\gamma$ satisfying \eqref{gamma}.
In this case, we get 

\[ \begin{cases}
 &\hat\mu^p_t+\hat\mu^q_t= \frac{\ln(\gamma_t)}{c}\\
 &\hat\lambda^p_t=\big( \lambda_0+g(X_t + [0,0, 0, P^p_t,1,0,0]) - g(X_t)+Z^{4,p}_t \big) \\
 &\hat\lambda_t^q=\big( \lambda_0+g(X_t + [0,0, 0, 0,0,P_t^q,1]) - g(X_t)+Z^{6,q}_t \big).
    \end{cases}\]
\end{corollary}


\section{Stock Exchange's Problem: optimal rebates and transaction fees}
\label{sec:principalprb}
The principal, the stock exchange, aims to minimize the market inefficiency (defined as the distance between the clearing price and the efficient price), minimize total incentives provided to the strategic traders, and maximize total transaction fees collected from non-strategic traders. Define $\rho(\xi,d,\alpha) = \mathbb{E}^{\alpha}\Big[|P^{cl}_T - P_T^{*}|^2 + \xi \cdot I_2 - d(\sum_{i=1}^{N_t^a} v^a_i \mathbf 1_{A_i \leq \theta(T - \tau_i)} + \sum_{j=1}^{N_t^b} v^b_j \mathbf 1_{B_j \leq \theta(T - \tau_i)})\Big]$, where $I_2 = [1;1]$. The exchange aims to find the best $\xi$ and $d$ that minimizes $\rho(\xi,d,\alpha)$.  \vspace{0.5em}


Define $NEI(\xi,d) = \{\alpha \in NE(\xi,d): \rho(\xi,d,\alpha) \leq \rho(\xi,d,\beta), \text{ for any }\beta \in  NE(\xi,d) \}$.

\begin{remark}
The reason we introduce $NEI(\xi,d)$ is because certain pairs $(\xi,d)\in NE(\xi,d)$ might result in more than one pairs of Nash equilibrium actions of the strategic traders; we thus assume that the traders always pick the Nash equilibrium action that benefits the exchange the most. The exchange proposes thus recommended price and intensity of arrival to the Market Makers, as explained in \cite{elie2019contracting}. Unlike \cite[Assumption 3.1]{hernandez2024principal} we are not assuming the uniqueness of Nash equilibrium and we defer the choice to the exchange as formulated in the seminal paper of Holmstrom and Milgrom \cite{holmstrom1987aggregation}
as recommended actions. \end{remark}

%\begin{remark}
%Note that for the choice $\lambda^a_t = \lambda_0 e^{-c_1\mu^p_t - c_2\mu^q_t} e^{-d} \text{ and }\lambda^b_t = \lambda_0 e^{c_3\mu^p_t + c^4 \mu^q_t}e^{-d},$ we note that $NE(\xi,d)$ is reduced to one element, so that $NE(\xi,d)=NEI(\xi,d)$ for any $\xi\in \mathcal C^p]times \mathcal C^q$ and $d>0$.
%\end{remark}


For any $d \in \mathbb{R_+}$, Define $\mathcal{I}(d)$ to be the set of incentives $\xi$ such that $\xi \in \mathcal{I}$ and $NE(\xi,d) \ne \emptyset$. Let $\hat\alpha(\xi,d)\in NEI(\xi,d)$ given by Theorem \ref{thm:main}. We formulate the problem of the exchange as 
\begin{align}
   \nonumber  \rho &=  \min_{d>0,\xi \in \mathcal{I}(d)}\;  \rho(\xi,d,\hat\alpha(\xi,d)) \\
    &= \min_{d >0,\xi \in \mathcal{I}(d)} \mathbb{E}^{\hat\alpha(\xi,d)}\Big[|P^{cl}_T - P_T^{*}|^2 + \xi \cdot I_2 - d(\sum_{i=1}^{N_t^a} v^a_i \mathbf 1_{A_i \leq \theta(T - \tau_i)} + \sum_{j=1}^{N_t^b} v^b_j \mathbf 1_{B_j \leq \theta(T - \tau_i)})\Big] \label{eq:ex}\\
    %\Lambda = &\min_{\xi \in} \mathbb{E}^{\hat\lambda(\xi)}\Big[\exp{ \Big(\rho\big(|P^{cl}_T - P_T^{*}| - \xi \cdot I_2 \big)\Big)}\Big], \label{eq:ex}\\
    &\text{ subject to } V_0^{p}(\xi^p,d,\hat\alpha) \geq R_0^p, \quad V_0^{q}(\xi^q,d,\hat\alpha) \geq R_0^q\label{eq:ex_const}
\end{align}
where $R_0=(R_0^p,R_0^q) \in \mathbb{R}^2$ is the vector of reservation constraint utility of the market makers $p$ and $q$. $R_0^p$ and $R_0^q$ can be for example chosen as the PnL of each market maker if they were trading on a coexisting limit order book at the fair price $P^*$ along the duration $T$. 
%Note that this is different from the discrete case in which the RHS of the constraint is $\mathbb{E}[\frac{\gamma}2  \int_0^T K(P^{cl}_T - P^{\mu}_{t})dN^{\lambda}_t ]$.

Due to the simplicity of the transaction fees structure for investors given by the $d$ constant, we rely on numerical method to find the optimal $\hat d$. Fixing $d>0$, the exchange optimizes the rebate by solving
\begin{equation}\label{eq:exchange_incentive}
\rho(d) = \min_{\xi \in \mathcal{I}(d)} \mathbb{E}^{\hat\alpha(\xi,d)}\Big[|P^{cl}_T - P_T^{*}|^2 + \xi \cdot I_2 - d(\sum_{i=1}^{N_t^a} v^a_i \mathbf 1_{A_i \leq \theta(T - \tau_i)} + \sum_{j=1}^{N_t^b} v^b_j \mathbf 1_{B_j \leq \theta(T - \tau_i)})\Big]
\end{equation}
to find the optimal rebate policy $\hat \xi(d)$. 

\subsection{Saturated utility reservations}\label{section:saturated}
Recalling Theorem \ref{thm:main}, it is equivalent to find optimal controls $(\hat Y_0^p,\hat Y_0^q,\hat Z^p,\hat Z^q)$ such that $\xi^p\in \Xi^p$ and $\xi^q\in \Xi^q$. Therefore,
\begin{align*}
    \rho(d)&=\inf_{Y^p_0\geq R_0^p,Y^q_0\geq R_0^q,\; (Z^p,Z^q)\in \mathcal Z} \mathbb{E}^{\hat\alpha( Z,d)}\Big[|P^{cl}_T - P_T^{*}|^2 + Y_T^{Y_0, Z} \cdot I_2 - d(X_T^1 + X_T^2)\Big]\\
    &=\inf_{Y^p_0\geq R_0^p,Y^q_0\geq R_0^q,\; (Z^p,Z^q)\in \mathcal Z} \mathbb{E}^{\hat\alpha( Z,d)}\Big[|P^{cl}_T - P_T^{*}|^2 + Y_0 \cdot I_2+(Y_T^{Y_0, Z}-Y_0 )\cdot I_2 - d(X_T^1 + X_T^2)\Big]\\
    &=\inf_{Y^p_0\geq R_0^p,Y^q_0\geq R_0^q} [Y_0 \cdot I_2]+ \inf_{(Z^p,Z^q)\in \mathcal Z} \mathbb{E}^{\hat\alpha( Z,d)}\Big[|P^{cl}_T - P_T^{*}|^2 +Y_T^{0, Z}\cdot I_2 - d(X_T^1 + X_T^2)\Big]\\
    &=R_0^p  +R_0^q+ \inf_{(Z^p,Z^q)\in \mathcal Z} \mathbb{E}^{\hat\alpha( Z,d)}\Big[|P^{cl}_T - P_T^{*}|^2 +Y_T^{0, Z}\cdot I
    _2- d(X_T^1 + X_T^2)\Big].
\end{align*}

The optimization problem of the exchange is reduced to the optimization on the $Z$ process controlling $X,Y$:

\begin{equation}\label{opt:tilderho} \inf_{(Z^p,Z^q)\in \mathcal Z} \mathbb{E}^{\hat\alpha( Z,d)}\Big[|P^{cl}_T - P_T^{*}|^2 +Y_T^{0, Z}\cdot I_2 - d(X_T^1 + X_T^2)\Big].\end{equation}

