\subsection{Optimal incentives and rebate policy}
We turn to the solution of \eqref{opt:tilderho} by using a verification argument. We first define $\mathcal C'([0,T])$ as the set of function $\phi$ defined from $t\in [0,t] \times (x,y,r,p;z,d)\in \mathcal S= \mathbb R^7\times \mathbb R^2\times \mathbb R^2\times \mathbb R^2\times \mathbb R^{7\times 2}\times \mathbb R_+$ into $\mathbb R$, which are continuously differentiable in time $t$, twice continuously differentiable with respect to the variables $x_3,p,y$ and continuous in the other variables. We then define the Dynkin operator $A$ associated with the processes $X,Y$ for any $\phi\in \mathcal C'([0,T],\mathcal S) $ by 
\begin{align*}
    A\phi(t,x,y,r,p;z,d):=& \sum_{i = p,q} \frac{\partial \phi}{\partial y_i} (t, x, y,r,p) \Bigl\{\lambda_0(z^{1,i} + z^{2,i} +z^{4,i} +z^{6,i} ) - F^i(x,z,r,p, \hat \alpha^j_s,d;\hat \alpha^i_s) -  z^{5,i} \frac{\mu^p}{\sigma} - z^{7,i} \frac{\mu^q_s}{\sigma} \Bigl\} \\
    &+\frac{1}{2} \frac{\partial^2 \phi}{\partial x_3 \partial x_3} (t, x,y,r,p) \sigma^2 + \frac{1}{2}\sum_{i,j=p,q} \frac{\partial^2 \phi}{\partial y_i \partial y_j} (t, x,y,r,p) \Bigl\{z^{3,i} z^{3,j} + z^{5,i}z^{5,j}+z^{7,i}z^{7,j}\Bigl\}\\
    &- \sum_{j=p,q}  \frac{\partial^2 \phi}{\partial x_3 \partial y_j} (t, x,y,r,p) \sigma z^{3,j}  + \sum_{i=p,q} \frac{\partial \phi}{\partial p_i} (t, x,y,r,p)\mu^i +\frac{1}{2}\sum_{i =p,q}  \frac{\partial^2 \phi}{\partial p_i \partial p_i} (t, x,y,r,p) \sigma^2 \\
    &-\sum_{i = p,q}\frac{\partial^2 \phi}{\partial y_i \partial p_p} (t, x,y,r,p) \sigma z^{5,i} - \sum_{i = p,q}\frac{\partial^2 \phi}{\partial y_i \partial p_q} (t, x,y,r,p) \sigma z^{7,i} \\
    &+  [\phi(t,x+[r_1 , 0,0, 0,0,0,0],y +[-z^{1,p},-z^{1,q}],r,p)  - \phi(t, x,y,r,p)]  \lambda^a_t \\
    &+ [\phi(t,x+[0 , r_2,0, 0,0,0,0],y +[-z^{2,p},-z^{2,q}],r,p)  - \phi(t, x,y,r,p)]  \lambda^b_t\\
    &+ [\phi(t,x+[0 , 0,0, p^p,1,0,0],y +[-z^{4,p},-z^{4,q}],r,p)  - \phi(t, x,y,r,p)] \hat\lambda^p_t\\
    &+ [\phi(t,x+[0 , 0,0, 0,0,p^q,1],y +[-z^{6,p},-z^{6,q}],r,p)  - \phi(t, x,y,r,p)] \hat\lambda^q_t,
\end{align*}
where  $\lambda^a,\lambda^b,\hat\alpha=(\hat\alpha^p;\hat\alpha^q)=(\hat\mu^p,\hat\lambda^p;\hat\mu^q,\hat\lambda^p)$, are functions of $(x,z,p,d)$ from Theorem \ref{thm:main}.



\begin{theorem}[Verification and optimal rebates]\label{thm:hjb}Let $d>0$ be fixed. Assume that
        \begin{itemize}
            \item there exists a function $\phi \in C'([0,T],\mathcal{S})  $ satisfying\\
            \begin{equation}
            \left\{
            \begin{aligned}
                &\frac{\partial \phi}{\partial t} + \inf_{z\in \mathbb R^{7\times 2}} A\phi(t,x,y,r,p;z,d) = 0,\text{ }t<T, \\
                &\phi(T,x,y,r,p;d) = \left(\frac{x_1 - x_2 + K^p x_4 + K^q x_6 + K^0 P_0^*}{K^p x_5 + K^q x_7 + K^0} - x_3\right)^2 + y \cdot I_2 - d(x_1 + x_2),\; (x,y,r,p)\in \mathcal S;
            \end{aligned}
            \right.
            \label{eq:zsolution} 
            \end{equation}

            \item there exists $n_1,n_2, n_3 \in \mathbb{N}$ and $C \in \mathbb{R}$ s.t. $|\phi(t,x,y,r,p,d)| < C(1+ |x|^{2}+|y|+|r|^{n_1}+|p|^{n_2})$ for every  $(t,x,y,r,p) \in [0,T] \times\mathcal{S}$;
            \item for every $(t,x,y,r,p) \in [0,T] \times \mathcal{S} $, there exists $\hat z(d)=\hat{z}(t,x,y,r,p;d) \in \mathbb{R}^{7\times 2}$ such that $ A\phi(t,x,y,r,p;\hat z(d),d) =  \inf_{z}\in \mathbb R^{7\times 2}A\phi(t,x,y,r,p;\hat z(d),d)$ and such that $\hat Z_t(d)=\hat{Z}(t,X_t,Y_t,r_t,P_t;d) \in \mathcal{Z}$.
        \end{itemize}
        Then $\rho(d) =R_0^p  +R_0^q+ \phi(0,X_0, Y_0, r_0,p_0)$ and $\hat Z(d)$ is the optimal control of the exchange's problem \eqref{eq:ex}. Consequently, the optimal rebate policy is 
        \[\xi^p=Y
        _T^{p,\hat Z^p(d),d},\; \xi^p=Y
        _T^{q,\hat Z^q(d),d}, \]
        where $Y _T^{i,z,d}$ is defined by Theorem \ref{thm:main}.
\end{theorem}
