&= \mathbb{E}^{\hat\alpha} \Big[\phi(0,X_0,Y_0,r_0,P_0) + \int_0^{\theta_n}  \Bigr\{ \frac{\partial \phi}{\partial s} (s, X_s, Y^{Z,d}_s,r_s,P_s) ds  +A\phi (s, X_s, Y^{Z,d}_s, r_s, P_s; Z_s) \Bigr\} ds \Big] \\
&\geq \phi(0,X_0,Y_0,r_0,P_0), \text{ for any } Z\in \mathcal Z,\end{align*} where equality is attained at $Z=\hat Z$ by the definition of $\phi$ solving \eqref{eq:zsolution}.

