\subsection{The deep multi-FBSDE method}

Our deep multi-FBSDE method is based on a slightly modified variational formulation. To arrive at it, we notice that for sufficiently regular $\psi\colon[0,T]\times\R^d\times\R\times\R^\ell\to\R^d$, it holds by the It\^o formula, for $Y_t^\psi=v(t,X_t^\psi)$ and $Z_t^\psi=\mathrm{D}_xv(t,X_t^\psi)$ that
\begin{equation}\label{eq:FBSDE_drift}\begin{dcases}
  X_t^\psi
  =
  x_0+\int_0^t \big(b(s,X_s^\psi,Y_s^\psi, Z_s^\psi)-\psi(s,X_s^\psi,Y_s^\psi,Z_s^\psi)\big)\d s + \int_0^t\sigma(s,X_s^\psi)\d W_s,\\
  Y_t^\psi
  =g(X_T^\psi) 
  + 
  \int_t^T 
    \big(f(s,X_s^\psi,Y_s^\psi,Z_s^\psi) +\big\langle \psi(s,X_s^\psi,Y_s^\psi,Z_s^\psi),Z_s^\psi\big\rangle\big)
  \d s \\ \quad\quad\ 
  - \int_t^T  \big\langle Z_s^\psi ,\sigma(s,X_s^\psi) \d W_s\big\rangle,\quad t\in[0,T].
    \end{dcases}
\end{equation}
This defines a family of FBSDEs, indexed by $\psi$, which are all equivalent to the PDE~\eqref{eq:PDE}. In particular, for all $\psi$ we have $Y_0^\psi=v(0,X_0^\psi)=v(0,x_0)$ and thus the initial value is shared for all $\psi$, which we utilize. Introducing the shorthand notation
\begin{align*}
  b^{\psi}(t,x,y,z)
  &:=
  b(t,x,y,z) - \psi(t,x,y,z)\\
  f^{\psi}(t,x,y,z)
  &:=
  f(t,x,y,z)+\langle z, \psi(t,x,y,z)\rangle,
\end{align*}
we have for any $\psi$ the variational formulation 
\begin{equation}\label{var_Psi_FBSDE}\begin{dcases}
\underset{y_0,\zeta}{\mathrm{minimize}}\ 
 \E\big|Y_T^{y_0,\zeta,\psi}-g(X_T^{y_0,\zeta,\psi})\big|^2,\quad \text{where} \\
X_t^{y_0,\zeta,\psi}=x_0+\int_0^t b^\psi(s,X_s^{y_0,\zeta,\psi},Y_s^{y_0,\zeta,\psi},Z^{y_0,\zeta,\psi}_s)\d s  + \int_0^t\sigma(s,X_s^{y_0,\zeta,\psi})\d W_s,\\
Y_t^{y_0,\zeta,\psi}= y_0-\int_0^t f^\psi(s,X_s^{y_0,\zeta,\psi},Y_s^{y_0,\zeta,\psi},Z^{y_0,\zeta,\psi}_s)\d s +\int_0^t \big\langle Z^{y_0,\zeta,\psi}_s,\sigma(s,X_s^{y_0,\zeta,\psi})\d W_s \big\rangle,\\
Z^{y_0,\zeta,\psi}_t=\zeta(t,X_t^{y_0,\zeta,\psi}),\quad t\in[0,T].
    \end{dcases}
\end{equation}
Since the optimal $y_0^*$ and $\zeta^*$ are optimal for all $\psi$, we trivially have, for $K\in\N$, $\psi_1,\dots,\psi_K\colon[0,T]\times\R^d\times\R\times\R^\ell\to\R^d$, the equivalent variational formulation,
\begin{equation}\label{var_Psi_FBSDE2}\begin{dcases}
\underset{y_0,\zeta}{\mathrm{minimize}}\ 
 \sum_{k=1}^K\E\big|Y_T^{y_0,\zeta,\psi_k}-g(X_T^{y_0,\zeta,\psi_k})\big|^2,\quad \text{where for }\psi\in\{\psi_1,\dots,\psi_K\} \\
X_t^{y_0,\zeta,\psi}=x_0+\int_0^t b^\psi(s,X_s^{y_0,\zeta,\psi},Y_s^{y_0,\zeta,\psi},Z^{y_0,\zeta,\psi}_s)\d s  + \int_0^t\sigma(s,X_s^{y_0,\zeta,\psi})\d W_s,\\
Y_t^{y_0,\zeta,\psi}= y_0-\int_0^t f^\psi(s,X_s^{y_0,\zeta,\psi},Y_s^{y_0,\zeta,\psi},Z^{y_0,\zeta,\psi}_s)\d s +\int_0^t \big\langle Z^{y_0,\zeta,\psi}_s,\sigma(s,X_s^{y_0,\zeta,\psi})\d W_s\big\rangle,\\
Z^{y_0,\zeta,\psi}_t=\zeta(t,X_t^{y_0,\zeta,\psi}),\quad t\in[0,T].
    \end{dcases}
\end{equation} 

The deep multi-FBSDE is divided into two phases. Phase I is based on approximating \eqref{var_Psi_FBSDE2} for suitable $K$ and $\psi_1,\dots,\psi_K$, with time discretization, neural network approximation of $\zeta$ and stochastic gradient descent. In the second phase, a better approximation of $\zeta$ is obtained by solving the classical deep FBSDE method with the exception that only $\zeta$ is optimized and $y_0$ is taken from Phase~I. For easy and low-dimensional problems, Phase~I gives an accurate approximation of $\zeta$ and Phase~II is not needed. For more challenging and high-dimensional problems, we have observed that Phase~II improves the approximation accuracy. We believe that this has to do with the fact that in Phase~I the Markov map $\zeta$ is optimized for good fit along typical trajectories of $K$ different SDEs, i.e., in a larger domain than in Phase~II, where it is only trained along typical trajectories of the original forward SDE, i.e., for a more limited task. 

We next state the scheme and similar to the deep FBSDE method let $\zeta$ represent $\zeta_0,\ldots,\zeta_{N-1}$.

\vspace{0.5cm}
\noindent\textbf{Phase I - Approximation of $Y_0$:}\newline
\begin{equation}\label{var_discrete_FBSDE_K}\begin{dcases}
\underset{y_0,\zeta_0,\ldots,\zeta_{N-1}}{\mathrm{minimize}}\ 
 \sum_{k=1}^K\E\big|Y_N^{h,y_0,\zeta,\psi_k}-g(X_N^{h,y_0,\zeta,\psi_k})\big|^2,\quad \text{where for } \psi\in\{\psi_1,\dots,\psi_K\}\\
X_{n+1}^{h,y_0,\zeta,\psi}=X_n^{h,y_0,\zeta,\psi}+b^{\psi}\big(t_n,X_n^{h,y_0,\zeta,\psi},Y_n^{h,y_0,\zeta,\psi},Z_n^{h,y_0,\zeta,\psi}\big)h + \sigma(t_n,X_n^{h,y_0,\zeta,\psi})\Delta W_n,\\
Y_{n+1}^{h,y_0,\zeta,\psi} =Y_n^{h,y_0,\zeta,\psi}-f^{\psi}\big(t_n,X_n^{h,y_0,\zeta,\psi},Y_n^{h,y_0,\zeta,\psi},Z_n^{h,y_0,\zeta,\psi}\big)h +\big\langle Z_n^{h,y_0,\zeta,\psi},\sigma\big(t_n,X_n^{h,y_0,\zeta,\psi}\big)\Delta W_n\big\rangle,\\
Z_n^{h,y_0,\zeta,\psi}=\zeta_n(X_n^{h,y_0,\zeta,\psi}\big),\  X_0^{h,y_0,\zeta,\psi}=x_0,\ Y_0^{h,y_0,\zeta,\psi}=y_0,\\
\text{for }n\in\{0,1,\ldots,N-1\}.
    \end{dcases}
\end{equation}

\vspace{0.5cm}
\noindent\textbf{Phase II - Approximation of the full FBSDE with known initial value:}\newline
\begin{equation}\label{var_discrete_FBSDE_fix_y}\begin{dcases}
\underset{\zeta_0,\ldots,\zeta_{N-1}}{\mathrm{minimize}}\ 
 \E\big|Y_N^{h,\zeta}-g(X_N^{h,\zeta})\big|^2,\quad \text{where}\\
X_{n+1}^{h,\zeta}=X_n^{h,\zeta}+b\big(t_n,X_n^h,Y_n^{h,\zeta},Z_n^h\big)h + \sigma(t_n,X_n^{h,\zeta})\Delta W_n,\\
Y_{n+1}^{h,\zeta}= Y_n^{h,\zeta}-f\big(t_n,X_n^{h,\zeta},Y_n^{h,\zeta},Z_n^{h,\zeta}\big)h +\big\langle Z_n^{h,\zeta},\sigma\big(t_n,X_n^{h,\zeta}\big)\Delta W_n\big\rangle,\\
Z_n^{h,\zeta}=\zeta_n\big(X_n^{h,\zeta}\big),\  Y_0^{h,\zeta}=y_0^*, \quad \text{for } n\in\{0,1,\ldots,N-1\}.
    \end{dcases}
\end{equation}

We demonstrate the new numerical scheme on the LQG-problem, detailed in Section~\ref{lqgcp_num}, for which the deep FBSDE method was shown to fail in Section~\ref{sec:deepBSDE}. In Phase~I, we take $K=1,2,3,4$, with the choices $\psi_1=0$, $(\psi_1,\psi_2)=(0,b_1)$, $(\psi_1,\psi_2,\psi_3)=(0,b_1,-b_1)$ and $(\psi_1,\psi_2,\psi_3,\psi_4)=(0,b_1,-b_1,-0.5b_1)$, where the drift has the form $b(x,y,z)=b_1(x)+b_2(z)$, and plot the MSE curves in Figure~\ref{fig:5MSE}. For $K=2,3,4$ the optimization landscape is much more satisfactory than for $K=1$, which is the deep FBSDE method. In fact the minima are close to the real $Y_0=8.94$. To further indicate that the method is robust to the choice of $K\geq3$ (and possibly $K=2$) and $(\psi_1,\dots,\psi_K)$ we take $K=3$ and rather arbitrary choices $\psi_1=b_1\circ\xi$, $\psi_2=-b_1\circ\xi$, $\psi_3=0$, for $\xi\in\{x,-\sin(x),x\cos(x),1-\exp(\min(1,\max(-1,x)))\}$, where $\xi$ acts coordinate-wise on vectors. We obtain the four loss surfaces in Figure~\ref{fig:4MSE}, which, based on visual inspection, have the same minima. This robustness is a very important property because when the method is applied to a problem without a reference solution, one must be able to trust that the choice of $\psi_1,\psi_2,\psi_3$ does not need to be tuned based on comparison with a reference solution. Our results indicate a robustness in the choice of $K\geq2$ and $(\psi_1,\dots,\psi_K)$, but it needs to be investigated further, particularly theoretically. The deviation between $Y_0$ and the optimized $y_0^*$ is the discretization error due to the time stepping. This is seen empirically in the convergence plot in Figure~\ref{fig:L2_Y0} for $\xi(x)=x$, showing the experimental convergence order one, i.e., $|Y_0-y_0^*(h)|=\mathcal O(h)$. The convergence of $(X,Y,Z)$ as processes after Phase~II is shown in Section~\ref{lqgcp_num}.


