\subsection{Data Extraction} 

Relevant patient data, including the pCT and rpCT, and their corresponding CTV and OAR contours, were retrieved from an internal database in DICOM format. All the contours were manually delineated by attending physicians for treatment planning or replanning of the actual treatments. These DICOM files of CT images and contours were imported into the open-source treatment planning toolkit matRad~\citep{wieser2017development} to precalculate dose influence matrices ($\Vec{D}$) required for plan optimization, using the same beam arrangements (e.g., isocenter location, number of beams, and beam angles) as those used in the actual treatments. The dose matrix calculated from the pCT and its associated contours was used for training the DRL agents, while the matrix calculated from the rpCT and corresponding contours was used for testing. 

To train a patient-specific agent capable of adjusting the priorities among planning objectives to adapt the treatment plan to anatomical changes, we further generated augmented anatomies by simulating anatomical changes. In this proof-of-concept study, we simulated only two variation scenarios, i.e., tumor progression and regression, by expanding the original CTV contours on the pCT by $2$~\si{mm} or shrinking them by $3$~\si{mm}, respectively. These variations not only changed the CTV volumes but also altered their spatial relationships with surrounding OARs, increasing the diversity of the patient-specific training dataset in terms of anatomy and planning complexity. The pCT images, along with each set of modified contours, were also imported into matRad to calculate the corresponding dose influence matrices for the simulated anatomy variations. 

\begin{algorithm2e}
\caption{Patient-Specific DRL for IMPT Replanning}
\label{alg:drl_impt_replan}
% \SetAlgoLined
\LinesNumbered
\DontPrintSemicolon
    \KwIn{Patient cohort $\mathcal{P}$, RL algorithm (DQN/PPO), total episodes $N_{\text{episodes}}$, planning horizon $T_{\text{max}}$, learning rate $\eta$, target update rate $\tau$}
    \KwOut{Personalized policies $\{\pi_p\}_{p \in \mathcal{P}}$}
    % \vspace{0.1in}
    \ForEach{patient $p \in \mathcal{P}$}{
        \textbf{Initial Plan Setup:}\;
        % Apply anatomical variation: $\tilde{\Vec{D}}^p \leftarrow \text{Augment}(\Vec{D}^p)$\;
        Load dose matrices $\Vec{D}^p$, prescriptions (Rx), and initial priorities $\{\Vec{\omega}^p\}$\;
        Initialize beamlet intensity vector $\Vec{x}_0 \leftarrow \Vec{1}$\;
        Compute initial dose distribution $\Vec{d}_0 \leftarrow \Vec{D}^p\Vec{x}_0$\;
        Generate DVH curves as initial state $s_0^p \leftarrow \text{StateGen}(\Vec{d}_0)$\;
        Compute initial plan quality score (0-150 scale): $R_{\text{prev}}^p \leftarrow \psi(s_0^p)$\;
        \textbf{RL Training Setup:}\;
        Initialize policy network $\pi_{\Vec{\theta}_p}$ with weights $\Vec{\theta}_p^0$\;
        \If{DQN}{
            Initialize target network $\Vec{\theta}_p^- \leftarrow \Vec{\theta}_p^0$\;
            Create replay buffer $\mathcal{B}_p \leftarrow \emptyset$\;
        }
        \textbf{Training Loop:}\;
        \For{episode $= 1$ \KwTo $N_{\text{episodes}}$}{
            Reset environment: $s_t^p \leftarrow s_0^p$, $\Vec{x}_t \leftarrow \Vec{x}_0$\;
            \For{step $t = 0$ \KwTo $T_{\text{max}}$}{
                Select priority adjustment action $a_t^p \sim \pi_{\Vec{\theta}_p}(s_t^p)$\;
                Adjust tuning priorities: $\Vec{\omega}_{t+1}^p \leftarrow \text{UpdateTPP}(\Vec{\omega}_t^p, a_t^p)$ (Eqn.~\ref{eq:priority_update_rule})\;
                Optimize beamlet intensities: $\Vec{x}_{t+1} \leftarrow \arg\min_{\Vec{x} \geq 0} \mathcal{L}$ (Eqn.~\ref{eq:plan_optimization_problem})\;
                Compute new dose $\Vec{d}_{t+1} \leftarrow \Vec{D}^p\Vec{x}_{t+1}$ (Eqn.~\ref{eq:dij_mat})\;
                Extract state: $s_{t+1}^p \leftarrow \text{StateGen}(\Vec{d}_{t+1})$\;
                Calculate plan quality score $R_{t+1}^p \leftarrow \psi(s_{t+1}^p)$\;
                Calculate reward $r_{t+1}^p \leftarrow R_{t+1}^p - R_{\text{prev}}^p$\;
                \If{DQN}{
                    Store transition $(s_t^p, a_t^p, r_{t+1}^p, s_{t+1}^p)$ in $\mathcal{B}_p$\;
                    Sample batch $b \sim \mathcal{B}_p$, update $\Vec{\theta}_p \leftarrow \Vec{\theta}_p - \eta\nabla\mathcal{L}_{\text{DQN}}(b)$ (Eqn.~\ref{eq:dqn_loss})\;
                    Soft update: $\Vec{\theta}_p^- \leftarrow \tau\Vec{\theta}_p + (1-\tau)\Vec{\theta}_p^-$\;
                }
                \If{PPO}{
                    Estimate advantage $\hat{A}_t(s_t^p, a_t^p)$ (Eqn.~\ref{eq:gae}) \; % \leftarrow \text{GAE}(r_{t+1}^p, V(s_{t+1}^p))$\;
                    Update $\Vec{\theta}_p \leftarrow \Vec{\theta}_p - \eta\nabla\mathcal{L}_{\text{PPO}}(\hat{A}_t(s_t^p, a_t^p))$ (Eqn.~\ref{eq:ppo_loss})\;
                }
                \If{$R_{t+1}^p = 150.00$}{
                    Break %\tcp*{Early exit on perfect plan score}
                }
                Update next state $s_t^p \leftarrow s_{t+1}^p$\;
                Update previous plan score $R_{\text{prev}}^p \leftarrow R_{t+1}^p$\;
            }
        }
    }
\end{algorithm2e}


